[1651] = {
["Title"] = "奥妮克希亚",
["Description"] = "",
},
[1653] = {
["Title"] = "伊莉萨娜·拉文凯斯",
["Description"] = "拉文凯斯的女儿，上古之战后在守望者地窟中被囚禁了一万年。在玛维释放了被囚禁的恶魔猎手后，她也重获自由。回到故土后，为了保卫没能在上古之战时守护的家园，她献出了一切，包括自己的灵魂。",
},
[1655] = {
["Title"] = "橡树之心",
["Description"] = "橡树之心是莎拉达希尔上分出的树枝长成的古树，他经历过大分裂、大灾变和无数疫病，并顽强地存活了下来。这颗古树从梦境的精华中吸取力量，挺过了这些灾难。但现在，他力量的源泉变成了他堕落的本源。",
},
[1657] = {
["Title"] = "萨维斯之影",
["Description"] = "萨维斯曾是一名强大的法师，也是艾萨拉女王的谋臣，他后来与萨格拉斯达成协议，将燃烧军团第一次引入了艾泽拉斯。入侵失败后，萨维斯饱受诅咒与折磨，他现在从梦魇之中将自己真正的力量投射到我们的世界，为了摧垮老对手玛法里奥的意志而倾注自己所有的黑暗力量。",
},
[415] = {
["Title"] = "克罗卡斯",
["Description"] = "即便是在食人魔当中，克罗卡斯的火爆脾气也是臭名昭著，谁要是胆敢冒犯他或戈多克大王，就绝对没有好果子吃。他凶残地镇压那些与他意见相左的人，不过，总有人乐此不疲地散播他早年与一只豺狼人的热恋绯闻，对于这类造谣生事者，他更没有耐心。",
},
[1663] = {
["Title"] = "海拉",
["Description"] = "堕落的瓦格里女王海拉曾是奥丁的左膀右臂，负责将维库勇士的灵魂引入英灵殿，时刻准备着参加决定艾泽拉斯命运的最后一战。但洛肯背叛后，也说服了她与自己联手，背叛奥丁。她现在潜伏在地下的暗影国度，策划着复仇。",
},
[1665] = {
["Title"] = "乌拉罗格·塑山",
["Description"] = "乌拉罗格·塑山是一名古代卓格巴尔，他一生都在追求更强大的力量。乌拉罗格依靠暴力与欺骗的手段，一步步成为了地底之王倚重的谋士。他因纳瓦罗格将“入侵者”带进家园而对他怀恨在心，并很乐意无情地夺走这些入侵者的生命。",
},
[1667] = {
["Title"] = "乌索克",
["Description"] = "乌索克是一名荒野之神。这头古老的巨熊已守护艾泽拉斯多年，他也是熊怪的守护神，而且和德鲁伊变形术有着千丝万缕的联系。但当乌索克在灰熊丘陵的圣坛里沉睡之际，周围世界遭到了腐化，他在梦魇的折磨之下醒来，不过他的身心已经被扭曲。",
},
[418] = {
["Title"] = "群体打击者9-60",
["Description"] = "在诺莫瑞根的全盛时期，发明家们会相互比试自己的发明，以此提升自己的地位。工程师奥格索普·奥布诺提斯研制出了一个无敌机器人，这为他在大工匠协会中赢得了尊重。希科·瑟玛普拉格盗取了奥布诺提斯的蓝图，然后造出了一个巨版机器人。他任由自己的伪造品肆虐，引发了严重的后果，无辜的奥布诺提斯因此遭到了管理委员会的驱逐。群体打击者9-60至今仍是瑟玛普拉格最倾心的（剽窃）发明之一。",
},
[1673] = {
["Title"] = "纳拉萨斯",
["Description"] = "怪物之母纳拉萨斯自从奈萨里奥时代起就一直被卓格巴尔供奉为神明。他们不断向她献祭贡品，这样她就能孕育出一代代可怕的子孙供卓格巴尔用来对付敌人。无论如何，你必须赶在这头野兽被释放到至高岭肆虐之前将她除去，然后再直击地底之王。",
},
[419] = {
["Title"] = "格鲁比斯",
["Description"] = "在城内弥漫的放射性气体本是为了激怒穴居人，杀死侏儒，而瑟玛普拉格的凶残计划也实施得天衣无缝。但有一只穴居人却对这种物质产生了奇怪的反应——格鲁比斯长啊，长啊，越长越大。这是令希科始料未及的副作用，可他从来都不是一个会浪费珍贵（且危险）资源的人。这只体型庞大的穴居人如今就在诺莫瑞根的隧道中巡视。他忠实的蜥蜴宠物咀嚼者则帮助格鲁比斯嗅探气体泄漏，寻找美味的真菌，甚至是可口的入侵者。",
},
[420] = {
["Title"] = "粘性辐射尘",
["Description"] = "诺莫瑞根那原本恢弘优雅的复杂水道，现在被辐射得乌烟瘴气，到处都是毒性泥浆怪。有个曾住在侏儒蓄水层中的孤单水元素被污染困住，污染物将它的纯净形态腐化得面目全非。它现在愤怒而痛苦地游荡在诺莫瑞根的殿堂间，成为了瑟玛普拉格背叛留下的邪毒液体化身。",
},
[421] = {
["Title"] = "电刑器6000型",
["Description"] = "机械师瑟玛普拉格不是个有耐心的侏儒。他不喜欢通过一次次的实验去验证发明的安全性和有效性，而是急于将其投入使用，并将注意力转移到下一个项目上。电刑器6000型是他首次尝试通过超能机械坦克将电能作为武器的产物。“霹雳裤”汤姆·克兰科中尉是唯一一位驾驶过电刑器的幸存士兵，现在成了麻风侏儒里的大英雄。",
},
[1687] = {
["Title"] = "地底之王达古尔",
["Description"] = "达古尔是奈萨里奥时代以来最强大的地底之王。他确信只有自己才有权利运用卡兹格罗斯的力量，于是杀害了大酋长乌兰并夺走了至高岭牛头人的神器。现在，他使用锤子的力量在至高岭大肆破坏，粉碎一切与他为敌者。",
},
[423] = {
["Title"] = "诺克赛恩",
["Description"] = "诺克赛恩是腐化的活化身。瑟莱德丝命她的同伴维利塔恩造出这个腐烂的元素，充当强大的仆从和忠实的宠物，来化解公主心中的孤寂。诺克赛恩将自己的剧毒精华散播到玛拉顿尚未受到瑟莱德丝邪恶影响的其它区域。",
},
[1693] = {
["Title"] = "溃面",
["Description"] = "在冰冠堡垒陷落时，普崔塞德教授抓了很多实验对象。溃面很可能是更早时候制作的原型生物，但似乎是个失败的作品。它的后续作品就是大家耳熟能详的腐面和烂肠。",
},
[1695] = {
["Title"] = "审判官托蒙托鲁姆",
["Description"] = "在为燃烧军团效力的邪恶生物之中，最神秘恐怖的或许就是戴兜帽的审判官了。蒙托鲁姆在对守望者地窟的第一波攻击发动后到达。他在地窟的大厅中飘游，锐利的目光在阴影中搜寻至关重要的秘密。就连其他恶魔都对他退避三舍。",
},
[1697] = {
["Title"] = "赛尔奥隆",
["Description"] = "这些蜘蛛形恶魔的起源尚不完全明了。研究燃烧军团的学者们推测它们是萨格拉斯的大军在很久以前征服的一个异星种族的后裔。它们中有个名为赛尔奥隆的恶魔尤为凶恶，负责指挥达拉然潜入作战。",
},
[425] = {
["Title"] = "工匠吉兹洛克",
["Description"] = "工匠吉兹洛克与其它五位宝石猎人溜进了玛拉顿，前去采集异常珍贵的水晶。但当其它队友都被萨特屠戮殆尽，仅有吉兹洛克一人幸存时，他才明白他们的计划全盘落空了。这位地精被困在洞穴里，濒临疯狂的边缘，将自己视作这个地下王国的新统治者。",
},
[1703] = {
["Title"] = "尼珊德拉",
["Description"] = "尼珊德拉曾是守护世界之树莎拉达希尔的绿龙军团中的一员。当萨维斯的腐化梦魇吞噬了莎拉达希尔后，这位沉睡的守护者也被他的腐蚀吞噬了。如今的尼珊德拉只是过去的残影，深陷于瘟疫之中，时刻准备着吞噬任何胆敢深入她巢穴的愚者。",
},
[427] = {
["Title"] = "维利塔恩",
["Description"] = "萨特领主维利塔恩在闻听玛拉顿遭到腐化的消息后，便动身前往玛拉顿深处。瑟莱德丝起初对这位少言寡语的恶魔颇有戒心，但维利塔恩用行动证明了自己的价值，他为公主造出了许多邪恶的仆从，如诺克赛恩和锐刺鞭笞者。",
},
[1711] = {
["Title"] = "邪能领主贝图格",
["Description"] = "无情的军团指挥官时刻准备带领入侵部队从达拉然内部发动攻击。",
},
[1713] = {
["Title"] = "克洛苏斯",
["Description"] = "这名巨大的末日领主的体型和力量在燃烧军团中数一数二，但是在联盟和部落最强大英雄合力奋战之下，他在破碎海滩被击败了。伤势恢复后，克洛苏斯在暗夜要塞和萨格拉斯之墓之间的海湾里再次现身，一切与军团为敌者都会被他无情地碾碎。",
},
[429] = {
["Title"] = "兰斯利德",
["Description"] = "多年以来，名叫兰斯利德的古老山巨人都在玛拉顿料理着璀璨的水晶花园，但自打瑟莱德丝来此定居的那天起，兰斯利德便深深地被她吸引住了。这位曾经清心寡欲的巨人现今生活的唯一目的就是为他残暴的新主人效力。",
},
[1719] = {
["Title"] = "塔丽克萨·火冠",
["Description"] = "塔丽克萨是一名残暴的艾瑞达巫师。尽管她明白夜之子对她主人十分重要，但一想到自己在看守着住满精灵的建筑，她就气不打一处来。尽管如此，她还是和手下的副官们履行着职责。只要有他们在，就不会有闯入者打扰集会。",
},
[431] = {
["Title"] = "瑟莱德丝公主",
["Description"] = "土元素瑟莱德丝——石母塞拉赞恩的独生女，住在玛拉顿的内室深处。由于受到上古之神的影响，这位公主将她的家园变成了充满腐化与痛苦的窝巢。有人认为，她的邪恶力量是与她已故爱人扎尔塔的灵魂紧密联系在一起的。假如果真如此，那么解放这位陨殁的林地守护者，也许是净化玛拉顿的唯一希望所在。",
},
[1725] = {
["Title"] = "时空畸体",
["Description"] = "暗夜井底下的洞穴就是原始能量的大漩涡，维持整个文明的能量就源自于此。从这个混乱的能量涡流中诞生的时空畸体是阿曼苏尔之眼力量的化身。它发动攻击的同时，爆发出的能量能扭曲时间的流动。",
},
[1731] = {
["Title"] = "崔利艾克斯",
["Description"] = "曾经光荣地侍奉夜之子权贵的崔利艾克斯后来和其他多余的构造体一样遭到弃置，并慢慢损耗。尽管它完成任务的意愿坚定不移，但由于年久失修，它的性格矩阵产生了故障。它现在会毫无征兆地切换模式，前一刻还是慈爱的护理人员，可能突然就变成无情的杀戮机器，渴望得到早已不存在的主人的赞赏与认可。",
},
[1737] = {
["Title"] = "古尔丹",
["Description"] = "加尔鲁什逃往德拉诺后引发的一系列事件仍在继续，虽然经历了很多曲折，但还是发展到了现在这一步。在德拉诺遭受挫败的古尔丹，代表着他的燃烧军团主人，现在距离最终的胜利仅一步之遥。恶魔能量的漩涡在暗夜要塞上空旋动，站在要塞之巅的这位被放逐的兽人术士静候着他的命运。",
},
[1743] = {
["Title"] = "大魔导师艾利桑德",
["Description"] = "艾利桑德曾因为对抗燃烧军团而享有盛名。她和手下的上层精灵追随者们背弃了走上黑暗之路的艾萨拉女王，之后利用阿曼苏尔之眼的力量创造出了暗夜井，保护了苏拉玛免遭大分裂的破坏。但一万多年后，军团再临了，她被逼上了绝路。于是她与恶魔结盟了，希望能再一次利用暗夜井的力量“拯救”她的人民。",
},
[437] = {
["Title"] = "暮光领主巴赛尔",
["Description"] = "暮光之锤从不容忍失败，所以当暮光领主巴赛尔接管黑暗深渊后，他的第一个命令就是将领主克尔里斯扔进阿库麦尔饥饿的大嘴中。现在，这个元素升腾者正在努力运用他深不可测的力量唤起古神的巨兽，让世界陷入黑暗。",
},
[1749] = {
["Title"] = "尼索格",
["Description"] = "巨龙尼索格曾是托林尼尔巨龙的一员，这些巨龙宣誓效忠泰坦守护者后很快就离开了龙巢。尼索格相信他总有一天能变得比守护者更强大，因此拒绝听命于他们。之后他便栖息在纳斯托迪尔山中自己繁衍后代，有兴致的时候就去附近的地区作恶。",
},
[1751] = {
["Title"] = "魔剑士奥鲁瑞尔",
["Description"] = "奥鲁瑞尔一向有着过人的魔法天赋。她在暗夜卫队中也轻而易举地一路晋升，因为她也是天生的使剑高手。但不管她变得多强，她依然渴望更强的力量。她进入苏拉玛大学和法师们一起学习，白天练习武艺，晚上练习锻造技能。她在暗夜井中施展魔法制造出贵重金属，并用这些金属打造了自己的武器和护甲。精通火焰、冰霜和奥术魔法的她成了第一位魔剑士。",
},
[1761] = {
["Title"] = "高级植物学家特尔安",
["Description"] = "夜之子特尔安自幼就对植物着迷。不管是野火烧不尽春风吹又生的野草，还是看似平淡无奇却能从阳光中吸收能量的小草，或是会生出树枝，同时树枝还能嫁接到别的树上的树木，都让他觉得无比神奇。他用暗夜井的能量把自己变得面目全非，原本夜之子精灵的特征几不可见。他认为现在的自己已经变成了更伟大的存在。",
},
[1763] = {
["Title"] = "沙索斯",
["Description"] = "这位林地的守卫遭到了梦魇的腐化。从前他为丛林带来生机，现在他走过之处只有凋零和毁灭。",
},
[1769] = {
["Title"] = "勒凡图斯",
["Description"] = "在深渊中沉睡的勒凡图斯受到了惊扰，浮上水面后发现群岛上恶魔横行。邪能魔法渗入了周围的水里，导致她脾气极度暴躁。",
},
[443] = {
["Title"] = "弗雷斯特恩",
["Description"] = "净化斯坦索姆的行动，夺去了无数无辜者的性命，他们唯一的罪行就是不该待在这座厄难临头的城市里。旅行歌手兼短笛演奏者弗雷斯特恩就是其中一位牺牲者。他在死后继续在城市中游荡，无法接受自己的悲剧命运。",
},
[444] = {
["Title"] = "阿库麦尔",
["Description"] = "阿库麦尔是个古老的邪魔，在他身上也有着上古之神的些许力量。这只颈上长有三颅的多头蛇因其盲目的凶蛮以及对活人血肉的极端渴望而令人畏惧不已，但暮光之锤却将他视作上古之神即将归来的神圣预兆而大加崇拜。",
},
[445] = {
["Title"] = "悲惨的提米",
["Description"] = "提米森因在战场上的凶蛮而臭名远播。有人推测，他的病态性格是源自童年时期不断被欺负的经历。现在他已经以天灾怪物的身份重生，心智破碎，饱受过往记忆的煎熬，只要有人唤起那个曾令他深恶痛绝的名字——提米，他就会应声而来。",
},
[1783] = {
["Title"] = "魔王纳扎克",
["Description"] = "这只怪物是法多雷的头领，潜伏于法兰纳尔隧道。他在碎石中穿行时，发现了灌魔之石，并吸收其中的奥术能量维持自己的生命，静候着更难对付的猎物出现。",
},
[447] = {
["Title"] = "深渊守护者",
["Description"] = "在被诅咒的月神圣地废墟下，远古生物们在为争夺领地乐此不疲。来自废墟的瑟拉吉斯受到深渊守护者的驱使，不断寻找着新的孵化场。现在，守护者看护着成千上万的蛋，直到它们孵化，并散播蔓延至艾泽拉斯的地下水域。",
},
[1789] = {
["Title"] = "冷血的杜贡",
["Description"] = "多年以来，栖息在至高岭冰封的山顶上的冷血的杜贡一直是诸族的祸害。现在，这个强大的双头怪离开了自己的巢穴，企图趁乱将这片区域占为己有。",
},
[448] = {
["Title"] = "档案管理员加尔福特",
["Description"] = "加尔福特曾经将看管十字军珍贵文献的工作视作莫大荣耀。但在临死前，他却惊恐地看着那些被他视如珍宝的书卷被付之一炬。巴纳扎尔用这痛苦的记忆为他的仆从注入了生时令他不得安宁的炽热力量。",
},
[1795] = {
["Title"] = "浮骸",
["Description"] = "饥渴的浮骸从海洋深处浮上水面觅食。浮骸最先遇上的是沉船海湾的沼泽鱼人，他一口气就吞下了几十个。尽管绝大部分成员都被浮骸吃掉了，这些鱼人还是将他奉若神明，并不断送亲友给他吃，直到他饱得晕过去为止。浮骸醒来时，会把区域内的所有人都视为自己的食物。",
},
[450] = {
["Title"] = "不可宽恕者",
["Description"] = "莉莉娅曾是他族人间的正义之刃。在阿尔萨斯率军净化城市后，莉莉娅亲眼目睹无数无辜者死在她的手上，这使她丧失了理智。她选择挥剑逃避身边的疯狂，而现在，她则以鬼魂的身份存在，所犯下的恶行永远都不会得到赦免。",
},
[451] = {
["Title"] = "安娜丝塔丽男爵夫人",
["Description"] = "安娜丝塔丽在世时，就会为了占有心仪之物不惜任何代价。死亡也没能让她转性。安娜丝塔丽的灵魂被剥离出身体，变成了女妖。她不再追求名贵的饰品，而是将热情倾注在更为邪恶的东西上面。",
},
[452] = {
["Title"] = "奈鲁布恩坎",
["Description"] = "奈鲁布恩坎在蜘蛛大战中是一位可怕的战士。最后，她却因伤势过重而屈服，化身成为不死族，变成了天灾军团听话的爪牙。现在这位蛛魔正在斯坦索姆凶狠地守卫着一座通灵塔，如同用生命捍卫自己的家园。",
},
[453] = {
["Title"] = "苍白的玛勒基",
["Description"] = "玛勒基是第一批加入诅咒神教的，在应对墓穴的阴寒方面表现出了过人的天资。对力量永无止境的渴求驱使这位法师热忱地磨练自己对黑暗魔法的驾驭能力，时刻准备迎接化身巫妖的那一天。",
},
[454] = {
["Title"] = "巴瑟拉斯镇长",
["Description"] = "巴瑟拉斯是在阿尔萨斯及其军团净化斯坦索姆的行动中惨遭洗劫的众多无辜者之一。巫妖王最终从墓里唤醒了这位昔日的镇长，并命令这只巨大的亡灵怪物守卫他被毁灭的家园。",
},
[1817] = {
["Title"] = "麦迪文之影",
["Description"] = "末代守护者麦迪文的力量如此强大，他的魔法至今仍在卡拉赞的殿堂中回荡。这些回响有的形成了画面，展示着访客们的往事。其他的则变成了更为邪恶的形态，让人回想起守护者面目全非时的所作所为。",
},
[1819] = {
["Title"] = "奥丁",
["Description"] = "许多世代以前，奥丁曾带领泰坦铸造的大军对抗黑暗帝国的上古之神。但数千年来，他被宿敌海拉的诅咒禁锢在了英灵殿里。如今，奥丁正在征召凡人勇士，以期推翻冥狱深渊的统治者并重获自由。",
},
[456] = {
["Title"] = "奥里克斯·瑞文戴尔领主",
["Description"] = "奥里克斯竟在陡然间一堕千丈。与他遭到腐化的父亲——瑞文戴尔男爵一样，生前是位圣骑士，死后却不得安宁。他悲惨地沦为了天灾军团的工具，为他誓死铲除的邪恶力量效命。",
},
[1825] = {
["Title"] = "贞节圣女",
["Description"] = "这位泰坦守护者来到卡拉赞，本是要净化这座邪恶与堕落之塔，但麦迪文声名狼藉的宴会和放纵的生活彻底激怒了她。她一边寻找皈依者加入她的美德之战，一边努力运用一切力量净化这里伤风败俗的生活。",
},
[1827] = {
["Title"] = "歌剧院：美女与野兽",
["Description"] = "受到诅咒变成野蛮怪物的布鲁特必须找到真爱才能避免被这黑暗的变形魔法夺去性命。他能及时学会正确的餐桌礼仪，赢得美丽的贝拉的心吗？",
},
[1829] = {
["Title"] = "海拉",
["Description"] = "虽然曾经是奥丁的左膀右臂，但在满腔仇恨的驱使下，海拉会不惜一切巩固她的古老诅咒，将那位泰坦守护者继续囚禁在英灵殿中。如今，她已不再满足于统治她的暗影王国，即将指挥她的克瓦迪尔大军掠夺生者的土地。",
},
[458] = {
["Title"] = "预言者迦玛兰",
["Description"] = "迦玛兰是阿塔莱的现任领袖，这是一个由疯狂崇拜哈卡的祭司组成的极端教派。在深度冥想中，迦玛兰收到了指示，得知可用哈卡宿敌——绿龙的鲜血使其复活。迦玛兰和他的亡灵侍卫——可悲的奥戈姆，决心消灭任何胆敢阻止哈卡回归的叛逆之徒，但这位先知的行动很可能会让更为可怕的翡翠梦魇笼罩艾泽拉斯。",
},
[1835] = {
["Title"] = "猎手阿图门",
["Description"] = "原本负责在主人的宴会上进行狩猎游戏的阿图门如今又盯上了一种完全不同的猎物。阿图门那著名的战马“午夜”一直是小偷觊觎的对象，所以他会时刻保持警惕，用精湛的战斗技艺对付一切入侵者。",
},
[1837] = {
["Title"] = "莫罗斯",
["Description"] = "卡拉赞的管家莫罗斯在大宴会厅里招待着主人的晚宴客人。他不知疲倦，全心全意地照料着这座塔楼，以高超的效率对付着不速之客。",
},
[463] = {
["Title"] = "伊兰尼库斯的阴影",
["Description"] = "伊兰尼库斯——梦境之神伊瑟拉从前的配偶，被派去守卫阿塔哈卡遗迹，阻止哈卡现身。进入神庙之后，他和随从便遭到了黑暗力量的腐化，伊兰尼库斯变成了阴影，在翡翠梦境与真实界域间饱受撕扯。但腐化并未抹除伊兰尼库斯的所有记忆，他还能凭借自己身为绿龙的力量，朝敌人喷吐腐蚀酸液，或使其陷入沉睡。",
},
[464] = {
["Title"] = "霍格",
["Description"] = "罪犯：#SC55：霍格\r\n\r\n罪名：不计其数\r\n\r\n关押河爪首领的代价很是高昂，典狱官甚至落得个半盲的下场。因担心霍格越狱，塞尔沃特下令对这只豺狼人严加看管。",
},
[465] = {
["Title"] = "灼热勋爵",
["Description"] = "罪犯#NA：灼热勋爵\r\n\r\n罪名：杀人（多起）\r\n\r\n由大灾变引起的自然灾害，使元素纷纷涌入监狱，它们到来时杀死了一半囚犯。只有尽快消灭这些暴徒，才能恢复监狱的秩序。",
},
[1861] = {
["Title"] = "主母萨丝琳",
["Description"] = "主母萨丝琳毕生都致力于用她的黑暗意志束缚海洋生物。依靠这种力量，她从大海深处召唤出了可怕的梦魇，能淹没一切敢于挑战她的敌人。",
},
[466] = {
["Title"] = "兰多菲·摩洛克",
["Description"] = "罪犯#AC317：兰多菲·摩洛克\r\n\r\n罪名：侵吞钱款、诈骗、偷窃以及杀人\r\n\r\n摩洛克已被认定是造成监狱暴动的罪魁祸首。但考虑到他的贵族身份，在制服这名罪犯时不得使用致命手段。",
},
[1867] = {
["Title"] = "恶魔审判庭",
["Description"] = "由于早就预料到凡人部队会入侵萨格拉斯之墓，基尔加丹召来了他最好的捕手，阿提甘和贝拉克，来围剿入侵者，防止他们使用创世之柱继续深入地下城。",
},
[468] = {
["Title"] = "失落的矮人",
["Description"] = "为了名望，更为了财富，埃瑞克、奥拉夫和巴尔洛戈这三兄弟与探险者协会签订了合约，到奥达曼的殿堂中一探究竟，并为身后的研究人员扫清道路。但对这三位矮人来说，“扫清道路”却不幸地演变成了“在古老的迷宫中绝望地迷失方向”。可他们毕竟是骄傲的矮人，他们英勇战斗，决不让奥达曼与探险者协会的秘密落在部落的手里。",
},
[1873] = {
["Title"] = "堕落的化身",
["Description"] = "艾格文击败了萨格拉斯的化身，却无法将其摧毁。在将其封印的过程中，这套铠甲被埋在了月神殿下方，并在那里沉睡了数百年。现在，随着燃烧军团撕裂了萨格拉斯之墓的屏障，基尔加丹终于有机会复活它，并将它的力量释放到艾泽拉斯了。",
},
[469] = {
["Title"] = "艾隆纳亚",
["Description"] = "泰坦并没有直接建造奥达曼，而是让诸多仆从共同缔造了这一巨石筑成的华丽殿堂。万神殿委托看守者艾隆纳亚监管奥达曼的建造和维护，可随着时间的流逝，曾经令人惊叹的宫殿变成了废墟。在地图厅里，艾隆纳亚静待了数千年，苦苦分析由卡兹格罗斯起草的原始蓝图，设法将这一恢弘建筑复原到最初的风貌。",
},
[470] = {
["Title"] = "远古巨石卫士",
["Description"] = "远古巨石卫士是驻守和看管伟大泰坦殿堂的众多魔像之一，也是介于看守者与众多仆从之间的中间角色。在黑曜石哨兵的腐化发生后，远古巨石卫士成了它群体中的最后一位，尽自己最大努力守护泰坦的秘密，直到自己也倒下为止。",
},
[1883] = {
["Title"] = "布鲁塔卢斯",
["Description"] = "深渊领主布鲁塔鲁斯身经百战。他最近一次参加的战斗就是太阳之井战役。他的战术通常都不复杂，基本都是依赖纯粹的力量击退敌人的军队。",
},
[1885] = {
["Title"] = "丝瓦什",
["Description"] = "丝瓦什所掌控着海洋的愤怒，并用它来攻击过于靠近海岸的敌人。她麾下勇猛的丝瓦什荣誉卫士追随她横行于艾泽拉斯诸海，渴望着摧毁毫无防备的港口。",
},
[472] = {
["Title"] = "格瑞姆洛克",
["Description"] = "在穴居人社会中，块头最大、最强壮且最为凶狠的穴居人，常常会通过展示实力成为酋长。格瑞姆洛克相对而言是个天才，他通过威慑和某种意义上的心理战术，维持着对石窟穴居人的统治。他训练了一只致命的蜥蜴，用这野兽的石化手段令任何妄图谋逆的宵小不敢造次。",
},
[473] = {
["Title"] = "阿扎达斯",
["Description"] = "在奥达曼深处有间密室，里面藏有泰坦最伟大的财宝之一，由诺甘农亲自缔造。然而，至今为止还没有哪位冒险家拿到过这件圣物，因为任何动静都会激活强大的看守者阿扎达斯，这是一位体型庞大的护卫，凭借有力的攻击与名副其实的仆从大军，将对财宝怀有不轨企图的宵小之徒轻松消灭。由采自奥达曼深处的远古坚石塑造而成，阿扎达斯是位既古老又可怕的对手。",
},
[474] = {
["Title"] = "安娜科德拉",
["Description"] = "当纳拉雷克斯自作主张地派人前往贫瘠之地时，绯叶是第一个自告奋勇的人。在心智被主人的噩梦彻底粉碎后，这位年轻的侍僧便将自己的名姓丢诸脑后，现在正酝酿着艾泽拉斯邪恶阴险的未来。",
},
[1897] = {
["Title"] = "戒卫侍女",
["Description"] = "戒卫侍女受命于艾格文，在此保卫萨格拉斯之墓。她已经守卫了数百年。但守护者没有预料到，化身渗漏出的邪能会对这个泰坦构造体造成怎样的影响。被这股邪恶力量慢慢扭曲的侍女现在将摧毁一切阻拦她的人。",
},
[475] = {
["Title"] = "考布莱恩",
["Description"] = "加拉克斯拉驾驭动物形态的能力，为他在塞纳里奥议会的德鲁伊间赢得了威名。然而，哀嚎洞穴的腐化却扭曲了他的特殊能力。现在，加拉克斯拉已将一种致命的毒蛇形态演练得出神入化，为自己冠以考布莱恩的新名字，以体现他那全新的邪恶力量。",
},
[1903] = {
["Title"] = "月之姐妹",
["Description"] = "在萨格拉斯的化身被埋入月神殿的地下前，月之姐妹早已成为了神殿的守卫。即使在死后，她们依然尽忠职守。但在这数千年中，有什么东西扭曲了她们分辨敌友的能力。疯狂慢慢吞噬了她们。现在，任何进入这座圣殿的人都会被她们处死。",
},
[1905] = {
["Title"] = "阿格洛诺克斯",
["Description"] = "空中花园的这棵古树守卫着艾露恩神殿的暗夜精灵女祭司们。但随着军团的恶毒力量逐渐渗透进大教堂，这位守护者的根系吸收到了越来越多的邪能能量。现在的阿格洛诺克斯正在向他曾经保卫过的这片圣所散发腐蚀，却认为自己终于达到了理想的状态。",
},
[477] = {
["Title"] = "克雷什",
["Description"] = "这只巨龟是哀嚎洞穴的古老住民，终日在地下洞穴间游荡，他顽强的心智丝毫没有受到纳拉雷克斯无情噩梦的影响。别被他乐天的性情给骗了，克雷什已经将许多妄图偷取他巨大龟壳的冒险者打得落荒而逃。",
},
[478] = {
["Title"] = "斯卡姆",
["Description"] = "斯卡姆原本只是为了逃避贫瘠之地的恶劣环境才前往哀嚎洞穴的。与洞内的许多其它住民一样，他也很快就遭到腐化。如今在他周身流淌着黑暗能量，他已经无可挽回地变成了一只强大凶残的野兽。",
},
[479] = {
["Title"] = "瑟芬迪斯",
["Description"] = "毒牙德鲁伊的领袖曾是纳拉雷克斯最出色的学生。他的悲剧源自于他想要成为大导师，也就是“荣誉导师”的热望，想要和纳拉雷克斯比肩。疯狂在他心中生根发芽，瑟芬迪斯将他的兄弟们召集在一起，成立了这个名叫毒牙德鲁伊的组织。",
},
[480] = {
["Title"] = "永生者沃尔丹",
["Description"] = "在纳拉雷克斯来到哀嚎洞穴之前，人们对这只生物了解甚少。永生者沃尔丹被看作是洞穴的原始守护者，没能逃过降临在自己家园的腐化。沃尔丹与其他疯狂的德鲁伊结为盟友，对那些擅自闯入的不速之客保持着高度警惕。",
},
[481] = {
["Title"] = "吞噬者穆坦努斯",
["Description"] = "从纳拉雷克斯扭曲心灵最为阴暗的角落里，席卷翡翠梦境的腐化之力已体现在德鲁伊的死敌——鱼人的身上。名叫穆坦努斯的怪物来到这个清醒的世界上，吞噬任何想要将纳拉雷克斯从梦魇中解救出来的人。",
},
[482] = {
["Title"] = "水占师维蕾萨",
["Description"] = "和大部分沙怒巨魔不同，水占师维蕾萨踏遍了世界各地，搜集学识与神器，希望能够掌控祖尔法拉克的圣水。虽然水占师的行径树敌无数，但她觉得只要掌控了不可思议的力量，就能为过去犯下的累累恶行正名。",
},
[483] = {
["Title"] = "加兹瑞拉",
["Description"] = "相传，加兹瑞拉是上古之神心爱的宠物，甚至她自身就是一位半神。不论真相如何，沙怒巨魔都对这只多头蛇有着长达数千年的崇拜历史。由于对这野兽的寒冰怒火心怀惧意，巨魔们只会在祭品丰裕时才会唤醒加兹瑞拉，让它大快朵颐。",
},
[484] = {
["Title"] = "安图苏尔",
["Description"] = "安图苏尔希望自己的苏利萨斯蜥蜴们长得又壮又凶残。他对待这些周身长满鳞片的野兽如同家人一般，任何人——哪怕是巨魔，如果胆敢伤害他的宝贝孩子们，都会遭到他的无情痛击。安图苏尔不会给对手留下全尸，而是允许蜥蜴们对那些自己送上门来的倒霉蛋大快朵颐。",
},
[485] = {
["Title"] = "殉教者塞卡",
["Description"] = "许久以前，殉教者塞卡在其拉与巨魔间爆发的激烈战争中不幸殒命。由于他的英勇牺牲，祖尔法拉克仍然屹立不倒。即便是在死后，他仍警惕地守护着自己挚爱的城市，据说，那些害死他的虫人战士们都受到了诅咒，化身为无脑圣甲虫，在殉道者身边奔来跑去。",
},
[486] = {
["Title"] = "巫医祖穆拉恩",
["Description"] = "强大的守护者邦桑迪照看着暗矛巨魔的灵魂，可许多沙怒部族亡故成员的灵魂却没能得到这样的庇佑。这些饱受折磨的灵魂服从于祖穆拉恩，这是一位残忍的巫医，用黑暗魔法迫使城中的亡者无止无休地为自己效命。",
},
[487] = {
["Title"] = "耐克鲁姆和塞瑟斯",
["Description"] = "耐克鲁姆在寿命终结后，继续以不可思议的方式存活着，他日渐腐烂的身体仍能对塞瑟斯提供帮助。这两位巨魔共同为沉睡在城市中心的神秘巨兽加兹瑞拉搜罗祭品。许多巨魔追随者都迫不及待地等待着这只可怖怪物的苏醒，为了亲眼观看仪式不惜付出任何代价。",
},
[489] = {
["Title"] = "乌克兹·沙顶",
["Description"] = "乌克兹·沙顶沉迷于为自己的部族寻获往日的荣光。在他的成长过程中，早已对那些辉煌时代的传奇故事耳熟能详。那时，巨魔们在其古老的土地上称王称霸，完全没有地精、侏儒、海盗、食人魔以及其它外来入侵者的滋扰。沙顶邀请他的挚友卢兹鲁帮他一同书写沙顶历史的新篇章，用自己部族仅有的方式——追风掣电且目空一切的暴力，重振雄风。",
},
[1979] = {
["Title"] = "晋升者祖拉尔",
["Description"] = "祖拉尔的出现代表影卫终于成功制造出了头脑清醒的虚空破碎者。作为一名曾经声名远播的斗士，祖拉尔使用自己新获得的黑暗力量强化攻击，消灭敌人。",
},
[1981] = {
["Title"] = "总督奈扎尔",
["Description"] = "总督奈扎尔和他的同胞一样，沉迷于驱使虚空的力量来满足自己的野心。他受到执政团之座深处散发出的庞大黑暗力量的吸引，想要不惜一切将它据为己有。\r\n\r\n从这位督军给容器灌注暗影力量的实验来看，倘若不加以阻止，他在阿古斯所获得的战果将会非常可怕。",
},
[1983] = {
["Title"] = "瓦里玛萨斯",
["Description"] = "瓦里玛萨斯虽是在第三次大战中统帅过军团部队的恐惧魔王之一，但却没能阻止巫妖王的反叛。之后，他又不幸与希尔瓦娜斯·风行者结盟，并在可耻地失败之前最后祈求了一次力量。\r\n\r\n为了惩罚他犯下的错误，瓦里玛萨斯受到了破坏魔女巫会的折磨。这些心怀恶意的主母剥离了他的血肉和理智，只剩下了向害他失去一切的凡人复仇的欲望。",
},
[1985] = {
["Title"] = "传送门守护者哈萨贝尔",
["Description"] = "传送门守护者哈萨贝尔维护着传送枢纽，这里是燃烧军团将它的邪恶大军送往无数世界的关键。利用通向深暗领域各大战略要地的传送门，哈萨贝尔能够将军团的火力倾泻到一切敢于跟她作对的人头上。",
},
[1987] = {
["Title"] = "萨格拉斯的恶犬",
["Description"] = "灌注了烈焰和暗影的法尔格和沙图格是萨格拉斯的宝贝宠物。这些为杀戮而生的恶犬以消灭主人的敌人为乐。\r\n\r\n随着圣光军团及其盟友进抵安托鲁斯，燃烧军团已经准备好将这两头邪恶的怪物放入战场，阻止这场进攻了。",
},
[1997] = {
["Title"] = "安托兰统帅议会",
["Description"] = "早在艾瑞达文明的黄金年代，这个议会曾负责管理阿古斯的防务并维护和平。但在与萨格拉斯达成黑暗的交易后，这些战术大师用他们的军事才能组织起了燃烧的远征，并毁灭了无数世界。\r\n\r\n现在，他们掌握着燃烧军团的全部力量，并准备用这股可怕的力量消灭一切违抗黑暗泰坦意志的人。",
},
[2009] = {
["Title"] = "猎魂者伊墨纳尔",
["Description"] = "作为燃烧军团臭名昭著的走狗，伊墨纳尔能够跨越宇宙追杀猎物。在各种装置和陷阱的帮助下，伊墨纳尔从未错失一笔赏金……而他当然也不打算因为最近接下的这笔生意而毁掉自己的完美纪录。",
},
[2011] = {
["Title"] = "妖女奥露拉黛儿",
["Description"] = "只要有人看了妖女奥露拉黛儿一眼，就会被她的邪恶之力控制。她会命令受害者对其自身造成可怕的伤害。死亡将是这些奴隶逃脱的唯一希望，但在厌倦他们痛苦的哀嚎之前，奥露拉黛儿是不会给他们这个机会的。",
},
[2013] = {
["Title"] = "奥库拉鲁斯",
["Description"] = "奥库拉鲁斯以敌人的心智为食。在烧灼他们血肉的同时，他还会品味他们的绝望。这个邪恶的怪物已经吞噬了许多世界，但他的饥渴依然没有尽头。",
},
[2015] = {
["Title"] = "深渊领主维尔姆斯",
["Description"] = "即使在燃烧军团中，深渊领主维尔姆斯也以野蛮著称。他喜欢用邪能烈焰点燃敌人，然后嘲笑那些绝望地祈求一死的受害者。",
},
[2025] = {
["Title"] = "生命的缚誓者艾欧娜尔",
["Description"] = "虽然生命的缚誓者艾欧娜尔倒在了萨格拉斯的剑下，但她的精华还是逃出了黑暗泰坦的掌心。在独自躲藏了数千年后，艾欧娜尔的圣殿终于被军团发现了。\r\n\r\n如果她的灵魂落入敌人之手，艾欧娜尔的自然与生长之力就将成为燃烧的远征源源不绝的动力。",
},
[2031] = {
["Title"] = "寂灭者阿古斯",
["Description"] = "禁锢、折磨。\r\n无数纪元被痛苦充斥。\r\n支离破碎的灵魂为无尽的邪恶输送着给养。\r\n主人在召唤。来吧……站起来吧！\r\n开启万物的寂灭。",
},
[2082] = {
["Title"] = "女祭司阿伦扎",
["Description"] = "身为阿塔达萨金色圣域的狂热守护者，女祭司阿伦扎会不惜一切代价清除神庙的腐化。",
},
[523] = {
["Title"] = "死亡观察者希尔拉克",
["Description"] = "大主教玛拉达尔塑造了希尔拉克，让其负责看管在奥金尼地穴中游荡的德莱尼鬼魂。这只长有腐目利齿和触手的亡灵怪物饥肠辘辘地汲取着奥术能量，决不容忍活人从他身边经过。",
},
[2094] = {
["Title"] = "藏宝竞技场",
["Description"] = "在自由镇里有一个搏斗比赛，专供五湖四海的强盗们切磋武艺。这里鱼龙混杂各显神通，但没有人比得上现任擂主，鲨鱼拳击手。无数挑战者试图撼动他的地位，但没人能逃过被他揍扁的命运。",
},
[2098] = {
["Title"] = "杰斯·豪里斯",
["Description"] = "两面三刀的杰斯·豪里斯非常凶残。他和弟弟一起被抓进了监狱，但是一场暴动让他重获自由。从此杰斯就成了帮派里真正的掌权者，控制了下层监狱。",
},
[2102] = {
["Title"] = "天空上尉库拉格",
["Description"] = "天空上尉库拉格和他忠诚的坐骑鲨鱼饵是自由镇的守护者，他们在自由镇的上空不停巡逻，以预防入侵者。至少，这些是他们本来的任务。然而，这两个家伙却常常在自己的瞭望台里打盹，或是从天上砸些鸟粪到毫无防备的受害者身上。",
},
[527] = {
["Title"] = "巡视者加戈玛",
["Description"] = "加戈玛是外域住民心中的毒瘤，众所周知，他总是把出现在地狱火堡垒附近的倒霉蛋抓起来，吃他们的心，不管他们是不是有进入堡垒的打算。巡视者加戈玛奉卡加斯·刃拳本人的命令守卫城墙，他总是坚定不移地忠于自己的职守。",
},
[528] = {
["Title"] = "无疤者奥摩尔",
["Description"] = "无疤者奥摩尔是驯犬者哈卡的门徒，当他的主人在上古之战中落败后，他便接管了这位传奇战士剩余的地狱犬。从那时起，奥摩尔屡战屡胜，从没在哪一场对决中被打败过。这位古老的恶魔是伊利丹派往地狱火堡垒面对那些邪兽人的使者。",
},
[2114] = {
["Title"] = "艾泽洛克",
["Description"] = "地精钻取艾泽里特时打扰到了艾泽洛克，一个强大的大地之灵，它现在已经将自己的形态实体化，开始实施复仇。",
},
[530] = {
["Title"] = "塞林·火心",
["Description"] = "塞林·火心曾经有着尊贵的身份，他是凯尔萨斯·逐日者私人卫队的队长，但由于对主人太过忠心，他变得理智全无。绕室的水晶里蕴藏着恶魔能量，塞林被这股能量蛊惑，沉湎在那邪恶力量之中不能自拔。他会杀死任何胆敢接近魔导师平台的人，并从他们的尸体里汲取法力、生命和鲜血。",
},
[531] = {
["Title"] = "维萨鲁斯",
["Description"] = "维萨鲁斯是具有超强力量的奥术元素，被三个血精灵召唤到了魔导师平台，当他抵达时便杀死了他们。周围水晶中的魔法能量与维萨鲁斯体内的力量产生了共鸣，他的身体则时刻处在向外爆发混乱洪流的状态。",
},
[2126] = {
["Title"] = "魂缚巨像",
["Description"] = "魂缚巨像吞噬了众多库尔提拉斯人民，而他们被折磨的灵魂又与巨像融为了一体。饱受痛苦的哭嚎在这只怪物体内回荡，宛如丧钟般哀悼着那些胆敢阻挡巨像的蠢货们。",
},
[2130] = {
["Title"] = "孢子召唤师赞查",
["Description"] = "由于受到戈霍恩的扭曲，赞查唯一残存的意志，就是散播自己溃烂肉体内孕育的瘟疫。",
},
[2134] = {
["Title"] = "哈达尔·黑渊",
["Description"] = "哈达尔·黑渊是个远古海巨人，从深海中被召唤出来，向伯拉勒斯宣泄自己的怒火。他会使用强大的力量粉碎建筑，雕塑以及人类文明的一切。",
},
[535] = {
["Title"] = "塔瓦洛克",
["Description"] = "在凯尔萨斯·逐日者的命令下，计算者帕萨雷恩召唤出了一个强大的巨像，把流动在法力陵墓下方的奥术能量收集起来。特殊的放射物意外地将塔瓦洛克变了形，使他摆脱了帕萨雷恩的红色腐化影响。这个白色的奥术巨像获得了自由意志，并用这意志贪婪地吞噬着任何对他构成阻碍的人。",
},
[2142] = {
["Title"] = "阿德里斯和阿斯匹克斯",
["Description"] = "这对强大的蛇人奉命守卫神庙的入口，阻挡任何想要干扰他们主人计划的人。",
},
[2146] = {
["Title"] = "腐臭吞噬者",
["Description"] = "奥迪尔里面进行的实验对象包括不计其数的生物形态，其中就有数个居住在赞达拉周边森林里的洛阿神灵。这些实验夺取了洛阿神灵的生命，但它们的遗体并没有得到妥善处置，这让囚禁于奥迪尔的邪恶意志无比高兴。",
},
[538] = {
["Title"] = "德拉克中尉",
["Description"] = "德拉克中尉是一位颇有野心的军人，在第二次战争期间专注于挥斥方遒的无上荣耀。他的野心之大，只有他对绿皮肤兽人的仇恨才能与之相较，这些兽人杀死了他麾下的众多勇士，他将这份深仇大恨化作了残酷的刑罚，狠狠地加诸在敦霍尔德城堡集中营囚犯的身上。",
},
[2154] = {
["Title"] = "海贤议会",
["Description"] = "铁舟修士和唤风者菲伊用他们的力量庇佑着库尔提拉斯的船只，确保库尔提拉斯的舰队在海上所向披靡。",
},
[2158] = {
["Title"] = "不羁畸变怪",
["Description"] = "不羁畸变怪是戈霍恩腐化最纯粹的形态，它的唯一诉求就是感染所有生灵。",
},
[541] = {
["Title"] = "黑暗编织者塞斯",
["Description"] = "黑暗编织者塞斯奉利爪之王艾吉斯之命，在那些鸦人叛徒们寻找他们神秘的神灵时守卫塞泰克大厅。这位身形消瘦的诡计大师精通暗影魔法，深知如何让元素对他唯命是从。",
},
[2166] = {
["Title"] = "维克提斯",
["Description"] = "腐血之疫夺走了无数巨魔的生命，掀开了赞达拉历史上最为骇人的篇章。奥迪尔的构造体研究过这种疾病，试图寻求解决办法，但却发现唯一能做的就是隔离并消灭受害者。不幸的是，这所设施的安全防护措施已经分崩离析，而这种瘟疫意外地与一个戈霍恩之血的样本进行了融合，生成了一个渴求更多受害者的全新存在。",
},
[2170] = {
["Title"] = "部族议会",
["Description"] = "曾经没有一位帝王能一统赞达拉。经历了漫长的内战后，三大部族的首领建立了一个摇摇欲坠的联盟，以期共同执掌帝国。尽管他们时常政见不合，但赞达拉也一度迎来了短暂的和平。",
},
[544] = {
["Title"] = "赫尔默大使",
["Description"] = "赫尔默大使是一位强大的恶魔仆从和苦痛侍僧，专注于研究死亡艺术。没有什么能比凡人那混杂着恐惧与绝望的鲜血更令他着迷了。暗影迷宫中的邪兽人束缚着赫尔默，源源不断地向他喂食囚犯，支撑着这位恶魔为其主人的黑暗意志效力。",
},
[545] = {
["Title"] = "煽动者布莱卡特",
["Description"] = "当兽人部落第一次通过黑暗之门入侵艾泽拉斯时，两位暗影议会的成员却把他们的注意力投到了奥金顿这座古老的德莱尼坟场上。那些游荡在这片土地上的不安怨灵，恰好是术士布莱卡特用来完善他精神控制能力的绝佳试验品。",
},
[546] = {
["Title"] = "沃匹尔大师",
["Description"] = "在部落发展的早期，沃匹尔大师说服兽人术士古尔丹允许他调查奥金顿的秘密，然而他暗中却渴望驾驭遍布奥金顿各处强大到骇人的宇宙精华能量。",
},
[547] = {
["Title"] = "摩摩尔",
["Description"] = "“混沌初开时”、“很久很久以前”……这些辞藻都不足以说明这一元素的起源有多么久远。它的存在预示着纯粹的毁灭。只要它动一动念头，世界便会分崩离析，支离破碎。只有真正的疯子才会想要召唤它。也许现在还来得及赶在摩摩尔彻底进入外域前将它放逐。",
},
[548] = {
["Title"] = "自由的瑟雷凯斯",
["Description"] = "来自扭曲虚空的大部分生物都需要主人不断地给予指示，但少数杰出的虚空幽灵却不用主人下达这种命令。瑟雷凯斯屹立在禁魔监狱的入口处，时刻准备消灭那些胆敢挑战他的不速之客。",
},
[2194] = {
["Title"] = "拆解者米斯拉克斯",
["Description"] = "米斯拉克斯，拆解者，湮灭使者，塞塔里斯斩杀者。他的使命已经完成，便回归到主人的身边，静候新的指令。",
},
[2198] = {
["Title"] = "战争使者耶纳基兹",
["Description"] = "黑暗低语覆盖了整个斯托颂谷地，有传闻说这里遍布着可怕的生物，人们会用符文在门上刻下符咒。虽然这种说法常被认为是夸大其词，但这些家庭主妇间流传的故事远不及潜伏在黑暗中的真正恐惧。",
},
[551] = {
["Title"] = "预言者斯克瑞斯",
["Description"] = "纳鲁相信，只要将预言者斯克瑞斯关起来，并迫使他进入漫长而无梦的睡眠状态，就能让他那极具说服力的声音安静下来。然而禁魔监狱中的不幸典狱官却发现纳鲁的想法是错的。斯克瑞斯的精力太过旺盛，可以用微弱的低语轻声与监护者梅里卡尔交谈。时间会解决剩下的一切问题。",
},
[552] = {
["Title"] = "时空领主德亚",
["Description"] = "永恒之龙军团用力量做承诺，引诱了许多龙人，但大多数龙人却只得到了奴役和绝望。时空领主德亚是少数几个例外之一，他凭借自身的原始力量和狡诈，在军团中确立了属于自己的一席之地。",
},
[2210] = {
["Title"] = "食沙者克劳洛克",
["Description"] = "这头巨型爬虫曾深受所有巨魔，尤其是赞达拉巨魔的尊敬，他的骨骸散落在赞达拉大地。但黑暗能量在这片沙丘之下肆虐，本应死去的生物却再次苏醒。如今，他已被怒火和临死时的无尽苦难蒙蔽了神智，在沙漠中肆意横行，向所有生物宣泄自己的痛苦。",
},
[554] = {
["Title"] = "埃欧努斯",
["Description"] = "埃欧努斯强大凶蛮，永恒之龙军团领主命他亲自监督针对真实时间流关键时刻所采取的破坏行动。",
},
[555] = {
["Title"] = "制造者",
["Description"] = "所有利用邪恶魔法的生物，不论自愿与否，都会渐渐变成恶魔的样子。至于那些试图抵抗的人，制造者加速了他们腐化的进程，并在他们身上进行了残忍的实验。",
},
[556] = {
["Title"] = "布洛戈克",
["Description"] = "某些生物偶尔会重新考虑是否应该忠于他们堕落的新主人。布洛戈克要确保任何存在于邪兽人之间的谋逆念头都会被永久根除。",
},
[557] = {
["Title"] = "击碎者克里丹",
["Description"] = "当伊利丹推翻深渊领主玛瑟里顿的统治并夺取外域时，他将那位恶魔领袖囚禁在了地狱火堡垒的下方。只有伊利丹麾下最坚定的勇士才会希望担当看守之职，唯一有可能的人选就是凶残的兽人克里丹了。",
},
[558] = {
["Title"] = "指挥官萨拉妮丝",
["Description"] = "当堕落的血精灵领袖凯尔萨斯夺取风暴要塞的控制权后，他立刻命令指挥官萨拉妮丝部署防御力量，以抵御纳鲁有可能派来夺取要塞的任何兵力。",
},
[559] = {
["Title"] = "高级植物学家弗雷温",
["Description"] = "进入生态船不过短短几分钟，弗雷温便不顾后果地开始了他的实验，以解开潜藏在外域原生植物生命当中的神秘力量。",
},
[560] = {
["Title"] = "看管者索恩格林",
["Description"] = "资源对于实验来说是必不可少的。看管者索恩格林要确保凯尔萨斯的植物学家有他们所需要的力量和精华，来揭开纳鲁的秘密，哪怕这意味着必须牺牲无数活体生物来达到这一目的。",
},
[561] = {
["Title"] = "拉伊",
["Description"] = "纳鲁从外域各地搜集不同寻常的野生生物样本。当生态船遭到入侵时，他们的防御瓦解了，一些危险系数最高的标本获得了自由，到处游荡。",
},
[562] = {
["Title"] = "迁跃扭木",
["Description"] = "达纳苏斯的暗夜精灵们请求外界帮忙复原一棵奥术古树，它被困在了风暴要塞之中。凯尔萨斯·逐日者的军队近来发动的攻击令迁跃扭木恐惧不已，它已经失去了分辨敌友的能力，会攻击任何打扰它的人。",
},
[563] = {
["Title"] = "机械领主卡帕西图斯",
["Description"] = "必须具备极为强大的技能和精准度，才能收集纳鲁魔法晶格的力量。这些天赋可以轻易被用来对付任何入侵者。",
},
[564] = {
["Title"] = "灵术师塞比瑟蕾",
["Description"] = "塞比瑟蕾擅长快速召唤生物来摧毁任何敌人，因此她被掌管能源舰的血精灵——计算者帕萨雷恩选作了学徒。",
},
[565] = {
["Title"] = "计算者帕萨雷恩",
["Description"] = "在太阳井沦陷后，自负的秘术师帕萨雷恩看到了一个可以令自己声名远播的好机会，他决定帮助凯尔萨斯寻找让他的族人摆脱魔法依赖的良方。这一单纯的任务使他加入了身在外域的血精灵王子，并负责监管他灾难性的实验。就在不久前，帕萨雷恩开始驾驭风暴要塞的异世技术，以期让自己名利双收。",
},
[566] = {
["Title"] = "高阶术士奈瑟库斯",
["Description"] = "奈瑟库斯曾是影月氏族的萨满祭司，他放弃了对元素的崇敬，转而研习运用邪恶魔法的艺术。他所控制的恶魔能量使他仅剩下一副躯壳，唯有在折磨年轻的邪兽人时才能获得乐趣，以检验他们精神和肉体力量的极限。",
},
[568] = {
["Title"] = "战争使者沃姆罗格",
["Description"] = "凶残而狡诈的食人魔沃姆罗格被视作是邪部落最致命的成员之一。但这一人人惧怕的暴徒却也有自己的麻烦。这位食人魔颈上的双颅总会在哪怕是最简单的事情上争论不休。两年前，沃姆罗格开始了一个由十二个步骤组成的计划，从而让他好战的双重性格取得同步。但他的双颅至今还没决定好先从哪一个步骤开始实行。",
},
[569] = {
["Title"] = "酋长卡加斯·刃拳",
["Description"] = "身为碎手氏族的首领和邪部落的酋长，卡加斯是近代最伟大的兽人英雄之一。多年来，他已经割断了双手，用战争武器取而代之，这是他氏族中特有的血腥仪式。他通过对别人和自己施加痛苦而获得快感，成为了兽人中的传奇人物。作为邪部落的残暴统治者，他用自己的残暴和凶猛打造出了一支势不可挡的作战大军，就驻扎在地狱火堡垒的钢铁城墙之内。",
},
[570] = {
["Title"] = "背叛者门努",
["Description"] = "门努原本是一位破碎者，是被兽人释放出的能量扭曲变形的德莱尼。当纳迦入侵赞加沼泽时，这些不幸的生物有许多都试图逃离这一地区。门努却另辟了一条通往幸福的蹊径。为了活命，他背叛了自己的破碎者同伴，转而为这些蛇形入侵者效命，同意以奴隶监工的身份看管自己的族人。",
},
[571] = {
["Title"] = "巨钳鲁克玛尔",
["Description"] = "在德拉诺覆灭后，鲁克玛尔逃进了赞加沼泽深处。撕裂世界的能量席卷了这只巨兽，它的力量和体型都变得更大，但却要付出忍受无尽痛苦的代价。当纳迦初次来到这片区域时，他们为鲁克玛尔的凶猛而感到震惊不已。纳迦没有杀死这只野兽，而是奴役了它，用这只生物来管制赞加沼泽众多的本土生物。",
},
[572] = {
["Title"] = "夸格米拉",
["Description"] = "夸格米拉曾是赞加沼泽众多真菌巨人的统治者。他在赞加沼泽蜿蜒洞穴中游荡时被纳迦擒获，并遭受了难以忍受的折磨。现在这一饱受摧残的生物心无旁骛地效忠于自己的领主，让所有胆敢违抗瓦丝琪女士意志的人收声。",
},
[573] = {
["Title"] = "水术师瑟丝比娅",
["Description"] = "在暗夜精灵帝国的鼎盛时期，上层精灵瑟斯比娅热衷于艺术与音乐。然而她对这些事物的喜爱在大分裂期间全都消失了，她和众多族人一起被吸进了艾泽拉斯的深渊之中，变成了充满仇恨的纳迦。在那之后的数千年里，瑟斯比娅始终是她儿时玩伴瓦丝琪女士的知己密友。她毫不犹豫地与同伴前往赞加沼泽，立誓监督纳迦对该地水源补给的汲取任务。",
},
[574] = {
["Title"] = "机械师斯蒂里格",
["Description"] = "诺莫瑞根的辐射物把这座城市中的许多幸存者变成了麻风侏儒。杰出的机械师斯蒂里格就是这些受害者当中的一员。尽管他逃出了诺莫瑞根，并保留住了自己的聪明才智，但他曾经拥有的伦理观和同情心却已尽皆泯灭。他在艾泽拉斯四处游荡，将自己的知识出卖给一些厚颜无耻的组织，如血帆海盗。最近，纳迦雇用了斯蒂里格，让他负责操作赞加沼泽蒸汽地窟里的复杂机械装置。",
},
[575] = {
["Title"] = "督军卡利瑟里斯",
["Description"] = "在蒸汽地窟深处，纳迦开始用一种神秘物质进行实验，以强化他们的战士，荡除他们心中的恐惧。卡利瑟里斯是瓦丝琪的仆从之一，自愿充当这一黑暗药剂的试验品。作为奖赏，他被赋予守卫广阔蒸汽地窟的使命，确保这片区域的奥术机械设备能不受干扰的正常运行。",
},
[576] = {
["Title"] = "霍加尔芬",
["Description"] = "霍加尔芬与同伴夸格米拉不同，这一伟大的真菌巨人目前还没有沦为纳迦的奴隶。然而他始终对所有闯入赞加沼泽至深洞穴的外来者保持着极强的攻击性。霍加尔芬对纳迦在赞加沼泽其它地区实行的阴谋诡计一无所知，花费大量时间照料幽暗孢子，那是一种古老的植物，据说是他最为珍视的宝物。",
},
[577] = {
["Title"] = "加兹安",
["Description"] = "历史学家长久以来都对艾泽拉斯与外域的巨型多头蛇是否同出一源争论不休。但有一点可以确定的是，这些凶残的生物从上古时期开始就在这两块区域存在了。加兹安是外域最为恶名昭彰、可怕骇人的多头蛇。在瓦丝琪的控制下，这只贪婪的恶魔对赞加沼泽的下层发起了猛攻，以威胁当地的住民。",
},
[578] = {
["Title"] = "沼地领主穆塞雷克",
["Description"] = "身为破碎者就要接受被放逐的命运。这一真理是沼地领主穆塞雷克的心头大石。虽然他是暗血破碎者的成员，他更愿意独自在赞加沼泽下方的洞穴中游荡。在他最近一次游荡的时候，他利用自己对野兽的驾驭力迷住了唤风者克劳恩，那是一位德鲁伊，当时正以凶猛的熊形态探索那片区域。穆塞雷克强迫克劳恩充当他的忠实同伴，不会因为他被扭曲成了怪物就对他心存偏见。",
},
[579] = {
["Title"] = "黑色阔步者",
["Description"] = "外域的泥沼游荡者是徘徊在野外的高个子生物，以遇到的任何小型生物为食。在赞加沼泽的孢子人当中流传着与其中一位掠食者有关的传说，它的名字叫黑色阔步者，是个极为凶残的野兽。作为所有沼泽游荡者的巢母，据说她从幽暗沼泽深处的老巢中出来，就是为了满足自己想吃美味孢子人的口腹之欲。",
},
[580] = {
["Title"] = "纳多克斯长老",
["Description"] = "纳多克斯原本是一位倍受尊敬的蛛魔领袖，将他种族的古老传统转授给后世子嗣。当蜘蛛之战席卷艾卓-尼鲁布时，他被亡灵军团击败了。巫妖王复活了纳多克斯的尸体，将他体内一切睿智高尚的品质悉数荡除，迫使他杀死了自己的学生、好友和所有其它对抗天灾之力的蛛魔。",
},
[581] = {
["Title"] = "塔达拉姆王子",
["Description"] = "在凯尔萨斯攻击巫妖王落败后，他麾下一些最为精锐的血精灵追随者惨遭杀戮，被复活成了名为黑暗堕落者的不死怪物。塔拉达姆王子就是这些狡诈嗜杀的吸血鬼生物中的一员。为了尽心竭力地取悦巫妖王，他进入了饱受战争摧残的安卡赫特深处寻找失落的蛛魔圣物，用以强化那些凶暴的亡灵蛛魔。",
},
[582] = {
["Title"] = "耶戈达·觅影者",
["Description"] = "耶戈达梦到了天启。她相传是暮光之锤最为狂热的追随者之一。在凶残食人魔法师古加尔的指引下，她学会了扭曲自己的萨满之力以效忠上古之神。不久以前，耶戈达进入了安卡赫特深处，准备迎接光荣日的到来——届时尤格-萨隆将再次崛起，用暗影吞噬艾泽拉斯的所有土地。",
},
[2330] = {
["Title"] = "神选者教团",
["Description"] = "在达萨罗深处有一间密室，供奉着赞达拉的六位最显赫的洛阿神灵，而守护此处的是他们最虔诚的追随者。胆敢踏足这座神圣殿堂的人都将面对前所未见的原始怒火。",
},
[2334] = {
["Title"] = "大工匠梅卡托克",
["Description"] = "格尔宾·梅卡托克精巧的发明无人能敌，在联盟突袭达萨罗的战斗中起到了至关重要的作用。他操纵的机甲已经达到了登峰造极的水平，同时还配备了侏儒工程学最新，同时也是最致命的军械。",
},
[585] = {
["Title"] = "看门者克里克希尔",
["Description"] = "在巫妖王抵达前，艾卓-尼鲁布的大门牢不可破地矗立了好几个世纪。这位名叫克里克希尔的蛛魔被变成了亡灵，被迫守护着他在生前没能成功守住的这道大门，仿佛是在嘲笑他连自己的家园都保护不了。",
},
[2342] = {
["Title"] = "丰灵",
["Description"] = "很久以前，达萨大王对他的黄金珍宝间施展了魔法。除了它的主人外，任何踏足这里的人都会被它攻击。许多无谋的窃贼都死在自己垂涎的宝藏手中。他们的死正是对其他意欲窃取皇家珍宝的人的警告。",
},
[587] = {
["Title"] = "阿努巴拉克",
["Description"] = "艾卓-尼鲁布和阿努巴拉克的命运从很久以前就交织在一起了。在世时，他是帝国的国王；往生后，他成了帝国的征服者。这位叛徒国王奉巫妖王之命再次保护他的古老帝国，警惕着任何威胁他王国的人。",
},
[588] = {
["Title"] = "托尔戈",
["Description"] = "达卡莱是最为凶残的巨魔部族之一，而托尔戈又是最能够代表该部族野蛮程度的典范。但这个大块头怪物却发现与巫妖王相比，自己大肆吹嘘的暴行根本算不了什么，他现在尽心维护阿尔萨斯的统治，向任何胆敢挑战其权威的人发出可怕警告。",
},
[2354] = {
["Title"] = "艾什凡女勋爵",
["Description"] = "普里西拉·艾什凡对力量的追求 永不停歇，最终，她来到了永恒王宫，与艾萨拉女王签订了黑暗的契约。但艾什凡的忠心获得的回报或许已经超过了她最初所需要的一切。",
},
[2358] = {
["Title"] = "冈克",
["Description"] = "麦卡贡的有毒废料经过多年的累积和聚合，终于产生了恶毒的意识。现在净化系统已经失效，冈克可以随心所欲地在艾泽拉斯散播淤泥。",
},
[2362] = {
["Title"] = "奥玛斯，缚魂者",
["Description"] = "缚魂者奥玛斯想要奴役纳沙塔尔不息的幽灵。如果放任不管，它终将聚集一支亡灵大军。他们将被它的意志掌控，成为所向披靡的力量。",
},
[2366] = {
["Title"] = "恩佐斯的外壳",
["Description"] = "在尼奥罗萨的中心，耸立着一座由血肉构成的可怕高山，山上长满了眼球和触须，不羁的腐蚀在其中流动。从这团蠕动的巨物中，渗出了疯狂的实体，足以腐蚀任何胆敢靠近的人的理智。这便是黑暗帝国的心脏，恩佐斯的权力宝座，神灵的身体。",
},
[2370] = {
["Title"] = "维克修娜",
["Description"] = "维克修娜沉湎于操纵恩佐斯赋予她的力量，聚集了一大群垂涎虚空赐福的崇拜者。她的神殿位于黑暗帝国深处，她从神殿最顶端将最虔诚的追随者转化为不可阻挡的恐魔。",
},
[2374] = {
["Title"] = "伊格诺斯，重生之蚀",
["Description"] = "伊格诺斯在翡翠梦魇败退后，撤回了尼奥罗萨的深处，在此重拾力量。如今它已经和城市的建筑融为一体，像潜伏的感染一样在黑暗帝国中不断扩散。伊格诺斯的腐化血肉日渐增长的同时，它的力量也越加强盛。",
},
[2378] = {
["Title"] = "大女皇夏柯扎拉",
["Description"] = "恩佐斯觉醒后，螳螂妖女皇夏柯扎拉宣誓，她的虫群会实现上古之神的意志。为了侍奉她的黑暗主人，她向锦绣谷派出了大军，企图以恩佐斯的名义占领潘达利亚。",
},
[596] = {
["Title"] = "迦尔达拉",
["Description"] = "当天灾军团侵入祖达克时，达卡莱巨魔只得求助自己的神灵。冰巨魔并没有选择对神灵俯首乞怜，而是拿起了利刃。眼看遇害的神灵阿卡里血流成河，高阶先知迦尔达拉和他那些背弃信仰的追随者们将神灵的力量据为己有。",
},
[597] = {
["Title"] = "比亚格里将军",
["Description"] = "洛肯的钢铁大军浩浩荡荡，而比亚格里将军则是他们当中最为骁勇善战的大将。作为洛肯闪电大厅的先锋尖兵，这位铁血指挥官要确保对任何擅闯主人领地的不速之客施以极端惩罚。",
},
[598] = {
["Title"] = "沃尔坎",
["Description"] = "洛肯的强大军团是他的铁匠沃尔坎精湛技艺的绝佳证明。他的工作永无止息，不眠不休地塑造士兵为堕落的守护者作战。只有当铁匠的创造物踩在敌人破碎的尸体上时，他的工作才算告一段落。",
},
[2394] = {
["Title"] = "泥拳",
["Description"] = "泥拳出生于纳斯利亚堡脚下的淤泥地基。如今，他在大厅中漫步，随时听候德纳修斯大帝的指令。他震耳欲聋的脚步声在城堡中回响，隔着几个房间就能感知到他的到来。",
},
[2398] = {
["Title"] = "商人赛·艾柯莎",
["Description"] = "商人赛·艾柯莎是个狡猾的收购专家。她使用着数千年来收藏的各种魔法装置，依靠操纵空间获得优势，从而应对她在交易中结下的仇敌。",
},
[2402] = {
["Title"] = "唤雾者",
["Description"] = "守护塞兹仙林的不光有重装的部队，也有狡诈的妖精。喜爱玩闹的唤雾者会使用迷雾让入侵者晕头转向。由于德鲁斯特的袭击，导致唤雾者无法轻易地区分敌我，只有等你解开她的谜题，陪她做完游戏后，你才能安全地到达塞兹仙林之心。",
},
[2406] = {
["Title"] = "哈尔吉亚斯，罪污巨像",
["Description"] = "罪碑本来是过往罪责的记录，没有活性可言。堕落的温西尔却利用种种诡计，让哈尔吉亚斯从无人照管的罪碑中汲取力量，最终成长为了一尊巨大的魔像。宫务大臣的部队历经千辛万苦才控制住它，并将它的心能分摊到多个罪碑魔像的碎片上。",
},
[2410] = {
["Title"] = "穆厄扎拉",
["Description"] = "沉眠之父，时间之子，夜晚之友。远在邦桑迪做出第一个交易之前，穆厄扎拉就早已开始引领艾泽拉斯的亡者。他知道，身为神就该统治臣民，而不是祈求仆从和信徒的到来。他从远古时代开始就计划重夺权位，如今，只要他处理掉这个背叛他的替代品，他的计划就会马上实现。",
},
[2414] = {
["Title"] = "奥莱芙莉安",
["Description"] = "在忠诚圣杰的先锋里，奥莱芙莉安的火力是最强大的。在针对城市的入侵行动中，这个黑暗的巨像利用灌注了心能的炮弹，堪称所向披靡。现在，她正在热切地守护着执政官宝座前的能量之泉。",
},
[2418] = {
["Title"] = "圣物匠赛·墨克斯",
["Description"] = "并非所有纳斯利亚堡的居民都忠于德纳修斯大帝。有些人只是发现了良机，想借此大赚一笔。圣物匠赛·墨克斯一直在与德纳修斯合作，但他最关心的还是从交易中获利，而要达成交易，纳斯利亚的入侵者就必须死。",
},
[606] = {
["Title"] = "远古法庭",
["Description"] = "埃比德努、卡德拉克和玛尔纳克组成了远古法庭，它们是蕴藏着艾泽拉斯古老历史的泰坦圆盘的管理者。这些无法移动的构造体决不会轻易放弃泰坦的秘密，但像布莱恩·铜须这样勇敢的冒险者却坚信，只有高风险才能换来高回报。",
},
[2426] = {
["Title"] = "猩红议会",
["Description"] = "猩红议会主要负责维持雷文德斯宫廷的运转。作为一个一丝不苟的军事指挥官，堡主尼克劳斯具有不屈的意志力和坚不可摧的护甲。斯塔夫罗斯勋爵是位充满纨绔气息的花花公子，他负责宫廷的舞蹈事宜，但手上的双刃却锋锐而无情。芙莱达女男爵会使用强大的心能魔法，不仅号令着泥仆侍者，也令整个宫廷都拜服于她的威严。",
},
[2430] = {
["Title"] = "瓦里诺，万古之光",
["Description"] = "格里恩制作瓦里诺的目的是为了考验最强大的战士。它是个拥有卓绝力量的百心长。但是在被弃誓者夺走后，它被怀疑的种子所影响，将所有敌人都视为了挑战者。",
},
[609] = {
["Title"] = "伊克和科瑞克",
["Description"] = "身材矮小的亡灵法师科瑞克监管着萨隆矿坑中的工人。他待在可怕的伊克身上，能安全地朝敌人投掷毒药、炸弹或施放黑暗法术。他的工作还使他能够了解到冰冠堡垒中有助于推翻巫妖王统治的黑暗秘密。",
},
[2438] = {
["Title"] = "Generic Template",
["Description"] = "[PLACEHOLDER] Summary and lore for the encounter.",
},
[2442] = {
["Title"] = "典狱长之眼",
["Description"] = "在艾泽拉斯的历史早期，奥丁和穆厄扎拉做了笔交易，以自己的一只眼睛为代价窥探了暗影界。自负的奥丁其实被骗了，典狱长扭曲了这只眼睛来执行他自己的命令。这只眼睛的坚定目光帮助典狱长看到了自己国度发生的一切——也许甚至包括其他国度。",
},
[2446] = {
["Title"] = "初诞者的卫士",
["Description"] = "这个出故障的卫士是被典狱长的锁链从一个遥远的未知国度拖拽过来的，她想要保护被称为“密文”的神秘知识。任何想夺取自己谜一般创造者的秘密的人都会被她歼灭，哪怕付出自己最后残存的力量。",
},
[613] = {
["Title"] = "时光领主埃博克",
["Description"] = "永恒之龙军团通常会尝试使用精妙的手法来操纵时间流，但若是失败，他们也会派出刺客去直接“处理”阿尔萨斯。尽管人们对永恒之龙军团的刺客知之甚少，但这位埃博克却有着可怕的时间驾驭能力，使他成为了横亘在阿尔萨斯未来道路上的致命障碍。",
},
[614] = {
["Title"] = "玛尔加尼斯",
["Description"] = "玛尔加尼斯在历史中的地位已经定格了。阿尔萨斯对这名恐惧魔王的仇恨将驱使他前往诺森德，拿起霜之哀伤。但这一切的前提是玛尔加尼斯在战斗中认同阿尔萨斯的价值。为了证明自己的价值，踏上成为巫妖王的征途，阿尔萨斯必须在玛尔加尼斯的攻势下存活下来。",
},
[2458] = {
["Title"] = "警戒卫士",
["Description"] = "初诞者圣墓的入口处，永恒的卫士静静地等待着，时刻警醒地注视着入口。",
},
[616] = {
["Title"] = "噬魂者",
["Description"] = "布隆亚姆在灵魂洪炉中从事的黑暗产业可以生产出饱受折磨、支离破碎的灵魂。为了阻止这些灵魂逃走，并将这些亡魂的价值发挥到极致，巫妖王创造出了噬魂者。噬魂者会追击并吞噬那些游荡的灵魂，并将它们在自己可怕的身体里拆解。被吞噬的灵魂会因痛苦和煎熬而陷入疯狂，但噬魂者的欲望却永不满足。",
},
[617] = {
["Title"] = "指挥官斯托比德",
["Description"] = "指挥官斯托比德领导自己的军队对抗联盟最为危险的敌人。停滞大厅或许使他放慢了脚步，但是只要一看见部落冒险者，他又会立刻打起精神来，急速狂奔。",
},
[618] = {
["Title"] = "大魔导师泰蕾丝塔",
["Description"] = "相传大魔导师泰蕾丝塔是凯尔萨斯王子的导师。尽管她认为王子与纳迦结盟的做法愚不可及，她还是无法支持达拉然囚禁自己的人民。玛里苟斯只需要让她想起这一背叛，就会让她自愿给他的法师猎手充当导师。",
},
[619] = {
["Title"] = "阿诺玛鲁斯",
["Description"] = "让艾泽拉斯如此多的奥术能量流经魔枢，这在现实中造成了裂隙。当玛里苟斯的大军试图击退入侵生物时，混乱的奥术能量化成了阿诺玛鲁斯的形态。要是不及时制止这一生物，它就会毁灭自己所能触碰到的一切。",
},
[2478] = {
["Title"] = "提拉和马鲁克",
["Description"] = "尤克赫尔氏族的通灵师正在复活传奇的半人马。主母提拉和半人马最伟大的战士马鲁克都从已坟墓中复活。在他们的愤怒消减后，也许就能再度安眠……并寻得永恒的宁静。",
},
[621] = {
["Title"] = "克莉斯塔萨",
["Description"] = "克莉斯塔萨所遭受的折磨究竟是因为莎拉苟萨之死，还是因为玛利苟斯想要将其转变成自己的配偶，答案只有玛里苟斯自己才知道。不论他意图如何，她的同伴一直都听得见她痛苦的哭喊和她神智渐失所发出的不安低语声。",
},
[2486] = {
["Title"] = "原始议会",
["Description"] = "这些元素大师在追求力量时行事坚决，暴虐无道。恩巴尔·火途就像她所掌控的火焰一样残忍。乳石之牙会驱使大地之力粉碎敌人。卡德罗斯·冰怒冷酷无情，而他的同胞达瑟雅·风鞭则像肆虐的风暴一样狂野不羁，神出鬼没。",
},
[2490] = {
["Title"] = "查尔加斯，龙鳞之灾",
["Description"] = "这名老练的巨龙猎手的头衔是许多时代前获得的，是他传奇地位的象征。他号令着手下的卡拉希猎人，计划着下一次攻势，急切地等待着展现自己才干的机会。",
},
[2494] = {
["Title"] = "岩浆之牙",
["Description"] = "在掠夺奈萨鲁斯时，贾拉丁发现了奈萨里奥的许多秘密。一种试验性药水出了差错，造出了岩浆之牙，这头猛犸象巨兽一心只想着破坏与毁灭。",
},
[2498] = {
["Title"] = "格拉尼斯",
["Description"] = "整个欧恩哈拉平原都笼罩在格拉尼斯的阴影之下，他就是死亡和毁灭的预兆。在半人马氏族间的战斗席卷平原之时，格拉尼斯知道，一劳永逸地摧毁自己远古宿敌的时机已经到来。很快，他将降临战场。席卡尔氏族的炮台会蓄势待发。",
},
[2502] = {
["Title"] = "晋升者达瑟雅",
["Description"] = "铩羽而归的达瑟雅狂躁不安，她与莱萨杰丝达成协议，以求获得更强大的力量。在注入化身巨龙的一小部分力量之后，达瑟雅获得了掌控强风的能力，肆意释放烈风粉碎敌人。",
},
[2506] = {
["Title"] = "巴斯律孔，页岩之翼",
["Description"] = "巴斯律孔远比其同类要重，因此比起翱翔天际，他更喜欢在地面上生活。巴斯律孔征服了周围的环境，并将自己的技艺练得炉火纯青。他一言令下，大地只得服从，这样一来，他就能让那些妄图直面他的愚蠢之人感受大地的全部实力。",
},
[2510] = {
["Title"] = "不屈者卡金",
["Description"] = "守护者提尔破坏了提尔要塞下方的古老水源，不屈者卡金因此对他心怀恨意。一度流淌着艾泽拉斯永恒精华的河流已被秩序魔法所污染。卡金祈愿见证世界能从泰坦的邪恶遗产中解放出来……为此愿意付出任何代价。",
},
[2514] = {
["Title"] = "多拉苟萨的回响",
["Description"] = "首席教师多拉苟萨在来到艾杰斯亚学院时已经想好了一切。其中就包含了一个复杂的自我拟像，以便在群岛休眠时处理所有日常任务，并且能够胜任维护工作。现在学院已经再次开放，也许她可以用这个拟像帮助追踪所有新生。拟像在此期间表现良好，而且绝对是多年来没有退化的法术。它完美稳定，益处多多。不是吗？",
},
[2518] = {
["Title"] = "利斯卡诺兹，未来灾劫",
["Description"] = "利斯卡诺兹身负磅礴的冰雪之力，监视着拜荒者所征服的领土。所有遇到利斯卡诺兹的人都会因其存在而脊背发凉，如坠冰窟。如果对盘踞于此的恶龙放任不管，她将消灭所有胆敢踏入索德拉苏斯的人。",
},
[631] = {
["Title"] = "湮灭者祖拉玛特",
["Description"] = "达拉然派出了上百名精锐将士才制服了祖拉玛特，又出动了两倍兵力才把那杀戮场中成堆的尸体清理干净。湮灭者的狠毒甚至让疯狂的玛里苟斯都感到吃惊和犹豫，虚空领主对魔法的贪欲令他厌恶，但大屠杀却让两者臭味相投。",
},
[2526] = {
["Title"] = "永恒守护者提尔",
["Description"] = "姆诺兹多的崛起改变了正确的时间线，而艾泽拉斯的英雄们也在与许多异常的事物对峙。当中最紧迫的莫过于泰坦守护者提尔与永恒龙军团的合作。他传奇般的忠诚现在成为了英雄们的一大阻碍，除了决一死战，别无他途。",
},
[2530] = {
["Title"] = "被遗忘的实验体",
["Description"] = "龙希尔的开发经历了多次迭代，有些版本相比之下更加成功。实验的早期版本太过不稳定，甚至无法被摧毁，于是它们就在休眠中度过了上万年。现在，这些造物终于苏醒，想发挥自己力量的极限，和艾泽拉斯的勇士一较高下。",
},
[2534] = {
["Title"] = "迷时战场",
["Description"] = "联盟和部落的战斗众多，其中有一场已经渗入了时间流，现在艾泽拉斯的英雄们必须终结此时光中的这个异象才能继续旅程。但首先，英雄们会与安度因·洛萨对峙，他是联盟最伟大的指挥官之一。为了部落！",
},
[635] = {
["Title"] = "纯洁者耶德瑞克",
["Description"] = "在英雄们得以挑战黑暗大军之前，他们必须击败圣光的代言人。大领主提里奥·弗丁从银色北伐军中挑选出了一位令人敬畏的圣骑士来测试挑战者的勇气。耶德瑞克会不遗余力地剔除那些缺乏道德信念的人，将他们隔绝在冰冠堡垒之外。",
},
[636] = {
["Title"] = "银色神官帕尔崔丝",
["Description"] = "在英雄们得以挑战黑暗大军之前，他们必须击败圣光的代言人。大领主提里奥·弗丁从银色北伐军中挑选出了一位令人敬畏的牧师来测试挑战者的勇气。帕尔崔丝会竭尽所能地确保只有那些拥有坚定信念的人才有资格面对天灾军团。",
},
[637] = {
["Title"] = "黑骑士",
["Description"] = "巫妖王万分狡猾，并且善于利用策反来削弱自己的敌人。为了达到这个目的，他已经派出黑骑士去扫除大领主提里奥·弗丁军中的后起之秀。亡灵的出现亵渎了十字军演武场，那些击败他的勇士将得以证明自己的价值。",
},
[638] = {
["Title"] = "凯雷塞斯王子",
["Description"] = "巫妖王将凯雷塞斯派往乌特加德城堡，希望能够抑制维库人身上的潜在毁灭力。抵达之后，这位大使发现了一群更加渴望帮助天灾军团的人。乌特加德城堡是威胁嚎风峡湾的绝佳位置，凯雷塞斯丝毫没有将它拱手让给粗鲁入侵者的打算。",
},
[2554] = {
["Title"] = "残虐者艾姬拉",
["Description"] = "艾姬拉无比残虐，能够利用敌人的惨叫声打造摧枯拉朽的武器。在翡翠梦境这个茏葱的界域中，这个嗜虐者想进一步扩展她的军械库。",
},
[640] = {
["Title"] = "掠夺者因格瓦尔",
["Description"] = "即便是在维库人当中，因格瓦尔的残忍力量也充满了传奇色彩。相传他曾经在一场打斗中击败了伊米隆国王。真相无人知晓，但散播这个传说的人通常都无法活着将这个故事再讲一遍。因格瓦尔向巫妖王保证，自己会竭尽所能守住城堡，这是一个他不敢打破的承诺。",
},
[2562] = {
["Title"] = "休眠者奥罗斯托",
["Description"] = "奥罗斯托遵循严格的作息规律。菲莱克对翡翠梦境的攻击扰乱了他的睡眠，过早地将这位熊怪荒野之神从沉眠中唤醒。在睡眠不足的状态下，这名狂怒的荒野之神攻击着所有路过的人，想让自己因疲惫而再度入睡。",
},
[2566] = {
["Title"] = "凯里欧斯",
["Description"] = "雷卫戈伦的雷鸫虽然被虚空魔法腐化，但仍然忠诚地与戈伦并肩作战。任何妄图阻挡戈伦的不速之客，都会被凯里欧斯尽职尽责地撕成碎片。",
},
[643] = {
["Title"] = "残忍的斯卡迪",
["Description"] = "维库人往往根据个人所取得的成就来赋予绰号。肃清一条达卡莱血脉或是消灭一只牦牛人，可以获得“忠实”的称谓，但必须要足够邪恶才能被称作“残忍”。很久以前，有维库人出手保护被伊米隆定罪的畸变婴儿即人类始祖，斯卡迪残酷无情地对其展开了追杀，因此获得了“残忍”的称号。",
},
[644] = {
["Title"] = "伊米隆国王",
["Description"] = "骄傲的伊米隆统治着北部荒野，直到维库人的长眠令他的伟业不再具有举足轻重的意义。等他苏醒过来，却发现他的妻子惨遭杀害，自己的土地已被敌人重重包围。他放弃了自己凡人的身份，一心渴望复仇，迫不及待地想要向敌人展示一位苏醒巨人的可怕决心。",
},
[2582] = {
["Title"] = "虚空代言人艾里克",
["Description"] = "艾里克已被罢黜，权威尽失！他不堪失败，逃到了矶石宝库最深处的密室里。然而机关算尽的他最终屈服于异变：一件故障的神器渗出了虚空能量，并腐化了他的岩石之躯！如今，神秘的启示已经击碎了他的理智。",
},
[2586] = {
["Title"] = "酿造大师阿德里尔",
["Description"] = "阿德里尔是酒庄的招待和酿酒大师，但他会的可不止是酿酒。谁要是敢惹燧酿酒庄的新晋管理层，那就是和阿德里尔过不去，而他在底层有的是朋友。",
},
[2590] = {
["Title"] = "机械大师",
["Description"] = "机械大师只喜欢在高端的工地处理复杂的工作。布洛克和多利塔一直是队友，合作的时间长到都没人记得了。布洛克的工作效率确实是在下降，但这两位都有权通过直接而高效的暴力来捍卫自己的工地。",
},
[649] = {
["Title"] = "莱公",
["Description"] = "这个体型庞大的螳螂妖是攻击城门的开路先锋。莱公扮演着活体攻城槌的角色，无情地冲击着熊猫人的防线，妄图消灭阻挡螳螂妖凶残入侵潘达利亚的任何障碍。",
},
[2602] = {
["Title"] = "安苏雷克女王",
["Description"] = "发现宫中的叛徒之后，安苏雷克女王决定亲自铲除王宫的闯入者。但是偏执使她无法信任他人，并逐渐吞噬了她的内心。随着身边的盟友越来越少，安苏雷克女王可能会借助黑暗之力来赢取胜利，即便要让最忠心的士兵成为她下一顿的美餐也在所不惜……",
},
[654] = {
["Title"] = "武器大师哈兰",
["Description"] = "血色十字军的武器多种多样，而新兵必须学会使用剑刃、战锤、弓箭和盾牌等一系列对抗亡灵的有效工具。武器大师哈兰毕生都在钻研这些利器的挥持之道，他很愿意用十字军的宿敌来加以示范。",
},
[655] = {
["Title"] = "破坏者吉普提拉克",
["Description"] = "螳螂妖并不是战场上的门外汉，他们善于用科技扭转战局。熊猫人在吉普提拉克这样的军需专家面前几乎毫无胜算，他能从敌人阵线的大后方发起攻击，并威胁从内部瓦解本已衰弱不堪的防御工事。",
},
[656] = {
["Title"] = "织焰者孔格勒",
["Description"] = "织焰者孔格勒对那些颇具魔法天赋的血色十字军成员进行了高深的秘法训练。火焰是他的专长，他还借此烧毁了教团的历史书典，抹除了十字军过往的败绩。除了书典之外，孔格勒还用烈焰将众多宵小之辈——亡灵、差生和闯入者烧得灰飞烟灭。",
},
[657] = {
["Title"] = "雪流大师",
["Description"] = "雪流大师认识到，部落和联盟之间的战争与禅院今时今日的没落脱不了干系。英雄们如果想要让这位谨慎的大师以诚相待，就必须先击败他的得意门生。只有胜者才能得见大师本尊——穷其毕生精力以达到形神绝伦境界的武术泰斗。",
},
[658] = {
["Title"] = "刘·焰心",
["Description"] = "从幼时起，女祭司刘·焰心就开始研究青龙玉珑的重生循环。当疑之煞发起攻击时，刘是第一个奋起反抗的，也是第一个屈从于堕落的。现在她的心中充满了疑虑，怕自己再也没有力量确保玉珑的重生。",
},
[659] = {
["Title"] = "指导者寒心",
["Description"] = "课程：黑暗艺术入门\r\n\r\n指导者寒心从诺森德远道而来，对发愤图强的亡灵法师们进行训练，严惩那些令她失望的不肖徒弟。她善于驾驭北地的冰冷严寒之力，并能将通灵学院图书馆的致命威力发挥到极致。",
},
[660] = {
["Title"] = "驯犬者布兰恩",
["Description"] = "最快速且万无一失的探测亡灵的方法，就是分辨他们身上的腐烂气味，而即便是身经百战的老兵，其嗅觉也不能跟犬类相提并论。驯犬者布兰恩驯养出了一群凶残的战犬，能帮助十字军战士追猎他们的敌人——不论是活人还是亡灵。",
},
[2642] = {
["Title"] = "斯提克斯·堆渣",
["Description"] = "垃圾回收算得上是城市服务中最重要的一环了……至少斯提克斯·堆渣希望大家这么想。从人们有记忆开始，斯提克斯和他的清理团队就一直在寻求通过创新性的方式来处理城中不受欢迎和无人提及的一切。",
},
[2646] = {
["Title"] = "铬武大王加里维克斯",
["Description"] = "在“战略撤退”之后，加斯特·加里维克斯躲进了加乐宫深处的大厅里。不管加里维克斯在捣鼓什么，肯定都是强大而致命的利器，能够将任何反对者碾个粉碎。",
},
[663] = {
["Title"] = "詹迪斯·巴罗夫",
["Description"] = "课程：高级幻象\r\n\r\n巴罗夫的灵魂已在通灵学院中游荡多年，现在她正发挥出更为积极的作用——训练新生代法师。她掌握着有关幻象的广博知识，对学生而言，她是一位杰出的导师；对那些激怒她的蠢货而言，则是一位可怕的对手。",
},
[664] = {
["Title"] = "游学者石步",
["Description"] = "疑之煞的爪牙们兴致勃勃地冲进青龙寺的藏书阁，用扭曲和极富毁灭性的手段，颠覆了熊猫人英雄和其他大人物的光辉形象。尽管游学者石步已经竭尽全力，但他还是无力将这些往昔记载复原到未被玷污时的本来面目。",
},
[665] = {
["Title"] = "血骨傀儡",
["Description"] = "课程：复生导论第一章\r\n\r\n人们都以为血骨傀儡在安多哈尔被消灭了，但加丁很快就将这个狂躁的畸形巨怪复生了，并让他来阻挡入侵者。黑暗院长还设法将血骨傀儡变得更为凶残，使其贪得无厌地尽享敌人的血肉。",
},
[666] = {
["Title"] = "莉莉安·沃斯",
["Description"] = "课程：再教育\r\n\r\n亡灵莉莉安·沃斯因背叛而亲手扼死了她的父亲——血色十字军的高阶祭司，然后大举出击，最终进入了通灵学院的阴暗走廊。可黑暗院长加丁不但没有下令消灭这位入侵者，反而仁慈地指引沃斯，教她如何拥抱无情的命运。她那曾经指向学院的怒意和利刃，现在对准了加丁的敌人。",
},
[2666] = {
["Title"] = "傀儡统帅阿格曼奇",
["Description"] = "阿格曼奇毕生对长生不死的追求，使他按自己的样貌造出了魔法替身。有传闻说，他甚至使用了某种形式的黑暗魔法，当这位傀儡统帅的血肉之躯遭到毁坏时，他的新造物便能成为他灵魂的容器。",
},
[668] = {
["Title"] = "乌克乌克",
["Description"] = "即使对猢狲而言，乌克乌克也是出了名的那粗野呱噪。这个大块头近日带着他的跟班们闯进了风暴烈酒酿造厂，将珍贵的酒桶统统打破，在那里搞起了史上规模最大的派对——乌克大狂欢。",
},
[669] = {
["Title"] = "跳跳大王",
["Description"] = "跳跳大王是四风谷农夫的天敌——他是一只庞大无比的兔妖，一晚上就能吃掉整片农田的庄稼。有传言称，这只大害虫和他的儿孙们已经侵入酿酒厂，开始吞吃存放在那里的精米和大麦。",
},
[670] = {
["Title"] = "破桶而出的炎诛",
["Description"] = "为拯救家族酿酒厂，高老伯决定破釜沉舟，研制一种他心目中的终极麦酒——一种口感醇厚的浓烈饮品。他这大胆的实验却催生了一个可怕又极为暴躁的酒灵生物，被称作破桶而出的炎诛。",
},
[671] = {
["Title"] = "科洛夫修士",
["Description"] = "科洛夫修士最初是从游历艾泽拉斯的熊猫人大使身上学到的武僧神功。当这位十字军战士向他的长官展示身手时，他们一致决定命科洛夫以武僧之道训练出一代新兵。",
},
[672] = {
["Title"] = "贤者马里",
["Description"] = "德高望重的锦鱼人水语者贤者马里，已经无数次在永视泉里寻获了知识和远见。可当疑之煞将他所熟悉的现状腐化得面目全非时，马里心中充满了无限的怀疑与猜忌。",
},
[673] = {
["Title"] = "古·穿云",
["Description"] = "在煞魔逃脱前，古·穿云受托对影踪派的精英施法者进行训练。而现在，这位曾经文雅恬淡的熊猫人却醉心于放纵他那令人震惊的力量，造成了毁灭性的后果。他宣称自己已经控制了神秘的碧空翔龙，穿云的弟子们在他的致命攻击面前显得渺小无助。",
},
[674] = {
["Title"] = "大检察官怀特迈恩",
["Description"] = "萨莉·怀特迈恩在童年时期就目睹了可怕的一幕，她的家人在途经北洛丹伦时，感染了可怕的亡灵瘟疫。当他们变成了无脑天灾爪牙时，她被迫亲手杀死了双亲和弟妹，心中充满了内疚与愤怒。从那天起，只有一件事能令这位可怕的祭司感到快乐和满足——那就是消灭亡灵。",
},
[675] = {
["Title"] = "突袭者加杜卡",
["Description"] = "突袭者是螳螂妖帝国庞大军队的空中力量。在他们当中不乏老练的作战高手，如加杜卡。他能凭借一己之力用烈焰席卷地面上的敌人大军，正率领爪牙妄图从天上送城门守卫者们去见死神。",
},
[676] = {
["Title"] = "指挥官瑞魔克",
["Description"] = "指挥官瑞魔克从高处俯视着那些竭力攻门的螳螂妖地面大军。丝毫未将防御者放在眼里的瑞魔克召集了无数援军，以粉碎那些不自量力胆敢阻挡他的蠢货。",
},
[677] = {
["Title"] = "皇帝的意志",
["Description"] = "宝库的中央内室里有一群静静矗立了数个世纪的石头战士。这些战士雕像列队整齐，时刻准备迎接一场从未打响的战斗。它们守护着怎样的财宝？它们与埋藏在这暗影中的泰坦之力又有什么关联？",
},
[679] = {
["Title"] = "石头守卫",
["Description"] = "宝库的第一道防线是由一排被施了魔法的凶残雕像组成的。这些充当哨兵的石头守卫坚硬如花岗岩，不眠不休地警戒着，形成了由烈焰、毒牙和利爪筑起的难以逾越的围墙。",
},
[682] = {
["Title"] = "缚灵者戈拉亚",
["Description"] = "赞达拉巨魔的领袖对宝库发起了攻击，戈拉亚决意要掘开这蕴满古老奥秘的宝藏，将他所能找到的一切奥术能量和知识带回来。戈拉亚拥有过人的黑暗天赋，身边又有一群对他忠心耿耿的赞达拉密士，他已冲破外墙，在彻底夺取宝库之前，决不会停手。",
},
[683] = {
["Title"] = "无尽守护者",
["Description"] = "当惧之煞入侵永春台时，三位德高望重的锦鱼人守护者遭到了腐化，他们背叛了其他的凡人看守，将他们悉数杀死。这几位扭曲的守护者现在已将注意力转移，意图消灭任何胆敢妨碍煞魔粉碎当地最后一道防线的好事者。",
},
[684] = {
["Title"] = "黑暗院长加丁",
["Description"] = "课程：高阶进修\r\n\r\n近来在安多哈尔的战败，令黑暗院长加丁的心情糟糕透顶。通灵学院的全体学生最好都时刻打起十二分的精神来。要是谁敢让他们的校长不高兴，他就会被罚出教室，去实验室里干活……或是被当成实验品。",
},
[685] = {
["Title"] = "狂之煞",
["Description"] = "嗜血、凶残、野蛮的狂之煞在影踪禅院里恣意肆虐。一边汲取部落和联盟的暴虐情绪，一边兴致勃勃地腐化那些奋力抵挡攻势的武僧。",
},
[686] = {
["Title"] = "祝踏岚",
["Description"] = "恨之煞腐化了影踪派强大而务实的首领——祝踏岚。曾致力于保护自己挚爱家园的祝踏岚，如今对世间万物憎恨不已，恨之煞扭曲了他对身边所有事物——以及所有人的看法。",
},
[687] = {
["Title"] = "先王之魂",
["Description"] = "在古老的档案中记述着这些传奇统治者，他们是强大的魔古族，在潘达利亚一砖一石地建起了雄伟帝国。他们的名字至今仍能令这片土地战栗——永影之提安、暴虐之蒙恩、无情之齐昂和迅弓之速不台。有人说，他们的鬼魂还在宝库中游荡，迷失在往昔战斗与荣耀的晦暗记忆中。",
},
[688] = {
["Title"] = "裂魂者萨尔诺斯",
["Description"] = "萨尔诺斯因“净化”新兵的凶残折磨手段而在血色十字军中赢得了声望。最终，这位施虐成性的法师却染上了亡灵瘟疫，变成了恐怖的骷髅怪物。复仇心切的萨尔诺斯现在终日在修道院的墓地中徘徊，命令幽魂和僵尸攻击任何闯入他邪恶领地的不速之客。",
},
[689] = {
["Title"] = "受诅者魔封",
["Description"] = "很久以前，魔封是魔古山宝库的看守者，负责守护存放在这些暗影殿堂里的宝藏。在忠心效力多年之后，他因偷窃被抓（尽管有人说他是被心存嫉妒的下属陷害了），而魔古统治者对他施加了致命诅咒。从那以后，魔封受诅咒的灵魂就一直游荡在宝库里，与已故魔古英雄和战争领主们的鬼影谈心。",
},
[690] = {
["Title"] = "杰翰",
["Description"] = "当魔古部族正忙着争权夺利时，狡诈的杰翰带领他那令人闻风丧胆的蜥蜴人奇袭小队，进入了宫殿传说中的藏宝室。这些凶残的爬虫类生物很少会把“忠诚”二字当回事，可杰翰的胆魄和雄才伟略还是在他的部下心中激起了某种荣誉感。",
},
[691] = {
["Title"] = "怒之煞",
["Description"] = "怒气的实体形态——怒之煞，从昆莱山的影踪禅院中逃了出来。在席卷潘达利亚的激烈战争中，这个邪恶实体变得越发强大。最近，煞魔一直在昆莱地区徘徊，用负面能量腐化与其相遇的一切。",
},
[692] = {
["Title"] = "将军帕瓦拉克",
["Description"] = "将军帕瓦拉克追求实效，他对熊猫人或他们的盟友毫无畏惧，也不介意究竟是凭借自己的力量还是利用螳螂妖大军来击溃敌人。胜利是他追寻的唯一荣耀，帕瓦拉克对那些有辱使命的部下也毫不手软。",
},
[693] = {
["Title"] = "宰相金巴卡",
["Description"] = "宰相金巴卡就在螳螂妖的天然桥梁附近游荡，收集树根分泌出的宝贵汁液。利用自己掌握的广博炼金学识，这个强大的家伙会将这种物质转变为武器和其它工具，帮助推进对砮皂寺的围攻。",
},
[694] = {
["Title"] = "阿达罗格",
["Description"] = "怒焰裂谷穴居人的人数近几个月急剧下跌，原因只有一个：阿达罗格。这只贪吃的怪物是最早被黑暗萨满从火焰之地赶离的烈焰猎犬之一。阿达罗格的驯养员每天喂这只狂怒难驯的巨兽吃超出他体重两倍的穴居人肉块，以使他心平气和。",
},
[695] = {
["Title"] = "黑暗萨满柯兰萨",
["Description"] = "柯兰萨始终认为凶蛮之力是控制艾泽拉斯元素的唯一方法。正是这一极端观点使他加入了邪恶的暮光之锤。当教派衰落后，这位兽人和其它志同道合的萨满一同潜入了怒焰裂谷，继续从事他们的邪恶勾当。",
},
[696] = {
["Title"] = "焰喉",
["Description"] = "事实证明，与其它被黑暗萨满奴役的熔岩虫不同，焰喉几乎不受任何控制。这只猛兽在地下深处恣意钻掘，对其行动引发的后果毫不在意，谁要是挡了它的路也只能自认倒霉。",
},
[697] = {
["Title"] = "熔岩守卫戈多斯",
["Description"] = "在狂妄的驱使下，才华横溢的萨满戈多斯变成了汲取火焰之地力量的活体导管。他和同伴想要效仿暮光之锤创造的元素升腾者。结果，能量汇聚而引发的爆炸使戈多斯陷入疯狂，还把他的身体扭曲成了令人惨不忍睹的形态。",
},
[698] = {
["Title"] = "武器大师席恩",
["Description"] = "在艾泽拉斯，武器大师的头衔有许多种定义。对于席恩来说，这意味着魔古族所有的兵器都对他唯命是从。这位国王不吝于向任何胆敢质疑他对潘达利亚统治权的人展示他那勾魂夺命的技能。",
},
[708] = {
["Title"] = "君王的试炼",
["Description"] = "鬼谋神算冥谷子、力冠三军库乌艾和势不可挡哈伊岩携各自的部族来到了宫殿，争相向他们的君王证明自己的价值。可这些魔古族派系却遭遇了可怕的对手。暴力威胁要席卷这座宏伟的殿堂，除非这几个水火不容的部族能找到无需大动干戈即可证明其力量的方法。",
},
[709] = {
["Title"] = "惧之煞",
["Description"] = "惧之煞是潘达利亚恐惧的实体形态。很久以前被传说中的熊猫人皇帝少昊囚禁，近来却因岛上纷争四起而再次变得强大。",
},
[713] = {
["Title"] = "加拉隆",
["Description"] = "也许是时候重新考虑踩死虫子的问题了。别嘲笑这只巨兽的小翅膀，那会令他大发雷霆。",
},
[725] = {
["Title"] = "萨莱斯的兵团",
["Description"] = "残忍的蜥蜴人游荡在潘达利亚大陆上，盗取能够找到的一切，使其他住民不得安宁。在这些爬虫掠夺者当中，最为臭名昭著的便是头领萨莱斯和他麾下的兵团。多年以来，这位蜥蜴人指挥官在炮舰上率领骑兵们在四风谷中大肆横行，炮舰是一头体型庞大、装备精良的穆山兽，与其说是坐骑，它更像是一座移动堡垒。",
},
[726] = {
["Title"] = "伊拉贡",
["Description"] = "致力于发展帝国的魔古族，大肆挽救泰坦科技并使其为己所用，在这古老的复合体内生成了难以言喻的力量。至于为什么要把这些能量汇聚在一条神龙的冰冷意志之中，则是深埋在宝库深处的神秘谜团。",
},
[727] = {
["Title"] = "翼虫首领尼诺洛克",
["Description"] = "翼虫首领尼诺洛克凭借他那迅猛有力的攻击赢得了上百场战斗。在尼诺洛克看来，如果换成他领军，那么将军帕瓦拉克的小小成就跟他的大捷比起来简直不值一提。虽然他的空中攻势已经消灭了寺院的守卫，但这只长翅膀的怪物还在寻找机会，以证明自己的能力远在将军之上。",
},
[728] = {
["Title"] = "血卫士伯鲁恩",
["Description"] = "在血腥围攻沙塔斯期间，伯鲁恩对一块德莱尼圣骑士领地发起了猛攻，这些圣骑士当时将自己封锁在城市的角落里。他单枪匹马地消灭了防御者，但却身负重伤，无法跟随部落加入此后突袭艾泽拉斯的行动。现在，伯鲁恩的伤势已经痊愈，他在地狱火堡垒中为卡加斯酋长效力，希望能弥补自己错过那些辉煌战役的遗憾，并用敌人的鲜血在兽人历史上写下自己的名字。",
},
[729] = {
["Title"] = "雷施",
["Description"] = "在无数岁月里，这位友好的水灵都带着孩童般的天真与欢欣，在永春泉里嬉戏玩耍。当这片平静之地被战乱席卷时，雷施看见原本澄净如晶的水面突然变得混浊晦暗，于是她陷入了恐惧。",
},
[737] = {
["Title"] = "琥珀塑形者昂舒克",
["Description"] = "急于取悦女皇的昂舒克创造出了几种新配方。可这位才华横溢的年轻炼金师却因与螳螂妖女皇过于亲近而被煞的负面能量攫住了心智。现在，对失败的过度恐惧迫使昂舒克不断研制越发致命的武器。",
},
[738] = {
["Title"] = "指挥官沃加克",
["Description"] = "指挥官沃加克以凶猛的战斗力弥补了自己战略部署方面的不足。他的毁灭性打击在螳螂妖顺利渡桥的过程中发挥了至关重要的作用，使其得以渗入岛屿。筹谋作战计划是螳螂妖将军的事，在沃加克心中只有对鲜血的渴望。",
},
[741] = {
["Title"] = "风领主梅尔加拉克",
["Description"] = "风领主梅尔加拉克统领着螳螂妖不计其数的空中大军。尽管傲慢，这只狡诈的虫子却疯狂地保护着他的士兵，乐于与他们并肩作战。梅尔加拉克相信，螳螂妖是凌驾于所有其它种族之上的优等生物，坚信他的族群绝不会落败。",
},
[742] = {
["Title"] = "烛龙",
["Description"] = "传说有一条盘旋的金色翔龙，有时会出现在高空的云层之上，沐浴在阳光下。据个别声称亲眼看见过它的人说，这条翔龙会疯狂地保护平台。",
},
[743] = {
["Title"] = "大女皇夏柯希尔",
["Description"] = "古老的卡拉克西组织刚刚作出了一个令人遗憾的决定——必须废黜堕落的大女皇夏柯希尔。依照传统，当螳螂妖统治者年老体衰之时，会由慎重选出的继任者继承王位。但由于夏柯希尔正当壮年，远未到退位的年纪，卡拉克西别无选择，惟有处死当今女皇。如果再不尽快对她采取行动，整个潘达利亚都将在螳螂妖贪婪虫群的席卷下粉碎殆尽。",
},
[744] = {
["Title"] = "刀锋领主塔亚克",
["Description"] = "塔亚克以耐心和智慧著称。在战斗中，他善于识破对手的弱点，静待良机、一招致命。塔亚克的剑法无人能及，而他也十分乐意将自己的战斗技巧传授给年轻的螳螂妖战士。",
},
[745] = {
["Title"] = "皇家宰相佐尔洛克",
["Description"] = "佐尔洛克尖声宣布旨意，以确保让庞大螳螂妖宫殿中的各个角落都能听得见。他代表女皇的意志，而且他的言辞本身也足以激起这些螳螂妖战士的斗志，让他们心甘情愿为女皇献出生命。佐尔洛克忠心不二，任何事情都动摇不了他守护挚爱女皇的信念，即便她身陷堕落，也矢志不渝。",
},
[748] = {
["Title"] = "黑曜石哨兵",
["Description"] = "黑曜石哨兵负责守护奥达曼的秘密，直到它遭到了未知力量的腐化。这一守护者原本是由筑造奥达曼殿堂的石料制成，现在全身上下大部分都被换成了可以反射法术的黑色玻璃。不论是什么力量导致黑曜石哨兵产生了这种变化，这力量无疑都强大到了令人难以置信的地步，因为要想改变泰坦造物的魔法石料可不是件容易的事。",
},
[749] = {
["Title"] = "指挥官玛洛尔",
["Description"] = "玛洛尔与其他几位勇敢的战士们甘愿冒一切风险守护血色十字军堡垒，使其免受亡灵的亵渎。但可悲的是，他们失败了。巴纳扎尔将这名无惧的指挥官腐化成了他的仆从，使这名狂热者不得不与自己生前最憎恨的仇敌同流合污。",
},
[814] = {
["Title"] = "暴风领主纳拉克",
["Description"] = "当雷神发现了这群稀有的雷霆云端翔龙后，他颇为震惊，并试图驯服它们。其中最大的一条雏龙反抗很激烈。当雷神去兽栏查看时，墙边那一排被烤焦的魔古族引得他狂笑不止。他将那条雏龙收为己用，并为了表彰它的忠诚，雷神赐予其驾驭风暴和天空的能力。雷电之王死后的数千年以来，纳拉克一直守卫着他秘密堡垒的城墙，等待雷神的回归。",
},
[816] = {
["Title"] = "长者议会",
["Description"] = "达卡莱、法拉基、阿曼尼和古拉巴什——这些巨魔部族千万年的历史中充斥着背叛和冲突，但开创一个崭新而无可阻挡的赞达拉帝国的承诺终于将这些充满分歧的巨魔首领联合了起来。",
},
[817] = {
["Title"] = "铁穹",
["Description"] = "有关铁穹和他魁麟勇士的传说流传甚广。这位无所畏惧的魔古族将领不顾代价、铁血无情地为帝国夺取了一场又一场胜利，雷电之王因此赐予他“铁穹”的称号。",
},
[818] = {
["Title"] = "遗忘者杜鲁姆",
["Description"] = "雷神命他麾下的巫师塑造出了一个畸变体，可以窥入追随者的内心，令背叛无处遁形。杜鲁姆因此获得了生命。这个聪明的家伙偏执地遵从主人的命令，直到雷电之王陨殁后，它才消失在了要塞迷宫般的走廊里。直至不久前，几乎被魔古族遗忘的杜鲁姆终于重新走进了人们的视线。",
},
[819] = {
["Title"] = "赫利东",
["Description"] = "赞达拉将强大的生物带到了雷神岛，把它们当做战争机器。在战神贾拉克的率领下，赞达拉驭兽者当中的恐龙统领用古老的部族法术强化这些巨兽，并使它们对自己唯命是从。赫利东是贾拉克的传说坐骑，它的锐角不费吹灰之力就能将要塞的石头城墙扯成碎片。",
},
[820] = {
["Title"] = "普利莫修斯",
["Description"] = "在雷神岛的要塞深处，魔古族的血肉塑造者们用一种来源不明的神秘物质造出了蜥蜴人。当要塞被废弃后，某些实验品就一直在幽暗的池水中饱受折磨……",
},
[821] = {
["Title"] = "墨格瑞拉",
["Description"] = "即使是最为无情麻木的魔古族人，想到那些雷电之王指使的黑暗实验的时候都会不寒而栗。很久之前，一条年幼的云端翔龙被扭曲成了多头蛇，并被遗弃在了雷神的王座下。而今这个扭曲的生物潜伏在被遗忘的深渊中，等待着释放它那无尽的愤恨。",
},
[824] = {
["Title"] = "黑暗意志",
["Description"] = "雷神在统治期间不遗余力地塑造机械仆从，令其毫无畏惧地戍守要塞。在首次尝试以失败告终后，雷电之王变得怒不可遏。他将自己的负面情绪倾注在下一个——也是他最成功的造物身上，那就是黑暗意志。直到今天，这个华丽的构造体仍在尽忠职守，汇聚魔古生命改造实验精华的神秘物质使其变得无比强大。",
},
[825] = {
["Title"] = "托多斯",
["Description"] = "数千年来，不断有零星的魔古血肉塑造魔法渗入雷电之王要塞下方的洞穴之中。黑暗能量使原本生活在内室中的一只龙龟产生了变异，使其融进了周围的水晶墙体。这个由血肉与顽石化成的生物名叫托多斯，从那以后，它便以洞穴中丰富的矿藏为食，体型变得无比巨大。",
},
[826] = {
["Title"] = "乌达斯塔",
["Description"] = "随着对雷神岛堡垒的战役打响，联盟和部落的斥候就一直致力于截断几个主要的赞达拉营地间的往来通信。其中一封似乎围绕着一个未知的赞达拉语——乌达斯塔，而且总是和力量还有征服挂上钩。在潘达利亚的某处，赞达拉的驭兽者将他们的强大野兽作为战争机器来驯养，且这种被神灵之力所灌注的怪物已接近完成阶段。至于具体的地点位置，尚未知晓……",
},
[827] = {
["Title"] = "击碎者金罗克",
["Description"] = "雷电之王觉醒时，他将难以想象的力量赐予了那些最忠诚且最具野心的巨魔。狂战士金罗克是第一批接受雷神祝福的战士，虽然雷神的礼物几乎撕碎了他的身体，但这只巨魔现在已经拥有了在战斗中呼风唤雨的能力。",
},
[828] = {
["Title"] = "季鹍",
["Description"] = "魔古族的血肉塑造者们将失败的造物丢弃在雷神要塞下方的深井里。许多食腐鸟循着腐肉的恶臭来到了这个废料坑，这其中就包括巨禽季鹍。这只巨鸟凶残狡诈，将对手一个接一个地吞入腹中，直到自己成为这幽暗隧道的唯一统治者。",
},
[829] = {
["Title"] = "神女双天",
["Description"] = "神女双天是雷神最为骁勇的部下之一。雷神为了维护自己的统治，让自己最信任的勇士守护在他身边，希望用她们卓绝的武力击溃来犯之敌。",
},
[831] = {
["Title"] = "莱登",
["Description"] = "当雷神误打误撞闯入了位于现今魔古山宝库下方的大厅时，他的人生彻底发生了改变。传说他发现了远古泰坦守护者看守着一个称为纳拉克煞引擎的不可思议装置。没人知道这两者之间到底发生了什么，但雷神离开该地的时候，已经拥有了建立帝国的力量。而守护者的命运，以及他如今的下落，仍然是一个谜。",
},
[832] = {
["Title"] = "雷神",
["Description"] = "暴君、独裁者、征服者以及皇帝。雷电之王的这些称号之下映照出了潘达利亚其他种族的种种不幸。如今复活于一个魔古族不再拥有统治权的世界里，雷神已经下定决心要结束这出闹剧，并把世界再次踩于他的脚下。",
},
[833] = {
["Title"] = "指挥官库鲁尔格",
["Description"] = "指挥官库鲁尔格四处搜寻危险的宝物来充实部落的军械库。他在停滞大厅中遭遇的不幸令他愤怒不已，当他发现有联盟冒险者想要偷走他的战利品时，就会变得越发怒不可遏。",
},
[834] = {
["Title"] = "总冠军",
["Description"] = "巫妖王凶残至极，他的亡灵大军总是倾巢而出，瞬间席卷他的敌人。为了挑选足以对抗他的后备勇士，大领主提里奥·弗丁发起了勇气、忍耐力和团队协作力的试炼。他麾下经验丰富的精兵强将会淘汰掉那些缺乏勇气，无法面对铺天盖地亡灵大军的弱者。",
},
[846] = {
["Title"] = "马尔考罗克",
["Description"] = "马尔考罗克在潘达利亚的整场战役中都是加尔鲁什最为忠诚和可靠的副官。当酋长需要有人自告奋勇接受亚煞极之力的灌注时，马尔考罗克顺理成章地站了出来，没有半点犹豫。",
},
[849] = {
["Title"] = "堕落的守护者",
["Description"] = "那场毁灭性的爆炸把锦绣谷变得面目全非，身处这场灾难正中心的金莲教和影踪派的守卫者们也被黑暗能量撕得粉碎。他们的灵魂仍然徘徊在自己生前守护着的地方，为自己的无能而感到困惑和痛心。",
},
[850] = {
["Title"] = "纳兹戈林将军",
["Description"] = "纳兹戈林将军曾经是前任酋长萨尔麾下的一名步兵，在灰熊丘陵和沉没之城瓦丝琪尔取得大捷后，他便迅速得到了晋升。纳兹戈林对部落无比忠诚，严格遵循荣誉与责任的教条，他义无反顾地为酋长戍守着阵线，至死方休。",
},
[851] = {
["Title"] = "嗜血的索克",
["Description"] = "当巨兽岛在潘达利亚沿海被发现时，岛上住满了原始恐龙，加尔鲁什派部队抓了一些最为可怕的恐龙回来做样本，希望能够驾驭它们，把它们变为战争巨兽。无数想要驯服索克的兽人驯兽师都倒在了它的巨颚之下，但这头巨兽对鲜血的渴望却始终得不到满足。",
},
[852] = {
["Title"] = "伊墨苏斯",
["Description"] = "潘达利亚的古老住民意识到了能量池的重要作用，它具有赋予生命的力量，于是他们修建了地下水利系统来守护水源，并滋养着锦绣谷中的万众生灵。腐化之触驱动并扭曲了这些水源，伊墨苏斯则成为了山谷悲伤的邪恶化身。",
},
[853] = {
["Title"] = "卡拉克西英杰",
["Description"] = "这九位依然健在的卡拉克西瓦英杰是螳螂妖族群中的古老斗士，曾与唤醒者并肩作战，对抗女皇夏柯希尔的疯狂暴政。但这些英杰与其他所有螳螂妖一样，有着赤诚的拳拳之心。当加尔鲁什找到亚煞极之心时，英杰们追随着自己远古主人的低声呼唤，来到了奥格瑞玛下方的钢铁大厅。",
},
[856] = {
["Title"] = "库卡隆黑暗萨满",
["Description"] = "哈洛姆和卡德里斯训练了数千名萨满祭司，他们会虔诚地对元素发出低声呼唤，令其助自己一臂之力。然而，加尔鲁什的大军从来不会“请求”——他们只会以正统部落的名义夺走想要的东西。黑暗萨满们强迫元素对其唯命是从，把它们扭曲成了燃灭灰烬、腐化之水和剧毒空气。",
},
[857] = {
["Title"] = "朱鹤赤精",
["Description"] = "赤精发起的是希望试炼。由于自己族人的未来充满未知数，皇帝少昊请求伟大朱鹤的帮助。朱鹤向少昊提出了挑战，让他在自己的身体里寻找希望，从而抛开疑虑。当疑之煞被战胜后，皇帝变成了自己族人的希望信标。要想通过朱鹤的试炼，战士们必须坚信希望犹存，哪怕是在最黑暗的时期里。",
},
[858] = {
["Title"] = "青龙玉珑",
["Description"] = "玉珑发起的是智慧和信念的试炼。关于晦暗未来的预感在皇帝少昊的脑海中久久徘徊，于是他爬上了不息山，想要听取青龙的意见。玉珑力劝少昊抛开困扰他的负面情绪，在完成试炼后，皇帝少昊与这片土地融为了一体。要想通过青龙的试炼，战士们必须睿智地作出选择。",
},
[859] = {
["Title"] = "玄牛砮皂",
["Description"] = "砮皂发起的是勇气与坚毅的试炼。当皇帝少昊被恐惧席卷时，玄牛劝他直面自己心中的恐惧。皇帝与惧之煞展开了一场旷日持久的战斗，最后终于得胜而还。要想通过玄牛的试炼，战士们必须不屈不挠地面对压倒一切的危险。",
},
[860] = {
["Title"] = "白虎雪怒",
["Description"] = "雪怒同时发起了力量与抑制力的试炼。当雪怒给了皇帝少昊一根十尺长杆，命他攻击雪怒的一位战士时，皇帝根本无法击中目标。若是没有抑制力，愤怒和仇恨就会变得失去控制。要想通过白虎的试炼，战士们必须学会驾驭他们的力量，并压下自己暴力的念头。",
},
[861] = {
["Title"] = "野牛人火神斡耳朵斯",
["Description"] = "斡耳朵斯曾经是一名野牛人萨满祭司，但在火焰之王许下承诺之后，他便将自己献给了烈焰，以期成为一个半神。他的肉身永远被火焰烧灼，这使他陷入了无尽的痛苦之中。野牛人控火者们仪式性地将自己点燃，以效仿斡耳朵斯的成神过程，并通过施法和祈祷的方式来减轻他的痛苦。",
},
[864] = {
["Title"] = "钢铁战蝎",
["Description"] = "这只机械怪物是加尔鲁什攻城武器中的擎天柱石，威慑与毁灭是它几乎同等重要的两大用途。钢铁战蝎的原型是强大的库卡隆战蝎，它戍守着奥格瑞玛的大门，将任何胆敢挑战加尔鲁什正统部落权威的人撕成碎片。",
},
[865] = {
["Title"] = "攻城匠师黑索",
["Description"] = "赫利克斯·黑索是在加尔鲁什为正统部落寻找工程师的过程中脱颖而出的，他是唯一一位集高超的工程技术、专业性和残忍品质于一身的地精。黑索有着一颗雇佣兵的心，他对自己的创造物（以及高昂报酬）的热爱使他的命运永远地和自己的酋长兼雇主紧紧连在了一起。",
},
[866] = {
["Title"] = "诺鲁什",
["Description"] = "有人说魔古族就是依照这个巨型魔像被创造出来的，他在潘达利亚地下深处看守并保卫着这片大陆上最为黑暗和危险的秘密。",
},
[867] = {
["Title"] = "傲之煞",
["Description"] = "第七煞叫做傲之煞，是皇帝少昊难以摆脱的最后一项罪责，在它的影响下，皇帝用迷雾遮蔽了这片土地。一万年来，傲之煞一直在等待时机。当加尔鲁什唤醒亚煞极之心时，他心中的傲慢之力使得这股黑暗能量在亚煞极之心出现的房间内聚集了起来。",
},
[868] = {
["Title"] = "迦拉卡斯",
["Description"] = "督军扎伊拉和加尔鲁什在暮光高地的事件期间形成了非常亲密的关系，且她和她的龙喉兽人承诺为加尔鲁什的事业效忠。骇人的迦拉卡斯是所有龙族灾变祖先的直系后裔，扎伊拉骑在它的背上，监管着奥格瑞玛的海防力量。",
},
[869] = {
["Title"] = "加尔鲁什·地狱咆哮",
["Description"] = "当萨尔在外域遇见这位年轻的兽人时，格罗玛什·地狱咆哮之子——加尔鲁什第一次听说了他父亲的英雄事迹。骄傲的种子在他心中生根发芽。加尔鲁什作为酋长，率领部落大军在诺森德频频告捷，在大灾变的混乱中巩固了部落的力量。但他不择手段打造兽人霸权的理想，已经引得世界各路大军一路杀向奥格瑞玛……要向加尔鲁什发起最终清算，而他本人也已经做好了血战到底的准备。",
},
[870] = {
["Title"] = "潘达利亚战利品",
["Description"] = "当加尔鲁什凝视潘达利亚时，他看到了未经发掘的力量。在他领军作战的过程中，加尔鲁什掠夺了熊猫人、魔古和螳螂妖的各种武器、财宝和遗物。他将它们存放在地下基地深处的仓库里，由起源自泰坦的神秘安全系统看守。",
},
[881] = {
["Title"] = "迦拉卡斯",
["Description"] = "督军扎伊拉和加尔鲁什在暮光高地的事件期间形成了非常亲密的关系，且她和她的龙喉兽人承诺为加尔鲁什的事业效忠。骇人的迦拉卡斯是所有龙族灾变祖先的直系后裔，扎伊拉骑在它的背上，监管着奥格瑞玛的海防力量。",
},
[887] = {
["Title"] = "罗托尔",
["Description"] = "罗托尔是由戈洛克亲手制造出来的一个可怕的元素生物，它镇守在戈洛克房间的入口处，以防奴隶造反掀起暴动。这个冷酷无情的生物不眠不休地坚守在自己的岗位上，并随时准备召唤熔岩来击退入侵者。",
},
[888] = {
["Title"] = "守奴人库鲁斯托",
["Description"] = "这个残忍的食人魔工头负责监管运作这座位于霜火岭地底深处，闷热又潮湿的矿场。来自德拉诺各处的奴隶们都会被送往守奴人库鲁斯托处，在他眼里奴隶只是消耗品，一旦有越界之嫌便会毫不犹豫地毒打他们（甚至更糟），迫使其屈服。",
},
[889] = {
["Title"] = "戈洛克",
["Description"] = "戈洛克出生于悬槌堡的城中心，后来被委任为霜火岭地底深处血槌矿井的总督。刚开始他对这项任命感到很不满，但后来随着时间的流逝，他又喜欢上了这份差事。因为这里山高皇帝远，戈洛克在这拥有绝对的权力，还没什么人在自己头上指手画脚。",
},
[893] = {
["Title"] = "玛格莫拉图斯",
["Description"] = "霜火岭的食人魔地卜师以其能够自由驾驭元素的能力傲视群雄，但他们也有玩过火的时候。戈杜哈试图将其锻炉内的烈焰提升到一个新高度，并驱使玛格莫拉图斯陷入狂怒。这需要戈杜哈集中全部的注意力来控制这个狂暴的熔渣元素。",
},
[895] = {
["Title"] = "鲁古格",
["Description"] = "野猪人部族一直以来将地卜术——一种对巨石和水晶的解读——视为萨满教的最高形式。鲁古格已经为野猪人部族服务多年，默默提高自己的占卜技艺。如今，作为全体野猪人地卜师的首领，鲁古格召唤出了一大片水晶晶簇来对付卑微的对手，他和他手下的地卜师攻占南贫瘠之地只是时间问题了。",
},
[896] = {
["Title"] = "猎手布塔斯克",
["Description"] = "如果用猎物的多少来评判一位猎手实力的话，那么布塔斯克无疑是其中的佼佼者。他的狡诈和野兽般的本能使他的狩猎与追踪技巧达到了前所未有的新高度，只有强者才能有机会和这位老练的猎手一较高下。",
},
[899] = {
["Title"] = "督军拉姆塔斯",
["Description"] = "作为剃刀大军的指挥官，督军拉姆塔斯是一头魁梧的老野猪人。在与半人马、鹰身人、兽人甚至牛头人的多年战斗中，他厚实的外皮上留下了数不清的伤疤。在他的迟暮之年，拉姆塔斯又感受到了野猪人精神领袖，阿格姆和亡语者贾格巴来自灵魂国度的指引。",
},
[900] = {
["Title"] = "盲眼猎手格罗亚特",
["Description"] = "在沉寂多年后，一只巨大的怪物从黑暗的洞穴深处现出了真身。这头巨大的蝙蝠一直靠一头曾经被称为暴怒的阿迦赛罗斯的野猪提供食物，而他的粪便则为这头野猪提供了强大的黑暗力量。",
},
[901] = {
["Title"] = "卡尔加·刺肋",
["Description"] = "卡尔加·刺肋是剃刀部族的“领袖”（或者说“主母”），她在地卜术方面的造诣无人能及。她的迅速崛起和野猪人部族之间无休止的暴力冲突最终只会导致一个结局：战争。",
},
[959] = {
["Title"] = "黑手",
["Description"] = "作为黑石氏族的督军，黑手是个好勇斗狠的战士，也是个残酷无情的暴君。他在钢铁部落是仅次于格罗玛什的存在。经受着常人难以忍受的酷热高温，黑手坐镇在他的熔炉顶上统管整座铸造厂，挥舞他那覆满炽热炉渣的战锤打造出一把把神兵利器。",
},
[965] = {
["Title"] = "兰吉特",
["Description"] = "兰吉特花费了毕生心血来提高他的飞轮技巧。当他对这项传统鸦人武器的运用达到炉火纯青的地步时，他甚至能将风塑形，并用来对付敌人。他现在正把守着通往通天峰内部圣殿的入口处，并愿誓死捍卫鸦人在通天峰至高无上的权威。",
},
[966] = {
["Title"] = "阿拉卡纳斯",
["Description"] = "通天峰上的高等鸦人曾仔细观察过德莱尼文明，他们对那些用来保护城市和圣殿的强大构造体产生了浓厚兴趣。鸦人开始筹划并建造类似的版本，一台由阳光驱动的，拥有毁灭力量且绝对服从的——强能构装体。",
},
[967] = {
["Title"] = "鲁克兰",
["Description"] = "这只看上去雄壮威严的火鹰，谣传曾是鸦人敬奉的太阳神——鲁克玛的子嗣，太阳的光芒照射在阿兰卡峰林的大地上。鲁克兰对日光能量有着与生俱来的自然亲和，它能吸收并利用太阳的能量，将所有猎物烧成灰烬。",
},
[968] = {
["Title"] = "高阶贤者维里克斯",
["Description"] = "为了执行鲁克玛的意志，高阶贤者维里克斯甘愿放弃一切来试图驾驭埃匹希斯神器的力量。最终，成型的大规模水晶超级武器聚集了太阳能量消灭了敌人，现在是时候重申鸦人在德拉诺应有的统治地位了。",
},
[971] = {
["Title"] = "屠夫",
["Description"] = "这个食人魔出生于悬槌堡下恶臭的屠宰场，他或许曾有过自己的名字，但早已被人淡忘。早年的酷虐与折磨已让他失去了心智，但却使其体格得到了高度强化。现在悬槌堡没有一个食人魔敢靠得他太近，因为他的骨锯所到之处可谓血肉横飞，尸横遍野。",
},
[2051] = {
["Title"] = "PvP战场",
["Description"] = "",
},
[2083] = {
["Title"] = "莱赞",
["Description"] = "莱赞曾经是祖达萨国王们信奉的洛阿神灵，他的灵魂在一场仪式中被剥离。现在的他只剩下一具扭曲的驱壳，准备吞噬任何进入猎场的人。",
},
[2095] = {
["Title"] = "哈兰·斯威提",
["Description"] = "哈兰·斯威提是铁潮突袭队的领袖，比他的巨额财富更甚的是他的卑鄙无耻。目前斯威提由女勋爵艾什凡资助，奉她之命用尽一切手段笼络各路海盗。",
},
[2099] = {
["Title"] = "骑士队长瓦莱莉",
["Description"] = "骑士队长瓦莱莉掌管着艾什凡军械库里的易爆军火。但不幸的是，瓦莱莉对于火焰的痴迷总让下属们的工作环境变得极其恶劣。",
},
[2115] = {
["Title"] = "瑞克莎·流火",
["Description"] = "瑞克莎是一位著名的药剂师和极端的纵火狂，就是她监督风险投资公司建立了艾泽里特催化剂的供应链。",
},
[2127] = {
["Title"] = "贪食的拉尔",
["Description"] = "贪食的拉尔曾经是维克雷斯家族的主厨。如今，他的厨房成了恐怖的所在，他会切下自己身体的一部分，呈给受诅咒的客人们。",
},
[2131] = {
["Title"] = "被感染的岩喉",
["Description"] = "这只野兽遭到寄生瘟疫感染，如今它的唯一愿望就是逃离洞窟，将戈霍恩的腐化散播到整个世界。",
},
[2139] = {
["Title"] = "提赞",
["Description"] = "由于受到附近冥宫强大巫毒法术的驱动，提赞不停地在纳兹米尔沼泽中徘徊，以寻求吞噬更多的灵魂。",
},
[2143] = {
["Title"] = "米利克萨",
["Description"] = "米利克萨是禁忌实验的产物，而实验的目的是制造一整支无人能挡的野兽大军。米利克萨的子嗣破壳而出时，这位母亲开始为了她饥饿的孩子们四处猎食。",
},
[2147] = {
["Title"] = "戈霍恩",
["Description"] = "泰坦们希望在奥迪尔找到解决上古之神威胁的办法。当对其无穷无尽的腐化欲望进行实验时，他们意外地创造出一个这种欲望的完美化身。戈霍恩是纯粹的堕落、瘟疫和腐化，是终极的寄生体，他在吸干宿主之前永远不会停下。",
},
[2155] = {
["Title"] = "斯托颂勋爵",
["Description"] = "斯托颂勋爵身为家族领袖，领导着海潮贤者施行海洋祝福，奉行海洋之道。但是，这一切并不是表面上看上去那样……",
},
[2167] = {
["Title"] = "纯净圣母",
["Description"] = "奥迪尔的泰坦守护者坚韧不拔，而且立志要找到对抗上古之神的“解药”。虽然设施中的许多系统都已经失效，但各项协议依然完好无损。警告：纯净圣母不会接受被污染的个体的协助。",
},
[2171] = {
["Title"] = "殓尸者姆沁巴",
["Description"] = "赞达拉部族曾有专人殓葬并守护先王的遗骸。然而当可怕的腐血之疫席卷整个帝国时，凡人来照料亡者就变得危险重重。因此赞达拉部族召唤了魔像来进行这项恐怖的殓葬工作，这一传统也由此延续到了今天。",
},
[2195] = {
["Title"] = "重生者祖尔",
["Description"] = "祖尔曾经是赞枢利议会万人崇敬的领导者，赞达拉历代帝王的最高顾问，人们赞颂他是最伟大的预言者。如今，这个黑暗先知已经背叛了拉斯塔哈大王，想要让真正的巨魔帝国重新君临世界，就算是臣服于鲜血之神戈霍恩也在所不惜。",
},
[2199] = {
["Title"] = "蔚索斯，飞翼台风",
["Description"] = "蔚索斯是库尔提拉斯海域上的恐怖生物，掌控着狂风的力量，能将敌人连根卷起，引发海龙卷倾覆船只。他是库尔提拉斯最为凶残的野兽之一。",
},
[1122] = {
["Title"] = "兽王达玛克",
["Description"] = "作为一名年轻的兽人，达玛克以天才驯兽师的身份在雷神氏族中迅速蹿升。当其他人只着眼于野兽的本能时，他还看到了它们的智慧，并引导它们发挥出大脑、肌肉和骨骼中从未被开发的潜力。当钢铁部落要求他效劳时，达玛克将提供和训练全德拉诺最凶猛的野兽视为莫大的荣誉。",
},
[1128] = {
["Title"] = "卡加斯·刃拳",
["Description"] = "卡加斯·刃拳是碎手氏族的督军，他曾作为奴隶，在食人魔的角斗比赛中磨练出了凶猛的战斗技巧。他为了一个虚无缥缈的自由承诺杀死了无数对手，却在获胜后和其他退役的“勇士”一起被关了起来。在怒火的推动下，卡加斯斩断了自己的手逃出生天，并领导了一场让德拉诺的食人魔血流成河的大战。现在，他已经迫不及待地返回竞技场，让你见识下野蛮的真谛。",
},
[1138] = {
["Title"] = "箭火和波尔卡",
["Description"] = "铁路主管保利·箭火是恐轨车站的首席监工。他受加尔鲁什·地狱咆哮的雇佣，来为钢铁部落的基础建设建立必要的技术体系。在负责搬搬抬抬的笨蛋助手波尔卡的帮助下，箭火已经开始建设恐轨车站。",
},
[1140] = {
["Title"] = "骨喉",
["Description"] = "食腐蛆虫骨喉蛰伏在影月谷地底深处的洞穴里，它和耐奥祖的追随者们保持着一种微妙的共生关系：骨喉以影月教派黑暗仪式上那些被牺牲的祭品，作为回报它会效忠于耐奥祖，替他把守通往内部神殿的道路。",
},
[1142] = {
["Title"] = "阿鲁克斯",
["Description"] = "亡首教派的魔灵师对自己的成果非常骄傲。经过无数次失败的尝试后，他们终于为亡语者布莱克松创造出了合适的护卫。阿鲁克斯是一只巨型蜘蛛，它的身躯长满剧毒的脓疱，爆裂后能溅出可怕的毒液。现在，魔灵师们正在等待机会展示他们的造物。",
},
[1144] = {
["Title"] = "刽子手戈尔",
["Description"] = "随着阿库麦尔的力量增长，它所需的祭品也在不断增多。而刽子手戈尔最擅长的就是杀害尖叫着的无辜者。暮光之锤很好地利用了他的长处。",
},
[1146] = {
["Title"] = "亡语者布莱克松",
["Description"] = "在寒冰之王亚门纳尔被击败后，亡语者布莱克松在亡首教派内迅速蹿升。在夺得教派的绝对控制权后不久，布莱克松开始聆听到黑暗低语。这些低语承诺，如果他能令亚门纳尔重返世间，就会得到惊人的力量与财富。受强大的非自然力量驱使，布莱克松发现了亚门纳尔的护命匣的存放处。现在，返回剃刀高地的布莱克松已经准备好完成仪式，并让他的前主人再次复活。",
},
[1148] = {
["Title"] = "独眼魔双子",
["Description"] = "普尔和费莫斯是元首马尔高克的贴身侍卫，他们俩把守着悬槌堡之巅通往迦台农神殿的大门。这对食人魔兄弟虽然在智力上有所欠缺，但他们的力量和意志绝对是出类拔萃的，他们的块头和凶残程度也是无与伦比的。",
},
[1154] = {
["Title"] = "爆裂熔炉",
["Description"] = "黑石氏族的传世技艺便是熔炼黑石矿石，这是一种高密度的矿石，一般的烈焰甚至不能将其软化。黑石氏族世世代代守护着他们的独门秘籍。在铸造厂深处，他们的熔炉所蕴含的原始力量甚至和德拉诺的历史一样久远，被禁锢在其中的狂暴之力散发出令人难以置信的极热。",
},
[1160] = {
["Title"] = "耐奥祖",
["Description"] = "耐奥祖是影月氏族的酋长和萨满长者，他将整个部族的灵与肉都奉献出来，只为能加入钢铁部落。他现在隐退至氏族的远古墓地，并企图在黑暗的道路上越走越远，全身心地投入到无尽虚空和通灵邪术的怀抱中去。",
},
[1162] = {
["Title"] = "克罗莫格",
["Description"] = "玛戈隆是种迷一样的生物，古老而又神秘。为了满足钢铁部落大型造物的生产需要，矿工们夜以继日地在铸造厂进行挖掘开采工作。他们后来被一头蛰伏在密室里的玛戈隆给吓呆了，竟然还是活着的。但令他们感到惊讶的是，克罗莫格开始帮他们出力，用他那硕大的石拳锤炼出巨型铁板，为钢铁部落巨兽般的攻城机械提供原材料。",
},
[2331] = {
["Title"] = "麦卡贡国王",
["Description"] = "麦卡贡国王疯狂而聪明，他看不起一切有机生命。他的机械归源器现在已经准备完毕，没人能阻止他清除艾泽拉斯的血肉诅咒的计划了。整个世界都将被他机械化。",
},
[2335] = {
["Title"] = "拉斯塔哈大王",
["Description"] = "两百多年来，拉斯塔哈大王一直统治着赞达拉帝国。莱赞陨落后，他转投了新的洛阿神灵——死亡之神邦桑迪。他通过黑暗的交易获得了足以碾压敌人的力量……但代价是什么？",
},
[2339] = {
["Title"] = "狂犬K.U.-J.0.",
["Description"] = "地渊废料场是这个城市垃圾的储藏室，邦多的那群侏儒很喜欢来这里窃取宝贵的机械零件。垃圾主母温迪·考格斯沃在永不停歇地为城市的垃圾分类，而她忠诚的护卫犬则会赶走所有不受欢迎的入侵者，不管是机械侏儒还是冒险者都一样。",
},
[2343] = {
["Title"] = "吉安娜·普罗德摩尔",
["Description"] = "联盟舰队从达萨罗撤退的同时，吉安娜·普罗德摩尔与几只库尔提拉斯舰船一同殿后，借此拖住部落的追击步伐。天空中，乌云正在聚集，而吉安娜则要把部落追击者引入无尽之海深处，在那里，她将使用大海的力量来扭转整个战局。",
},
[2347] = {
["Title"] = "黑水巨鳗",
["Description"] = "黑水巨鳗是从无人所知的深渊被召唤而来的，它潜伏的深渊过于黑暗，即使是纳迦也不敢前往那里。只有艾萨拉才有能力驯服这只野兽，而她还将这只巨鳗训练为看守她的财宝的忠实护卫。",
},
[2351] = {
["Title"] = "奥戈佐亚",
["Description"] = "奥戈佐亚照看着艾萨拉的孵化场，期待着她孵化的恐怖生物席卷艾泽拉斯的那一天。",
},
[2355] = {
["Title"] = "HK-8型空中压制单位",
["Description"] = "HK-8型空中压制单位是天空中的掠食者，它翱翔在垃圾场上空，执行着它的首要指令：消灭所有入侵者。它的护甲坚不可摧，武器强大而致命，任何出现在它的阴影里的人都将化为尘埃。",
},
[2359] = {
["Title"] = "女王法庭",
["Description"] = "一万年来，女王法庭都成功执行着艾萨拉的指令。现在，女王最强大的仆从已经准备好执行她最终的法令了。",
},
[2363] = {
["Title"] = "维科玛拉",
["Description"] = "维科玛拉是由古代的纳迦仪式从深渊召唤而来，它再度崛起，想要在地表世界兴风作浪。",
},
[2367] = {
["Title"] = "无厌者夏德哈",
["Description"] = "无厌者夏德哈是恩佐斯最可怕的造物之一，它依靠吞噬上古之神的爪牙丢弃在它的领域中的腐化残骸为生。夏德哈被无尽的饥渴折磨着，它每进食一次，身体就会发生扭曲、变异。",
},
[1186] = {
["Title"] = "缚魂者尼娅米",
["Description"] = "尼娅米是一名德莱尼女祭司，表面上她是深受信任的慰魂者，可以自由进出奥金顿内最为神圣的区域。但实际上她是暗影议会的人，此刻的她正密谋策划关掉保护陵墓免遭侵犯的神圣护盾。",
},
[2375] = {
["Title"] = "腐蚀者恩佐斯",
["Description"] = "恩佐斯虽然被泰坦铸造的囚牢困于波涛之下，但依然在无数个纪元里不断用潜移默化的方式扩展着自己对艾泽拉斯的影响力。如今，腐蚀者恩佐斯终于挣脱了束缚，现出了真身，开始进行他的终极计划，也就是将他对黑暗帝国的愿景变为崭新的现实。如果不阻止他，我们所知的一切都会被重塑为他永恒疯狂的写照。",
},
[2387] = {
["Title"] = "艾谢朗",
["Description"] = "强大的石裔魔艾谢朗从来都对外来者，尤其是凡人不屑一顾。他从高空中俯瞰着赎罪大厅，任何人只要胆敢踏足这里，就会被他碾碎。",
},
[2391] = {
["Title"] = "收割者阿玛厄斯",
["Description"] = "阿玛厄斯从亡灵畸兽骨牙的背上俯瞰战场，监督着对尸体的收割。这个嗜虐的指挥官干掉了勇气之手，现在的目标是勇气圣杰。",
},
[2395] = {
["Title"] = "凋骨",
["Description"] = "这团名为凋骨的巨大腐肉是由外科医生缝肉所精心打造的。这只憎恶正急切地想要对勇气神庙发动攻击。",
},
[2399] = {
["Title"] = "金-塔拉",
["Description"] = "格里恩候选者只能在心能枯竭期间耐心地等候早该完成的晋升，而弃誓者则无畏地将翅膀赐予他们的信仰者。金-塔拉向黑暗的格里恩证明了自己，从而在晋升后迅速统御了天空。只要她还没有倒下，晋升高塔就属于德沃丝。",
},
[2403] = {
["Title"] = "伊库斯博士",
["Description"] = "凋零密院毁于一旦，软泥也发生了大爆发，但这一切并没有让伊库斯博士这个自以为是的天才停下脚步，他依然进行着自己那些疯狂的实验。",
},
[2407] = {
["Title"] = "卡尔将军",
["Description"] = "卡尔将军是德纳修斯大帝手下的得力干将之一，她执掌着大帝在雷文德斯的事务。她强大、敏捷、狡诈，会利用自己的能力和灌注心能的天生优势来消灭所有反对主人的对手。",
},
[2411] = {
["Title"] = "高阶裁决官阿丽兹",
["Description"] = "在赎罪大厅的深处，庭院和石像鬼的背后，有一座完全不像艾泽拉斯任何建筑的教堂。高阶裁决官阿丽兹在此管理着幽魂信众，向不值得救助的人散播着德纳修斯大帝的黑暗之语。",
},
[2415] = {
["Title"] = "执行者塔沃德",
["Description"] = "许多温西尔都认为拷问是他们的天职，提取罪孽和心能是他们的神圣使命。这个名为执行者塔沃德的生物便是一名狱卒，他会通过折磨这里的囚犯来获得病态的快感。他的存在展现出雷文德斯如今已经堕落到了何等程度。",
},
[2419] = {
["Title"] = "酤团",
["Description"] = "凋零密院陨落时所喷射出的魔药和污泥的真正性质究竟是什么？我们也许永远无从得知。但由软泥和血肉集合而成的酤团依然以狂热的方式守护着这片宝地。",
},
[2423] = {
["Title"] = "多米娜·毒刃",
["Description"] = "多米娜·毒刃相信，她可以在凋魂之殇找到一件武器，从而帮助她为锐眼密院的陨落复仇。不管是谁，甚至包括她从前的盟友，都不能阻止她从这片废墟中找出这把武器。",
},
[1214] = {
["Title"] = "枯木",
["Description"] = "在戈尔隆德繁茂的密林深处，枯木已经经历了不计其数的花开花落，生死轮回。这些个自命不凡的“钢铁部落”和奇怪物种以为是他们的天下了。可对枯木来说，他们只不过是昙花一现，早晚会成为过眼云烟，唯有枯木才会永恒。",
},
[2431] = {
["Title"] = "莫塔尼斯",
["Description"] = "莫塔尼斯是祭仪密院最博学的通灵师之一，他孜孜不倦地研究着，想发明一种办法将自己转化为更加强大的形态。现在距离他的成功只剩最后几分钟了。",
},
[2435] = {
["Title"] = "塔拉格鲁",
["Description"] = "典狱长的残暴野兽塔拉格鲁从第一座塔柱耸立之时就一直在托加斯特的大厅中游荡。无数灵魂都在这只怪兽的脚下化为了灰烬。如今，他正等待着突破塔楼入口的凡人勇士。",
},
[2439] = {
["Title"] = "九武神",
["Description"] = "希尔瓦娜斯和瓦格里达成了黑暗交易，借由此，希尔瓦娜斯铸就了和典狱长之间的纽带。多年来，这群飞翼姐妹忠诚地侍奉着黑暗女王，即使为了女王牺牲自己也在所不惜。现在，希尔瓦娜斯召唤她的九位瓦格里，这是她们最后一次为她而战。",
},
[2443] = {
["Title"] = "痛楚工匠莱兹纳尔",
["Description"] = "痛楚工匠莱兹纳尔是个嗜虐的操纵大师，他花了永恒的纪元来完善托加斯特的致命陷阱。他热衷于聆听受害者的尖叫，以此作为自己技艺的明证。他沉醉于恶毒的快乐之时，这些尖叫依然回响在塔楼荒寂的大厅中。",
},
[2447] = {
["Title"] = "命运撰写师罗-卡洛",
["Description"] = "罗-卡洛曾经是一名命运撰写师，刻希亚的无数秘密都由他保管。渊誓者抓住了他，并将他与典狱长的意志绑在了一起。罗-卡洛现在可以随意支配托加斯特的力量，从而为暗影界撰写全新的命运。",
},
[2451] = {
["Title"] = "索·阿兹密",
["Description"] = "在仗剑谋生的掮灵之中，索·阿兹密的技艺无出其右。索·阿兹密是索财团最为致命的刺客，他对技艺的磨练永无止境。他很乐意就对手的武艺指点一二，随后将其大卸八块。",
},
[2455] = {
["Title"] = "索·莉亚",
["Description"] = "索·莉亚对力量的贪图在最终的战斗中显露无遗漏。财团领袖释放出了自己无法理解的力量，变化成了无拘无束的残暴生物。狂暴的能量从神器中溢流而出，必须阻止索·莉亚，不能让她摧毁暗影界的根基。",
},
[2459] = {
["Title"] = "道茜歌妮，堕落先知",
["Description"] = "道茜歌妮被典狱长统御后，率领渊誓者作战，夺取了冥世锻炉的控制权。典狱长计划用冥世锻炉的力量，来让现实世界中的一切都遭受永恒的折磨。",
},
[2463] = {
["Title"] = "回收者黑伦度斯",
["Description"] = "无数纪元来，黑伦度斯一直穿行于初诞者圣墓的悬崖之间，履行着自己神圣的使命：回收幻磷，让它重归伟大的轮回。现在，入侵者让这条法则陷入了混乱，这名远古的守护者会使出浑身解数来维系秩序。",
},
[2467] = {
["Title"] = "莱葛隆",
["Description"] = "莱葛隆被初诞者圣墓发生的重大事件所吸引，前来进行观察，却屈服于佐瓦尔的统御之力。现在这名星圣会用自己的宇宙之力来对抗任何胆敢反对被流放者的人。",
},
[2471] = {
["Title"] = "劈爪的战团",
["Description"] = "莉拉·劈爪和她的同胞伤齿和狡诈图腾组成了一个致命的战团，从蕨皮豺狼人当中一跃而起。他们的战术使得海象人从不独自旅行，他们的力量使得怒眼让他们看守山谷大门。",
},
[2475] = {
["Title"] = "失落的矮人",
["Description"] = "对远古知识、神秘财宝以及举世威名的追求驱使埃瑞克、奥拉夫和巴尔洛戈再次深入奥达曼。但这些无所顾忌的冒险者可能在地下呆得太久了，以至于感官已经错乱，无法分清谁是朋友……谁是敌人。",
},
[2479] = {
["Title"] = "时空领主戴欧斯",
["Description"] = "巨龙女王想恢复守护巨龙的力量，但龙族里有些成员并不希望阿莱克丝塔萨的计划成功。时空领主戴欧斯企图让他的军团控制时间流，并引领那位真正的守护巨龙的到来，而他的统治将会是……永恒的。",
},
[2483] = {
["Title"] = "泰拉什·灰翼",
["Description"] = "泰拉什·灰翼对蓝龙军团怒意难平，决心找到辛达苟萨藏在碧蓝魔馆的秘密。他与碎裂之焰合作，确信自己会发现更多关于龙希尔起源的历史……以及足以证明蓝龙军团的罪状的证据。",
},
[2487] = {
["Title"] = "布罗马奇",
["Description"] = "壮实的布罗马奇是石窟穴居人的酋长，这一族相信奥达曼的财宝属于他们。布罗马奇对于矮人的搅局特别不快，同时他也决心阻止任何外来者的闯入。",
},
[2491] = {
["Title"] = "库洛格·恐怖图腾",
["Description"] = "库洛格曾是玛加萨·恐怖图腾的得意弟子，这位原始元素大师如今正在准备释放他最具毁灭性的造物。如果不加以阻止，他的风暴、火焰、寒冰和大地生物将为整个艾泽拉斯带来浩劫。",
},
[2495] = {
["Title"] = "克罗兹",
["Description"] = "利旭莱斯竞技场又称“龙爪球场”，近些日子一直有鸟类盘踞于此。克罗兹已经入住体育场的中心，目前并没有搬离的打算。 看看我们能不能让她陪着一起踢球……然后让她离开吧。",
},
[2499] = {
["Title"] = "莱萨杰丝，噬雷之龙",
["Description"] = "莱萨杰丝深信龙族应该像风暴一样狂野自由。如果她能顺利地从远古囚笼中解救化身巨龙同伴，莱萨杰丝及其亲眷便会推翻守护巨龙的统治，并将抹除泰坦在世界上留下的一切痕迹。",
},
[2503] = {
["Title"] = "基拉卡与厄克哈特·风脉",
["Description"] = "基拉卡和厄克哈特在红玉新生法池的上空游荡，会对下方神殿发动协同攻击，同时也会消灭任何试图干扰的巨龙。如果不加以控制，他们会将新生法池烧成灰烬，并在净化元素的风暴中吹走剩余的所有灰烬。",
},
[2507] = {
["Title"] = "吞喉巨蛙",
["Description"] = "吞喉巨蛙潜伏在注能大厅深处的洞穴之中。这只巨蛙是一代代龙蛙的先祖，和其子嗣在未经处理的水源中繁衍生息。饥肠辘辘的它会贪婪地吞噬任何靠近巢穴的生物。",
},
[2511] = {
["Title"] = "原始海啸",
["Description"] = "注能者萨莉亚一心想引导世界回归本来面目：原始而充盈着不羁元素之力。她用尽全部意志和智慧召唤了原始海啸，这只元素生物力大无比，足以倾覆守护者提尔的设施，使此处的水源恢复自然状态。",
},
[2515] = {
["Title"] = "斯图恩兰，苍天苦难",
["Description"] = "众所周知，天空因斯图恩兰的出现而哭泣。他的风暴令空气通电，在大地上肆意横行。斯图恩兰对欧恩哈拉平原产生了极大威胁，使平原上的土地和人民饱受狂风之苦。",
},
[2519] = {
["Title"] = "火光之龙菲莱克",
["Description"] = "菲莱克吞噬了暗影烈焰，挥舞着传说利斧“菲莱拉兹，梦境之瞑”。他已经做好万全准备，即将把阿梅达希尔的能量据为己有。",
},
[1262] = {
["Title"] = "鲁克玛",
["Description"] = "鲁克玛偶尔会以一只炽燃火鹰的形象出现在阿兰卡峰林的上空。尽管鲁克玛被鸦人们看作是太阳的化身而被奉若神明，但没有人知道这只大鸟究竟从何而来。",
},
[2527] = {
["Title"] = "玛格莫莱克斯",
["Description"] = "玛格莫莱克斯是奈萨里奥从幼崽开始一点一点养大的。唯一能超越它的忠诚的，便是它的胃口。这只熔岩多头蛇守护着通向焰影熔炉最深处密室的通路。它会保护主人的秘密，消灭任何胆敢前来窥探的蠢材。",
},
[2531] = {
["Title"] = "扎卡利长老",
["Description"] = "强大的贾拉丁长老瓦坎和苟尔娜是掌控对应元素的大师。苟尔娜能随心所欲地挥舞熔岩，瓦坎则对暗影烈焰如臂使指。为了决出更强大的一方，他们卷入了难以平息的争斗。长老们企图通过毁灭与混乱摧毁彼此，只有一人能够笑到最后。",
},
[2535] = {
["Title"] = "迦拉克隆之荒",
["Description"] = "这些原始之龙被迦拉克隆尸体上渗出的死灵魔法所复活。昂佐恩是霹雳风暴的饥渴。达扎克是吞噬万物的烈焰的贪婪。洛斯凯勒兹是寒冰下冻结的饥荒。而艾泽拉斯的英雄们看起来正像是他们的一顿美餐……",
},
[2555] = {
["Title"] = "梦境议会",
["Description"] = "梦境议会坚定不移地履行着护卫的职责。匹普使用致命的幻术来欺骗敌人；乌克托斯依靠蛮力来摧垮敌人；艾尔雯用智慧和手段来统御战场，指引其他议会成员。",
},
[2559] = {
["Title"] = "布雷炙孔",
["Description"] = "活化的烈焰渴望燃料，布雷炙孔怀着满腔的怨念和愤怒，烈焰在暗焰裂口恒燃不灭。忠诚的狗头人信徒在这里祭拜供奉，因为他的燎火王国已经被可怕的黑暗所包围。为了满足这个怪物的饥渴，狂热的狗头人会很乐意献上祭品……也就是你。",
},
[2563] = {
["Title"] = "斯莫德隆",
["Description"] = "身为新任炎魔领主，斯莫德隆让火焰之地的力量倾泻而出，意图扩张疆域，将翡翠梦境焚烧殆尽。",
},
[2567] = {
["Title"] = "雷卫戈伦",
["Description"] = "雷卫戈伦曾是风暴护持贝尔格里姆的副手，如今已被虚空魔法所腐化，让他对贝尔格里姆更加恨之入骨。凭借自己新获得的虚空之力，他企图占领风暴之栖，号令由堕落的驭雷者组成的驭虚者大军。",
},
[2571] = {
["Title"] = "戴尔克莱上尉",
["Description"] = "戴尔克莱上尉掌管着圣焰隐修院的训练场。他以帝国认可的练武教条教化侍僧们，并确保他们的武艺和忠诚都能达到帝国标准。",
},
[2579] = {
["Title"] = "斯卡莫拉克",
["Description"] = "在无数个年月中，高阶代言人一直试图修复觉醒主机。而一次失败孕育出了新的恐魔：一个注入了斯卡丁腐蚀的魔像。水晶增强了它的元素构造。虽然无法传达出格格不入的思维，但它对万千生灵的憎恨溢于言表。",
},
[2583] = {
["Title"] = "阿瓦诺克斯",
["Description"] = "当艾拉-卡拉毁灭时，这个名为阿瓦诺克斯的生物也被遗弃了，当时她还只是一只不起眼的蜘蛛。多年以来，她与世隔绝，在一片适合进食的地区自由地生长，用无与伦比的体格和凶悍监管着自己的子嗣、信众和领地。",
},
[2587] = {
["Title"] = "艾帕",
["Description"] = "作为工业事故的产物，蜜酒元素艾帕对自己的存在感到愤怒，就和对酒庄本身受到干扰燃起的怒火一样旺盛。艾帕是燧酿浓厚、劲烈特性的充分体现，任何胆敢纠缠的家伙都会拜倒在它面前。",
},
[2595] = {
["Title"] = "女王之牙",
["Description"] = "孪生双胞恩克斯和维克斯一起出生，一起长大，一起接受了诡计和奇袭的训练。这对致命的双子也一起获得了扬升。他们成为了女王之牙，并乐于消灭任何威胁安苏雷克统治的敌人。",
},
[2599] = {
["Title"] = "苏雷吉队长席克兰",
["Description"] = "席克兰成为了安苏雷克女王宫廷中一位傲慢的决斗者。他从未知晓对手的剑刃有多锋利，因为他总能一个接一个地把他们解决，故而女王亲自授予他苏雷吉队长的头衔。这位不服输的斗士会确保任何威胁到安苏雷克女王的家伙都倒在王座跟前。",
},
[2607] = {
["Title"] = "噬灭者乌格拉克斯",
["Description"] = "安苏雷克女王的进化实验创造了许多骇人的守卫来守护她的王座，而其中最为贪婪的就是噬灭者乌格拉克斯。乌格拉克斯因为无尽的饥饿而癫狂，成为了安苏雷克女王宫中最欲壑难填的守护者。",
},
[2611] = {
["Title"] = "血缚恐魔",
["Description"] = "在尼鲁巴尔王宫下方黑暗的深坑里，上古之神的血液凝结成了肮脏的黑色血池。血缚恐魔从这片邪恶的淤泥中现身——将遇到的一切拖入无明界。",
},
[2619] = {
["Title"] = "埃鲁达克，地狱公爵",
["Description"] = "死亡之翼派出了他最厉害的副手之一，旨在探寻强大的红龙牺牲性命也要保住的秘密。这名无面者将军来自深岩之洲的洞穴世界，任何敢于向他发起挑战的蠢货，都会被其体内融合的新生代龙族之力所消灭。",
},
[2623] = {
["Title"] = "赫利克斯·破甲",
["Description"] = "赫利克斯从前是锈水财阀的工匠，可之后他收到了迪菲亚兄弟会的一笔款项，足以让他那样的无名部落工程师所做的一切都一文不值。就像所有精明的地精会做的那样，他迅速接下了这份工作，声称不再对前任雇主效忠。",
},
[2627] = {
["Title"] = "铸炉之主索朗格斯",
["Description"] = "这名巨大的双头魔是暮光之锤教派的匠人，他热衷于用自己所铸造的武器和铠甲，消灭那些入侵者。",
},
[2631] = {
["Title"] = "艾德温·范克里夫",
["Description"] = "范克里夫原本是石工协会的领袖，在与贵族产生纠纷后毅然离开了暴风城，成立了迪菲亚兄弟会。范克里夫随后夺取了死亡矿井，将这里作为行动基地，开始建造用于复仇大业的无畏舰。",
},
[2635] = {
["Title"] = "惊魂聚合体",
["Description"] = "虚空侵染的斯卡丁残骸融聚一处，孕育出了惊魂聚合体。这个可怕的畸形怪物正准备让自己的瘟疫席卷整个喧鸣深窟。",
},
[2639] = {
["Title"] = "维克茜和磨轮",
["Description"] = "维克茜·满油已经在磨轮帮遭遇的每个人心里留下了恐惧的阴影。她和她的手下为了报一个旧情，甘心协助加里维克斯，给安德麦的街道上增添了新的油污。",
},
[2651] = {
["Title"] = "吉泽尔·超震",
["Description"] = "在水能堡大坝的核心地带，电气大师吉泽尔·超震正在为“工程项目”汲取能量。若是吉泽尔走投无路、加里维克斯的密谋濒临终结，他就会将这股能量导向安德麦……还有他自己！",
},
[2663] = {
["Title"] = "洛考尔",
["Description"] = "洛考尔对火元素诡计多端、尔虞我诈的本性感到深恶痛绝。为了能远离在熔火之心中效力的其它同类，这个强大的生物故意惹得炎魔之王大发雷霆。洛考尔为自己的危险之举付出了代价——他被逐出了熔火之心，被迫孤绝地守卫黑石深渊。",
},
[2667] = {
["Title"] = "黑铁七贤",
["Description"] = "几个世纪以前，巫王索瑞森和他麾下七位最强大的黑铁同伴误打误撞地将拉格纳罗斯召唤进了艾泽拉斯，并致使自己的整个部族都惨遭奴役。尽管七贤在仪式中死亡，但他们不得安息的灵魂却一直在黑石深渊徘徊，被迫为自己的元素主人和现在的黑铁统治者效命。",
},
[2675] = {
["Title"] = "阿兹希卡",
["Description"] = "吞噬者通常会跟随大吞噬者蠕虫的痕迹，前往新的界域大快朵颐。阿兹希卡也不例外。它一路掘进来到了新的土地，一心只想着满足那无法平息的饥渴。阿兹希卡有时甚至会以其他吞噬者为食，但吞噬者们依然会响应它的召唤——在无尽饥渴的螺旋之中，要么大口吞噬他人，要么成为腹中美餐。",
},
[2683] = {
["Title"] = "地精教父",
["Description"] = "地精教父曾经在破拆穹顶中风光无限，成为了锈水财阀的自豪之源。这无疑是地精创造力的巅峰之作……直到有人忘了给它换油。破拆穹顶的王者如今陷入了错乱，横冲直撞的它即将为安德麦的居民带去一场浩劫。",
},
[2687] = {
["Title"] = "熔炉编织者阿拉兹",
["Description"] = "熔炉编织者阿拉兹掌控着法力熔炉：欧米伽内的所有运作，确保能量源源不断地流入其中央核心。他如今成为了迪门修斯重生的首位见证者，并将不惜一切代价完成自己的使命。",
},
[2691] = {
["Title"] = "诸界吞噬者迪门修斯",
["Description"] = "在法力熔炉：欧米伽的深处，迪门修斯——诸界的吞噬者，卡雷什的毁灭者——正在缓缓苏醒。虔诚的虚灵追随者正利用黑暗之心为他提供给养。若是让他们得逞，这个具有无上力量的存在就会降临世间，现实世界的一切都将难逃覆灭。",
},
[1372] = {
["Title"] = "血魔",
["Description"] = "落入神圣陵墓奥金顿核心的暗影议会副官塔隆戈尔吞噬了上百个德莱尼的灵魂，变成了一头臃肿的畸形怪物。如今塔隆戈尔的外表早已无法再被称为兽人，他已抛弃旧名，给自己起了一个新名字：血魔。",
},
[2747] = {
["Title"] = "弗兰克提鲁斯",
["Description"] = "法力熔炉周围的峭壁与沙丘孕育出了一个元素。这片险恶的废土上不乏蚀骨的飞沙和坚硬的琉璃，它们成为了弗兰克提鲁斯守护疆土的力量。",
},
[1392] = {
["Title"] = "考莫克",
["Description"] = "与德拉诺一样古老的考莫克曾是戈尔隆德的统治者，这只巨型玛戈隆毁灭性的怒火足以令这片土地上的生物退避三舍。但在钢铁部落到来之后，就捉住了这只巨兽并试图打垮他的意志。他们完全失败了……直到古尔丹执掌大权时——考莫克完全无法抵抗邪能的力量。",
},
[1394] = {
["Title"] = "暴君维哈里",
["Description"] = "在古尔丹带来送给萨格雷的“礼物”后，维哈里就表现出了极大的野心，并在组织中迅速蹿升。被敌人称为“暴君”的她是最先接受邪能之触的萨格雷之一，这进一步强化了她的战斗力。如今，维哈里身负着嘲弄纳鲁的圣徽，以表达她对新教派的坚定信仰。",
},
[1396] = {
["Title"] = "基尔罗格·死眼",
["Description"] = "血环氏族督军基尔罗格·死眼在经历过预见自身死亡的仪式后就掌握了自己的氏族。在认清自己的命运后，他无所畏惧地带领着氏族历经无数战役，向着他所渴望的荣耀之死进发。现在，血管中流淌着恶魔之血的基尔罗格正在地狱火堡垒中等着你，准备迎接自己——或者你的末日。",
},
[89] = {
["Title"] = "格拉布托克",
["Description"] = "只是一阵心血来潮，格拉布托克就释放出强大的魔法力量，把他的食人魔山给夷为了平地。听到这个消息，迪菲亚立刻雇佣了这只硕大的食人魔法师作为死亡矿井的工头，借助他毁灭性的天赋来监督那些劳工。",
},
[1426] = {
["Title"] = "奇袭地狱火",
["Description"] = "在黑索公司的佣兵帮助下，钢铁部落在地狱火堡垒的脚下建造了毁灭性的攻城器械，并计划在总攻艾泽拉斯的主城时使用它们。在将坦克改装为使用邪能之后，攻城大师玛塔克只等古尔丹一声令下，就能发动攻击。",
},
[1432] = {
["Title"] = "高阶地狱火议会",
["Description"] = "数千名钢铁部落的兽人喝下了玛诺洛斯的鲜血，但只有很少数能像这三位勇士一样变得如此强大。作为虚空魔法的大师，影月氏族的流亡者，迪亚·暗语迅速展露头角，成为古尔丹的左膀右臂。古尔图格是一个永不满足的嗜血屠夫，身经百战未尝一败，只有剑圣朱倍尔索斯曾与他战成过平手。在被邪能腐蚀后，他们成为了古尔丹的亲卫和战争议会成员。",
},
[1438] = {
["Title"] = "阿克蒙德",
["Description"] = "污染者阿克蒙德是最早背叛阿古斯德莱尼的艾瑞达之一，如今他已经成为黑暗泰坦萨格拉斯的左膀右臂，指挥着燃烧军团的大军。他跨越了时间与空间降临德拉诺，以确保入侵艾泽拉斯的计划如期展开，同时防止古尔丹令他的军团主子们失望。",
},
[1452] = {
["Title"] = "霸主卡扎克",
["Description"] = "霸主卡扎克再次从扭曲虚空现身，代表燃烧军团监督古尔丹的行动。他就站在塔纳安丛林的腐化中心——基尔加丹王座附近。",
},
[91] = {
["Title"] = "死神5000",
["Description"] = "迪菲亚的工程师们在死神4000的基础上，日以继夜地想要完善出一种新型号的收割机。兄弟会相信，只要完工，这台恐怖的机械就能像割麦子一样从暴风城的武装士兵中杀出一条路来。",
},
[1468] = {
["Title"] = "阿什高姆",
["Description"] = "阿什高姆是拉格纳罗斯手下的一名副官，曾在卡利姆多的森林里肆意纵火，后来守望者们终于设法将他禁锢。守望者们无法彻底消灭阿什高姆，于是把他关在冰牢里。不幸的是，最近燃烧军团的入侵削弱了冰封阿什高姆多年的反制机关……",
},
[1470] = {
["Title"] = "科达娜·邪歌",
["Description"] = "奸细。叛徒。放逐者。科达娜曾追随卡德加的先锋部队，将加尔鲁什赶进黑暗之门，并为阻止暗影议会的阴谋而奋斗。但古尔丹的黑暗魔法腐蚀了她的心灵，把她变成了自己的终极武器。她曾是恪尽职守的楷模，而现在却成为了瓦解守望者的工具。",
},
[1480] = {
["Title"] = "督军帕杰什",
["Description"] = "这名凶残的指挥官负责监督占领阿苏纳的纳迦军事力量，试图搜寻高戈奈斯潮汐之石。在积怨纳迦中，他的地位仅次于阿茜萨，而他的威信并不比阿茜萨低，下属对他无不敬畏。",
},
[1486] = {
["Title"] = "赫娅",
["Description"] = "赫娅生前是一位天下无敌的战士，她保卫瓦尔基拉免受一切威胁。她的勇气和事迹获得了泰坦监护者艾尔的注意。在赫娅去世后，她升入了英灵殿，艾尔赐予了她最崇高的奖赏：将她转化为一名瓦格里。",
},
[1488] = {
["Title"] = "神王斯科瓦尔德",
["Description"] = "古尔丹向维库国王斯科瓦尔德做了一个简单的提议：加入燃烧军团并获得最强的力量，不然等着他的是灭族的命运。渴望征战沙场、建功立业的斯科瓦尔德接受了军团的提议，并奉命执行一项至关重要的任务。他必须前往英灵殿取得奥丁的阿格拉玛之盾，并将其交给古尔丹。之后他才能踏上无尽的征服之路。",
},
[1490] = {
["Title"] = "积怨夫人",
["Description"] = "这个纳迦海巫出身积怨贵族，并受到艾萨拉女王本人的青睐。她驾驭着波涛和天空的力量，能粉碎妨碍积怨纳迦的一切敌人。",
},
[1492] = {
["Title"] = "艾萨拉之怒",
["Description"] = "艾萨拉的一名心腹侍女主动提出愿意成为女王陛下复仇的工具。帕杰什失败后，走投无路的积怨导魔者召唤出了恐怖的艾萨拉之怒，其存在的目的就是消灭一切妨碍她的陆地行者。",
},
[1498] = {
["Title"] = "科蒂拉克斯",
["Description"] = "这个巨大的构造体在苏拉玛的地道中巡逻，搜索并排除异常情况。他发现了一个异常，是暗夜井能量导管上的裂口，于是他前往修复。但在地道中游荡的外来生物也是异常，科蒂拉克斯同样会将其排除。",
},
[1500] = {
["Title"] = "纳尔提拉",
["Description"] = "这只巨大的蜘蛛在一颗巨大的法力之树的树洞里筑巢。纳尔提拉在渗出的魔法能量长年累月的作用下拥有了奥术魔力，变成了魔法回廊里最可怕的捕食者。",
},
[1502] = {
["Title"] = "堕落君王伊米隆",
["Description"] = "伊米隆曾是诺森德维库人的国王，也是个受人敬畏的强大战士。英灵殿的大门原本将在死后向他敞开。但渴望力量的他和巫妖王做了一笔黑暗的交易。被冒险者击败，他发现英灵殿的大门紧闭。因此，这位受诅咒的国王只能在噬魂之喉海岸的炼狱中苦苦煎熬。",
},
[1512] = {
["Title"] = "哈布隆",
["Description"] = "神秘的灵魂摆渡人是纳格法尔号的掌舵人，他收集被诅咒的灵魂，并将其带到海拉的领地。哈布隆与堕落的瓦格里女王之间的关系尚不明了，但当微风吹起他的斗篷时，就会看到里面一片晶莹闪亮，宛如群星。有点奇怪。",
},
[1518] = {
["Title"] = "融合之魂",
["Description"] = "在古尔丹施术将伊利丹的灵魂切离他的躯体时，无穷无尽的灵魂能量被释放了到了黑鸦堡垒中。这股能量将拉文凯斯家族的灵魂拉回到了他们远古的家园——残余的灵魂能量将他们融合成了一个巨大的怪物。",
},
