[1638] = {
["Title"] = "掌炉者伊格尼斯",
["Description"] = "跟奥杜尔的其他泰坦造物一样，伊格尼斯如今也遵从上古之神尤格-萨隆的扭曲意志。这个硕大的火焰巨人一直在巨人熔炉劳作，创造着钢铁部队，势必要以尤格-萨隆之名征服艾泽拉斯。",
},
[1640] = {
["Title"] = "XT-002拆解者",
["Description"] = "米米尔隆设计这个发条造物时只给了它执行使命所需的基本智力，而他的使命就是在奥杜尔的废料场巡逻。XT-002渐渐把自己看成是守护者的儿子，而且经常像熊孩子一样乱发脾气。",
},
[1642] = {
["Title"] = "科隆加恩",
["Description"] = "洛肯命令掌炉者伊格尼斯塑造了这名高大的巨人来守护破碎步道。科隆加恩的巨大手臂可以敲碎任何企图接近内部圣殿的入侵者。",
},
[1644] = {
["Title"] = "霍迪尔",
["Description"] = "巨人霍迪尔以前住在寒冬神殿，帮助风暴峭壁的冰巨人。如今这名守护者住在寒冬大厅的冰冷洞穴里，被迫为尤格-萨隆效力。",
},
[1646] = {
["Title"] = "弗蕾亚",
["Description"] = "守护者弗蕾亚一直是所有生命的守护者，而帮助她的则是三名坚韧的长老。虽然她的温室依然生机勃勃，但其实她也已经屈从于上古之神的疯狂低语。",
},
[1648] = {
["Title"] = "维扎克斯将军",
["Description"] = "名为无面者的奇怪生物潜伏在奥杜尔的深处。他们中最强大的指挥官之一就是维扎克斯将军。他守护着通向尤格-萨隆监狱的扭曲通道。",
},
[1650] = {
["Title"] = "观察者奥尔加隆",
["Description"] = "洛肯之死触发了对泰坦万神殿的警告：艾泽拉斯已经失去了首席管理员。观察者奥尔加隆被派遣前来评估是否有系统腐蚀的存在。如果有必要，这名星圣会触发整个世界的结构重组，消灭这个世界当前的一切居民。",
},
[1652] = {
["Title"] = "海里昂",
["Description"] = "",
},
[1654] = {
["Title"] = "大德鲁伊格兰达里斯",
["Description"] = "格兰达里斯曾是艾泽拉斯最有才华的变形者之一，月光林地会定期将最有前途的学徒送到他那里接受熏陶。但很不幸，越是亲近自然的人就越容易被梦魇腐化，他也不例外。",
},
[1656] = {
["Title"] = "德萨隆",
["Description"] = "德萨隆曾是一条年轻的绿龙，在世界之树的树荫之下照料幼崽。但现在却被梦魇吞噬，在仇恨和恐惧的迷雾中迷失了自我。他用强有力的双翼和令生命凋零的吐息向一切落入他手中的猎物倾泻怒火。",
},
[1662] = {
["Title"] = "洛克莫拉",
["Description"] = "洛克莫拉是乌拉罗格·塑山的作品，它至今尚未完成。乌拉罗格希望这个水晶怒灵能歼灭一切反抗地底之王的敌人。创造这个怪兽的狂野魔法尚未完全生效，但已赋予洛克莫拉的所有碎片足够的恶意去摧毁它的敌人。",
},
[1664] = {
["Title"] = "可恨的斯麦斯帕",
["Description"] = "可恨的斯麦斯帕是一名凶残而庞大的莫尔葛中尉。他领导军团部队入侵了黑鸦堡垒，并指挥旗下的邪蝠部队从空中保卫这座要塞。",
},
[1672] = {
["Title"] = "库塔洛斯·拉文凯斯",
["Description"] = "黑鸦堡垒领主库塔洛斯·拉文凯斯在上古之战时曾是卡多雷抵抗军的指挥官，后来艾萨拉女王派瓦罗森将他暗杀。千万年后古尔丹的邪恶灵魂魔法唤醒了拉文凯斯以及他先祖们原已安息的灵魂。渴望复仇的燃烧军团强行把他的灵魂逼回他的躯体，并将他催眠，强迫他在脑海中一遍又一遍地浮现出上古之战的可怕景象。",
},
[105] = {
["Title"] = "摧骨者罗姆欧格",
["Description"] = "作为外域食人魔中少见的“缺失的一环”，摧骨者罗姆欧格因其食人魔凶残的本性而被暮光之锤邪教所看重。他如今统领着焚烧之厅，靠折磨他人满足着自己的嗜虐欲。",
},
[1686] = {
["Title"] = "夺心者卡什",
["Description"] = "这只可怕的生物被捕获于奥杜尔的深处，尤格萨隆被击败后，它一度处于无意识的状态。自从达拉然到达破碎群岛后，这头怪物神秘地苏醒了。只有紫罗兰监狱的强力结界才能困住它。",
},
[1688] = {
["Title"] = "米尔菲丝·法力风暴",
["Description"] = "米尔菲丝是技艺高超的工程学天才，她的性格似乎与其夫米尔豪斯截然相反。米尔菲丝聪明而又诡计多端，是个不可小觑的对手。",
},
[1694] = {
["Title"] = "颤栗之喉",
["Description"] = "这头可怕的冰霜巨龙据说是辛达苟萨的后代，巫妖王的部队在冰冠堡垒卖力的创造这种怪兽，这一头就捕获于堡垒里的霜翼大厅。",
},
[1696] = {
["Title"] = "阿努贝斯特",
["Description"] = "阿努贝斯特是如今所剩无几的蛛魔地穴领主之一。在进攻冰冠堡期间被肯瑞托所俘获并囚禁在紫罗兰监狱。军团入侵期间他得以逃脱，意图向生者释放他的复仇怒火。",
},
[1702] = {
["Title"] = "鲜血公主萨安娜",
["Description"] = "鲜血公主萨安娜是强大的萨莱因女王兰娜瑟尔的女儿。诺森德战役后，她就一直被囚禁在紫罗兰监狱里，承受着无止尽饥渴的折磨。现在牢房已经打开，她打算把整个世界变成自己的盘中餐。",
},
[1704] = {
["Title"] = "梦魇之龙",
["Description"] = "伊瑟拉负责守护翡翠梦境，她派最强大的绿龙子嗣镇守直接连通艾泽拉斯的四座传送门。但在灾变之前，这些巨龙就有了腐化堕落的迹象。现在，通往梦魇核心的途中就要经过这些巨龙的巢穴。",
},
[1706] = {
["Title"] = "斯考匹隆",
["Description"] = "在暗夜要塞深处的海底，有若干被遗忘已久的密室，这些密室直接通向暗夜井。这头甲壳厚重的巨蝎在其中一间密室里安了家。斯考匹隆体内注入了暗夜井的力量，还有无数同类的保护，看来这条进入暗夜要塞的后门小道一点也不好走啊。",
},
[107] = {
["Title"] = "卡尔什·断钢",
["Description"] = "巨大的龙人卡尔什·断钢在暮光铸炉日夜工作，用稀有的水银制造着武器。尽管卡尔什的作品在通常情况下都坚不可摧，可在高温下，它们就如锈铁一般脆弱。",
},
[1718] = {
["Title"] = "巡逻队长加多",
["Description"] = "暮色卫队的队长加多一生都致力于捍卫苏拉玛城内的和平。尽管燃烧军团到来后，他的不安情绪与日俱增，但他依然相信并忠于苏拉玛的领导层。艾利桑德已经守护了这座城市无数年，她很清楚怎么做才会为人民带来最大的利益。今晚，加多的任务是确保没有闲杂人等混入在庄园里举行的重要集会。",
},
[1720] = {
["Title"] = "顾问麦兰杜斯",
["Description"] = "大魔导师的首席剑士麦兰杜斯与艾利桑德形影不离。他刻意不研习魔法，而是用暗夜井的力量将他的反应和移动速度提升到了超越凡人极限的水准。",
},
[1726] = {
["Title"] = "萨维斯",
["Description"] = "萨维斯曾是一名强大的法师，也是艾萨拉女王的谋臣，他后来与萨格拉斯达成协议，将燃烧军团第一次引入了艾泽拉斯。萨维斯失败之后饱受诅咒与折磨，他在艾林裂隙之中策划着向世界发起复仇。闯入梦魇者将与力量全盛状态下的他对决。他的真身是一头令人作呕的肿胀怪物。",
},
[1732] = {
["Title"] = "占星师艾塔乌斯",
["Description"] = "夜之子星术师艾塔乌斯花费多年研究艾泽拉斯的天空，探索宇宙的奥秘。他靠占卜发现了很多我们看不到的星球，并用暗夜井的力量吸取那些星球的精华，以强化他自身的力量。",
},
[1738] = {
["Title"] = "伊格诺斯，腐蚀之心",
["Description"] = "住在现已枯朽的世界之树中的伊格诺斯是梦魇之心的恐怖化身。它是腐化的聚合物，他就不该存在于世。它的卷须渗入地面，无数可怕的眼柄和肢体在另一头破土而出。",
},
[109] = {
["Title"] = "升腾者领主奥西迪斯",
["Description"] = "堕落者德希里克曾是一名强大的萨满，因为其狂热的虔诚和对暴行的嗜好，他被恩准升腾：通过一道黑暗仪式，他被注入了元素之力，变成了一头名为升腾者领主奥西迪斯的畸形生物。",
},
[1744] = {
["Title"] = "艾乐瑞瑟·雷弗拉尔",
["Description"] = "艾乐瑞瑟曾是一名精通变形术的强大德鲁伊，但她后来因相信自己遭到最亲近的盟友背叛而走上了黑暗之路。她的意识现被困在梦魇之中，终日饱受恐惧、迷惑和仇恨的折磨。",
},
[1750] = {
["Title"] = "塞纳留斯",
["Description"] = "半神塞纳留斯是艾泽拉斯德鲁伊教之父，也是艾泽拉斯最古老强大的保护者之一。他沉睡在了瓦尔莎拉林中的事实令人不安，说明来自梦魇的威胁已经相当严重。现在，那股黑暗的力量已经完全将他占据，也许他已经彻底堕落了。",
},
[1756] = {
["Title"] = "夺魂者",
["Description"] = "这三名掠夺者奉海拉之名，率领手下洗劫维库人国王的陵墓。他们设法进入了列王陵墓，企图夺取安息在那里的灵魂。",
},
[110] = {
["Title"] = "克伯鲁斯",
["Description"] = "死亡之翼奴役着巨大的旋岩虫克伯鲁斯，让它挖掘大量源质来为黑龙之王铸造新的盔甲。但是，当死亡之翼离去后，愤怒的克伯鲁斯摆脱了管束，在巨石之核里盲目地肆虐。",
},
[1762] = {
["Title"] = "提克迪奥斯",
["Description"] = "纳斯雷兹姆以前的首领恐惧魔王提克迪奥斯曾被获得全新力量的伊利丹·怒风击杀。他在扭曲虚空中重塑形体后，代表燃烧军团监督古尔丹的行动，确保这个兽人术士不会再次让主人失望。",
},
[1764] = {
["Title"] = "国际象棋",
["Description"] = "",
},
[1770] = {
["Title"] = "胡墨格里斯",
["Description"] = "胡墨格里斯一直梦想着能施展魔法。他发现自己毫无魔法天赋后，改为使唤别的巫师替他施法。胡墨格里斯找到并抓住了名为帕达沃森的法师，用暴力胁迫的方式逼他在战场上替自己施展魔法。",
},
[1774] = {
["Title"] = "卡拉米尔",
["Description"] = "卡拉米尔是古代先贤在盛怒之下召唤出来的魔法生物，力量无比强大。卡拉米尔体内充盈着火焰、冰霜和奥术之力，挡他去路者将被他无情地消灭。",
},
[1790] = {
["Title"] = "鬼母阿娜",
["Description"] = "这个邪恶的鬼母住在邪魂堡垒的深处，浸泡在纯净的邪能之池中。她在孩子们的拥簇下，沐浴在恶臭的空气中，腐化着目力所及的一切。",
},
[1796] = {
["Title"] = "凋零者吉姆",
["Description"] = "这个堕夜精灵被驱逐出苏拉玛后，沿着海岸线游荡，同时身心慢慢衰弱。就在他即将丧失最后一点人性之际，突然感觉到附近的洞穴里散发出来的能量。在洞里，他发现了暗夜井的能量碎片。这块碎片维持了他的生命，强化了他的力量，还扭曲着周围的时间和空间，并让他的心智彻底崩溃。现在没人敢进入凋零者吉姆的洞穴。傻子都知道不能进去。",
},
[113] = {
["Title"] = "高阶女祭司艾苏尔",
["Description"] = "尽管心智尽毁，但高阶女祭司艾苏尔仍然是少数几个能在同暮光之锤教派恐怖的主子沟通后，还能活下来的人。她将恐怖植根在低级教徒心中，好让他们在主子下令的时候，毫不犹豫地牺牲自己。",
},
[1818] = {
["Title"] = "魔力吞噬者",
["Description"] = "法力浮龙基本不会对老练的冒险者构成威胁。这些形体娇小、头脑简单的生物四处飘荡，吞食散逸的奥术能量。但在卡拉赞，一切往往都不按常理出牌，看似无害的东西可能会造成巨大的威胁。",
},
[1820] = {
["Title"] = "歌剧院：魔法坏女巫",
["Description"] = "恶棍究竟是天生的，还是在别人的影响下堕落的？从猢狲的视角考虑这个难题或许会有所启发……",
},
[114] = {
["Title"] = "大宰相埃尔坦",
["Description"] = "奉主人阿萨德之命，埃尔坦守护着旋云之巅，对抗任何来自地面的、胆敢侵入这个领域的人们。为了履行其职责，这名元素贵族被授予了统御闪电和风暴大军的特权。",
},
[1826] = {
["Title"] = "歌剧院：西部故事",
["Description"] = "在两大敌对的黑帮为争夺西部荒野的草场而争斗不休时，一对来自不同世界的恋人将为幸福而战。据说爱情都是盲目的……现在看来，爱情似乎还需要一个翻译？",
},
[1830] = {
["Title"] = "高姆",
["Description"] = "海拉所圈养的这只凶猛的三头猎犬忠心耿耿地守护着冥狱深渊的入口。经过精心的育种，高姆不追求享受也不需要睡觉，它永远警惕着一切前来挑战他残酷女主人的入侵者。",
},
[1836] = {
["Title"] = "馆长",
["Description"] = "馆长保护着展览馆，使其免受不速之客的侵扰，并处决想要窃取卡拉赞秘密的入侵者。虽然是由麦迪文本人组装的，但这个构造体卫兵已经变质，很容易发生能量过载并作出疯狂的举动。",
},
[1838] = {
["Title"] = "监视者维兹艾德姆",
["Description"] = "全知全能的维兹艾德姆受基尔加丹的指使，前来占领卡拉赞，并篡改塔内的魔网支流。一旦他成功将这座建筑与被燃烧军团占领的无数世界连接起来，黑暗泰坦的大军就会淹没艾泽拉斯，将其化为焦土。",
},
[116] = {
["Title"] = "西风君王阿萨德",
["Description"] = "奥拉基尔亲自指名阿萨德作为旋云之巅的守护者。自从南风之主希亚玛特遭到尼斐塞特托维尔人的囚禁之后，这名可怕的元素相信自己只要干好这份差事，没准就能升上风之议会。",
},
[1856] = {
["Title"] = "哈亚坦",
["Description"] = "哈亚坦从出生起就接受杀敌训练。经过野蛮的征伐，他聚集了一群视他为神的穴居鱼人。现在，只要这个纳迦暴徒一声令下，就会有大群虔诚的追随者前赴后继地为他效劳。",
},
[1862] = {
["Title"] = "格罗斯",
["Description"] = "作为对过去失败的惩罚，格罗斯浑身遍布烧伤。这头巨兽的每一个动作都会令他的血肉开裂并嗞嗞作响，同时还伴随着无尽的痛苦。他很乐意将这种痛苦强加给所有挑战他的人。",
},
[117] = {
["Title"] = "胡辛姆将军",
["Description"] = "泰坦们曾亲自指派胡辛姆将军作为奥丹姆的守护者之一。在南风之主希亚玛特治愈了尼斐塞特托维尔人的血肉诅咒之后，胡辛姆将军发动了反叛，并最终将那名强大的空气元素囚禁了起来。",
},
[1872] = {
["Title"] = "大魔导师艾利桑德",
["Description"] = "艾利桑德曾因为对抗燃烧军团而享有盛名。她和手下的上层精灵追随者们背弃了走上黑暗之路的艾萨拉女王，之后利用阿曼苏尔之眼的力量创造出了暗夜井，保护了苏拉玛免遭大分裂的破坏。但一万多年后，军团再临了，她被逼上了绝路。于是她与恶魔结盟了，希望能再一次利用暗夜井的力量“拯救”她的人民。",
},
[1878] = {
["Title"] = "孟菲斯托斯",
["Description"] = "孟菲斯托斯一手策划了军团从破碎海滩开始的入侵行动。眼看艾泽拉斯抵抗力量越过了他的部队前线，孟菲斯托斯撤回了永夜大教堂。他要在那里运用最狡诈的计谋，让英雄们无法取回阿格拉玛之盾。",
},
[1884] = {
["Title"] = "马利费库斯",
["Description"] = "作为一个至恶至邪的生物，马利费库斯能唤起对手内心的恐惧。在他降临前通常都会出现一些征兆，包括在平民中间爆发的大规模恐慌，以及出现庆祝末日来临的死亡邪教。",
},
[118] = {
["Title"] = "锁喉",
["Description"] = "在尼斐塞特发动起义，反抗希亚玛特的乱战中，俾格米人奥弗在托维尔古城中大偷特偷。在他们的族人中，奥弗因为两件事而备受尊重：一是他的狡诈；还有一个是他的宠物，那条叫做锁喉的凶狠鳄鱼。",
},
[1896] = {
["Title"] = "绝望的聚合体",
["Description"] = "这里曾是暗夜精灵神圣的墓园，但燃烧军团已经用灵魂引擎扭曲了它。这台邪恶的机器抽取着亡者的能量，将他们扭曲成怪物。在这种腐蚀侵袭之下，这些饱受折磨的幽灵已经变成了怪物，会吞噬所有深入墓穴的人。",
},
[1898] = {
["Title"] = "基尔加丹",
["Description"] = "自从与燃烧军团达成交易，将德莱尼人逐入群星之中后，基尔加丹就深信，没有人可以阻挡军团的力量。然而，他的所有欺诈手段都无法阻止你来到这最紧要的关头。萨格拉斯曾经做出了胜利的许诺，但却迟迟不曾兑现，这使得恶魔领主变得怒火中烧，他决定亲自来面对你。你们之间的这场最终之战将决定艾泽拉斯未来的命运。",
},
[119] = {
["Title"] = "高阶预言者巴林姆",
["Description"] = "高阶预言者巴林姆是尼斐塞特神圣的精神领袖。为了对抗希亚玛特，他与胡辛姆将军集结尼斐塞特人，将这名空气元素囚禁了起来。然而，某种黑暗力量依然驱使着巴林姆和他的追随者们，在奥丹姆散播着恐惧。",
},
[1904] = {
["Title"] = "多玛塔克斯",
["Description"] = "阿格拉玛之盾再次回到了它原本的位置，多玛塔克斯带领恶魔军团发动袭击，想要摧毁这圣物。",
},
[1906] = {
["Title"] = "轻蔑的萨什比特",
["Description"] = "萨什比特是斯麦斯帕令人生厌的兄弟，他的任务是肃清任何进入大教堂图书馆的生物。这头智力低下的莫尔葛对知识与学习不存在任何的尊重，摧毁古老的文物、践踏宝贵的典籍会让它感到无比满足。",
},
[122] = {
["Title"] = "希亚玛特",
["Description"] = "净化尼斐塞特托维尔人的血肉诅咒，让可怕的元素希亚玛特几乎耗尽了能量。正是在这个薄弱的关头，托维尔人发动了进攻，奇迹般地将希亚玛特囚禁在了他们的沙漠古城的中央。",
},
[1956] = {
["Title"] = "阿波克隆",
["Description"] = "作为燃烧军团在数千年前建造的杀戮机器，阿波克隆已经导致了无数文明的毁灭。每征服一个世界，这个魔能机甲的力量都会变得更强，以确保将它的下一个目标化为火海。",
},
[1980] = {
["Title"] = "萨普瑞什",
["Description"] = "始终坚信战术至上的萨普瑞什依靠精密的计算部署着影卫的兵力。虽然已经是成熟的指挥官和战术家，萨普瑞什仍然很享受亲自上阵的感受。他会利用敌人的弱点对付他们，并放出贪吃的宠物对付脆弱的敌人。",
},
[1982] = {
["Title"] = "鲁拉",
["Description"] = "维伦和他的追随者登上吉尼达尔逃离阿古斯时，纳鲁鲁拉留了下来，为这些德莱尼争取逃跑的时间。基尔加丹被这次叛逃激怒，下令将受伤的纳鲁封印在执政团之座中。\r\n\r\n经过了漫长的岁月，鲁拉从圣光生物堕落为虚空怪物。她优美的勇气与希望之歌变成了绝望的黑暗挽歌，引诱着那些想要夺取她力量的人。",
},
[1984] = {
["Title"] = "阿格拉玛",
["Description"] = "阿格拉玛曾经是高贵的万神殿复仇者，被萨格拉斯击败后，又被重生为毁灭泰坦。他现在就盘踞在阿古斯的核心内，守护着足以毁灭宇宙的力量。\r\n\r\n就连恶魔也不能进入这个泰坦的殿堂，任何敢于闯入的凡人都将在阿格拉玛燃烧的长剑——泰沙拉克之下化为灰烬。",
},
[1986] = {
["Title"] = "破坏魔女巫会",
["Description"] = "作为萨格拉斯最堕落、最狂热的追随者，女巫会承担着一个邪恶的使命——扭曲陨落泰坦的意志，并让他们组成不可阻挡的黑暗万神殿。\r\n\r\n每一位主母都有自己招牌式的折磨手法，能让受害者的尖叫声响彻安托鲁斯的殿堂。据说，无论是凡人还是恶魔都无法抗拒她们的低语。所以，泰坦们的意志崩溃只是时间问题。",
},
[1992] = {
["Title"] = "加洛西灭世者",
["Description"] = "这台战争机器建造于阿古斯的核心内，配备了足以毁灭诸界的武器。它存在的目的只有一个，就是击溃凡人的进攻。",
},
[125] = {
["Title"] = "地怒者塔赫",
["Description"] = "地怒者塔赫墓穴外的沙地上铺满了累累白骨，他们都是被安努尔所净化的生物。据说塔赫能操纵这些遗骨，让它们去对付那些成功绕开第一道防线的入侵者。",
},
[2004] = {
["Title"] = "金加洛斯",
["Description"] = "所有军团战争机器的设计思路都来自金加洛斯的邪恶头脑。沉迷于制造屠杀工具的金加洛斯将自己的身体与生产设备融合，以便更加高效地生产出毁灭机器。\r\n\r\n按照军团的黑暗主人的命令，金加洛斯那发热的天才大脑想出了一种新的超级武器。而他正准备用它来对付圣光军团。",
},
[2010] = {
["Title"] = "主母芙努娜",
["Description"] = "主母芙努娜带领自己的子嗣毁灭了许多世界。这些邪恶的怪物像瘟疫一样在大地上横行，腐化和吞噬着眼前的一切。",
},
[2012] = {
["Title"] = "审判官梅托",
["Description"] = "审判官梅托精通邪能魔法，在军团中几乎无人能及。梅托会使用这种力量给宇宙带去混乱和毁灭。他所到之处，只会留下无数燃烧的世界。",
},
[2014] = {
["Title"] = "索塔纳索尔",
["Description"] = "索塔纳索尔辗转宇宙，经历过无数场白热化的战役，铸就了传奇般的力量。作为一名野蛮的将军，这个恶魔指挥着一支百战百胜的大军。",
},
[2030] = {
["Title"] = "亚兹玛",
["Description"] = "亚兹玛在吞噬了蜘蛛之神沙德拉的力量后，奉自己的主人先知祖尔之命，正在守卫阿塔达萨神庙。",
},
[2036] = {
["Title"] = "沃卡尔",
["Description"] = "沃卡尔生前是亚兹玛备受信赖的护卫。在他死后，亚兹玛运用她新得的力量将其复活，如此一来这位前任军官就能永世为自己效劳了。",
},
[128] = {
["Title"] = "阿穆纳伊，生命的造物",
["Description"] = "尽管在设计上，起源大厅里生命重组系统的初衷，是将艾泽拉斯降解为最基本的元素结构，但它同时也能够创造新的生命。为此，结构体阿穆纳伊控制着设施内部流动的自然能量，确保生命能在重塑后的艾泽拉斯继续存在。",
},
[129] = {
["Title"] = "塞特斯，毁灭的造物",
["Description"] = "考虑到起源大厅的用途，泰坦认为创造一个掌握毁灭力量的结构体十分必要，那就是塞特斯。要是塞特斯被腐化了，那么后果将是灾难性的。",
},
[130] = {
["Title"] = "拉夏，太阳的造物",
["Description"] = "拉夏所监管着的能量，滋养也湮灭了他的无数同类。他是四个构造体中最强的一个，其能力可以将一千个太阳的怒火倾泻到艾泽拉斯之上。",
},
[131] = {
["Title"] = "乌比斯将军",
["Description"] = "艾泽拉斯的勇者和他们的红龙盟军对格瑞姆巴托的大门发动了进攻，率领堡垒中教徒和暮光龙兽展开防御的，正是凶神恶煞般的乌比斯将军。",
},
[2096] = {
["Title"] = "科古斯狱长",
["Description"] = "狱长科古斯看守着托尔达戈，维系着这座巨大的海岛监狱。他对艾泽里特的痴迷众所周知，甚至还将它灌进子弹里，并用囚犯来检验效果。",
},
[132] = {
["Title"] = "铸炉之主索朗格斯",
["Description"] = "这名巨大的双头魔是暮光之锤教派的匠人，他热衷于用自己所铸造的武器和铠甲，消灭那些入侵者。",
},
[2116] = {
["Title"] = "商业大亨拉兹敦克",
["Description"] = "商业大亨拉兹敦克虽然永远没法当上贸易大王，但他确信，成为世界上最重要的艾泽里特巨头可以为他带来远超他身份的名誉和财富。",
},
[133] = {
["Title"] = "达加·燃影者",
["Description"] = "这名暮光之锤的信使正在执行一个来自暮光之锤的任务。如果英雄们能够征服他那些烈焰的爪牙，达加就会让艾泽拉斯的保卫者们见证一个真实的末日预言。",
},
[2128] = {
["Title"] = "维克雷斯勋爵和夫人",
["Description"] = "丈夫的病情让维克雷斯夫人痛苦无比，她呼唤任何可以挽救丈夫的力量。高莱克·图尔回应了她，许诺他们只要愿意付出代价，就能永生不死。",
},
[2132] = {
["Title"] = "“屠夫”血钩",
["Description"] = "“屠夫”血钩的残忍之名响彻库尔提拉斯。在铁潮突袭队的支持下，“屠夫”在整个伯拉勒斯横行，沿途留下一片狼藉。",
},
[2140] = {
["Title"] = "维克戈斯",
["Description"] = "女勋爵艾什凡从深渊召唤出维克戈斯，令港口满目疮痍。这头深海巨兽能够把数艘巨舰拖进深渊中。如果不加阻止，库尔提拉斯的舰队就会化为乌有。",
},
[2144] = {
["Title"] = "加瓦兹特",
["Description"] = "在塞塔里斯的神庙遭到腐化后，她的雷霆之力创造了扭曲的元素生物，在沉没的神庙中徘徊。加瓦兹特是其中最强大的生物，能够彻底铲除任何挡路的敌人。",
},
[2156] = {
["Title"] = "低语者沃尔兹斯",
["Description"] = "艾萨拉女王派沃尔兹斯来转化海潮贤者，她的低语承诺，只要愿意倾听，就会获得力量。",
},
[2168] = {
["Title"] = "塔罗克",
["Description"] = "泰坦守护者为这座设施安装了无数系统来检测和控制入侵。其中最强大的构造体塔罗克一直在监视着这片区域，检测腐化的迹象并无情地消灭。但千万年过去了，随着内部防御系统开始腐朽，使得它自身都变得容易被腐蚀。",
},
[2172] = {
["Title"] = "始皇达萨",
["Description"] = "达萨，赞达拉的建立者与第一位帝王。他带领自己的子民走出了泥潭，建立了黄金之城。他是初代迅猛龙骑手，所向披靡的战士，帝国之父。\r\n\r\n祖尔的黑暗魔法将他从永恒的长眠中唤醒，现在让他再度安息的重任就落到你身上了。\r\n",
},
[2212] = {
["Title"] = "雄狮之吼",
["Description"] = "雄狮之吼是联盟工程技术的巅峰之作，可以用来主宰整个战场。它能搭载数支部队，彻底摧毁敌方的防御工事。只要有这头巨兽在战场上，就没人能阻挡它夺取胜利的脚步。",
},
[139] = {
["Title"] = "阿尔加洛斯",
["Description"] = "由于深渊领主阿尔加洛斯过于巨大，达拉然宏伟的紫罗兰监狱都无法容下，肯瑞托的法师们别无选择，只好把这头强大的恶魔关在托尔巴拉德的地下。",
},
[140] = {
["Title"] = "欧库塔尔",
["Description"] = "这头饥饿的恶魔从牢笼中挣脱了出来，来到了监狱的西侧，吞噬了那里关押的所有囚犯。欧库塔尔的贪吃导致他的身躯臃肿，难以逃离，结果无非只是将自己困在了更大的牢狱中。",
},
[2328] = {
["Title"] = "无眠秘党",
["Description"] = "无眠秘党从深渊中被召唤而来，他们的目的是夺取三件拥有远古力量的圣物。无眠秘党决心为恩佐斯服务，实现他的意志。扎克萨奇口中总是谈及承诺与力量，而法索乌则会用暴力将敌人击溃。",
},
[2332] = {
["Title"] = "乌纳特，虚空先驱",
["Description"] = "一万年前，艾萨拉女王与恩佐斯达成交易时，她指派了自己的一位心腹去侍奉古神。如今，正如群星所预言的那样，乌纳特和他号令的蠕行生物已经化身为他的主人降临的先锋。",
},
[2336] = {
["Title"] = "坦克大战",
["Description"] = "麦卡贡最初的工程师通过制作特制的战斗机器人来测试他们的勇气（和金属强度）。这些坦克一般是在互相战斗来赢得荣耀，但如果出现了有勇无谋的有机入侵者，想要进入麦卡贡，他们还是会联合起来驱逐外来者。",
},
[2340] = {
["Title"] = "格洛恩，还魂者",
["Description"] = "强大的格洛恩生前甘愿牺牲一切来为联盟服务，但死后却被复活，并被迫与从前的战友为敌。这只高贵的大猩猩对自己为部落效命这一点极其痛恨，他唯一渴望的解脱就是干净利落的死亡。",
},
[2344] = {
["Title"] = "圣光勇士",
["Description"] = "拉瓦妮及其麾下的部队是对抗联盟的排头兵，他们发誓为守护首都献出生命。他们步调一致，互相强化和治疗，以此击退来犯之敌。",
},
[2348] = {
["Title"] = "机械师的花园",
["Description"] = "首席机械师闪流的金属花园美丽又危险，其设计目的既是为了装饰，又是为了打击目标。只要扳下开关，宁静祥和的花园就会化为死亡的陷阱，没有闯入者能够逃脱。",
},
[2352] = {
["Title"] = "深渊指挥官西瓦拉",
["Description"] = "深渊指挥官西瓦拉是武术和魔法的大师，她残酷无情，带领着艾萨拉的先锋赢得了无数场胜利。",
},
[2360] = {
["Title"] = "崔克茜和耐诺",
["Description"] = "崔克茜和耐诺是邦多最强大的副官，他们的关系如暴风雨般剑拔弩张。崔克茜为自己无情的高效率而自豪，而耐诺坐上机车时，则是混沌的化身。他俩唯一的共同点，是对无意义的暴力的渴望。任何胆敢踏足他们领地的蠢货都将成为他们发泄的对象。",
},
[2364] = {
["Title"] = "虚无者莱登",
["Description"] = "莱登为了拯救心之秘室而奋勇作战，但却被拉进了尼奥罗萨，变成了恩佐斯低语的牺牲品。他心中徘徊多年的绝望吞噬了最后的一丝希望，导致他被彻底地腐化了。现在，这位前任至高守护者会不惜一切代价，执行上古之神的命令。",
},
[2368] = {
["Title"] = "黑龙帝王拉希奥",
["Description"] = "虽然拉希奥做了很多准备，但依然无法摆脱腐蚀了他父亲的疯狂。黑王子的心灵被恩佐斯扭曲后，他相信，只有以上古之神的名义，他才能真正守护艾泽拉斯。拉希奥不再是位王子，他登上了自己应得的宝座，化身为黑龙帝王。",
},
[2372] = {
["Title"] = "主脑",
["Description"] = "卡吉尔和泰克利斯这两个将军永远都在进行意志的角力，想要争夺对亚基虫族的统治权。每当大权被另一边掌握时，虫巢就会改变战术。无论是由谁统御大军，虫巢都会疯狂地追随它。",
},
[2388] = {
["Title"] = "贪食的克里克西斯",
["Description"] = "贪食的克里克西斯感知到了赤红深渊内贮藏的心能，而吞噬能量的渴望则令他发狂。雷文德斯最近出现的裂隙让克里克西斯得以进入古墓。它的目标是吸干这座地下储藏所里的每一滴心能。",
},
[2392] = {
["Title"] = "外科医生缝肉",
["Description"] = "可怕的憎恶被从浮空堡垒佐尔拉姆斯投放至战场，而缝肉医生是主导这一切的人。他狂热地投入到这项任务中，用陨落的敌人的血肉来制作亡灵造物，投入到玛卓克萨斯的战争中。",
},
[2396] = {
["Title"] = "缚霜者纳尔佐",
["Description"] = "缚霜者纳尔佐高高在上，在飞行的通灵塔佐尔拉姆斯的顶端号令着大军对晋升堡垒发动进攻。这个巫妖作为共犯，计划在晋升堡垒的璀璨土地上降下冰霜魔法和死亡之息。",
},
[2400] = {
["Title"] = "英格拉·马洛克",
["Description"] = "德鲁斯特所受到的诅咒使其存在于生死循环之外。如今，他们希望利用炽蓝仙野的重生魔法来改变自己的命运。由此塞兹仙林也就成为了他们征服之路的一部分。英格拉·马洛克和他的追随者在这里使用邪恶的魔法来控制当地居民。",
},
[2404] = {
["Title"] = "斯特拉达玛侯爵",
["Description"] = "人们相信，斯特拉达玛侯爵已经伴随着自己密院的毁灭而消逝。其实，这场爆炸把她转化成了一种可怕的新形态，也导致了她的疯狂。现在，她被留在了陨落的凋零密院中心。",
},
[2408] = {
["Title"] = "夺灵者哈卡",
["Description"] = "夺灵者哈卡刚一现身就在艾泽拉斯造成了动荡。暴力和灾祸是他无上力量的象征。他的信徒甘愿为他赴死，并且死后也将继续为他效力。他从来都不会主动放弃力量，即便这力量并不属于他自己。",
},
[2412] = {
["Title"] = "疑虑圣杰德沃丝",
["Description"] = "德沃丝一直都是忠诚的象征，直到有一天，一个饱受过往困扰的灵魂来到了晋升堡垒。她的疑虑吞没了她，使她堕入了公开的反叛大军。这支叛军的助力又是暗影界最为黑暗的力量。占领晋升高塔只是第一步，接下来，即便是消灭执政官这样的目标，对她来说也是唾手可得。",
},
[2416] = {
["Title"] = "雯图纳柯丝",
["Description"] = "雯图纳柯丝是最致命的弃誓者构造体之一，最初的设计初衷是为了考验格里恩候选者的勇气。这个裁定者的行动极其迅速，会让敌人产生自己突然消失的错觉。",
},
[2420] = {
["Title"] = "伊涅瓦·暗脉女勋爵",
["Description"] = "心能滋润着暗影界，而伊涅瓦·暗脉女勋爵想解开其中的奥秘。在德纳修斯的指导下，她掌握了其中潜藏的秘密，可以用来对抗他的仇敌。她会把心能从任何纳斯利亚的入侵者身上剥离，并用它来塑造一个黑暗的崭新未来。",
},
[2424] = {
["Title"] = "德纳修斯大帝",
["Description"] = "无数纪元中，德纳修斯大帝一直和其他永恒者一起统治着死亡的国度。但在暗影界最黑暗的时刻，他却背叛了自己神圣的使命。他身边有嗜血的活体利刃蕾茉妮雅，以及一群谄媚的死忠。德纳修斯大帝会轻松地击败任何胆敢反对他的人，并将其残躯投入无法逃离的恐怖噬渊。",
},
[2428] = {
["Title"] = "饥饿的毁灭者",
["Description"] = "吞噬者只要在一处地方发现了心能，就会将其吞噬掉。而在心能枯竭荼毒着暗影界的现在，这些最饥饿、最危险的吞噬者自然会被丰饶的心能贮藏点所吸引，这个地方正好位于纳斯利亚堡深处。",
},
[2432] = {
["Title"] = "“长青之枝”奥拉诺莫诺斯",
["Description"] = "奥拉诺莫诺斯曾是塞兹仙林最古老的守护者之一，现如今却已经和巨树一起枯萎了。她现在所剩的心能太少，戈姆也在不断地吞噬她衰老的身躯。她已无法区分敌我。",
},
[2436] = {
["Title"] = "收发室乱战",
["Description"] = "寄送物品办公中心（P.O.S.T.）出了大乱子，维度传送门将包裹抛撒一地，经营办公中心的自动设备也发生了故障。如果不能尽快解决乱局，整座城市都会和邮局一同瘫痪。",
},
[2440] = {
["Title"] = "克尔苏加德",
["Description"] = "臭名昭著的克尔苏加德在灵魂之河的顶端等待着，这名巫妖可以吸取无尽的力量之井中的能量。他生前死后的无数阴谋诡计最终会在这场战斗中迸发。他早已做好了谋划，想让凡人勇士们最终陨落，从而侍奉自己的真正主人。",
},
[2444] = {
["Title"] = "耐奥祖的残迹",
["Description"] = "典狱长本希望初代巫妖王耐奥祖成为他统治艾泽拉斯的先锋，但最终，这名部下辜负了典狱长的期待。这名堕落兽人扭曲灵魂的最终残迹被封入了布满尖刺的影钢之中，被罚永世为自己的失败而遭受折磨。任何挡在他面前的人都会领教他承受的痛苦。",
},
[2448] = {
["Title"] = "希尔布兰德",
["Description"] = "一件远古泰坦神器失窃后，奉命看守它的希尔布兰德，守护者之剑苏醒了过来。若不能破解希尔布兰德控制的众多安保协议，就只能在坟墓中永远沉眠。",
},
[2452] = {
["Title"] = "麦扎的绿洲",
["Description"] = "饮品虚无缥缈，环境令人倾倒，门卫佐·格伦脾气糟糕。在这绿洲怀抱，观众若是不叫好，乐队吃不了兜着跑。",
},
[2456] = {
["Title"] = "莫盖斯，罪人的折磨者",
["Description"] = "即使在典狱长无穷的大军中，也很少有人像恶毒的莫盖斯一样，喜欢回味创造扭曲产物的乐趣。落入他手中的灵魂的意志必将被他粉碎，而他也痴迷于此。即使是在战场上，他也毫不放弃自己固执的控制欲。他要让敌人的每一步错棋都成为生命中最后的一份悔恨。",
},
[2460] = {
["Title"] = "死亡万神殿原型体",
["Description"] = "因为缺少永恒者的宇宙灵魂，这些未完成的宿主身体只能执行基础指令，不懂得怜悯和同情。但既然大敌当前，利许威姆也没有别的选择，只能重新激活这些危险的原型体。",
},
[2464] = {
["Title"] = "典狱长",
["Description"] = "无数岁月以来，典狱长一直耐心地一步步展开计划，试图到达圣墓的中心。现在，他距离最终的胜利仅剩一步之遥。艾泽拉斯的英雄们必须齐心协力，阻止典狱长统御现实的一切。",
},
[2468] = {
["Title"] = "安特洛斯",
["Description"] = "安特洛斯守护着先行屿的宝藏。典狱长的军队在统御了他以后，想利用他来发掘这座岛屿的秘密，从而进一步亵渎扎雷殁提斯。",
},
[2472] = {
["Title"] = "肠击",
["Description"] = "这个豺狼人不仅百发百中，还精通狩猎、布陷和处决猎物。腐朽主母对肠击的能力和狡诈很满意，就派她监督和训练其他猎人，并解决闯进蕨皮山谷深处的入侵者。",
},
[155] = {
["Title"] = "奥拉基尔",
["Description"] = "借着无人能比的智慧和狡诈，风元素领主奥拉基尔曾是上古之神那支可怖军队中最出色的战略家。大灾变之后，他和死亡之翼同流合污，把神一般的力量用来对付空气元素的远古宿敌托维尔人。",
},
[2480] = {
["Title"] = "艾拉诺格",
["Description"] = "拜荒者部队的指挥官艾拉诺格一直在不间断地追寻力量。随着化身巨龙即将被释放，艾拉诺格召唤了整支大军，为了获得胜利，他可以毫不犹豫地牺牲忠诚的部下。",
},
[2484] = {
["Title"] = "哨兵塔隆达丝",
["Description"] = "塔隆达丝是一名莱弗提，这一族是守护者提尔铸造的，属于泰坦造物。创造他们的目的是为了和龙族进行密切合作。莱弗提一族对其创造者无比忠诚，有时候他们会受命前往遥远的地方执行重要的使命。哨兵塔隆达丝的职责是守护通往存放提尔记忆的圆盘的通路，她下定决心，一定要将企图夺取她的创造者的遗产的害虫拒之门外。",
},
[2488] = {
["Title"] = "梅莉杜莎·寒妆",
["Description"] = "梅莉杜莎·寒妆在红玉新生法池领导着拜荒者部队的注能工作。她笃信自己是在保护幼小的龙蛋不受泰坦影响，并能将它们从污秽的秩序魔法中净化干净。她会不惜一切代价地完成使命，力求让龙蛋回归她所认定的自然状态。",
},
[2492] = {
["Title"] = "莱魔",
["Description"] = "莱魔刚出生时，只是魔网能量池里的一棵不起眼的小树苗，但玛里苟斯发现了它。它这棵幼苗在辛达苟萨的花园里慢慢成长，经过上万年后，莱魔的身形长得十分巨大。在无人看护的情况下，这个魁梧的巨人定会摧毁整座碧蓝魔馆。",
},
[2500] = {
["Title"] = "泰洛斯",
["Description"] = "拜荒者试图将桀骜不驯的毁灭力量拉出元素位面，但仪式却中道而废。魁梧可怖的泰洛斯受困于两个世界之间，一心想重归自由，扫清他面前的万事万物。",
},
[2504] = {
["Title"] = "看护者伊里度斯",
["Description"] = "自守护者提尔任命看护者伊里度斯守御并维护注能大厅以来，他始终尽善尽美地履行着自己的职责……直到现在。在拜荒者入侵时，他被那些人所释放的元素力量打了个措手不及。他不想一错再错。",
},
[157] = {
["Title"] = "瑟纳利昂和瓦里昂娜",
["Description"] = "奇迹般成年的瓦里昂娜和瑟纳利昂本该在新一代的暮光巨龙中充当典范，带着其子嗣吞噬艾泽拉斯的生命。然而，他们却总是把无与伦比的力量浪费在争斗和口角上。",
},
[2512] = {
["Title"] = "茂林古树",
["Description"] = "米斯塔科里亚教授和艾基斯塔兹教授在清理植物学实验室的过程中所使用的魔法稍微过火了一点，现在他们遇到了巨大而繁茂的植物问题，这棵茂林古树很有可能会使他们的辛勤劳作化为乌有。",
},
[2520] = {
["Title"] = "鳞长萨卡雷斯",
["Description"] = "身为碎裂之焰的首领，萨卡雷斯与其他龙希尔分道扬镳，想闯出新的未来。随后他带领部队来到了亚贝鲁斯，希望获取这份遗产。在他眼里，这份遗产本来就属于他们一族，他愿意为此付出一切。",
},
[158] = {
["Title"] = "升腾者议会",
["Description"] = "和大多数被转化成元素生物的强大暮光之锤邪教徒一样，升腾者议会的成员早已忘记了他们作为凡人的存在。他们在邪恶的圣堂里监管着新的升腾者候选人的选拔。",
},
[2528] = {
["Title"] = "时间流具象",
["Description"] = "时间之沙的具象。这个古老的存在一直在观察着，等待着时间流出现危机的时刻。她无法阻止永恒龙军团一路轰开通向过去的道路。现在她面对着更多的闯入者，而她也不愿一再失败。",
},
[2532] = {
["Title"] = "警戒管事兹斯卡恩",
["Description"] = "很久以前，兹斯卡恩受命测试奈萨里奥实验产物的强度。只有最强大的产物才能够符合要求，得以保命。焰影熔炉新进的拜访者吸引了他的注意力，但想通过他的考验可没那么容易。",
},
[2536] = {
["Title"] = "米罗克",
["Description"] = "米罗克是克罗米在另一个时间线的形态，那个时间线里姆诺兹多得以崛起，永恒龙统御了一切。可凑巧的是，她很喜欢到正确的时间线来活动，她不希望这一点有所变化。而不幸的是，艾泽拉斯的英雄们不断地给她的计划添麻烦。",
},
[2556] = {
["Title"] = "尼穆威，轮回编织者",
["Description"] = "艾欧娜尔和弗蕾亚塑造梦境时，派遣尼穆威驻守在这片茏葱的国度。它在圣泉神殿对翡翠梦境进行定序，并保护着随之而来的秩序，将无序的荒野编织成了复杂的模式。",
},
[2560] = {
["Title"] = "蜡烛之王",
["Description"] = "蜡烛之王是狗头人王国的暴君。他的臣民都在矿井里为他辛苦劳作，直到一位来自远方的外乡人偷走了他的王冠并将他废黜。如今他逃进了暗焰裂口的深处，满腔怒火的他誓要卷土重来。让他的火焰就此熄灭吧。",
},
[2564] = {
["Title"] = "瘤根",
["Description"] = "这棵古树曾经苍翠挺拔，忠心耿耿地守护着翡翠梦境，但如今，它被烈焰蹂躏后，只想毁灭一切。",
},
[2568] = {
["Title"] = "虚空石畸体",
["Description"] = "这是由腐化的驭雷者组成的怪异融合体，这团诞生于虚空的庞然大物只知道痛苦和制造痛苦的手段。只有摧毁它才能净化风暴之栖和其中的栖巢。",
},
[2572] = {
["Title"] = "E.D.N.A.",
["Description"] = "启动防御协议！土灵防御与灭除自动体已激活。非正式名称：E.D.N.A。此魔像会对任何潜在的入侵者采取不可预见的紧急措施。虽然它的主要指令是灭除斯卡丁，但任何未经授权的入侵者都会引发它作出致命应对。",
},
[2580] = {
["Title"] = "代言人夏多克朗",
["Description"] = "身为玄夜会的新领袖，夏多克朗与艾基-卡赫特结盟，策划了一出窃取旗舰破晨号的大胆计划。她曾经是隐修院的焰牧，如今则被贝雷达尔之影的黑暗所吞噬。",
},
[2584] = {
["Title"] = "阿努布泽克特",
["Description"] = "虽然阿努布泽克特还没有获得扬升，但他已经得到了监督艾拉-卡拉收割行动的殊荣。阿努布泽克特的战术风格彪悍，自己也强悍无比，如果他的军队不足以保卫艾拉-卡拉，他会毫不犹豫地亲自上阵。",
},
[2588] = {
["Title"] = "本克·鸣蜂",
["Description"] = "本克的养蜂资质可能值得商榷，但他确实有控制蜜蜂和简化蜂蜜提取流程的诀窍。不过他的干预限制了蜜蜂的自由，也牺牲了蜜酒的质量，这是不能容忍的。",
},
[2596] = {
["Title"] = "大捻接师艾佐",
["Description"] = "长久以来，进化一直都是蛛魔生活的核心部分，而没有蛛魔比艾佐更痴迷于此，更精于此道。安苏雷克赐予了艾佐扬升的方法，艾佐则坚定地追求这条完美之路，并不关心到底是在为谁效力、目的为何，也不在乎付出怎样的代价。",
},
[2600] = {
["Title"] = "凝结聚合体",
["Description"] = "大捻接师艾佐的进化实验经常会带来废物和淤泥等副产品。对某些人来说，这些恶心的淤泥似乎毫无用处，但艾佐会发挥聪明才智，把它们变成更多实验的绝佳材料——以及一个静候生命的恶毒怪物。",
},
[2608] = {
["Title"] = "流丝之庭",
["Description"] = "甲虫领主阿努巴拉什和纺束者塔卡兹基是安苏雷克女王最信任的顾问，但这两位强大的蛛魔对彼此的仇恨甚至比对王权的忠诚更为强烈。他们争相向敌人倾泻强大的力量，还不忘将对方置之死地。",
},
[2612] = {
["Title"] = "虫巢扭曲者欧维纳克斯",
["Description"] = "在女王宫殿的深处，虫巢扭曲者欧维纳克斯正在用艾基-卡赫特发现的黑血进行可怕的实验。这个肥硕的恐怖生物在王宫的深处蹒跚而行，将漆黑的淤泥灌入幼虫的体内，观察它们身上可怕的效果。",
},
[2620] = {
["Title"] = "“船长”曲奇",
["Description"] = "随着迪菲亚兄弟会前任无畏舰指挥官的死亡，曲奇自封为船长。尽管他在主厨的工作上仍然尽职尽责，但若是有谁质疑其船长的头衔来得是否光明磊落，那人就会因为严重的食物中毒而倒地不起。",
},
[2624] = {
["Title"] = "格拉布托克",
["Description"] = "只是一阵心血来潮，格拉布托克就释放出强大的魔法力量，把他的食人魔山给夷为了平地。听到这个消息，迪菲亚立刻雇佣了这只硕大的食人魔法师作为死亡矿井的工头，借助他毁灭性的天赋来监督那些劳工。",
},
[2628] = {
["Title"] = "基尔尼格",
["Description"] = "天才工程师基尔尼格是迪菲亚兄弟会行动体系中的冶炼主管。他负责为无畏舰装配充足的火炮和弹药，不完成使命便誓不罢休。",
},
[2632] = {
["Title"] = "曲奇",
["Description"] = "除了艾德温·范克里夫，没人知道曲奇怎么稀里糊涂地成了随船的厨子。不过对海盗而言，有饭吃就不错了。",
},
[2636] = {
["Title"] = "修拉伊，地渊之海的暴虐者",
["Description"] = "海床所掩盖的恐怖超乎我们的想象。陨圣峪距离地渊之海近在咫尺，因而成为了深渊住民的掌中之物，蜃鱼人也在不遗余力地把握良机。他们的召唤令修拉伊，地渊之海的暴虐者得以崛起，在他们的狩猎场上横行无忌。修拉伊是由最可怕的恐魔与海渊深处的腐肉所组成的聚合体，要想阻止它，阿拉希人需要所有可能的援手。",
},
[2640] = {
["Title"] = "血腥大熔炉",
["Description"] = "历史的长河见证了许多史诗之战，但在最为劲爆的这场大战中，交战的双方分别是电光四射的风暴巨猩托克，以及一头熔火机甲暴龙，狂龙弗莱兰多。今夜，所有人只为见证两位冠军在大熔炉内战个天翻地覆，把整个安德麦都撕成两半！快来见证这场腥风血雨，否则你就是地精之耻！",
},
[2644] = {
["Title"] = "独臂盗匪",
["Description"] = "独臂盗匪是加里维克斯娱乐城中的一台高端游戏机。这台令人愉悦的游戏设备只有一个简单的要求：公平游戏，不能作弊。只不过判断作弊的标准一直是个谜，而它的独臂能够施加的惩罚可不是开玩笑的。",
},
[2648] = {
["Title"] = "老大娘",
["Description"] = "由席尔瓦·层烁驾驶的原型机甲，代号“老大娘”，已被部署到水能堡地区开展运营安保工作，负责为加里维克斯的阴谋保驾护航。这台机甲配备了令人眼花缭乱的通讯装置，暗索的黑血试验品更是令它如虎添翼。",
},
[2664] = {
["Title"] = "贝尔加",
["Description"] = "可怕的熔岩巨人贝尔加在黑铁大道上隆隆缓行，黑铁大道是筑于黑石深渊内部的矮人工程学建筑奇迹。拉格纳罗斯将这巨人从火焰之地的中心地带引来这里，命他看守位于大道尽头的封印重门。相传，只有炎魔之王和黑铁氏族最德高望重的成员才知道在那扇神秘的大门背后，究竟藏着什么。",
},
[167] = {
["Title"] = "古加尔",
["Description"] = "在古加尔的控制下，暮锤氏族的兽人已经变成了一支嗜杀的邪教，盲目地崇拜着上古之神及其使者死亡之翼。因为长时间地同他那黑暗的主子接触，古加尔的身心已经遭到了异常的扭曲。",
},
[2676] = {
["Title"] = "塔尔·巴特和阿瓦兹吉",
["Description"] = "作为撰魂师的左膀右臂，塔尔·巴特会不惜代价实现她的愿望。猛兽之王和狂野的迁跃兽阿瓦兹吉建立了牢不可破的情谊，也掌握了它独一无二的天赋。一人一兽如今进退如一，灵活地穿梭在相位之间，袭击胆敢阻挠撰魂师复仇的敌人。",
},
[168] = {
["Title"] = "希奈丝特拉",
["Description"] = "作为死亡之翼的原配，希奈丝特拉创造了第一代暮光巨龙，却在之后被自己所诞下的可怖生物所泯灭。如今的她只是一具疮痍满布的枯骸，被恶毒的魔法所复生，监管着新一代暮光龙群的诞生。",
},
[2688] = {
["Title"] = "狩魂猎手",
["Description"] = "阿达拉斯·暮焰是一名充盈着深渊之力的恶魔猎手，他渴望吞噬法力熔炉：欧米伽周围全部的虚空能量。他与心狠手辣的盟友伊莉萨·悲夜和维拉瑞安·血愤达成联手，将一同歼灭所有挡路的敌人。",
},
[169] = {
["Title"] = "全能金刚防御系统",
["Description"] = "全能金刚防御系统曾被标榜为黑铁矮人最伟大的技术奇迹。当奈法利安来到黑翼血环时，他修复了这个当时业已废弃的系统，并用其歼灭任何胆敢闯入他实验室的人。",
},
[170] = {
["Title"] = "熔喉",
["Description"] = "熔喉是一只巨大的岩浆虫。几个世纪前，它被拉格纳罗斯的黑铁奴仆们从火焰之地召唤出来。一开始奈法利安觉得熔喉不过是只麻烦的害虫，不过后来他养成了一个特别的习惯……用这头畜生来处理失败的试验品……",
},
[171] = {
["Title"] = "艾卓曼德斯",
["Description"] = "艾卓曼德斯，又称实验体25463-D，是企图为一只黑龙幼崽强化感知力而诞生的失败作品。剧毒的药膏夺去了他的视力，迫使他只能靠嗅觉和听觉来生存。刨去艾卓曼德斯邪恶非凡这一点来看，这还真是个悲惨的故事。",
},
[172] = {
["Title"] = "奇美隆",
["Description"] = "恐怖、丑恶、邪恶。杀了它。",
},
[173] = {
["Title"] = "马洛拉克",
["Description"] = "马洛原是一名前途无量的人类炼金师，直到奈法利安将他绑架，并把他同一具龙兽的尸体融合在一起。结果就造出了这名笨手笨脚、只有几分前世心智残存的仆从：马洛拉克。",
},
[174] = {
["Title"] = "奈法利安的末日",
["Description"] = "因为曾使用艾泽拉斯各大龙族军团的精华来创造多彩巨龙，死亡之翼之子奈法利安变得臭名昭著。在他死于黑翼之巢后，死亡之翼将他复活，并赐予其新的力量，让他继续那邪恶的计划。",
},
[175] = {
["Title"] = "高阶祭司温诺希斯",
["Description"] = "温诺希斯本来是被派去杀死哈卡的，可他却被那凶残的存在所奴役，直到艾泽拉斯的英雄们完成了他的使命。在夺灵者的使徒们的努力下，温诺希斯从灵魂世界转生，受命和他的毒蛇一起守卫祖尔格拉布。",
},
[176] = {
["Title"] = "血领主曼多基尔",
["Description"] = "恶名昭著的血领主曼多基尔多年前备受折磨而死，之后其尸体更是被血顶巨魔所亵渎。风传曼多基尔将其恶毒的灵魂寄宿在强大的血顶酋长甘祖拉恩的尸体里，血领主再一次出现在了荆棘谷的丛林中。",
},
[177] = {
["Title"] = "疯狂之缘——格里雷克",
["Description"] = "疯狂之缘里有四名充满仇恨的灵魂：可怕的巨魔格里雷克被神剥夺了再生能力；战士雷纳塔基以热衷施虐而臭名昭著；先知哈扎拉尔整日被恐怖的未来预言所折磨；强大的战将乌苏雷则拥有号令风暴的力量。",
},
[178] = {
["Title"] = "疯狂之缘——哈扎拉尔",
["Description"] = "疯狂之缘里有四名充满仇恨的灵魂：可怕的巨魔格里雷克被神剥夺了再生能力；战士雷纳塔基以热衷施虐而臭名昭著；先知哈扎拉尔整日被恐怖的未来预言所折磨；强大的战将乌苏雷则拥有号令风暴的力量。",
},
[179] = {
["Title"] = "疯狂之缘——雷纳塔基",
["Description"] = "疯狂之缘里有四名充满仇恨的灵魂：可怕的巨魔格里雷克被神剥夺了再生能力；战士雷纳塔基以热衷施虐而臭名昭著；先知哈扎拉尔整日被恐怖的未来预言所折磨；强大的战将乌苏雷则拥有号令风暴的力量。",
},
[180] = {
["Title"] = "疯狂之缘——乌苏雷",
["Description"] = "疯狂之缘里有四名充满仇恨的灵魂：可怕的巨魔格里雷克被神剥夺了再生能力；战士雷纳塔基以热衷施虐而臭名昭著；先知哈扎拉尔整日被恐怖的未来预言所折磨；强大的战将乌苏雷则拥有号令风暴的力量。",
},
[181] = {
["Title"] = "高阶祭司基尔娜拉",
["Description"] = "高阶祭司娅尔罗被杀之后，豹神贝瑟克选择她的妹妹基尔娜拉作为其新的凡间代表。为了支持最近古拉巴什和赞达拉部落达成的协议，基尔娜拉放出了她凶残的猎豹，来对付这里不设防的住民。",
},
[184] = {
["Title"] = "赞吉尔",
["Description"] = "因为把同胞变成了丧失心智的奴隶，赞吉尔一度被劈颅部落所放逐。为了壮大祖尔格拉布的军队，碎神者金度让他在古拉巴什中任职。众所周知，起死回生这种事，对他的药剂来说一点都不难。",
},
[185] = {
["Title"] = "碎神者金度",
["Description"] = "在祖尔格拉布被打败之后，金度的灵魂因为没能满足哈卡的愿望而饱受折磨。但最近，他通过某种办法回到了现世，并奴役了夺灵者。带着恐怖神灵的可怕力量，金度誓要恢复古拉巴什帝国往日的辉煌。",
},
[186] = {
["Title"] = "埃基尔松",
["Description"] = "作为阿曼尼部落曾经的萨满，埃基尔松驾驭空气元素的本领令人赞赏。他的天赋被妖术领主玛拉卡斯所看中，这也让巨魔们的鹰神没费太大力气就找到了合适的宿主。",
},
[187] = {
["Title"] = "纳洛拉克",
["Description"] = "纳洛拉克在战场上以其可怕的怒火和野蛮的力量而著称，妖术领主玛拉卡斯认为他是承载熊神精华的理想容器。",
},
[188] = {
["Title"] = "加亚莱",
["Description"] = "龙鹰是敏捷的猛禽，其利爪可以轻易地撕碎敌人。阿曼尼部族也有这样一只训练有素的野兽，它就是加亚莱。",
},
[189] = {
["Title"] = "哈尔拉兹",
["Description"] = "艾泽拉斯的山猫是凶猛的猎手，拥有能够撕碎猎物的利爪和利齿。受启发的妖术领主玛拉卡斯觉得，在部族最厉害的猎手里挑一名，把山猫之神的精华封在里面，应该很合适。",
},
[190] = {
["Title"] = "妖术领主玛拉卡斯",
["Description"] = "数十年来，妖术领主玛拉卡斯都被说成是阿曼尼部族里最可怕的巫医。他的所作所为令人难以想象，还将数名强大的巨魔动物神灵的精华封存在部族最强壮的战士体内……而他也把最为黑暗的一只寄宿在了自己身上。",
},
[191] = {
["Title"] = "达卡拉",
["Description"] = "为了弥补督军祖尔金死后所形成的权力真空，阿曼尼部族余下的巨魔们推举他们最喜爱的常胜将军：战无不胜的达卡拉来恢复他们失落的荣光。",
},
[192] = {
["Title"] = "贝丝缇拉克",
["Description"] = "作为烬网蜘蛛的蛛母，贝丝缇拉克和她无情的后代们靠吮吸火元素残骸上的岩浆和火焰来满足他们的食欲。为了给她的子嗣们提供更多的养分，贝丝缇拉克在她的巢穴周围编织了一张巨大的火网，用来诱捕误入其中的猎物。",
},
[193] = {
["Title"] = "雷奥利斯领主",
["Description"] = "雷奥利斯是现存最古老的元素生物之一，他源自创造艾泽拉斯的洪荒烈焰。他负责在火焰之地创造新的元素，同时他认为那些将他迁移的泰坦们过于的傲慢，这股仇恨仍在他胸中燃烧。",
},
[194] = {
["Title"] = "奥利瑟拉佐尔",
["Description"] = "当拉格纳罗斯的军队涌入海加尔山时，绿龙奥利瑟拉背叛了盟军，帮忙把叛变的大德鲁伊范达尔·鹿盔放了出来。作为奖赏，她被烈焰所净化，重生成了一只可怕的火鹰。",
},
[195] = {
["Title"] = "沙恩诺克斯",
["Description"] = "在火焰之地的元素守护者中，火妖是最为恐怖的一类。沙恩诺克斯也不例外。身为拉格纳罗斯帐下的首席猎人兼熔火恶犬驯犬人，沙恩诺克斯巡视着这块元素的领域，陪伴着他的是两只最为凶猛的畜生：裂肢和狂脸。",
},
[196] = {
["Title"] = "护门人贝尔洛克",
["Description"] = "在上古时代艾泽拉斯的元素战争中，贝尔洛克作为一名无情的战士而声名鹊起。如今他被困在了火焰之地，变得愈发不理智起来。很少有元素敢来打扰他，生怕牺牲在他对战斗的渴望之下。",
},
[197] = {
["Title"] = "管理者鹿盔",
["Description"] = "在流沙之战中痛失爱子瓦斯坦恩一事，彻底击垮了范达尔·鹿盔的精神。现在，他被拉格纳罗斯灌注力量，成了火焰之地新任的管理者（顶替死亡的管理者埃克索图斯），并兼任背叛塞纳里奥议会的烈焰德鲁伊首领。范达尔宁愿毁掉艾泽拉斯，也不要活在这个失去爱子的世界里。",
},
[198] = {
["Title"] = "拉格纳罗斯",
["Description"] = "火焰之地的领主拉格纳罗斯象征着愤怒与毁灭，一如铸就了艾泽拉斯的原初地狱之火。上古之神向拉格纳罗斯保证，他有机会把艾泽拉斯变成一片火海，而耐普图隆和塞拉赞恩将对此无能为力。为了取悦上古之神，拉格纳罗斯誓要点燃诺达希尔的世界之树。",
},
[471] = {
["Title"] = "加加恩·火锤",
["Description"] = "在铜须矮人发现奥达曼后，黑铁部族迅速做出反应，对这座地下宝库发起入侵，以防那些强大的神器落入先祖敌人之手。加加恩·火锤——来自暗炉城的参议员，被派去监督奥达曼的挖掘工作，以确保皇帝能利用神器的毁灭性潜能消灭黑铁部族的敌人。",
},
[2762] = {
["Title"] = "雷什诺尔，无拘者",
["Description"] = "在迪门修斯来袭之后，卡雷什的虚灵第一次目睹了这头虚空巨龙的破坏力。他们相信雷什诺尔的降临正是对他们永远的惩罚。多年以来，雷什诺尔总是反复出现，接连不断地吞噬生灵与星球，体型也变得越发庞大。",
},
[2690] = {
["Title"] = "节点之王萨哈达尔",
["Description"] = "作为卡雷什的前统治者、迪门修斯的宿敌，节点之王萨哈达尔从卡雷什破碎的残骸中傲然现身。如今，萨哈达尔跨上了皇家虚空之翼，统御着影卫的至高意志。誓约终将兑现。万物皆将为之效力。",
},
[2686] = {
["Title"] = "卢米萨尔",
["Description"] = "卢米萨尔是被影卫有意培育出的特殊生物，凭借其独特的能力，能够在织造大量丝线的过程中注入奥术能量。卢米萨尔被束缚于法力熔炉的机械装置中，为其主人不断纺出无尽的奥术丝线。",
},
[417] = {
["Title"] = "戈多克大王",
["Description"] = "谁要是想统治戈多克食人魔，只须站出来自封为王……然后消灭所有心怀异议的人即可。戈多克大王——当时人称乌尔洛克——就是劝服了十二位族中最为强大的战士，同时挑战国王，以此巩固自己的力量。一场疯狂混战过后，比试者死的死伤的伤，乌尔洛克手起刀落，不费吹灰之力就结果了那些幸存者和被战斗搞得疲累交加的国王。时至今日，每当戈多克食人魔提及“血战之日”时，还是只敢低声窃语。",
},
[2684] = {
["Title"] = "集能哨兵",
["Description"] = "集能哨兵在法力熔炉：欧米伽的巨构中往来巡视，确保破碎世界卡雷什的能量经过结构导管的过滤。所有输入的能量都会经过杀菌消毒，所有污染物质都将得到净除。",
},
[2677] = {
["Title"] = "撰魂师",
["Description"] = "撰魂师曾经是卡雷什神谕者的领袖，但母星的毁灭令他们只能在废土中流浪。他们的复仇之战由此拉开了序幕。她立下了古老的誓言，一定要毁灭萨哈达尔的敌人，还有他们所建立的一切。随着她逐渐找回了远古的力量，这座圆顶的未来也越发黯淡。",
},
[2670] = {
["Title"] = "达格兰·索瑞森大帝",
["Description"] = "达格兰·索瑞森大帝与敌对铜须部族的茉艾拉公主共掌统治大权。没人知道新娘究竟是受到了大帝的迷惑，还是自愿与他作伴。但不论真相如何，索瑞森的继续存在，始终会对他部族的未来造成不良影响。只要他还活着，黑铁矮人就仍是拉格纳罗斯的马前卒，也是艾泽拉斯各个王国的致命威胁。",
},
[405] = {
["Title"] = "荒野变形者奥兹恩",
["Description"] = "荒野变形者奥兹恩毕生最大的追求就是彻底腐化菲拉斯，但当他在厄运之槌中发现艾德雷斯神殿以前，他没有取得丝毫成功。现在，被奴役先祖的力量任他指挥，奥兹恩将附近森林的生命之力悉数汇聚到自己的巢穴中，随意支配。",
},
[2668] = {
["Title"] = "怒炉将军",
["Description"] = "经过毕生钻研，怒炉将军已成为矮人军事历史与用兵学的行家里手。他最近撰写了一篇抨击部族过往败绩的严苛文章，引得达格兰·索瑞森大帝大发雷霆。抛开这个政治错误不提，怒炉本质上还是个够格的黑铁矮人。为保护自己的人民与皇帝，他甘愿流血，乃至牺牲。",
},
[90] = {
["Title"] = "赫利克斯·破甲",
["Description"] = "赫利克斯从前是锈水财阀的工匠，可之后他收到了迪菲亚兄弟会的一笔款项，足以让他那样的无名部落工程师所做的一切都一文不值。就像所有精明的地精会做的那样，他迅速接下了这份工作，声称不再对前任雇主效忠。",
},
[2654] = {
["Title"] = "“屠夫”血钩",
["Description"] = "“屠夫”血钩的残忍之名响彻库尔提拉斯。在铁潮突袭队的支持下，“屠夫”在整个伯拉勒斯横行，沿途留下一片狼藉。",
},
[2653] = {
["Title"] = "链齿狂人洛肯斯多",
["Description"] = "作为加里维克斯的顶尖智囊，链齿狂人洛肯斯多总会大胆创新，他的发明清单已经比他精炼厂的传送带还要长得多了。为了同时提高效率和节省开支，洛肯斯多一直在寻找用于测试工具的新兴市场。",
},
[2650] = {
["Title"] = "沼面",
["Description"] = "水能堡的河床之下埋藏着一只休眠的野兽。水坝附近的骚乱吵醒了沼面，从泥潭中现身的它头脑昏沉却满心怒火，只想将第一个会动的玩意儿碾得粉碎。",
},
[2390] = {
["Title"] = "无堕者哈夫",
["Description"] = "哈夫击败过的敌人数不胜数，想要挑战他的人足以排起长队。如果有人能力压群雄，哈夫便能好好享受一场旗鼓相当的挑战。",
},
[2645] = {
["Title"] = "穆格·兹伊，安保头子",
["Description"] = "自出生的那一天起，穆格·兹伊魁梧的食人魔躯体上就长着两个脑袋，于是被加里维克斯专门招来监视娱乐城日常活动。最近的几周，穆格·兹伊被调到了新岗位，负责守卫加乐宫最深处的房间，不允许任何人踏足。",
},
[2405] = {
["Title"] = "特雷德奥瓦",
["Description"] = "戈姆们一直在炽蓝仙野的边缘地带咀嚼着、吞噬着逝去者的干瘪躯壳。但这只名为特雷德奥瓦的野兽却吞下了其他更为宝贵的东西——雷卡利，学识神灵的灵种。特雷德奥瓦已经品尝到了神灵力量与学识的滋味，所以她现在渴望着更多的知识，而不光只是生存。",
},
[2413] = {
["Title"] = "宫务大臣",
["Description"] = "宫务大臣通过残忍的手段在温西尔社会中步步攀升，并在拘捕叛变指控者的行动中出了一份力，从而晋升为收割者。如今，他统治着指控者的大厅，囤积着心能，为了达到自己反常的目的而扭曲了神圣的赎罪过程。",
},
[2417] = {
["Title"] = "无尽女皇莫德蕾莎",
["Description"] = "在无数场战斗和无数次胜利后，莫德蕾莎已经击败了所有挑战她的人。她生前精通的黑暗魔法在来到玛卓克萨斯后变得更为精进。今天就是伤逝剧场一直渴望看到的头衔争夺战吗？",
},
[2630] = {
["Title"] = "绿皮船长",
["Description"] = "来自藏宝海湾的绿皮是正在修造的无畏舰的船长，曾经统率过一整支海盗的舰队。",
},
[375] = {
["Title"] = "典狱官斯迪尔基斯",
["Description"] = "在对索瑞森大帝尽忠多年后，这位名叫斯迪尔基斯的狡诈法师赢得了大帝的信任，奉命看守其部族在黑色宝库中的宝箱。挚友驯犬者格雷布玛尔将一条凶犬——维雷克送给了这位忠心耿耿的矮人，以表达祝贺之情。法师对其善加利用，随时将它带在身边，以吓退那些擅闯宝库的贼人。",
},
[2626] = {
["Title"] = "斯尼德",
["Description"] = "残酷无情的效率为斯尼德赢得了伐木主管的岗位。他的目标非常简单：以尽可能低廉的成本建造一艘无畏舰。凭借自己建造的伐木机，他在生产作业中一马当先，做出了迅速而惊人的成绩。",
},
[108] = {
["Title"] = "如花",
["Description"] = "如花和比斯巨兽的传说犹如美女与野兽、海洋与星空一般悠久而浪漫。比斯巨兽在黑石塔上被英雄们宰杀之后，如花带着四条剩下的小犬加入了暮光之锤的部队，志在惩罚那些杀害她的伴侣的生物。",
},
[2622] = {
["Title"] = "死神5000",
["Description"] = "迪菲亚的工程师们在死神4000的基础上，日以继夜地想要完善出一种新型号的收割机。兄弟会相信，只要完工，这台恐怖的机械就能像割麦子一样从暴风城的武装士兵中杀出一条路来。",
},
[430] = {
["Title"] = "洛特格里普",
["Description"] = "有传闻说，洛特格里普已经在玛拉顿的地下水域中居住了上千年。大名鼎鼎的矮人猎手赫米特·奈辛瓦里有一次宣称无人能找到这野兽，于是就有许多业余追踪者接受挑战，立志寻找这只传说中的生物。结果全都有去无回。",
},
[2618] = {
["Title"] = "达加·燃影者",
["Description"] = "这名暮光之锤的术士正在执行一个来自暮光堡垒的任务。如果英雄们能够征服他那些烈焰的爪牙，达加就会让艾泽拉斯的保卫者们见证一个真实的末日预言。",
},
[372] = {
["Title"] = "秩序竞技场",
["Description"] = "对黑铁矮人犯下罪行的人只会受到一种惩罚，那就是死亡。根据古老的传统，有罪之人要在秩序竞技场中对抗来自艾泽拉斯的各种凶残生物，付出鲜血的代价。迄今为止，没人知道是否有在这残忍酷刑中侥幸生还的幸运儿。",
},
[92] = {
["Title"] = "撕心狼将军",
["Description"] = "詹姆斯·哈林顿身中狼人的诅咒后，在一个刺骨的寒夜里毁掉了钟爱的家庭和他的远洋航海生涯。在那之后，他改名为撕心狼，逃到了西部荒野，之后更是接受了任命，指挥迪菲亚兄弟会可怖的无畏舰。",
},
[99] = {
["Title"] = "沃登勋爵",
["Description"] = "高弗雷的左右手、傲慢的沃登勋爵曾发誓不惜一切代价，也要为其同胞鞠躬尽瘁。如今成了亡灵的一员，沃登依然信守诺言，用冰与毒对敌人发起猛攻。",
},
[476] = {
["Title"] = "皮萨斯",
["Description"] = "作为纳拉雷克斯的儿时玩伴，战士阿里恩在德鲁伊之道上有着过人的天赋。尽管受过严格训练，但这位侍僧却仍无力对抗令他丧失理智的腐化。阿里恩改名换姓，以皮萨斯的新身份将自己超凡的近战能力与德鲁伊的学识合二为一，粉碎一切入侵者。",
},
[2594] = {
["Title"] = "演说者基克斯威兹克",
["Description"] = "身为第五帛丝的演说者基克斯威兹克无比渴望扬升，整天都在颂扬安苏雷克女王的美德，指望能获得她的青睐。虽然他痴迷于此，却也不是毫无防备。如果有人敢惹这位演说者，就会发现他的狺狺狂吠可比他的撕咬厉害得多。",
},
[2454] = {
["Title"] = "卖品会",
["Description"] = "赛财团“采购”了稀有而宝贵的物品来出售，拍卖的货物百无禁忌，珍奇猛兽、禁忌科技、乃至被诅咒的神器，一应俱全。只要你付得起价钱，赛财团一定能帮你采购到。",
},
[2589] = {
["Title"] = "戈尔迪·底爵",
["Description"] = "精明的女商人戈尔迪·底爵总能抓住好机会——就比如燧酿酒庄。在连抢带骗拐走了文布兰德的生意之后，戈尔迪把主要的运营工作都交给了她的党羽。即便如此，她也不怕卷起袖子来教训那些声称要伸张正义的家伙。",
},
[2449] = {
["Title"] = "时空船长钩尾",
["Description"] = "当索·莉亚在时空船长钩尾的劫掠中凭空出现，将珍宝从她的爪子中盗走，几个月的深谋远虑全都打了水漂。被怒火吞噬的海盗女王展露了自己的真实形态，开始向眼前的所有人肆意宣泄愤怒。",
},
[2581] = {
["Title"] = "阿努布伊卡基",
["Description"] = "阿努布伊卡基是安苏雷克女王最杰出的战术家之一。他善于创造性地利用本地资源，因计划周密而闻名遐迩。他的士兵们对他有着狂热的忠诚。",
},
[2573] = {
["Title"] = "隐修院长穆普雷",
["Description"] = "隐修院长哈尔希·穆普雷指导建造了圣焰隐修院，在此深思神圣之星贝雷达尔的奥妙。尽管帝皇幻象对她来说依然扑朔迷离，但她发现了神圣烈焰的秘密，这将帮助他们战胜来自陨圣峪及帝国内部的敌人。",
},
[2570] = {
["Title"] = "布朗派克男爵",
["Description"] = "布朗派克男爵因弟弟的死而悲痛欲绝，他发誓效忠于隐修院长穆普雷。这位强大的骑士现在是她的私人执行者，保护修道院的秘密不为外来者和那些不够忠诚的阿拉希人的所知。",
},
[642] = {
["Title"] = "戈托克·苍蹄",
["Description"] = "维库人在乌特加德城堡里保存着许多战利品，戈托克是当中最令人印象深刻的一个。伊米隆国王用这一寒冰猛犸人的冷酷面容提醒人们，哪怕是最为凶残的野兽也只不过是维库人殿堂中的装饰物而已。这个活雕像一旦重获自由便会散播毁灭，不加选择地释放他心中的怒火。",
},
[2470] = {
["Title"] = "圣物匠赛·墨克斯",
["Description"] = "赛·墨克斯在纳斯利亚堡失利后，潜回阴影中谋划着下一次行动。如今，初诞者圣墓岌岌可危，赛·墨克斯便趁机召唤了赛财团的全部战力，前来劫掠深埋于此的远古知识和强大圣物。",
},
[641] = {
["Title"] = "席瓦拉·索格蕾",
["Description"] = "席瓦拉作为掠夺者因格瓦尔的副官而扬名于世，在部落和联盟的前哨站领导危险的侦察任务。正是她发现了敌人入侵乌特加德的计划，给了巫妖王准备的时间。为了表彰她所作出的贡献，巫妖王将她变成了维库人，成为了天灾军团倍受尊敬的女战士。",
},
[594] = {
["Title"] = "莫拉比",
["Description"] = "达卡莱巨魔想要牺牲犸托斯来获得力量，结果这位神灵却选择了自我毁灭。尽管如此，人们却不能否定莫拉比身上堪比神灵的力量。这位高阶先知饮下了神灵的鲜血，现在会不惜一切代价确保祖达克牢牢掌握在巨魔手中。",
},
[639] = {
["Title"] = "斯卡瓦尔德和达尔隆",
["Description"] = "依照维库人的传统，要让不太可能合作的伙伴相处共事。有人说这是为了让具备不同能力的人彼此之间实现互补，也有人说这是为了给伊米隆国王找乐子而已。不管怎样，斯卡瓦尔德和达尔隆都是这一风俗的完美榜样。一个是肌肉发达的维库人，一个是精通黑暗艺术的人类亡灵法师，他们会对任何妨碍天灾军团的人施以严惩。",
},
[2473] = {
["Title"] = "树口",
["Description"] = "这棵曾经无比自豪的古树因腐朽之力而枯萎，从而被豺狼人称为树口。腐烂侵入了它的枝条，也侵入了这个可怜生物的心灵，如今它一心只想强化和散播腐朽。",
},
[2474] = {
["Title"] = "腐朽主母怒眼",
["Description"] = "出于对力量的渴望，怒眼发现了腐朽魔法。她精通了这种魔法后，宣布自己是腐朽主母。现在她在部族里散布黑暗的魔法来提高蕨皮一族的战力，试图让海象人和碧蓝林海的所有生物都在她脚下腐烂。",
},
[2538] = {
["Title"] = "时空领主戴欧斯",
["Description"] = "终于，永恒龙军团将为艾泽拉斯世界带来崭新的黎明。时空领主戴欧斯深入遥远的过去，确保姆诺兹多必将崛起。之前艾泽拉斯的英雄们已经看到他成功过一次。但这一次，英雄们能阻止他吗？",
},
[625] = {
["Title"] = "魔网守护者埃雷苟斯",
["Description"] = "就连英雄也会在埃雷苟斯面前战栗，他是魔环的保护者，能量线导管的守卫者，也是不速之客的处决者。他将凭借对预言的笃信完成这些任务，守护着织法者帝国的完整和这里神秘的一切。",
},
[104] = {
["Title"] = "厄祖玛特",
["Description"] = "传说艾泽拉斯的大海出现过巨大的海怪，然而这个神话如今成了真。纳迦通过某种邪恶的手段，将海怪的宗主厄祖玛特控制在手下，用来对付耐普图隆及其追随者们。",
},
[524] = {
["Title"] = "大主教玛拉达尔",
["Description"] = "作为曾经雄霸奥金尼殿堂的唯一幸存遗老，当他所挚爱的一切人和物都在眼前消失殆尽时，玛拉达尔陷入了疯狂。他不遗余力地想要将过往的记忆留存住，这使他变成了精通黑暗艺术的大师。",
},
[317] = {
["Title"] = "缚风者哈格拉",
["Description"] = "哈格拉曾是跟随被遗忘者学习奥术魔法的第一人。作为一个这么晚才开始学习魔法的学徒，她表现出了惊人的天赋。可她肆无忌惮地进行魔法实验，试图奴役元素，最终被风元素领主奥拉基尔诱惑并扭曲。现在，她狂热地效忠暮光之锤，为她的元素主子们束缚并折磨那些牺牲品。",
},
[529] = {
["Title"] = "传令官瓦兹德",
["Description"] = "瓦兹德守卫着连接地狱火堡垒和黑暗神殿之间的补给运输、信息传递以及军队通行要道。瓦兹德的坐骑名叫纳杉，是条威风的虚空龙，他总是骑在纳杉背上，从空中用烈火、利爪和令人胆寒的尖叫声，对敌人发起势不可挡的攻势。",
},
[154] = {
["Title"] = "风之议会",
["Description"] = "随着南风之主希亚玛特被尼斐塞特所囚，奥拉基尔的副手们踊跃地想要填补风之议会里出现的权力真空。剩下的三名议会成员分别是：能够使用狂风治疗盟友或毒伤敌人的西风之主安舍尔，能够用风暴将最宏伟的山脉磨成齑粉的东风之主洛哈西，而葬送在北风之主尼希尔冰冷风暴之下的性命，比其他三位加起来的还要多。",
},
[532] = {
["Title"] = "女祭司德莉希亚",
["Description"] = "德莉希亚是效命于魔王基尔加丹的希瓦尔拉祭祀。当凯尔萨斯·逐日者在对风暴要塞的攻击中身负重伤时，正是德莉希亚救了他，从此她便跟在这位血精灵领主身边。这位女祭司手下有一批好战又忠实的侍从为其效命，并会不惜一切代价保护她。",
},
[533] = {
["Title"] = "凯尔萨斯·逐日者",
["Description"] = "凯尔萨斯·逐日者曾经是血精灵一族的真正勇士，也是血精灵古老遗产的守卫者，但却在恶魔基尔加丹留居外域时，沦为了他黑暗力量的牺牲品。在新主人的命令下，这位任性的王子回到艾泽拉斯夺取了太阳井，希望利用那魔力之泉为恶魔打开一道传送门，将他们送至这个全新未开化的世界上来。凯尔萨斯是一位卓越的战略家，一位强大的战士，在他的血脉中燃烧着无尽的邪恶魔法。",
},
[534] = {
["Title"] = "潘德莫努斯",
["Description"] = "这位臭名昭著的虚空领主又以混乱公爵、噬国者和灭世者的名号为人们所熟知。当虚灵的故乡卡雷什遭遇毁灭时，潘德莫努斯是迪门修斯麾下的一名指挥官。他后来受制于节点亲王沙法尔，为了继续满足他无休无止的欲望，不得不为虚灵效力。",
},
[134] = {
["Title"] = "地狱公爵埃鲁达克",
["Description"] = "死亡之翼派出了他最厉害的副手之一，旨在探寻强大的红龙牺牲性命也要保住的秘密。这名无面者将军来自深岩之洲的洞穴世界，任何敢于向他发起挑战的蠢货，都会被其体内融合的新生代龙族之力所消灭。",
},
[536] = {
["Title"] = "尤尔",
["Description"] = "这是伊利丹·怒风送出的“礼物”，以陪伴节点亲王沙法尔。尤尔是具有无限野性和力量的虚空猎犬。亲王的谏臣们提醒他，这份伊利丹送来的恶魔大礼很有可能暗藏着什么阴谋诡计，一旦达成目标就会背叛沙法尔。但亲王却把那些谏臣喂到了尤尔的肚子里……不过为了以防万一，他在那之后也把这只猎犬关进了一个静止的房间内。",
},
[537] = {
["Title"] = "节点亲王沙法尔",
["Description"] = "由于笃信在法力陵墓的地下深处埋藏着大量财富，节点亲王沙法尔花费了难以计数的个人钱财，将一支军队调遣到了这片破碎遗迹的暗影殿堂内，并将那些不安分的虚灵隔绝在外。亲王的贪欲无边无际，而且他发誓要揭开法力陵墓的秘密，不达目的誓不罢休。",
},
[632] = {
["Title"] = "塞安妮苟萨",
["Description"] = "玛里苟斯选择塞安妮苟萨来执行他的阴谋诡计，因为她有着毋庸置疑的忠诚。当她的主人陷入疯狂时，她没有退缩半分；当他霸占艾泽拉斯的魔网时，她也没有丝毫动摇；而且她一定会消灭所有胆敢违抗他的人。",
},
[539] = {
["Title"] = "斯卡洛克上尉",
["Description"] = "斯卡洛克上尉是埃德拉斯·布莱克摩尔的死忠，与至交好友奥里登·匹瑞诺德一同在敦霍尔德的军队中提升军衔。当奥里登决定对奥特兰克山脉采取行动时，斯卡洛克却选择留在他的领主兼良师身边。他后来成为了埃德拉斯最为信任的同伴和顾问，赢得了“布莱克摩尔之矛”的头衔。",
},
[540] = {
["Title"] = "时空猎手",
["Description"] = "这位名字神秘的时空猎手是永恒之龙军团派出的刺客，要赶在萨尔逃离敦霍尔德之前将他杀死，进而改变历史的进程。这条暗影龙在完成使命的过程中杀死过无数生灵，但这次却是他最为重要的一次暗杀。他将使出全部力量、能力、阴谋与诡计，来为这条时间线画上句号。",
},
[2524] = {
["Title"] = "扎卡利突袭",
["Description"] = "扎卡利战团在督军卡格尼的带领下对焰影熔炉发起了全面的进攻，想找到他们失踪的长老莱修克 。为了取得胜利，残暴冷酷的卡格尼不惜采用任何战术。",
},
[542] = {
["Title"] = "安苏",
["Description"] = "安苏是位神秘的鸟神，深受鸦人的崇拜，哪怕他们比他更加凶残。安苏的起源和力量与其它任何外域的陨落之神相比都大相径庭。纳鲁也对这一邪恶生物保持沉默，因为就算对于他们来说，安苏也可称得上是神秘莫测。",
},
[543] = {
["Title"] = "利爪之王艾吉斯",
["Description"] = "利爪之王艾吉斯是一群勇敢鸦人极富魅力的精神领袖，他们离开了位于泰罗卡森林的家园，前去寻找某位“预示之神”。他在睡梦中见到了这位神灵，领悟了深藏在奥金顿破碎殿堂中的启示。梦中的景象使艾吉斯陷入了疯狂，他现在自称是泰罗克转世，一位鸦人神话中的神圣英雄。",
},
[2523] = {
["Title"] = "奈萨里奥的回响",
["Description"] = "奈萨里奥的圣所隐藏在焰影熔炉深处，曾是大地守护者的安全港湾和研究基地。有人说，他强大力量的回响依然残存于此，谋划着黑龙军团的未来，思考着为了实现这未来，需要夺取怎样的力量。",
},
[2522] = {
["Title"] = "狱铸者卡扎拉",
["Description"] = "虽然奈萨里奥是很久以后才用上了源质装甲，但他在亚贝鲁斯创立之初就已经进行了这样的实验。源质和暗影烈焰的实验对象就是卡扎拉，而她实在是太过不稳定，所以奈萨里奥拒绝释放她。她被自己身上的源质装甲带来的极度痛苦所逼疯。而现在，她是焰影熔炉的守门人。",
},
[630] = {
["Title"] = "拉文索尔",
["Description"] = "冷酷狡诈的塞安妮苟萨释放出了熔火恶犬。达拉然的法师们将这只双头怪物囚禁在监狱里，原本是希望能平复它对鲜血的渴望，但多年的隔离生活丝毫没能改变它的本性。",
},
[549] = {
["Title"] = "末日预言者达尔莉安",
["Description"] = "在被纳鲁囚禁之前，达尔莉安是燃烧军团中最为邪恶好战的战士之一。和天怒预言者苏克拉底做了那么长时间的狱友，也没让她改掉自己的坏脾气。",
},
[550] = {
["Title"] = "天怒预言者苏克拉底",
["Description"] = "数千年前，苏克拉底在愤怒卫士当中享有尊贵的地位，站在燃烧军团的最高指挥官身边。监禁关不住他超强的自我意识。他的狱友也无能为力。",
},
[2482] = {
["Title"] = "瑟娜尔丝，冰冷之息",
["Description"] = "瑟娜尔丝是库洛格·恐怖图腾最邪恶的造物。这只巨大的蜘蛛冰冷无情，存在的唯一目的就是守护她成千上万的子嗣，等待它们孵化而出，好让艾泽拉斯在寒冬之网中陷入沉睡。",
},
[156] = {
["Title"] = "哈尔弗斯·碎龙者",
["Description"] = "受古加尔之赐，双头魔哈尔弗斯·碎龙者具备着超自然的力量和体力，能够捕获巨龙，来让暮光之锤的仪式得以为继。为此，他奴役了一头巨型的始祖龙，来帮他进行狩猎。",
},
[553] = {
["Title"] = "坦普卢斯",
["Description"] = "尽管相对年轻，坦普卢斯却在制定永恒之龙军团攻击计划的过程中发挥着重要作用。作为奖励，他被赋予了一项重要职责——将任何妄图干扰军团计划的宵小赶尽杀绝。",
},
[593] = {
["Title"] = "达卡莱巨像",
["Description"] = "巨魔们在施放巫毒法术时使用魔精的传统由来已久，但将那些法术融合在一起并注入魔像，却是极具革命性的突破。他们所取得的初步成功催生出了原始造物——巨像，并继而生成了无数哨兵。",
},
[2508] = {
["Title"] = "安布雷斯库",
["Description"] = "上万年前，安布雷斯库鲁莽地染指了原始的奥术力量。他长满了水晶增生后，被带到碧蓝魔馆，等待发现治疗的方法。但研究还未完成时，魔馆就被封印了，留下安布雷斯库在静滞状态沉睡……直到今天。",
},
[586] = {
["Title"] = "哈多诺克斯",
["Description"] = "在艾卓-尼鲁布即将陷落之际，蛛魔大臣们放出了一只蜘蛛，这只蜘蛛能在一天之内就成长到足以挑战巫妖王的不死军团。哈多诺克斯心中充满了为死去族人复仇的渴望，要从任何胆敢威胁其家园的人手中夺回失地。",
},
[1226] = {
["Title"] = "折铁者高尔山",
["Description"] = "作为一个强大的元素师，高尔山天生就有通过金属来塑造并引导能量的能力。他也因此充当了钢铁部落首次入侵艾泽拉斯的急先锋。他试图通过揭示藏在黑石塔中的，由黑铁矮人制造的上古符文中的秘密来强化自身，并静待下一步的指令。",
},
[623] = {
["Title"] = "瓦尔洛斯·云击",
["Description"] = "自从魔枢战争开始后，瓦尔洛斯·云击便负责协调针对龙眠联军的残忍进攻。他被召回以守卫魔环，而他手下的上尉和飞龙也已准备就绪。瓦尔洛斯还利用在魔环中涌动的力量来加强自己的防御。",
},
[285] = {
["Title"] = "吉安娜的残影",
["Description"] = "吉安娜·普罗德摩尔饱受折磨的投影已经惨遭撕裂并被注入了她的法杖碎片中。为了恢复时间流的平衡，你必须击败这个残影。可是，这位骄傲的前塞拉摩统治者掌握着毁灭性的魔法力量，而她这个时空错乱的幽灵投影同样如此。在这个未来的艾泽拉斯，她只是被分裂了，并且等待着……",
},
[1234] = {
["Title"] = "督军扎伊拉",
["Description"] = "当加尔鲁什命令铁军先锋部队赶赴艾泽拉斯执行任务时，他就曾告诫他们与那边的“昔日盟友”会合。这位盟友就是渴望复仇、凶狠残暴却又忠心耿耿的扎伊拉，龙喉氏族的督军。现如今，她已在黑石山的中心地带组装好灭世武器，复仇的时刻即将到来。",
},
[628] = {
["Title"] = "艾库隆",
["Description"] = "一位愚蠢的学徒从元素位面召唤了这个幽魂，却没料到那些愤怒的上古之神卫兵压根当不了宠物。艾库隆杀死了她的“准主人”，并从那天开始就赖在了紫罗兰监狱，急切地向她的狱卒复仇。",
},
[624] = {
["Title"] = "法师领主伊洛姆",
["Description"] = "伊洛姆背弃了肯瑞托，发誓效忠玛里苟斯，玛里苟斯自然求之不得地接受了他。这位变节的法师对蓝龙军团来说堪称无价之宝。他对肯瑞托的优势和弱点知道得一清二楚。他了解他们的思维方式。而他也会利用这知识毁灭他们。",
},
[289] = {
["Title"] = "姆诺兹多",
["Description"] = "游离于时间流之外，如今的姆诺兹多正是曾经崇高的时光之王，守护巨龙诺兹多姆。由于泰坦让诺兹多姆亲眼目睹了自己的死亡，饱受折磨的巨龙被上古之神所蒙骗。他企图扭转自己的宿命。于是，诺兹多姆破坏了时间的正常流转，并创造出了永恒之龙…艾泽拉斯的未来将被摧毁。",
},
[620] = {
["Title"] = "塑树者奥莫洛克",
["Description"] = "魔枢中难以置信的奥术能量改变了轻歌之林及其守卫者的形态。头脑简单的奥莫洛克被将他变形的强大能量牢牢控制住了。对于那些干扰他思考的入侵者，他很少废话，而是直接用暴力解决问题。",
},
[311] = {
["Title"] = "莫卓克",
["Description"] = "作为死亡之翼麾下最强大的元素生物，莫卓克曾是一个温顺的守护者。可现在，他却坚信，只有毁灭艾泽拉斯，他才有可能获得救赎。作为艾泽拉斯对抗暮光审判的最后希望，龙眠神殿尤其受到莫卓克的痛恨。",
},
[291] = {
["Title"] = "艾萨拉女王",
["Description"] = "歌颂艾萨拉女王的美丽、威严与强大的歌谣数不胜数，可也正是她的虚荣导致上层精灵召来了燃烧军团。现在，她正坐视她最信赖的法师们为萨格拉斯降临艾泽拉斯的传送门输送能量，让她的众多子民在黑暗泰坦降临之前死去。",
},
[1163] = {
["Title"] = "尼托格·雷塔",
["Description"] = "对于加尔鲁什引入德拉诺的全机械化重装部队而言，对火焰和爆炸有着极度狂热的尼托格可谓是指挥这支部队的不二人选。因此，他在钢铁部落内部蹿升得非常快。他负责管理整列恐轨号的火控系统，一心想要击溃沙塔斯的外围防御圈，并将那些试图对抗钢铁部落的敌人一网打尽。",
},
[583] = {
["Title"] = "埃曼尼塔",
["Description"] = "长久以来，在安卡赫特潮湿而不见天日的洞穴中，繁密地生长着各类真菌和其它温和的生物形态。然而就在不久前，尤格-萨隆将它的压迫意志散播进了这个原本独立的生态系统。上古之神用它强大的腐化之力将安卡赫特一只土著野兽扭曲成了畸形的生物，它就是埃曼尼塔，这是个毫无思想的恐怖怪兽，周身充满了从其主人身上取得的破坏能量。",
},
[292] = {
["Title"] = "玛诺洛斯与瓦罗森",
["Description"] = "瓦罗森是艾萨拉女王的亲卫队长，而玛诺洛斯则是在未来用自己的血液使所有兽人陷入堕落的深渊领主。现在他们组成了最后一道防线，抵御任何企图阻止萨格拉斯进入艾泽拉斯的势力。尽管泰兰德和伊利丹奋战至此，但永恒之井的动荡不安已经将艾泽拉斯的命运推向了危机的边缘。",
},
[584] = {
["Title"] = "传令官沃拉兹",
["Description"] = "在天灾军团入侵艾卓-尼鲁布期间，这个王国内的许多住民都逃进了地下隧道以躲避巫妖王的爪牙。但有一些人却挖得太深，使尤格-萨隆的卷须暴露在外。尤格-萨隆被这一骚乱吵醒了，于是派出了一名最为古老的战士——传令官沃拉兹，前去屠杀陷入围困的蛛魔，并将任何威胁到上古之神的蠢货全部歼灭。",
},
[1168] = {
["Title"] = "纳利什",
["Description"] = "耐奥祖在影月氏族的古老墓地进行着某种黑暗仪式，将现实世界撕开一个裂口，并任由虚空能量的溢出。食魂者纳利什正是通过这条裂隙进入到现实世界，并寻找可以吞噬的灵魂。纳利什由纯粹的黑暗能量所构成，渴望搜集并吞噬一切活物。",
},
[2093] = {
["Title"] = "海盗议会",
["Description"] = "拉乌尔船长、尤朵拉船长和乔里船长在自由镇内饮酒共谋。他们各自领导的黑齿帮，水鼠帮和破浪海盗现正齐聚在哈兰·斯威提的铁潮突袭队麾下。",
},
[2097] = {
["Title"] = "泥沙女王",
["Description"] = "人们对这只生活在监狱附近的沙里的怪物知之甚少。从没有人成功越狱，卫兵也只发现了散落的衣物和残骨。",
},
[627] = {
["Title"] = "摩拉格",
["Description"] = "塞安妮苟萨招募了摩拉格来帮她消灭达拉然那些胆敢忤逆蓝龙军团的法师。这个可怕的恶魔曾经效命于燃烧军团，用他七只眼睛的邪恶凝视重挫萨格拉斯的敌人。现在他将让艾泽拉斯的英雄们明白，不是谁都能随意进出紫罗兰监狱……",
},
[589] = {
["Title"] = "召唤者诺沃斯",
["Description"] = "诺沃斯向来都是投机主义者，想方设法超越他的平庸同伴。这位邪教徒将自己的心从身体里挖了出来，在死前几秒将这个仍在跳动的器官献给了自己的主人。他的进取心令主人大受感染，于是将他重塑成了巫妖。",
},
[2109] = {
["Title"] = "投币式群体打击者",
["Description"] = "地精吵架的时候，获胜的总是钱包最鼓的那个。为什么呢？因为有钱才请得起打手。",
},
[590] = {
["Title"] = "暴龙之王爵德",
["Description"] = "暴龙之王爵德是达卡莱巨魔中的传奇角色。相传，有个巨魔狩猎小队在天灾瘟疫肆虐的居住区里发现了一只强大的野兽。巨魔们驯服了这头魔暴龙，相信它自身就是一剂解毒药，能治愈在其族人中肆虐的可怕疫病。",
},
[591] = {
["Title"] = "先知萨隆亚",
["Description"] = "天灾军团势如破竹地挺近达克萨隆要塞，就算是盗取神灵之力也无力回天。眼看巨魔军团成群结队地在巫妖王身前倒下，萨隆亚现在只为自己的新主人预言胜利的捷报。",
},
[592] = {
["Title"] = "斯拉德兰",
["Description"] = "斯拉德兰毕生都在为神灵效忠，牺牲神灵让他感觉不到半点儿愉悦。当神灵的力量涌入他的身体时，这位高阶先知发誓，一定要让天灾军团也同样品尝到达卡莱巨魔被迫忍受的暴行。",
},
[2125] = {
["Title"] = "毒心三姝",
["Description"] = "身为第一批献身毒心女巫会的成员，三姐妹拥有各自专精的法术领域。现在她们正希望使用聚焦之虹，掌握更强大的力量。",
},
[2129] = {
["Title"] = "高莱克·图尔",
["Description"] = "两千年前，古代库尔提拉斯军队击败了高莱克·图尔及其嗜血的德鲁斯特。被困在枯败之地的高莱克·图尔卧薪尝胆，静待复仇的机会。如今，高莱克·图尔腐化了德鲁斯瓦的权力中心，他狂热的追随者们正密谋如何将自己的领袖释放出来。",
},
[2133] = {
["Title"] = "拜恩比吉中士",
["Description"] = "拜恩比吉中士是一名严酷的军官，雷厉风行，奉行铁腕统治。他相信软弱的代价只有死亡，会毫不犹豫地将反对自己的人送上绞刑架。",
},
[595] = {
["Title"] = "凶残的伊克",
["Description"] = "在对其进行多次武装未果后，达卡莱巨魔将他们失败的鳄鱼人实验封印了起来。当冰巨魔奋力抵抗入侵其挚爱家园的天灾军团时，伊克和他的仆从们则在等待着重获自由的时刻。",
},
[2141] = {
["Title"] = "基阿拉克",
["Description"] = "这只强大的翼手龙的巢穴位于祖达萨的群山之巅，那里空气稀薄，几乎没有生物能够存活。她常常飞到下方的沼泽，为自己的子嗣寻觅食物。",
},
[2145] = {
["Title"] = "塞塔里斯的化身",
["Description"] = "一股可怕的力量正掌控着塞塔里斯之心，想要将其彻底腐化。必须在这股邪恶之力完全扎根前拯救塞塔里斯，以免她重生为黑暗洛阿神灵，摧毁整个沃顿。",
},
[1195] = {
["Title"] = "泰克图斯",
["Description"] = "作为形成德拉诺大地的混乱之力的远古化身，泰克图斯被疯狂的白鬼兽人扭曲并奴役了——但就算是他们，也只能勉强驾驭这股自然的伟力。",
},
[2153] = {
["Title"] = "阿库希尔",
["Description"] = "深海中埋藏着许多遗失在时光长河中的强大秘密。这片海域的主人斯托颂勋爵唤醒了其中一只神秘生物，来保卫他神圣的殿堂。",
},
[2157] = {
["Title"] = "长者莉娅克萨",
["Description"] = "长者莉娅克萨身为戈霍恩虔诚的信徒，致力于通过鲜血献祭来进一步散播腐化。",
},
[1196] = {
["Title"] = "布兰肯斯波",
["Description"] = "布兰肯斯波是远古时代的深渊行者，钢铁部落停泊在悬槌堡附近水域的钢铁战蝎引起了他的注意。这位水栖巨人会在所到之处留下蔓延的真菌和苔藓，而原始本能则驱使他泯灭出现在德拉诺的任何文明的痕迹。",
},
[2165] = {
["Title"] = "黄金风蛇",
["Description"] = "诸王之眠曾久经战火。自从数万年前，一位愚蠢的巨魔试图将夺灵者哈卡唤回这片土地，赞达拉的祭司们就创造了一个强大的生物来保卫这座神庙。自此之后，黄金风蛇就在这里抵挡入侵者，考验他们是否有进入这些神圣殿堂的资格。",
},
[2169] = {
["Title"] = "泽克沃兹，恩佐斯的传令官",
["Description"] = "大分裂后不久，一个黑暗的使者登上了新形成的赞达拉海岸，想让这个刚刚被孤立的部族臣服于恩佐斯。泽克沃兹本想诱惑、贿赂、勾引、腐化，或者直接干掉他们，但他没想到自己会碰到奥迪尔的防御机制。他被捕捉、研究、解剖，然后被收藏在泰坦的档案馆中，而他只能静待逃脱的机会。",
},
[2173] = {
["Title"] = "恐怖船长洛克伍德",
["Description"] = "恐怖船长洛克伍德号令着海量的艾泽里特火炮。目前这些火炮已经瞄准了宫殿并威胁普罗德摩尔投降，如若不然就会将此处化为废墟。",
},
[599] = {
["Title"] = "艾欧纳尔",
["Description"] = "洛肯从不依赖他的钢铁仆从来充当他的个人卫兵。这位堕落的守护者靠的是闪电本身的力量。艾欧纳尔和它的同伴得以在闪电大厅中避难栖身，作为交换，它们必须献出绝对的忠诚和意愿，消灭任何妄图对抗自己新主人的闯入者。",
},
[600] = {
["Title"] = "洛肯",
["Description"] = "他是艾泽拉斯首席管理官，负责看管尤格-萨隆，确保将它安妥地关押在囚牢里。没人能预见到，从上古之神的手中救下这个世界的守护者，却是想要毁灭世界的罪魁祸首。",
},
[601] = {
["Title"] = "法瑞克",
["Description"] = "这位天灾军团的勇士是阿尔萨斯夺取霜之哀伤后创造的首批死亡骑士之一。明知那会是一场注定失败的战役，但法瑞克还是忠诚地追随自己的王子去了诺森德，结果他穷尽毕生精力为其效命的王子却背叛了他。",
},
[1202] = {
["Title"] = "奥尔高格",
["Description"] = "黑石铸造厂的仓库囤积了大量未经加工处理的黑石矿石，这对那些从地下钻进来的贪婪的鬣蜥人来说，可谓是一场饕餮盛宴了。奥尔高格是迄今为止块头最大的入侵者，贪婪且嗜石成性的他俨然已成为德拉诺有史以来体型最为庞大的鬣蜥人了。",
},
[602] = {
["Title"] = "玛维恩",
["Description"] = "玛维恩自小就认识阿尔萨斯，他不仅将他视作王子，还把他当成自己真正的朋友。当阿尔萨斯向着诺森德起航时，这位骑士毫不犹豫地跟他一起上路。尽管他的朋友后来将一把被诅咒的符文之刃插进了他的心脏，但眼见王子变成了这副模样，玛维恩还是体会到了心碎的感觉。",
},
[2197] = {
["Title"] = "冰雹构造体",
["Description"] = "冰雹构造体由德鲁斯瓦原住民建造，用来抵御入侵者。然而长久的休眠已然让它心智混乱，它现在将所有的生物都视作威胁，致力于毁灭整个世界。",
},
[603] = {
["Title"] = "逃离阿尔萨斯",
["Description"] = "两位领袖想要在一场对决中击败巫妖王，但她们很快便发现，自己根本不是这位真正王者的对手。为了活命，她们试图逃离他的圣所。她们每一刻徒劳的挣扎都令阿尔萨斯感到乐在其中。有些事情是无论如何都躲不掉的。",
},
[604] = {
["Title"] = "克莱斯塔卢斯",
["Description"] = "单凭力量无法赢得战争，要靠军队才行。这一固有真理激励着洛肯，他命人创造忠实的岩石生物来壮大自己的军团。克莱斯塔卢斯奉命监管这一作业，并粉碎任何威胁其运作的闯入者。",
},
[1208] = {
["Title"] = "大法师索尔",
["Description"] = "大法师索尔原本是坚守在紫罗兰断崖处的肯瑞托远征军中的一员，但最终还是被孢子侵占了她的大脑。或许在她内心深处仍然残留着部分人性，但现在的她只是一个被禁锢在自身躯壳里的囚徒。",
},
[2213] = {
["Title"] = "末日之嚎",
["Description"] = "末日之嚎来源于窃取的联盟工程图纸，它能将部落大军运往最激烈的战斗腹地。这一巨型载具还能变形为强大的攻城兵器，彻底摧毁敌方的防御工事。",
},
[605] = {
["Title"] = "悲伤圣女",
["Description"] = "洛肯统御着奥杜尔的军队，但这些士兵并非全都心甘情愿地为他效命。悲伤圣女奉命消灭任何妄图在岩石大厅起事的叛逆者。与昔日盟友为敌令她感到无比悲伤，但她履行使命的手段却异常残暴。她甚至将悲伤都化作了武器。",
},
[1210] = {
["Title"] = "雅努",
["Description"] = "原祖荆兽雅努古老而又神秘，它被紫罗兰断崖散发出来的奇异能量所吸引，该处是肯瑞托位于戈尔隆德的一个前哨站。长久以来，原祖荆兽和它们永恒的对手——玛戈隆（戈隆的一种，岩石之子）在德拉诺的对抗正陷入胶着。但雅努仿佛看到了一个全新的世界，通过这些奇异能量可以让它的族群繁荣兴旺、生生不息。",
},
[1211] = {
["Title"] = "永恒的塔尔纳",
["Description"] = "据说在塔尔纳抵达戈尔隆德之前，这里曾是贫瘠的不毛之地；据说原祖荆兽所到之处遍地花开，绿意盎然；据说这个家伙是不朽的，就像遭遇过山火的森林一样会重新恢复原貌。有关塔尔纳的传言有很多，但很少是被证实或亲眼目睹过的。",
},
[2422] = {
["Title"] = "太阳之王的救赎",
["Description"] = "在阴森的纳斯利亚堡内，灵魂不断受到折磨，而目的不是为了救赎罪孽，而是强化罪孽。而其他人的罪孽也被傲慢的王子凯尔萨斯承担了，通过引导他的痛苦和仇恨，他成为了强大的武器。这甚至危及到了他的灵魂，必须拯救他，不能让他被用来作为伤害暗影界的武器。",
},
[607] = {
["Title"] = "塑铁者斯约尼尔",
["Description"] = "尽管有些人在抵抗洛肯的腐化，但塑铁者斯约尼尔却迫不及待地要将意志熔炉用于更加黑暗的用途。他认为自己全新的创造物要大大优于土灵，并用它们对付那些胆敢违抗洛肯意志的敌人。",
},
[608] = {
["Title"] = "熔炉之主加弗斯特",
["Description"] = "加弗斯特制造出了一些极具杀伤力的致命武器，天灾军团用它们来对付活人。他能以极快的速度将萨隆邪铁铸成带来痛苦与死亡的可怕器具，也能直接将萨隆邪铁掷向自己的敌人。",
},
[1216] = {
["Title"] = "阿扎凯尔",
["Description"] = "在德莱尼曾经的故乡、燃烧军团如今的堡垒阿古斯，阿扎凯尔在等待着，随时准备作为燃烧军团的仆人，为它们打开一扇扇通往要想征服的异世界的传送门。当缚魂者尼娅米削弱奥金顿的防御时，阿扎凯尔感到时机来临了。",
},
[1123] = {
["Title"] = "缚火者卡格拉兹",
["Description"] = "在钢铁部落的大旗之下，黑手征召了火刃氏族的缚火者卡格拉兹来为黑石铸造的武器灌注火焰之力。卡格拉兹与她的助手艾克诺·钢铁使者正在一座永不熄灭的熔炉前孜孜不倦地工作着，为钢铁部落征服德拉诺提供支援。",
},
[610] = {
["Title"] = "天灾领主泰兰努斯",
["Description"] = "死亡骑士泰兰努斯在消灭巨人加弗斯特后，被提拔成了天灾领主。他凭借自身的力量、凶残和冰龙霜牙，成为了萨隆矿坑和映像大厅入口处最杰出的守护者。",
},
[611] = {
["Title"] = "肉钩",
["Description"] = "自从阿尔萨斯王子首次遭遇天灾憎恶以来，它们的邪恶程度与日俱增。肉钩比其它同类成长得更加强壮、更具毒性、更加敏捷。创造肉钩的亡灵法师们从没想过要把它塑造得多么聪明，但哪怕是最基本的狡诈就足以让它为所欲为了。",
},
[612] = {
["Title"] = "塑血者沙尔拉姆",
["Description"] = "塑血者沙尔拉姆是在通灵学院下方殿堂中受训的首批亡灵法师之一。在他眼里，那些试验品以及偶尔出现的小学徒都只不过是他工作中的有趣点滴而已。现在所有住在斯坦索姆里的人，以及那些妄图阻止他的闯入者，都成了他的实验对象……",
},
[283] = {
["Title"] = "泰兰德的残影",
["Description"] = "作为前暗夜精灵领袖及艾露恩高阶祭司，这个位于错乱时空中的泰兰德·语风的残影在艾泽拉斯未来的废土上徘徊。她被永恒的黑夜包围，几乎看不清艾露恩那令人慰藉的光辉。",
},
[1133] = {
["Title"] = "啸天者托瓦拉",
["Description"] = "在钢铁部落崛起之前，托瓦拉还未从未涉足过霜火岭那个冰冻苔原以外的地方。她在霜火岭带领着大批雷神氏族追踪者去诱捕并俘获德拉诺最为凶猛的双头飞龙。托瓦拉对双头飞龙的驾驭能力无人能出其右，而现在的她也被钢铁部落任命为空军指挥官。",
},
[1228] = {
["Title"] = "指挥官萨贝克",
["Description"] = "作为一名诡计多端的战歌氏族勇士，萨贝克被委以率领铁军远征队穿越黑暗之门发动突袭的重任。在加尔鲁什的授意下，他一路打到了黑石兽人在艾泽拉斯的老巢，并在那里集结兵力准备下一阶段的部署。",
},
[615] = {
["Title"] = "布隆亚姆",
["Description"] = "布隆亚姆从早期开始就一直在为诅咒神教效力了。克尔苏加德亲自向布隆亚姆传授了灵魂的价值，以及如何让灵魂饱受折磨，为天灾军团的战争机器供给能量。他能腐化敌人的灵魂，并将其一块一块地撕扯出来，这使他成为了看守巫妖王灵魂洪炉的理想守护者。",
},
[1139] = {
["Title"] = "莎达娜·血怒",
["Description"] = "莎达娜·血怒是影月氏族中一名非常强大的侍僧，与月运周期有着非常紧密的联系。当黑暗之星的低语飘荡在影月谷的中心地带时，莎达娜便追随她的酋长耐奥祖深入氏族的墓地，运用她的力量将灵魂从尸体中剥离出来，用来实现某种扭曲的意图。",
},
[1141] = {
["Title"] = "寒冰之王亚门纳尔",
["Description"] = "巫妖亚门纳尔曾是天灾军团的一员，在第三次大战中参与了对海加尔山的突袭。之后，巫妖王命令他的仆从留在卡利姆多，负责扩大天灾军团的影响力。但这次行动被部落和联盟的英雄挫败了。现在，剃刀高地的相对和平又受到了威胁。亡语者布莱克松想要复活这个强大的巫妖并重新发起对贫瘠之地的进攻。",
},
[1143] = {
["Title"] = "麦什伦",
["Description"] = "亡语者布莱克松最新的造物麦什伦是用其他失败的造物部件拼合而成的怪物。它体内充满了胆汁、脓水和其他毒液，将通往亡语者布莱克松的大厅都彻底污染了。",
},
[1145] = {
["Title"] = "苏克",
["Description"] = "苏克拥有许多对暮光之锤来说有十分宝贵的优良品质，但其中绝对不包括智慧。由于深信屠杀深渊守护者能够为他带来大量黄金，苏克的小脑瓜已经没空去考虑其他事情。任何打断他工作的人都会被他活剐了。",
},
[1147] = {
["Title"] = "主管索戈尔",
["Description"] = "和一身蛮力相比，索戈尔的狡诈与残酷似乎更富盛名，他负责整个恐轨的运作。从铸造厂车站开始，他就协调指挥与塔拉多德莱尼的持续地面作战，背后更是有整队随叫随到的作战部队以及炮火支援。",
},
[1235] = {
["Title"] = "血肉撕裂者诺格加尔",
["Description"] = "这位好勇斗狠的战歌领军在钢铁部落蹿升得很快，平步青云的他现在甚至统领了一整编的兽人部队。他骑在令人恐惧的座狼——惧牙身上厉兵秣马，似乎已经准备好对沙塔斯发动海面进攻。",
},
[1236] = {
["Title"] = "恐轨押运员",
["Description"] = "恐轨押运员是一群精英佣兵，他们受雇于黑索公司，负责保护穿行在戈尔隆德的火车。这个三人小组包括一名火刃剑圣，一名地精工程师和一个使用黑血魔法的萨满。这些利欲熏心的家伙眼里只有一个信条，那就是对金钱的贪婪和杀戮的狂热。",
},
[1153] = {
["Title"] = "克拉戈",
["Description"] = "在纳格兰悬槌堡的一次挖掘行动中，克拉戈是唯一一个直接暴露在神秘遗物下还能生还的幸存者，而这次经历使得他近乎免疫一切魔法。谣传他和悬槌堡的统治者有着说不清道不明的关系，但令人不解的是，拥有如此天赋的他为何还要在那位并不待见的巫师面前卑躬屈膝。",
},
[1155] = {
["Title"] = "汉斯加尔与弗兰佐克",
["Description"] = "汉斯加尔与弗兰佐克这对双胞胎兄弟从小就被培养成氏族的格斗大师。两人都踏上了追求氏族勇士的光荣道路，但命运却跟他们开了个玩笑。由于兄弟二人都不愿意在决斗中杀死对方，结果被双双逐出氏族，任其自生自灭。但他们在德拉诺的野蛮荒原上活了下来。当钢铁部落发出召唤时，这两位强大的战士又在这架庞大的战争机器里找到了新的位置。",
},
[1238] = {
["Title"] = "斯古洛克",
["Description"] = "钢铁部落在戈尔隆德降服巨人的计划执行得非常成功，强大的戈隆斯古洛克就是最好的证明。他在格罗姆卡军中鹤立鸡群，双肩还扛着一对巨炮，形容他是走在陆地上的铁甲舰一点都不为过。斯古洛克已准备好执行新主人的命令，将目标夷为平地。",
},
[290] = {
["Title"] = "佩罗萨恩",
["Description"] = "与他的许多上层精灵同伴一样，佩罗萨恩立誓效忠于堕落的萨维斯以换取恶魔的力量。\r\n\r\n佩罗萨恩在受到了萨特诅咒的影响后，成了一名操控恶魔法术的大师。他驻守在艾萨拉的宫廷之外，为燃烧军团担当防御职责，时刻准备着消灭那些企图阻止堕落泰坦萨格拉斯入侵艾泽拉斯的冒险者们。",
},
[1161] = {
["Title"] = "格鲁尔",
["Description"] = "加尔鲁什知道驯服戈隆的关键就在于降服他们的族长，格鲁尔。在另一个时空中大名鼎鼎的屠龙者如今已被贬为卑贱的工人。更加讽刺的是，他们还按照碎手氏族战士的传统，砍掉了他的一只手并装上铁钩，以便他能更轻松地将一盘盘燃料倒入熔炉。",
},
[2325] = {
["Title"] = "丛林之王格洛恩",
["Description"] = "格洛恩自愿成为活体超级武器后，他的智力退化了，变成了一只暴躁的巨兽。虽然他的智力下降了，他的力量却达到了前所未有的程度。",
},
[2329] = {
["Title"] = "森林之王伊弗斯",
["Description"] = "暗夜精灵在危难关头总会召唤森林之王伊弗斯，他已经多次用自己的原始之力对抗过部落。如今，他从奥特兰克山谷归来，击退威胁，保卫家园。",
},
[2333] = {
["Title"] = "圣光勇士",
["Description"] = "弗里达·铁吼满怀热情和虔诚领导着部队，充当着联盟突袭祖达萨的先锋军。她的战斗力和对圣光的坚定信仰都不可小觑。",
},
[2337] = {
["Title"] = "风暴之墙阻击战",
["Description"] = "约瑟夫修士和凯瑟琳修女是波涛的忠实信徒。他们身为骄傲的库尔提拉斯儿女，甘愿冒着生命危险保障其他士兵安全撤离。他们号令大海和风暴的能力以及古代的强力仪式都堪称奇观。",
},
[2341] = {
["Title"] = "玉火大师",
["Description"] = "虽然曼赛罗伊和玫斯特拉最近才开始一起训练，但他们的合作已经完全亲密无间，能够共同冲锋陷阵。他们已经准备好用火焰和拳头迎接任何胆敢挑战联盟的敌人。",
},
[2345] = {
["Title"] = "朽木伊弗斯",
["Description"] = "森林之王伊弗斯曾经是奥特兰克山谷中的坚定保护者，但他回到黑海岸保护家园后，却屈从于部落的亵渎之力。虽然身躯已经腐朽，心智已被黑暗魔法扭曲，他面对森林的敌人时依然不愿退让半分，就算粉身碎骨也在所不惜。",
},
[2349] = {
["Title"] = "扎库尔，尼奥罗萨先驱",
["Description"] = "作为末日的先锋，扎库尔会从混沌的世界撕碎理智的最后残迹，从而为艾泽拉斯的新主人奠定基础。",
},
[2353] = {
["Title"] = "艾萨拉之辉",
["Description"] = "艾萨拉让她的女仆自愿献身，将其铸造为了一个风暴和魔法的元素。这个怪物由艾萨拉的虔信者之魂驱动，是艾萨拉的光辉的象征。",
},
[2357] = {
["Title"] = "戈巴马克国王",
["Description"] = "戈巴马克国王痴迷于囤积在垃圾场里发现的危险技术。他坐拥一大堆可以毁灭世界的武器，但却没有足够的智力来操作或者理解。",
},
[2361] = {
["Title"] = "艾萨拉女王",
["Description"] = "纳迦女王，纳沙塔尔的女皇，艾泽拉斯有史以来最强大的实体之一。艾萨拉谋划了几千年，等待着这个宿命的时刻。如今，所有棋子已经登场，她的最终计划也终于揭晓。",
},
[2365] = {
["Title"] = "玛乌特",
["Description"] = "远古的亚基虫族从沙漠中崛起的同时，他们的先知也开始修建一个黑曜石毁灭者，并且灌注了上古之神的精华。玛乌特被对魔法的永无止境的饥渴所驱使，刚一苏醒就吞噬了它的创造者的法力，只留下他们的尸体在奥丹姆的焦阳下腐烂。",
},
[1185] = {
["Title"] = "警戒者凯萨尔",
["Description"] = "那些最最伟大的德莱尼勇士在其生命临近结束时，往往会响应最终的召唤：将自己封印在那些重装构造体中，作为奥金顿永恒的守护者来捍卫德拉诺的德莱尼文明。这些特殊的警戒者被委以守护剩余水晶的职责，而正是这些水晶在为奥金顿提供坚不可摧的能量护盾。",
},
[2373] = {
["Title"] = "德雷阿佳丝",
["Description"] = "这团名为德雷阿佳丝的血肉聚合体外表丑陋，在尼奥罗萨的地下沉眠了无数纪元，现在已被恩佐斯的回归所唤醒。她就像一颗恶心的疖子，随时都会爆发开来，将肮脏的气息散播到整个艾泽拉斯。",
},
[2377] = {
["Title"] = "黑暗审判官夏奈什",
["Description"] = "上古之神的低语几乎无人能够抵抗，而那些侥幸成功的，也会落入黑暗审判官夏奈什的魔掌。夏奈什残忍又嗜虐，擅长缓慢地将手中的猎物的理智剥离，将其变为恩佐斯的坚定追随者。她一直以此为傲。",
},
[2381] = {
["Title"] = "碎地者弗克拉兹",
["Description"] = "先知斯基特拉从艾泽拉斯被遗忘的深渊中唤醒了一只具有毁天灭地之力的亚基虫族——碎地者弗克拉兹。从地底的沉眠中觉醒后，弗克拉兹即将使用它的破灭之力来对付恩佐斯的敌人。",
},
[622] = {
["Title"] = "审讯者达库斯",
["Description"] = "那些违犯玛里苟斯律法的人，都会发现自己置身于达库斯的利爪下。在把克莉斯塔萨关进魔枢后，达库斯便返回魔环接管新的囚犯——那些违抗玛里苟斯命令的其它龙族。他不在乎所谓的名誉，也无需虚伪的遮掩。他的囚犯就是要在这里受刑的，谁也别想逃脱。",
},
[2389] = {
["Title"] = "库尔萨洛克",
["Description"] = "库尔萨洛克是通灵术的大师，他证明了蛮力不是迈向权位的唯一途径。若想打赢他，不单要穿过他的魔法传送门迷宫，还要胜过他的通灵术之力。",
},
[1197] = {
["Title"] = "元首马尔高克",
["Description"] = "作为悬槌堡至高无上的统治者，元首马尔高克出身于一个世代统治高里亚帝国的巫师家族。生性残忍且狡猾奸诈的马尔高克意识到钢铁部落的崛起，以及与之对抗的下场。所以他默允了与格罗玛什的同盟关系，即便如此他仍在寻找一个平衡点，从而使胜利的天平倾向于他这方。",
},
[2397] = {
["Title"] = "狭路相逢",
["Description"] = "卫冕冠军并不会跟随便一个人比拼。参战者首先要互相挑战才能证明自己有这个资格。斩首者德茜雅、疫毒者巴瑟兰和受诅者赛泽尔结合了他们多元的作战风格，成功击败了其他参战者。他们会消灭任何想阻止自己夺取冠军头衔的队伍。",
},
[2401] = {
["Title"] = "斩血",
["Description"] = "斩血对胜利和对新部件都极其渴望。他准备向大家证明，造物密院制造的战士更为优异。从到玛卓克萨斯起，他身上的每一个部位都是通过战斗赢得的，但他依然渴望从挑战者身上获得新的部件。",
},
[1203] = {
["Title"] = "钢铁女武神",
["Description"] = "在兽人的古老社会结构下，加安几乎没有机会发挥她的战术天赋。因此，作为第一批战士志愿加入钢铁部落海军时，她的心情异常激动。她在战斗中迅速大放异彩，被任命为钢铁部落舰队的海军上将，并选择了玛拉卡和苏卡作为她的副官。她们三人被称为钢铁女武神——并横扫了所有敢于在战斗中直面她们的人。",
},
[2409] = {
["Title"] = "法力风暴夫妇",
["Description"] = "绝对的诚实和信任造就了米尔菲丝·法力风暴和米尔豪斯·法力风暴这对模范夫妻。嗯，其实是诚实、信任、惊人的魔法和实验性的科技。将这四者以完美的方式结合起来后，法力风暴夫妇得以成为最致命、最危险和最灾难性的夫妻。",
},
[1207] = {
["Title"] = "远古的保卫者",
["Description"] = "高拉和特鲁是一对护林木精，他们以极快的速度在林地里生长蔓延，试图夺回他俩之间那座命运多舛的岗哨。负责保护他们完成此项任务的人便是恐怖屠夫杜尔胡，许久以前他曾是个黑石兽人，独自在原始林地的深处游荡，而现在的他更像是植物多一点了。",
},
[1209] = {
["Title"] = "艾里塔克",
["Description"] = "这只恶毒的蛛后守护着自己的蛛卵，她的巢穴位于戈尔隆德的地底深处。她正等待那些愚蠢的猎物送上门来，被其诱捕并吞噬。",
},
[2421] = {
["Title"] = "大学监贝律莉娅",
["Description"] = "只有年纪很大的人才能真正了解，大学监贝律莉娅究竟是在雷文德斯学会了这种无情的研究方式，还是说她从来就没有放弃过自己的这条罪孽。她为了掌握心能魔法所展现出的残忍在一个特别的新囚犯身上展露无遗，就是名叫兹拉莉的纳鲁。不管这名囚犯将付出怎样的代价，贝律莉娅都要号令这名囚犯的圣光之力。",
},
[2425] = {
["Title"] = "顽石军团干将",
["Description"] = "古老的石裔干将卡尔和格拉夏尔一直在打压着雷纳索尔王子的起义军。他们以前是德莱文将军的学徒和导师，现在，他们倾尽自己的力量、谋略和军队来阻止德莱文将军和其他违逆大帝意志的人。",
},
[2429] = {
["Title"] = "猎手阿尔迪莫",
["Description"] = "德纳修斯大帝很少参与狩猎，但阿尔迪莫确保了他的主人一旦想来狩猎就能拥有最优秀的野兽为伴。玛尔苟、巴加斯特和赫库提斯接受训练的时间远超绝大多数野兽，而且它们都已经准备好将猎手的愤怒发泄到任何擅闯他领域的人身上。",
},
[2433] = {
["Title"] = "诺尔伽什·泥躯",
["Description"] = "诺尔伽什脱胎于众多湿乎乎的泥仆，随后又由德纳修斯最精锐的巫师用黑暗魔法加以强化。他不算聪明，但他的拳头可以击碎城堡。",
},
[2437] = {
["Title"] = "哨卫佐·菲克斯",
["Description"] = "要进入掮灵都市金碧辉煌的大门，一窥其中隐藏的宇宙奇迹，就必须通过哨卫佐·菲克斯这一关。  佐·菲克斯对安保工作如痴如醉，他会将违禁品和持有人一同焚毁。",
},
[2441] = {
["Title"] = "希尔瓦娜斯·风行者",
["Description"] = "奥利波斯处于危难之中，统御圣所之巅也展开了一场孤注一掷的战斗。凡人们试图阻止典狱长，而希尔瓦娜斯·风行者则挡在典狱长之前。这位女妖之王终于抛弃了所有伪装，释放出了全部力量来保护被流放者，让他的终极计划得以实施。",
},
[2445] = {
["Title"] = "裂魂者多尔玛赞",
["Description"] = "裂魂者多尔玛赞会从托加斯特关押的残暴囚犯身上榨取心能，用来滋养典狱长的大军。多尔玛赞从没碰到过无法驯服的灵魂，但最近他手上得到了一个特别强韧的灵魂，通常的手段都无法让他屈服。多尔玛赞汲取着这名囚犯的无尽怒意，试图花上几千年来慢慢寻找他的弱点。",
},
[1225] = {
["Title"] = "塔隆戈尔",
["Description"] = "古尔丹的密探塔隆戈尔与萨格雷合谋，妄图吞噬在奥金顿神圣陵墓中安息的万千亡魂。",
},
[1227] = {
["Title"] = "奇拉克",
["Description"] = "作为幸存的奈法利安余孽，奇拉克为免于一死，向钢铁部落提出会想尽一切办法保存并巩固黑石塔孵化间内所剩无几的黑龙军团龙蛋。钢铁部落的使者当即与这头狡诈的黑龙达成协议。",
},
[1229] = {
["Title"] = "狂野的怒翼",
["Description"] = "怒翼是由暮光高地的龙喉氏族驯养的巨型始祖龙。虽然她与督军扎伊拉建立了亲密的伙伴关系并跟随其来到了黑石塔，盘踞在洞穴大厅里，但她坚强不屈的意志使其心智得以保全，没有沦为失去自我意识的坐骑。",
},
[2461] = {
["Title"] = "首席造物师利许威姆",
["Description"] = "利许威姆一丝不苟地将幻磷编织为造物，以实现初诞者的神圣意志。如今，渊誓大军想要夺取这股力量，编织的过程受到了威胁。",
},
[2465] = {
["Title"] = "司垢莱克斯，无穷噬灭者",
["Description"] = "初诞者圣墓被攻破后，吞噬者们一拥而入，寻找着果腹之物。这些可憎之物里有一个就是贪得无厌的司垢莱克斯。这只巨大的蠕虫吞噬着海量的幻磷，圣墓也失去了平衡，即将坍圮。",
},
[2469] = {
["Title"] = "安度因·乌瑞恩",
["Description"] = "安度因被统御魔法所控制，被迫帮助典狱长执行计划以重塑现实。时间正一步步流逝，阻止安度因的希望也变得越来越渺茫。艾泽拉斯的勇士们必须做出艰难的抉择：是击败这位年轻的国王来拯救宇宙，还是冒着牺牲万物的风险来拯救他的灵魂？",
},
[1237] = {
["Title"] = "奥舍尔",
["Description"] = "刃牙虎人奥舍尔本是徘徊在阿兰卡峰林的一个凶狠残暴的捕食者，狂妄自大终于使他栽了跟头，被雷神氏族诱捕并押至戈尔隆德接受驯化，最终沦为了钢铁部落的马前卒。奥舍尔已不止一天设想过要痛饮将其捕获者的鲜血。",
},
[2477] = {
["Title"] = "巴拉卡可汗",
["Description"] = "巴拉卡可汗是诺库德氏族残忍的领袖。他的风暴法师捉住了伟大的鹰隼之魂欧恩哈拉，他想获得风之母的力量。仇恨将他的氏族联合起来对抗所有“外来者”。由于侵扰不断发生，必须有人挺身而出来对抗这名暴君。",
},
[626] = {
["Title"] = "埃雷克姆",
["Description"] = "紫罗兰监狱中的住民都是外域最为臭名昭彰的罪犯，埃雷克姆也不例外。虽然他刺杀六人议会的阴谋被肯瑞托识破了，但现在蓝龙军团却征召了这位阴险的鸦人去实现更有野心的目标——荡除达拉然的所有法师。",
},
[2485] = {
["Title"] = "柯姬雅·焰蹄",
["Description"] = "拜荒者部队从四面八方突袭红玉新生法池时，柯姬雅和她的炎缚军官的使命就是趁守备军难以招架之时，夺取珍贵的龙蛋，并在所及之处散播烈焰和浩劫。",
},
[2489] = {
["Title"] = "熔炉主管戈雷克",
["Description"] = "熔炉主管戈雷克是贾拉丁最出色的工匠之一。他镇守在黑龙军营的酷热大厅中，在此驾驭巨大熔炉的炎火之力来打造致命的武器。",
},
[2493] = {
["Title"] = "巢穴守护者迪乌尔娜",
["Description"] = "凶猛的巢穴守护者迪乌尔娜负责看管拜荒者龙巢繁育场。她为保护尚未孵化的子嗣殚精竭力，并设法为失去的孩子复仇。",
},
[2497] = {
["Title"] = "狂怒风暴",
["Description"] = "躁狂的风暴在欧恩哈拉平原肆虐横行。巴拉卡的风暴法师已将风暴之怒凝结成了风暴的化身。狂怒风暴持续不断地积聚力量，不光想摧毁战场，还想毁灭整个巨龙群岛。如果不加以控制，拜荒者的混沌将笼罩这片平原。",
},
[2501] = {
["Title"] = "督军莎尔佳",
["Description"] = "督军莎尔佳是卡拉希贾拉丁的领袖，她在寻找所有能够增强氏族力量的手段，从而击败龙族宿敌。在奈萨鲁斯深处的珍宝中，她可能找到了贾拉丁梦寐以求的东西。",
},
[2505] = {
["Title"] = "青刃",
["Description"] = "青刃是魔馆的保安。魔馆被封印时，她拒绝离开，视责任高于自己的安危。而蓝龙军团没能归来，她的愤怒和无奈最终逼疯了她。青刃用曾经发誓守护的魔法来延续自己的生命，宣称自己是蓝龙军团遗留的全部财产的主人。",
},
[2509] = {
["Title"] = "维克萨姆斯",
["Description"] = "作为学院任期最长的教授之一，马克斯多姆利用自己身为青铜龙的力量，把历史课上得栩栩如生。\r\n\r\n尽管这门趣味盎然的历史课程相当具有教育意义，但它偶尔也会出错。维克萨姆斯是马克斯多姆教授最喜欢的课程之一，但如果吵闹的学生无法把握历史细节，他就会立即对其严加斥责。",
},
[629] = {
["Title"] = "谢沃兹",
["Description"] = "谢沃兹是一位奥术武器商人……直到肯瑞托发现，他在为燃烧军团提供军备。现在这个顽固的虚灵正准备分三阶段执行他的下一步商业计划——消灭他的敌人、逃离监禁、回去为他最大的主顾效力。",
},
[2517] = {
["Title"] = "巴祖阿尔，惊恐烈焰",
["Description"] = "巴祖阿尔与火元素位面有着特殊联系，这使得他可以直接从火焰之地吸取能量。在拜荒者势力的帮助下，巴祖阿尔正在碧蓝林海扩展通向火焰之地的界门。",
},
[2521] = {
["Title"] = "克罗妮卡",
["Description"] = "克罗妮卡把一生都献给了永恒龙军团，一步步爬上了指挥官的位子。即使在激进的永恒龙当中，她的狂热也无人能比。她身为崇圣亲卫，必将用一切手段来消灭任何违背她意愿的人。",
},
[2525] = {
["Title"] = "长老莱修克",
["Description"] = "上万年来，扎卡利长老莱修克一直被囚禁在亚贝鲁斯，他的狂怒烈焰被抽出，为奈萨里奥扭曲的实验室供能。这名长老长期徘徊在生死边缘，已经变得十分疯狂。一旦他获得自由，他复仇的怒火会席卷焰影熔炉的大厅。",
},
[2529] = {
["Title"] = "融合体密室",
["Description"] = "永恒炽焰的灼热有如千颗烈阳，而暗影精华则绽放着黑暗化身的阴幽。虽然他们各自已经十分强大，但他们合体时，更是会涌动着暗影烈焰的无拘能量，化身为终极的毁灭旋风。",
},
[2533] = {
["Title"] = "迷时战场",
["Description"] = "联盟和部落的战斗众多，其中有一场已经渗入了时间流，现在艾泽拉斯的英雄们必须终结这时光中的这个异象才能继续旅程。但首先，英雄们会与格罗玛什·地狱咆哮对峙，他是部落最强力的大酋长之一。为了联盟！",
},
[2537] = {
["Title"] = "伊律迪孔，石鳞之龙",
["Description"] = "伊律迪孔是头强大的化身巨龙，他能掌控大地的力量，也像磐石般充满耐心。他希望推翻守护巨龙，清除泰坦对这个世界造成的影响。但他的计划到底如何实现，目前还是个谜。为什么他要与永恒龙合作？无论答案是什么，都必须阻止他。",
},
[318] = {
["Title"] = "死亡之翼的背脊",
["Description"] = "当死亡之翼第一次引导巨龙之魂的力量对付其他巨龙军团时，爆发出来的巨大能量几乎毁掉他自己的躯体。可他并没有放弃这件武器，反而在自己的鳞片上嵌入了合金装甲以接合他的躯体。之后，他又用源质矿强化了这些装甲。可现在，这些装甲却成了他的弱点——这也是死亡之翼唯一的致命的弱点。",
},
[634] = {
["Title"] = "总冠军",
["Description"] = "巫妖王凶残至极，他的亡灵大军总是倾巢而出，瞬间席卷他的敌人。为了挑选足以对抗他的后备勇士，大领主提里奥·弗丁发起了勇气、忍耐力和团队协作力的试炼。他麾下经验丰富的精兵强将会淘汰掉那些缺乏勇气，无法面对铺天盖地亡灵大军的弱者。",
},
[2476] = {
["Title"] = "艾博隆",
["Description"] = "泰坦宝库一直都有臭名昭著的各种精密防御措施，奥达曼也不例外。守护者阿扎达斯用他的巧手铸造了艾博隆，并给他灌注了释放灼热烈焰的能力，可以将企图劫掠泰坦奥秘的人烧成灰烬。",
},
[2553] = {
["Title"] = "拉罗达尔，烈焰守护者",
["Description"] = "拉罗达尔曾是名忠诚的林地守护者，但他最终还是屈服于烈焰的力量。现在这个扭曲的守护者致力于将梦境和所有阻挠他的人化作灰烬。",
},
[2557] = {
["Title"] = "沃尔科罗斯",
["Description"] = "据说，熔岩巨蛇沃尔科罗斯的身躯无比巨大，没有生物的寿命长到有机会观察到他的整个身体。现在，这只硕大无朋的爬蛇缠结在翡翠梦境，想将它整个吞噬。",
},
[2561] = {
["Title"] = "黑暗之主",
["Description"] = "阴影中潜藏怎样的恐怖？狗头人为什么要点亮蜡烛？弱小的生物挤在篝火旁，讲述着远古的邪恶。黑暗之主可以被击败，但永远无法被摧毁。相反，它会不可避免地以某种新的恐怖形态卷土重来。记得要待在光里，黑暗在伺机而动。",
},
[2565] = {
["Title"] = "丁达尔·迅贤，烈焰预言者",
["Description"] = "丁达尔·迅贤痴迷于让卡多雷重新变得永生不死，便同意与菲莱克合作。现在，菲莱克的胜利已经唾手可得，这名烈焰预言者为了确保阿梅达希尔能够在烈焰中重生，决心阻止艾泽拉斯的勇士们前进的脚步。",
},
[2569] = {
["Title"] = "老蜡须",
["Description"] = "噢哟！快坐下，听听老蜡须的故事。狗头人尊重这个老家伙，因为他驯服了烛芯，那可是世上性子最烈的鼹鼠！什么茬儿老蜡须都见过。虽然现在是蜡烛之王管事儿，但那也不顶用！你可别闯进他的地盘！你怎么还在这里？去吧去吧！干你的事去！",
},
[322] = {
["Title"] = "阿奎里恩",
["Description"] = "部落与联盟对暮光之锤的进攻杀死了许多邪教徒的元素升腾者。但阿奎里恩是个例外。这个可怕的寒冰升腾者受命杀死萨尔并夺回巨龙之魂。如果让这个扭曲的元素生物获得成功，那就没有什么能阻止死亡之翼发动暮光审判了。",
},
[323] = {
["Title"] = "希尔瓦娜斯的残影",
["Description"] = "在破碎的时间流中，被遗忘者的领袖，希尔瓦娜斯·风行者疯狂的残影独自徘徊在红玉巨龙圣地的焦土上，不安地等待着。这个饱受折磨的残影失去了一切，在扭曲时空中无法安息，渴望向这片废墟上的一切活物发泄她黑暗的怒火。",
},
[1291] = {
["Title"] = "毁灭者多弗",
["Description"] = "多弗在过去的黑石氏族被称为毁灭者，一听到这名号，人们就会不由自主地与这个可怕的玛戈隆保持安全距离。多弗走到哪儿都是地动山摇，仿佛大地看到他也为之颤抖，并为其开路。",
},
[2585] = {
["Title"] = "收割者吉卡塔尔",
["Description"] = "作为安苏雷克麾下的一名扬升者，吉卡塔尔奉命监督从女王城堡下开始的黑血收割行动。吉卡塔尔冷酷无情，她会不惜一切代价继续收割，并充分利用她拥有的每一种强化之力。",
},
[324] = {
["Title"] = "督军佐诺兹",
["Description"] = "无数个世纪之前，督军佐诺兹和他的士兵们对克苏恩和尤格-萨隆发动了无休止的战争。数千年过去了，可这个督军依然听命于上古之神恩佐斯的混沌统治。现在，死亡之翼释放出了这个传奇无面者，想靠他来消灭龙眠神殿的守护者们。",
},
[2593] = {
["Title"] = "拉夏南",
["Description"] = "拉夏南是来自艾基-卡赫特深处的飞翼恐兽。如果安苏雷克女王的军队未能征服米雷达尔，拉夏南将成为女王摧毁阿拉希的秘密武器。",
},
[325] = {
["Title"] = "不眠的约萨希",
["Description"] = "暮光堡垒陷落之后，不眠的约萨希就尽心辅佐死亡之翼，帮助灭世者释放出被囚禁在大地深处的无面者。这些无面者拥有超乎想象的力量，而且他们的数量无穷无尽。而约萨希则渴望用忠诚换取可怕的奖励。",
},
[2601] = {
["Title"] = "节点女亲王凯威扎",
["Description"] = "节点女亲王凯威扎最近才来到尼鲁巴尔王宫，却很快就成为了安苏雷克女王的亲信。宫内传言说她可能隐瞒了一个黑暗而致命的秘密。如果东窗事发，女亲王已经准备好毫不留情地除掉所有目击人士……",
},
[393] = {
["Title"] = "军需官兹格雷斯",
["Description"] = "在第一次战争结束后，兽人猎手兹格雷斯因儿戏般地追捕和屠杀暴风城难民而变得臭名昭著。他厌恶黑石塔内幽闭恐怖的殿堂，但他相信，自己终有一天能在露天的战场上再次展开猎杀。",
},
[2609] = {
["Title"] = "拉夏南",
["Description"] = "被安苏雷克女王的实验扭曲之后，拉夏南从一个骄傲的蛛魔变成了长着翅膀的恐怖怪物。受困于新形态之中的拉夏南对过往的记忆也已经支离破碎，陷入了无尽的怒火。",
},
[2613] = {
["Title"] = "拉克佐",
["Description"] = "身为迪菲亚兄弟会安排在死亡矿井的首席工头，拉克佐负责监督和“鼓励”手下的劳工。他的手段并不传统，但卓有成效。",
},
[2617] = {
["Title"] = "乌比斯将军",
["Description"] = "艾泽拉斯的勇者和他们的红龙盟军对格瑞姆巴托的大门发动了进攻，率领堡垒中教徒和暮光龙兽展开防御的，正是凶神恶煞般的乌比斯将军。",
},
[2621] = {
["Title"] = "撕心狼将军",
["Description"] = "詹姆斯·哈林顿身中狼人的诅咒后，在一个刺骨的寒夜里毁掉了钟爱的家庭和他的远洋航海生涯。在那之后，他改名为撕心狼，逃到了西部荒野，之后更是接受了任命，指挥迪菲亚兄弟会可怖的无畏舰。",
},
[2625] = {
["Title"] = "欧尔塔，破碎山峦",
["Description"] = "这位渊行者在艾基-卡赫特的深渊和传说中漫步已久。他声若地震、坚如磐石、力达高山。可如今，他来到了艾基-卡赫特，被黑血的脓包污染，需要一个体面的解脱。谁能奋起对抗他？",
},
[2629] = {
["Title"] = "重拳先生",
["Description"] = "作为绿皮船长的大副，重拳负责管束好手下的船员。他是一名战技出众的武器大师，精通刀剑劈砍和拳打脚踢，偶尔也会展示自己的枪法。",
},
[2633] = {
["Title"] = "邮差马龙",
["Description"] = "马龙凭借自己对邮件无微不至的关照而当上了邮差。即使沦为如今的境地，他依然勤勤恳恳地维护着邮政系统。如果这一系统遭到干扰，乃至濒临瓦解，马龙就只好亲自出手摆平了。",
},
[2637] = {
["Title"] = "考尔达克，休眠的保护者",
["Description"] = "考尔达克几乎失去了所有功能，也鲜有人记得，年久失修让他被迫成为一位休眠的旁观者。即便发现了地下出现了虚空力量，他也束手无措。但情况已经发生了变化。许多不明生命形体来到了多恩岛，并且强大到足以威胁艾泽拉斯。于是他挺身而起，而我们寸步不让。",
},
[2641] = {
["Title"] = "里克·混响",
["Description"] = "里克·混响喜欢爆炸的轰鸣，喜欢烟花的炸响，而最重要的是，他喜欢自己的声音。里克·混响会用飞天声波共鸣器给加里维克斯做声势宣传，用致命而又令人欲罢不能的地精节奏吸引着安德麦的市民。",
},
[331] = {
["Title"] = "奥卓克希昂",
["Description"] = "与其说奥卓克希昂是一条龙，还不如说他是一个充满黑暗能量的畸形怪物。他在自己短暂的一生中，不停地吸收虚空之龙的精华。他也是唯一受到死亡之翼赏识的暮光龙，只有在爆裂的能量溢出他那扭曲的躯壳时，他才会收起自己的傲慢。奥卓克希昂对他的主子忠心耿耿，发誓要摧毁龙眠神殿。",
},
[2649] = {
["Title"] = "破拆双人组",
["Description"] = "齐扎·迅索和布隆特是风险投资公司的智囊打手二人组，加里维克斯签下了他们，打算将水能堡的大坝“爆破改建”。齐扎热衷于肆无忌惮地大搞破坏，而布隆特“热衷”于替她打扫留在身后的一片狼藉。",
},
[332] = {
["Title"] = "战争大师黑角",
["Description"] = "曾经数量庞大的暮光龙如今所剩无几。这些久经考验的幸存者背上的骑手则是暮光之锤大军的余孽：精锐幼龙骑手。他们也是死亡之翼的私人卫队。在狡诈的战争大师黑角的带领下，他们为着邪恶的目标，誓死保卫他们的黑暗君主。",
},
[2369] = {
["Title"] = "先知斯基特拉",
["Description"] = "斯基特拉擅长操纵幻象，每当他让受害者在真假难辨的臆想中错乱，在恐惧中颤栗时，他总能感受到无上的快乐。那些无法看透他的把戏的人，会在尼奥罗萨迷失，直到永远。",
},
[333] = {
["Title"] = "疯狂的死亡之翼",
["Description"] = "这个丑陋、毫无理智的恐怖生物满怀炽烈的恨意，裹挟着无穷的力量，势不可挡。大地守护者奈萨里奥早已消亡，他的头脑和灵魂已经彻底被上古之神腐蚀并吞噬。现在，这个怪物唯一的目标就是摧毁并灭绝一切生命。",
},
[2665] = {
["Title"] = "伊森迪奥斯",
["Description"] = "迦顿男爵教伊森迪奥斯驾驭自己的破坏力，可男爵怎么也没有想到，这位仆从竟会带来如此大的威胁。对伊森迪奥斯篡权的担忧日滋夜长，迦顿终于决定将这炽热元素逐出熔火之心，命其守卫黑铁矮人传奇的黑铁砧。",
},
[2669] = {
["Title"] = "弗莱拉斯大使",
["Description"] = "由于对拉格纳罗斯无比忠诚，弗莱拉斯以大使的尊贵身份被派往黑铁部族。这个卑鄙的家伙起初对他的矮人盟友们不屑一顾，但渐渐地对他们嗜好破坏的性格心生尊敬。",
},
[413] = {
["Title"] = "卫兵芬古斯",
["Description"] = "自从观察者克鲁什告诉他，说他能在执勤时遇见命中注定的伴侣，芬古斯便时刻打起十二万分精神在戈多克领土上巡逻。",
},
[335] = {
["Title"] = "疑之煞",
["Description"] = "当疑虑的实体形态于一万年前被皇帝少昊击败后，就被困在翡翠林中。疑之煞后来便开始纠缠青龙玉珑——睿智与远见之灵，现在正乐此不疲地想要腐化她的家园。",
},
[414] = {
["Title"] = "卫兵斯里基克",
["Description"] = "有些人也许会认为斯里基克只是小心谨慎，可他其实也懒得很。他不愿与戈多克大王正面交锋，而是希望凭借陷阱和又老又破的魔法装置，不费吹灰之力地对其造成致命打击。",
},
[2685] = {
["Title"] = "缚魂者娜欣达利",
["Description"] = "在她幽暗的密室中，缚魂者娜欣达利将卡雷什人的游离灵魂束缚为不甘愿的仆从。那些受害者被缠丝紧紧包裹，从囚笼中释放之后都成了行使影卫意志的工具。",
},
[370] = {
["Title"] = "洛考尔",
["Description"] = "洛考尔对火元素诡计多端、尔虞我诈的本性感到深恶痛绝。为了能远离在熔火之心中效力的其它同类，这个强大的生物故意惹得火焰之王大发雷霆。洛考尔为自己的危险之举付出了代价——他被逐出了熔火之心，被迫孤绝地守卫黑石深渊。",
},
[106] = {
["Title"] = "柯尔拉，暮光之兆",
["Description"] = "柯尔拉曾是一位功成名就的肯瑞托法师，如今她对暮光之锤忠贞不渝。她会祝福那些狂热的追随者，将虚空巨龙的精华授予他们，把他们变成凶狠的暮光龙人。",
},
[426] = {
["Title"] = "征服者克鲁尔",
["Description"] = "暮光之锤命令他们强大的执行者，征服者克鲁尔去清除洞穴中一切不受他们控制的生物。面对压倒性的力量，格里哈斯特成了克鲁尔的第一个受害者，洞穴里的鱼人也被克鲁尔所控制。克鲁尔还将格里哈斯特扭曲的尸体示众，作为他统治的证据，并利用鱼人掠夺那些死在洞穴里的生物们的财物。",
},
[93] = {
["Title"] = "“船长”曲奇",
["Description"] = "随着迪菲亚兄弟会前任无畏舰指挥官的死亡，曲奇自封为船长。尽管他在主厨的工作上仍然尽职尽责，但若是有谁质疑其船长的头衔来得是否光明磊落，那人就会因为严重的食物中毒而倒地不起。",
},
[2393] = {
["Title"] = "啸翼",
["Description"] = "盲眼怪物啸翼的使命是守卫纳斯利亚堡的入口厅堂。她通过在厅堂的墙壁间反射的声波来确定猎物的位置，如果有人擅闯宏伟步道，他们最后听到的声音就是这只怪物从天而降时所发出的尖啸。",
},
[339] = {
["Title"] = "憎恨女王阿丽萨巴尔",
["Description"] = "就在堕落法师把阿丽萨巴尔召唤到艾泽拉斯不久之后，肯瑞托就将这只希瓦尔拉囚禁在他们的紫罗兰监狱中。尽管奥术守卫限制了她的法力，负责看管她的守卫们还是在这只恶魔邪恶的影响下被突然的暴怒所控制，自相残杀。在大灾变发生之前，她被遣送到巴拉丁监狱，但这却让这座已沦为废墟的恐怖监狱雪上加霜。",
},
[428] = {
["Title"] = "被诅咒的塞雷布拉斯",
["Description"] = "在闻听叔叔的悲惨命运后，高尚的塞雷布拉斯立誓解救扎尔塔的灵魂。可当这位林地守护者在玛拉顿的阴暗廊道间遭逢恐惧时，他全然没有做好准备。塞雷布拉斯很快就被四处弥漫的黑暗能量席卷，心中充满了不可控制的愤怒。",
},
[340] = {
["Title"] = "贝恩的残影",
["Description"] = "贝恩·血蹄在时光之末的破碎阴影徘徊于黑曜石巨龙圣地的废墟之中，因为无法保护这个世界遭受灭顶之灾，更因为无法继承父亲的遗志保护部落，贝恩的阴影变成了恼羞成怒的怪物。在这支离破碎的艾泽拉斯的未来，虽然这不堪屈辱的破碎残影仍然和现世的牛头人大酋长一样强大，他更像是一个载满怨恨与愤怒的容器，寻求释放和平息。",
},
[373] = {
["Title"] = "控火师罗格雷恩",
["Description"] = "罗格雷恩曾是大地之环中一位饱受尊敬的成员，后来却以不为人知的原因加入了暮光之锤。他最后来到了黑石深渊，突然对著名黑铁建筑师弗兰克罗恩·铸铁有了兴趣。他眼下究竟意欲何为，我们不得而知，但罗格雷恩始终忠于他的教派，任何反对教派的人都是他不共戴天的仇敌。",
},
[341] = {
["Title"] = "大主教本尼迪塔斯",
["Description"] = "大主教本尼迪塔斯是备受尊敬的圣光教会领导者。多年以来，是他睿智的指引让人性在最黯淡的时代灼灼生辉。然而，在他仁慈善心的背后，隐藏着令人震惊的事实：为了效忠他的邪恶主宰和其爪牙死亡之翼，本尼迪塔斯立誓消灭艾泽拉斯土地上的所有生灵。",
},
[2457] = {
["Title"] = "恐惧双王",
["Description"] = "许多纪元以来，纳斯雷兹姆使用了种种阴谋诡计，以确保典狱长的计划获得成果，现在，他们的主人即将获得胜利。只需要完成最后一项任务，就可以确保再也没有人可以抵抗宇宙中全新的秩序。",
},
[342] = {
["Title"] = "埃希拉·黎明克星",
["Description"] = "曾经的赏金猎人埃希拉·旭日行者一开始对暮光之锤的勾当持保留态度，但暮光教会慷慨的佣金很快使她就范。最终，她受到了她的邪恶雇主们深深的影响，逐渐屈从于堕落，甚至将自己改名为“黎明克星”。作为暮光教会最致命的杀手之一，埃希拉这次的任务是铲除萨尔和他的战友们。",
},
[436] = {
["Title"] = "多米尼娜",
["Description"] = "当萨利维丝不能再提供魔法庇护后，多米尼娜献祭了这头纳迦以强化自己的黑暗仪式。与她的前任不同，黑暗女士多米尼娜并不害怕阿库麦尔，并亲手喂给这头野兽不计其数的无辜者，以博取古神们的青睐。",
},
[111] = {
["Title"] = "岩皮",
["Description"] = "上古之神强化了死亡之翼身为大地守护者的力量，让他轻易地就使得深岩之洲的石龙为暮光之锤效忠。这些生物中最有抱负的一个就是岩皮。他会铲除任何胆敢进入巨石之核的入侵者，希望能够借此赢得死亡之翼的青睐。",
},
[112] = {
["Title"] = "欧泽鲁克",
["Description"] = "从深岩之洲的创造之初，欧泽鲁克就一直是巨石之核的守护者。没有人知道他为什么还留在那里，但是很明显，这名守护者认为任何对死亡之翼不利的人，都是深岩之洲的威胁，应该予以消灭。",
},
[455] = {
["Title"] = "吞咽者拉姆斯登",
["Description"] = "拉姆斯登是天灾军团最臭名昭著的憎恶之一，是由许多具尸体缝合而成的可怕怪物，还有着永不满足的食欲。当天灾军团侵入斯坦索姆时，这只怪物对无数无辜者的灵魂犯下了令人发指的暴行。",
},
[2323] = {
["Title"] = "玉火大师",
["Description"] = "在外行人眼里，玛拉·恐牙和阿纳索斯·召火者是对古怪的搭档。但事实上，他们的合作极其亲密无间，两人合力足以攻无不克。",
},
[459] = {
["Title"] = "梦境守望者",
["Description"] = "四条前途光明的幼龙随伊兰尼库斯一同进入了阿塔哈卡神庙，急于证明自己能为伟大强力的飞龙助上一臂之力。结果却一个接一个遭到了翡翠梦魇的囚禁和腐化，现在终日在沉没的神庙里游荡，朝那些胆敢打扰自己清梦的不速之客发泄怒气。",
},
[95] = {
["Title"] = "梵妮莎·范克里夫",
["Description"] = "当梵妮莎还是一个小女孩的时候，她亲眼目睹了父亲艾德温·范克里夫的悲惨下场。作为前任迪菲亚兄弟会领袖之女，她接过父亲领袖的衣钵，在迪菲亚兄弟会据点死亡矿井的黑暗回廊里厉兵秣马，谋划着对暴风城的复仇。",
},
[380] = {
["Title"] = "霍尔雷·黑须",
["Description"] = "如果仅把黑须说成是黑铁酒吧的常客，那也太轻描淡写了。在过去十年间，这个搞怪的酒鬼只离开过酒吧一次，还是去偷雷霆啤酒的绝密配方。黑须偶尔也会清醒一阵子，亲自动手调制这美酒，并宣称喝下此酒的人能获得难以想象的力量与勇气。",
},
[467] = {
["Title"] = "鲁维罗什",
["Description"] = "在铁炉堡颇富威信的探险者协会里，有杰出人士提出，在其族人和穴居人之间存在着某种古老的联结，并指出，穴居人贮存的泰坦神器，正彰显着矮人自身对这种神奇装置的崇拜。假如果真如此，这位名叫鲁维罗什的穴居人就应该被看作是穴居人中的考古学家，尽管任何略有历史概念的冒险者在遇到他时，都会更愿意把他称作小偷。",
},
[2773] = {
["Title"] = "泽克维尔",
["Description"] = "",
},
[381] = {
["Title"] = "法拉克斯",
["Description"] = "在黑铁酒吧里几乎每天都上演着酒后滋事的戏码，直到最近才有所改观。酒吧老板普拉格派法拉克斯出马，大大降低了酒徒们闹事的频率，这是一个强大的魔像保镖，负责维持酒吧里的秩序，用极端暴力手段赶走那些无事生非的顾客。",
},
[1391] = {
["Title"] = "邪能领主扎昆",
["Description"] = "邪能领主被燃烧军团中的部分学者视为普通恶魔卫士的进化版，直接听命于阿克蒙德。他们的残酷天性与野蛮力量交相辉印。而扎昆的任务正需要他同时发挥这两项才能：击溃战歌氏族顽固而傲慢的兽人酋长的钢铁意志……",
},
[124] = {
["Title"] = "神殿守护者安努尔",
["Description"] = "泰坦在控制起源大厅最后的日子里，将掌握圣光所需的意志力赐予了神殿守护者安努尔。他被授命裁判那些进入神殿的人们是否纯洁。",
},
[1395] = {
["Title"] = "玛诺洛斯",
["Description"] = "嗜血而野蛮的玛诺洛斯一直是阿克蒙德最恐怖的手下。即使在被格罗玛什奋力斩杀之后，他的鲜血还被古尔丹当成了收买钢铁部落及其盟友的筹码。现在，古尔丹和他的爪牙正想方设法复活玛诺洛斯支离破碎的尸骨，好让他继续为燃烧军团效力。",
},
[126] = {
["Title"] = "安拉斐特",
["Description"] = "安拉斐特维护单位的用途是维护起源大厅的内部运作。一旦设施遭到外来物的污染，安拉斐特将获得攻击程式的权限，不计一切代价歼灭入侵者。",
},
[383] = {
["Title"] = "普拉格",
["Description"] = "他们说，在黑铁酒吧里，人人都知道彼此的名字。这种亲密无间的友爱之情都是普拉格的功劳，他是一位在诺莫瑞根陷落后来黑石深渊开创新生活的麻风侏儒。虽然他过去是个与魔鬼打交道的术士，但现在却对自己酒吧老板的身份引以为傲，确保让顾客的酒杯里永远美酒满溢。",
},
[96] = {
["Title"] = "灰葬男爵",
["Description"] = "灰葬男爵被狼人所杀，随后被遗忘者将其复活成亡灵。这个叛徒擅长使用暗影的力量，将他的敌人玩弄于鼓掌之间。",
},
[384] = {
["Title"] = "弗莱拉斯总大使",
["Description"] = "由于对拉格纳罗斯无比忠诚，弗莱拉斯以大使的尊贵身份被派往黑铁部族。这个卑鄙的家伙起初对他的矮人盟友们不屑一顾，但渐渐地对他们嗜好破坏的性格心生尊敬。为了展示团结，弗莱拉斯担负起守卫魔法之厅的重任，这是矮人们用来强化武器的圣所。",
},
[385] = {
["Title"] = "黑铁七贤",
["Description"] = "几个世纪以前，巫王索瑞森和他麾下七位最强大的黑铁同伴误打误撞地将拉格纳罗斯召唤进了艾泽拉斯，并致使自己的整个部族都惨遭奴役。尽管七贤在仪式中死亡，但他们不得安息的灵魂却一直在黑石深渊徘徊，被迫为自己的元素主人和现在的黑铁统治者效命。",
},
[386] = {
["Title"] = "玛格姆斯",
["Description"] = "弗莱拉斯大使让熔火巨人玛格姆斯守卫达格兰·索瑞森大帝的王座厅，但这一做法也没能让这位黑铁统治者放下忧虑。由于惧怕暗杀，大帝甚至允许玛格姆斯控制位于他王室门外的众多喷火雕像。",
},
[387] = {
["Title"] = "达格兰·索瑞森大帝",
["Description"] = "达格兰·索瑞森大帝与敌对铜须部族的茉艾拉公主共掌统治大权。没人知道新娘究竟是受到了大帝的迷惑，还是自愿与他作伴。但不论真相如何，索瑞森的继续存在，始终会对他部族的未来造成不良影响。只要他还活着，黑铁矮人就仍是拉格纳罗斯的马前卒，也是艾泽拉斯各个王国的致命威胁。",
},
[97] = {
["Title"] = "席瓦莱恩男爵",
["Description"] = "在这座城堡尚未落入阿鲁高狼人之手的时候，席瓦莱恩男爵是这里的主人。现在他被诅咒的灵魂召唤着将他杀害的狼人，惩处那些侵入其家园的来犯者。",
},
[388] = {
["Title"] = "欧莫克大王",
["Description"] = "欧莫克以铁腕手段统治着塔内的食人魔。许多下属都提出过跟他单挑，希望借此夺取大王的头衔，但全都无一例外地倒地落败，根本碰不到他。这个神秘的现象引发了传言，说有黑暗魔法在保护着欧莫克。",
},
[389] = {
["Title"] = "暗影猎手沃什加斯",
["Description"] = "沃什加斯以她的美貌和神经病倾向在巨魔间享有盛名。作为深谙暗影猎手之道的大师，她精通妖术、诅咒与治疗魔法。",
},
[390] = {
["Title"] = "指挥官沃恩",
["Description"] = "在第二次战争期间，沃恩率奇袭小队深入高等精灵的腹地深处，执行英勇的任务。这个狡诈的巨魔之所以选择加入落败的部落，是为了要成为首席战略家，而并非认同黑手的价值观。在沃恩眼中，这卑微阵营的成员无异于丧家之犬，他乐于逾越不可克服的障碍，并享受因此获得的满足感。",
},
[391] = {
["Title"] = "烟网蛛后",
["Description"] = "几个世纪前，黑铁矮人钻入了烟网蛛后的巢穴，将这只巨型蜘蛛放进了尖塔的殿堂。从那时起，蛛后就在塔内大量繁衍蛛群，甚至就连黑手军团都不敢在烟网蛛后的地盘上随意穿行。",
},
[98] = {
["Title"] = "指挥官斯普林瓦尔",
["Description"] = "作为一名忠诚的士兵，指挥官斯普林瓦尔的鬼魂游荡在议会大厅里，用不洁之力为他的领主席瓦莱恩男爵复仇。",
},
[392] = {
["Title"] = "尤洛克·暗嚎",
["Description"] = "尤洛克是尖塔食人魔的真正领袖。这个阴险的家伙用邪恶魔法魅惑了他信赖的助手——欧莫克大王，让他代替自己控制麾下的爪牙。他不遗余力地保持着这份深居幕后的神秘感，残忍地将那些胆敢质疑欧莫克统治的食人魔尽数消灭。",
},
[1425] = {
["Title"] = "钢铁掠夺者",
["Description"] = "在奥格瑞玛陷落之后，人们在黑索本人的工作室里发现了钢铁掠夺者的图纸。它的灵感来自燃烧军团强大的构造体，是这个邪恶地精的杰作。在他死后，这个项目才真正完工，并成为钢铁部落军事力量的巅峰之作。",
},
[1427] = {
["Title"] = "永恒者索克雷萨",
["Description"] = "德莱尼最伟大的战士会将自己的灵魂灌入闪闪发光的构装体，成为永远保护人民的警戒者。索克雷萨在堕入黑暗之前曾是主教议会的一员，他改造了这个神圣的仪式，试图在塔拉多的惨败之后，用一具扭曲的邪能构装体保存自己的灵魂。",
},
[394] = {
["Title"] = "哈雷肯",
["Description"] = "哈雷肯来自以残忍和忠诚著称的伟大座狼家族。多年以来，由这位狼群之母繁育出的凶蛮后代数量惊人。有传言称，她是燃烧军团某位深渊领主送给雷德·黑手的恶魔猎犬。",
},
[395] = {
["Title"] = "奴役者基兹鲁尔",
["Description"] = "在黑暗部落里很少有人见过避世隐居、神出鬼没的基兹鲁尔。只有当配偶哈雷肯发出召唤时，这只巨兽才会从他那阴暗的巢穴中钻出来。这两只可怕的怪物已经生出了不少又大又凶残的座狼，载入了兽人繁育座狼的史册。",
},
[1433] = {
["Title"] = "暗影领主艾斯卡",
["Description"] = "在复活泰罗克并重获力量的努力失败后，陷入沮丧的艾斯卡接受了古尔丹的招揽，以换取解除塞泰的古老诅咒的机会。如今，他已飞出暗影，重返天空。作为幻象与谎言的大师，艾斯卡的复仇之日已近在咫尺。",
},
[396] = {
["Title"] = "维姆萨拉克",
["Description"] = "黑色龙兽维姆萨拉克管理着黑石塔下层的军队，随时准备向矮人发动全面攻势。他对落败的部落及其凶残的成员并无好感，为了保护自己的主人奈法利安，就算要牺牲多少黑手军团的爪牙也在所不惜。",
},
[100] = {
["Title"] = "高弗雷勋爵",
["Description"] = "身为吉尔尼斯贵族及被遗忘者的眼线，狡猾而又多智的高弗雷勋爵擅使双枪，麾下还有大批残忍嗜血的食尸鬼。",
},
[402] = {
["Title"] = "瑟雷姆·刺蹄",
["Description"] = "为了向燃烧军团证明自己的价值，瑟雷姆·刺蹄告诉他的主人，他能奴役那些仍在厄运之槌徘徊的强大先祖。当他意识到自身力量的不足时，刺蹄就开始从其它生灵身上寻找额外的能量，将他们在祭坛上杀死，在其苦痛难耐的临终之际收集他们的精魄。",
},
[403] = {
["Title"] = "海多斯博恩",
["Description"] = "当名叫瑟雷姆·刺蹄的萨特想要控制厄运之槌的元素时，在他祭坛下方池塘中平静居住的海多斯博恩引起了他的注意力。在他进行邪恶的献祭仪式时，元素突然变得暴怒不安，出水攻击刺蹄的恶魔爪牙。一晃许多年过去了，刺蹄不断用牺牲者的能量激起海多斯博恩的狂怒，渐渐使他甘心接受自己的命令。",
},
[101] = {
["Title"] = "纳兹夏尔女士",
["Description"] = "在从蛮勇的克瓦迪尔手中夺回瓦丝琪尔的过程中，纳兹夏尔女士扮演了至关重要角色。她因此赢得了艾萨拉女王的青睐。最近，纳兹夏尔身先士卒，率军对耐普图隆发动了进攻，并成功地将这位强大的元素领主困在了海潮王座中。",
},
[404] = {
["Title"] = "蕾瑟塔蒂丝",
["Description"] = "厄运之槌的扭曲能量将蕾瑟塔蒂丝从远方吸引而来，令对奥术魔法有着无尽渴求的她看到了希望。她用献祭牺牲者的肌肉和韧带制出了特殊的网，从东翼虹吸腐化之力。让她高兴的是，她发现这个装置能收集并贮存势不可当的强大力量，足以送所有敌人归西。",
},
[1447] = {
["Title"] = "祖霍拉克",
["Description"] = "被古尔丹从扭曲虚空深处召唤出来的祖霍拉克是最强大的虚空亡魂之一——这种寄生性的虚空生物以撕裂空间，吞噬现实位面的能量和生物为生。古尔丹扭曲了祖霍拉克，对他灌输了庞大的恶魔能量，并利用他的力量开启传送门，以召集燃烧军团的大军。",
},
[406] = {
["Title"] = "特迪斯·扭木",
["Description"] = "特迪斯·扭木是埃雷萨拉斯的忠诚守护者，他的内心坚定地与这座城市的命运紧紧联系在一起。当大分裂使这片土地变得支离破碎时，他的决心也从未动摇过分毫，但当腐化之力在接下来的一万年间渗入废墟，这位先祖的灵魂也未能幸免于难。",
},
[407] = {
["Title"] = "伊琳娜·暗木",
["Description"] = "伊琳娜·暗木与她忠实的伙伴费拉，曾经是托塞德林王子最得力的猎手，后来，她因拒绝执行领袖的命令，不肯处死自己的伙伴而遭到重罚。托塞德林王子杀死了伊琳娜和她的熊，而且还用恶魔之力将他们的灵魂束缚在躯体上，责罚他们以亡灵守护者的身份继续留在厄运之槌。",
},
[102] = {
["Title"] = "指挥官乌尔索克，腐烂王子",
["Description"] = "乌尔索克是一名邪恶的上古生物，上古之神派他来帮助纳兹夏尔女士侵略潮汐王座。乌尔索克浑身迸发着罪恶的力量，在瓦丝琪尔最深邃的海沟里指挥着无面者军团。",
},
[408] = {
["Title"] = "卡雷迪斯镇长",
["Description"] = "当托塞德林王子下令处死大部分臣民时，他最忠心的中尉们负责执行他的意志。卡雷迪斯镇长不假思索地杀死了许多毫无戒备的辛德拉精灵，但在这群厄难临头的精灵中，却有一位在混战中对他造成了致命伤。但凡躯虽死，卡雷迪斯的灵魂却仍在厄运之槌游荡，继续为托塞德林保驾护航。",
},
[409] = {
["Title"] = "伊莫塔尔",
["Description"] = "当永恒之井被摧毁后，辛德拉精灵为重获往日的力量与不死之身，将魔鬼召进了厄运之槌的西翼，并将他禁锢在力场之内，用虚空恐魔的能量强化自己的法术。伊莫塔尔在将近一万年间无力回击，甚至动弹不得，只能眼巴巴地等待自己挣脱束缚的那一天，将囚禁者大卸八块。",
},
[410] = {
["Title"] = "托塞德林王子",
["Description"] = "在永恒之井遭到毁灭后，托塞德林王子将一只恶魔囚禁在埃雷萨拉斯的废墟间，继续统治幸存的辛德拉精灵，并让自己的臣民从中汲取力量。恶魔之力扭曲了托塞德林的心智，而当那恶魔力量衰退时，王子便下令处死了许多民众，只有他和那些最狂热的追随者们才能继续享用腐化能量。",
},
[411] = {
["Title"] = "卫兵摩尔达",
["Description"] = "摩尔达是戈多克食人魔中的狂热忠诚守卫。他说服戈多克大王赏给他一副施了魔法的手套，使他在族人间连续六年荣膺掰腕子大赛的冠军。事实上，戈多克大王是把这强大的护甲丢弃了，摩尔达只不过是第一个捡到它的人而已。",
},
[103] = {
["Title"] = "蛊心魔古厄夏",
["Description"] = "在深渊裂口的英勇一战后，大地之环的萨满石语者埃鲁纳克最终还是被纳迦军队所俘获，并沦为蛊心魔古厄夏的奴隶。恐怕这只寄生的畸兽已经彻底控制了埃鲁纳克的心智、肉体，以及他那毁灭性的萨满法术。",
},
[412] = {
["Title"] = "践踏者克雷格",
["Description"] = "鬼祟的刺客们不止一次因打翻克雷格的酒杯而惨遭毒手。尽管他总是会在当值时喝得酩酊大醉，但是只要一听到杯中美酒洒在石头地面上的声音，这位食人魔就会立即醒来，勃然大怒。",
},
[1467] = {
["Title"] = "提拉宋·萨瑟利尔",
["Description"] = "提拉宋曾是主人的盟友，后来为了得到更强大的力量而和燃烧军团狼狈为奸。被囚禁多年的他心中充满恨意，妨碍他的人都会惨遭折磨。如果碍事的碰巧是之前囚禁他的人，那就更痛快了。",
},
[1469] = {
["Title"] = "格雷泽",
["Description"] = "格雷泽和很多同类恶魔一样，能将凝望的目光汇聚成强有力的武器对付敌人。守望者发现把这种生物发射出的魔法反射回它本身就能使它陷入虚弱状态。他们利用这一点诱捕这种恶魔，并将其关在由镜子制成的监狱里。现在关不住了。",
},
[368] = {
["Title"] = "加摩拉",
["Description"] = "当邪教暮光之锤到来时，其信徒唤醒并囚禁了艾露恩神殿中的最后一只宁静生物。邪教徒们乐此不疲地将这只巨龟折磨了许多年，将它的灵魂与身体剥离，直到它终于陷入疯狂。邪教徒们把这只巨龟命名为加摩拉，试图控制它的野性，用它来保卫巢穴。",
},
[416] = {
["Title"] = "观察者克鲁什",
["Description"] = "克鲁什并没有既定立场，但当乌尔洛克掌权后，他的力量显然已经变得不可动摇。国王很快便任命克鲁什担任他的首席顾问，相信他的双头一定能带来令普通食人魔望尘莫及的双倍睿智。",
},
[369] = {
["Title"] = "审讯官格斯塔恩",
["Description"] = "暮光之锤邪教徒格斯塔恩向来沉湎于对生活品质的不懈追求：异国料理，靓衣华服，就连刑具都是由宝石镶嵌而成。囚徒那令人毛骨悚然的哭号声日夜在黑铁部族声名狼藉的禁闭室中回响。格斯塔恩骄傲地宣称，这骇人的声音是她谱写的尖叫交响曲，而她则时刻渴望在这和声中加入新的音色。",
},
[422] = {
["Title"] = "机械师瑟玛普拉格",
["Description"] = "杀人犯、叛徒、自我加冕的侏儒国王，机械师希科·瑟玛普拉格用破绽百出的铁腕手段统治着诺莫瑞根的放射性殿堂。他的臣民数量众多，邪恶疯狂，足以保护自己的疯王免受任何来自地上世界的侵袭。正是瑟玛普拉格的疯狂使他变得极其危险——他有着摧毁身边万物的狡诈，且丝毫不顾自身安危。难怪就连诺莫瑞根里的怪物都对他望而生畏。",
},
[1479] = {
["Title"] = "瑟芬崔斯克",
["Description"] = "驻扎在艾萨拉之眼的纳迦对北部边界敬而远之。因为那里的浅滩上住着一只古老的有鳞怪兽，它偶尔会伸出脖子吞掉附近的猎物。",
},
[424] = {
["Title"] = "锐刺鞭笞者",
["Description"] = "创造锐刺鞭笞者的初衷是为了让它在玛拉顿里陪伴诺克赛恩。随着时间的推移，这一全新造物却成了公主最珍爱的仆从之一。锐刺鞭笞者与诺克赛恩并肩在洞穴里游荡，用长满尖刺的卷须将所能找到的任何未受污染的植物撕成碎片。",
},
[371] = {
["Title"] = "驯犬者格雷布玛尔",
["Description"] = "格雷布玛尔·蚤须的猎犬是他唯一的家人。早在许久以前，这个矮人孤儿就开始繁育幼犬，把它们当做同伴和看门狗。要是驯犬者没有带上他的忠实跟班在黑石深渊里巡逻，那他通常就是在黑铁酒吧里喂它们喝上好的黑铁啤酒。",
},
[1485] = {
["Title"] = "海姆达尔",
["Description"] = "金盔金甲、高大魁梧的海姆达尔机警的守护着英灵殿的大门，一刻也不懈怠。他奉奥丁之命，防止没有资格的宵小之辈擅入英灵殿。他吹响号角还能招来附近盘旋的凶猛的风暴幼龙供他差遣。英灵殿由他当关，万夫莫开。",
},
[1487] = {
["Title"] = "芬雷尔",
["Description"] = "在永恒猎场之中，强大的维库勇士们磨炼着他们的战斗技艺，竞相猎杀最巨大的猛兽。但不论是人还是猛兽，若是遇上了可怕的芬雷尔也只能慌忙逃窜。它是猎场的真正主宰，总是悄悄接近猎物，然后以惊人的速度一击致命。",
},
[1489] = {
["Title"] = "奥丁",
["Description"] = "泰坦守护者奥丁接受了泰坦万神殿的力量，奉命率领泰坦铸造的大军对抗上古之神。之后，他将英灵殿升入天空，召集最强大的维库勇士组建起一支大军保卫艾泽拉斯。但奥杜尔落入尤格萨隆的魔爪后，他遭到了洛肯的背叛，并被海拉诅咒，现在永远困在了英灵殿内。",
},
[1491] = {
["Title"] = "深须国王",
["Description"] = "水手之中流传着海底巨人的传说，这个巨人会从深海中突然出现，并徒手把船只扯碎。据说他留下完好无损的船头当做肩甲和战利品穿在身上。大多数听众都不把这个传说当回事，认为这只是酒后的胡言罢了。",
},
[433] = {
["Title"] = "火眼莫德雷斯",
["Description"] = "亡语者布莱克松通过亡灵巫术重新点燃了火眼莫德雷斯的灵魂之焰，使他再度复活。\r\n\r\n生前作为萨满的莫德雷斯，复活后展现出了奴役元素的扭曲能力。他将毫不犹豫地烧死所有胆敢阻碍亡语者的人。",
},
[374] = {
["Title"] = "伊森迪奥斯",
["Description"] = "迦顿男爵教伊森迪奥斯驾驭自己的破坏力，可男爵怎么也没有想到，这位仆从竟会带来如此大的威胁。对伊森迪奥斯篡权的担忧日滋夜长，迦顿终于决定将这炽热元素逐出熔火之心，命其守卫黑铁矮人传奇的黑铁砧。",
},
[1497] = {
["Title"] = "伊凡尔",
["Description"] = "无法从暗夜井获取力量的伊凡尔被放逐进了黑暗的魔法回廊，他在那里漫无目的游荡，同时力量逐渐流失。但后来，他在苏拉玛的大图书馆的地基处发现了宝藏。现在他天天不知疲倦地破译那里的典籍，并吸取档案馆里圣物的力量维持生命。但圣物的力量只能维持他的肉体，他的心智依然日益衰弱。",
},
[1499] = {
["Title"] = "萨卡尔将军",
["Description"] = "古尔丹威胁说如果艾利桑德不满足他的要求，就把苏拉玛夷为平地。他并非随口说说而已。一支军团入侵部队挖地道潜入了城市，领队的是萨卡尔。他只待上头一声令下，就会冲上地面，在苏拉玛城内大开杀戒。",
},
[1501] = {
["Title"] = "顾问凡多斯",
["Description"] = "凡多斯是艾利桑德最倚重的顾问之一，他驾驭暗夜井魔力的能力仅次于艾利桑德本人。他通常不会亲自深入魔法回廊，但在留意到堕夜精灵抵抗军及其盟友的状态后，他感觉有必要亲自出马了。",
},
[376] = {
["Title"] = "弗诺斯·达克维尔",
["Description"] = "首席建筑师弗诺斯·达克维尔将其它更具天赋泥瓦匠的创意据为己有，并因此声名鹊起。他的傲慢与心计使长眠地下的前辈——弗兰克罗恩·铸铁心生怨愤。这位已故首席建筑师的鬼魂想要从达克维尔手中夺回他那把威力无比的铁胆之锤，以防它被用来作恶。",
},
[446] = {
["Title"] = "希望破坏者威利",
["Description"] = "巴纳扎尔愉快地发现，炮手威利在变成了亡灵之后仍能驾驭他那极具破坏性的力量，于是他给这位得力仆从起了个好名字——希望破坏者。恐惧魔王恣意扭曲威利和其他血色十字军成员的灵魂，把这些生时对亡灵恨之入骨的人，变成他的无脑爪牙。",
},
[377] = {
["Title"] = "贝尔加",
["Description"] = "可怕的熔岩巨人贝尔加在黑铁大道上隆隆缓行，黑铁大道是筑于黑石深渊内部的矮人工程学建筑奇迹。拉格纳罗斯将这巨人从火焰之地的中心地带引来这里，命他看守位于大道尽头的封印重门。相传，只有火焰领主和黑铁氏族最德高望重的成员才知道在那扇神秘的大门背后，究竟藏着什么。",
},
[449] = {
["Title"] = "巴纳扎尔",
["Description"] = "巴纳扎尔从没体会过真正的死亡，但他却尝过失败的苦果。在世界被大灾变破坏之后，他杀死了斯坦索姆中的血色十字军成员，并将他们变成了自己曾经憎恨的亡灵生物。这位恐惧魔王如今正在酝酿着对艾泽拉斯复仇的诡计。",
},
[378] = {
["Title"] = "怒炉将军",
["Description"] = "经过毕生钻研，怒炉将军已成为矮人军事历史与用兵学的行家里手。他最近撰写了一篇抨击部族过往败绩的严苛文章，引得达格兰·索瑞森大帝大发雷霆。抛开这个政治错误不提，怒炉本质上还是个够格的黑铁矮人。为保护自己的人民与皇帝，他甘愿流血，乃至牺牲。",
},
[457] = {
["Title"] = "哈卡的化身",
["Description"] = "哈卡惯于把追随者当成祭品，因此声名狼藉。千万年前，他命阿塔莱建造祭坛，将从活人身上汲取的鲜血进献给它。阿塔莱祭司现在想对这一仪式略作修改，以献祭绿龙的方式供奉哈卡祭坛。一旦阿塔莱成功了，哈卡祭坛便会复现，艾泽拉斯将在劫难逃。",
},
[379] = {
["Title"] = "傀儡统帅阿格曼奇",
["Description"] = "阿格曼奇毕生对长生不死的追求，使他按自己的样貌造出了魔法替身。有传闻说，他甚至使用了某种形式的黑暗魔法，当这位傀儡统帅的血肉之躯遭到毁坏时，他的新造物便能成为他灵魂的容器。",
},
[115] = {
["Title"] = "阿尔泰鲁斯",
["Description"] = "巨大的风暴之龙阿尔泰鲁斯不知疲倦地警戒着旋云之巅的浮空平台。风暴的能量在他体内脉动，传说他还驾驭着驱动着这座元素堡垒的气流。",
},
