[127] = {
["Title"] = "伊希斯特，魔法的造物",
["Description"] = "起源大厅所产生的奥术能量充盈在其内部，伊希斯特的职责就是对其进行调控。传说这个构造体对这一貌似是天赐的奥术掌控能力过于沉迷了。",
},
