["2x17114"] = {
["Title"] = "艾泽里特灌注",
["Description"] = "向一名地怒者注入艾泽里特，每1秒恢复其25%的生命值，持续2秒。注入完成时，地怒者获得强化，将它从群体控制中解救出来并使其造成的伤害提高50%，受到的伤害提高150%。\r\n\r\n同时每2秒产生艾泽里特能量脉冲，对所有玩家造成4点奥术伤害。\r\n\r\n优先影响未受到水力压裂图腾或其他群体控制效果的目标。",
},
["15x8359"] = {
