["1x4700"] = {
["Title"] = "步行炸弹",
["Description"] = "机械师瑟玛普拉格激活了附近的一个炸弹套件，使其周期性地释放步行炸弹，随机攻击一名玩家。在激活炸弹套件另一侧的红色开关之前，它会不断发射步行炸弹。",
},
["14x8305"] = {
["Title"] = "阶段转换：亚煞极之境",
["Description"] = "亚煞极周期性的召唤会将加尔鲁什和玩家传送进亚煞极之境，持续1.0分钟。加尔鲁什将恢复10%的最大生命值，并开始从亚煞极之心上吸收能量，直至玩家击败领域内所有亚煞极的爪牙并将其打断。",
},
["15x14216"] = {
["Title"] = "毒水吐息",
["Description"] = "喷出污秽的腐蚀气息，对正前方锥形范围内的敌人造成383点冰霜伤害并施加|cffffffff毒水氧化|r效果。\r\n\r\n生成数个毒水软泥怪拍击地面，对周围5码范围内的敌人造成104点冰霜伤害。",
},
["16x32720"] = {
