["17x14698"] = {
["Title"] = "折磨",
["Description"] = "当阿提甘和贝拉克攻击玩家时，折磨效果会逐渐积累。达到最大值时玩家将受到无法忍受的折磨影响，必须通过忏悔来移除此效果。",
},
["16x10509"] = {
["Title"] = "坦克",
