},
["14x32203"] = {
["Title"] = "游离震击",
["Description"] = "混乱能量在地面上爆发，对冲击点周围4码内的玩家造成29点奥术伤害，并使其昏迷2秒。",
},
["1x7347"] = {
["Title"] = "霜降",
