["15x27316"] = {
["Title"] = "地狱怒火",
["Description"] = "能量达到100点时，拉罗达尔肆意宣泄怒火，释放出烈焰波，每2秒对敌人造成374点火焰伤害，持续6秒。站在|cffffffff复苏的刺藤屏障|r后可使该伤害降低90%。\r\n\r\n狂暴地狱火结束后，拉罗达尔获得一层爆燃气息。",
},
["2x6025"] = {
["Title"] = "流星",
["Description"] = "势不可挡哈伊岩随机向一名玩家投掷一块火焰投石。流星落地时会对半径10码范围内的敌人造成总计136点火焰伤害，由受影响区域内的所有玩家平均分摊。",
},
["1x6025"] = {
["Title"] = "流星",
["Description"] = "势不可挡哈伊岩随机向一名玩家投掷一块火焰投石。流星落地时会对半径10码范围内的敌人造成总计81点火焰伤害，由受影响区域内的所有玩家平均分摊。",
},
["17x31756"] = {
