["14x14659"] = {
["Title"] = "综述",
["Description"] = "大魔导师艾利桑德使用暗夜井的力量塑造时间。她在生命值低到濒临死亡时会回溯时间，让玩家回到刚开始与她交战的时间点。战斗从这个时间点重新开始，但是艾利桑德会在她过去的回响中混入新的技能。她可以回溯两次时间，之后就连时间也无法拯救她了。",
},
["23x28820"] = {
["Title"] = "酸液翻腾",
["Description"] = "拉夏南向被标记的目标掷出剧毒混合物，随后从目标的位置朝指定方向溅起波浪。\r\n\r\n被最初的腐蚀喷发溅射到的玩家会陷入|cffffffff酸蚀昏迷|r。\r\n\r\n触及波浪的玩家的移动速度降低50%，并且每1秒获得|cffffffff腐蚀|r。\r\n\r\n波浪会烧毁|cffffffff粘性蛛网|r，对5码内的玩家造成37点自然伤害，并产生|cffffffff酸液池|r。",
},
["2x27828"] = {
["Title"] = "艾蕾娜·安博兰兹",
["Description"] = "",
},
["17x13202"] = {
["Title"] = "渗透腐蚀",
["Description"] = "梦魇恐魔存活时，每隔一段时间会在脚下制造梦魇腐蚀之池。",
},
["33x2851"] = {
["Title"] = "炽炎之能",
["Description"] = "奥利瑟拉佐尔继续放出火环，让它们出现在战斗区域的地面上，持续3秒。穿过火环的玩家将会获得炽炎之能的效果，提高急速8%，最多叠加25次。此外，每层炽炎之能都会恢复法力、怒气、能量、符文能量、神圣能量，并且刷新烈焰之翼的持续时间。",
},
["8x21789"] = {
["Title"] = "综述",
["Description"] = "哈卡会使用|cFF2959D3|Hspell:322773|h[鲜血屏障]|h|r保护自己，然后释放一次毁灭性的|cFF2959D3|Hspell:323064|h[鲜血弹幕]|h|r。哈卡的阿塔莱祭司也会来协助他，并在战斗中变为哈卡之子。",
},
["6x4119"] = {
["Title"] = "堕落熔岩",
["Description"] = "堕落熔岩从死亡之翼体内涌出，每2秒造成火焰伤害。死亡之翼的生命值越低，伤害越高。当其生命值降至15%、10%和5%，死亡之翼会出血。这将使堕落熔岩造成的伤害提高。",
},
["7x4119"] = {
["Title"] = "堕落熔岩",
["Description"] = "堕落熔岩从死亡之翼体内涌出，每2秒造成火焰伤害。死亡之翼的生命值越低，伤害越高。当其生命值降至15%、10%和5%，死亡之翼会出血。这将使堕落熔岩造成的伤害提高。",
},
["23x22086"] = {
["Title"] = "光辉残片",
["Description"] = "兹拉莉释放15个她的力量碎片。任何触碰到碎片的玩家受到|cffffffff至高仪式|r的伤害降低20%。最多叠加5次。",
},
["23x31551"] = {
["Title"] = "虚体",
["Description"] = "塔尔·巴特化作纯粹的能量，使受到的伤害降低99%，直到离开以太位面。\r\n\r\n被|cffffffff迁跃打击|r击中时，塔尔·巴特失去一层|cffffffff虚体|r。失去所有|cffffffff虚体|r层数时，阿瓦兹吉和塔尔·巴特都会陷入|cffffffff动荡能量|r。",
},
["16x19395"] = {
["Title"] = "火球术",
["Description"] = "投掷火焰球，造成火焰伤害。受害者会受到升腾之焰的影响。",
},
["17x31600"] = {
["Title"] = "易爆凝视",
["Description"] = "行走的高爆炸药随机追逐一名玩家，持续12秒。抵达目标身边时爆炸，对所有玩家造成50点火焰伤害。\r\n",
},
["19x2138"] = {
["Title"] = "不忠之盾",
["Description"] = "当指挥官斯普林瓦尔获得三层邪恶能量后，他会消耗它们，从盾中释放这股力量。不忠之盾每0.5秒对指挥官斯普林瓦尔正前方25度角范围内的敌人造成11点暗影伤害，持续3秒。",
},
["3x5771"] = {
["Title"] = "蓝晶守护者",
["Description"] = "蓝晶守护者在另一个守护者附近12码范围内时可获得能量。守护者用该能量来施放蓝晶过载。如果范围内没有其他守护者，则获得坚固的石头效果。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在10人普通难度下，每周轮流出现四个守护者中的三个。|r",
},
