["15x26664"] = {
["Title"] = "熔岩波浪",
["Description"] = "一股翻滚的熔岩波浪，每1秒对区域内的玩家造成62点火焰伤害。",
},
["14x30854"] = {
["Title"] = "潜行",
["Description"] = "隐藏施法者。该效果将在进入战斗时被移除。",
},
["14x30853"] = {
["Title"] = "心灵震爆",
["Description"] = "对一名敌人造成30点暗影伤害。",
},
["2x4688"] = {
["Title"] = "火球术",
["Description"] = "观察者克鲁什对一名玩家造成火焰伤害。",
},
["1x4688"] = {
["Title"] = "火球术",
["Description"] = "观察者克鲁什对一名玩家造成火焰伤害。",
},
["16x8410"] = {
["Title"] = "超载的激光炮台",
