["24x12397"] = {
["Title"] = "坦克",
["Description"] = "$bullet; |cFF2959D3|Hspell:197513|h[自爆月刃]|h|r会使你受到的物理伤害提高。\r\n$bullet; |cFF2959D3|Hspell:213576|h[侵蚀之影]|h|r会不断在平台扩散，除非被|cFF2959D3|Hspell:192656|h[艾露恩之光]|h|r摧毁。\r\n$bullet; |cFF2959D3|Hspell:197422|h[末日恶灵]|h|r的灵魂无法被看见，除非被|cFF2959D3|Hspell:192656|h[艾露恩之光]|h|r揭露。\r\n$bullet; |cFF2959D3|Hspell:192656|h[艾露恩之光]|h|r揭露复仇的化身后，要尽快建立威胁值。",
},
["14x11264"] = {
["Title"] = "死亡挣扎",
["Description"] = "每2秒对敌人造成18点火焰伤害，持续6秒。目标距离基尔罗格·死眼越远，受到的伤害越低。同时还向远处的随机位置发射飞弹，对5码范围内的敌人造成63点火焰伤害。",
},
["2x14686"] = {
["Title"] = "爆炸暗影",
["Description"] = "对被触发的混沌暗影球周围10码范围内的敌人造成44点暗影伤害。",
},
["15x30251"] = {
["Title"] = "回响联结",
["Description"] = "施法者与其他同类维系着黑暗的联结，将受到伤害的100%复制给其他同类。\r\n\r\n这些生物距离过近时会产生共鸣，免疫所有伤害，并且每1.5秒对所有玩家造成6点暗影伤害。每次脉冲使该伤害提高100%。",
},
["14x28078"] = {
["Title"] = "丝纹轰击",
["Description"] = "尼穆威用织纹光束轰击主要目标，造成125点物理伤害和62点自然伤害。",
},
["15x20687"] = {
["Title"] = "毁灭",
["Description"] = "毁灭施法者面前的玩家和教徒，每0.25秒造成6点暗影伤害，持续5秒。\r\n\r\n每次命中都会使其受到毁灭的伤害提高25%，持续6秒，最多叠加20次。",
},
["14x15055"] = {
["Title"] = "吞噬巨口",
["Description"] = "萨鲁克张开喉咙，吸入所有玩家，每2秒造成1,144点冰霜伤害。如果玩家进入萨鲁克的15码之内，则会被彻底吞噬。吸入3团|cffffffff污染墨汁|r云雾后，萨鲁克会感到恶心并逃走。",
},
["14x30850"] = {
["Title"] = "烈火之环",
