["2x10090"] = {
["Title"] = "综述",
["Description"] = "枯木在攻击玩家团队时会变得越来越脱水，不断消耗所储存的水源能量。当枯木的水源能量耗尽时，他会将自己扎根地下，同时引导周围湖边的小水滴为自己恢复活力。玩家可在那些小水滴抵达枯木根前摧毁它们，阻碍其恢复活力。",
},
["1x10090"] = {
["Title"] = "综述",
["Description"] = "枯木在攻击玩家团队时会变得越来越脱水，不断消耗所储存的水源能量。当枯木的水源能量耗尽时，他会将自己扎根地下，同时引导周围湖边的小水滴为自己恢复活力。玩家可在那些小水滴抵达枯木根前摧毁它们，阻碍其恢复活力。",
},
["15x21179"] = {
