["16x20845"] = {
["Title"] = "虚空之赐",
["Description"] = "击败虚空晋升者后会掉落一个可以拾取的纯净虚空能量球体。\r\n\r\n玩家可以消耗该赠礼以施放毁灭并清除自身的虚空腐蚀。",
},
["17x9586"] = {
["Title"] = "综述",
["Description"] = "独眼魔双子会在能量达到特定阶段时使用特殊技能攻击玩家。能量达到33点时，一名独眼魔会使用他的特殊武器攻击。能量达到66点时，一名独眼魔会进行一次强力咆哮。最终，当能量达到100点时，一名独眼魔会发起一次强力的全团攻击。\r\n\r\n两名独眼魔之间的距离越远，他们的急速就会越高，施法时间也越短。相对的，玩家对其各个技能的应对时间也越短。",
},
["15x11429"] = {
["Title"] = "邪火攻城车",
["Description"] = "",
},
["14x27570"] = {
["Title"] = "生命之力屏障",
["Description"] = "泰达希尔之魂的生命力达到全满时，会受到|cffffffff生命之力屏障|r的保护，使受到的所有伤害降低99%。",
},
["17x16948"] = {
["Title"] = "灵魂凋零",
["Description"] = "在8秒内每2秒造成70点暗影伤害，效果结束时在受影响玩家的位置制造一团死亡之雾。",
},
["17x14237"] = {
["Title"] = "守护者之息",
["Description"] = "高姆的三个头会分别喷出火焰、暗影或冰霜。如果受到影响的玩家过少，高姆会获得一层吐沫狂怒。",
},
["14x27566"] = {
["Title"] = "群体缠绕",
["Description"] = "丁达尔用烈焰藤蔓瞄准所有玩家，在6秒后喷发，使目标玩家定身，并对3码区域内的玩家造成25点火焰伤害。这些根须1秒造成5点火焰伤害，直到被摧毁。",
},
["14x27537"] = {
["Title"] = "燃烧树人形态",
["Description"] = "丁达尔变形为一个烈焰树人，周期性对玩家施加压抑灰烬。",
},
["14x27532"] = {
["Title"] = "天启咆哮",
["Description"] = "菲莱克发出焚蚀血肉的咆哮，对所有玩家造成268点暗影烈焰伤害并将其击退。\r\n\r\n玩家每1秒额外受到12点暗影烈焰伤害，持续12秒。",
},
["23x25669"] = {
["Title"] = "裂树击",
["Description"] = "茂林古树以碾压性的力量猛跺目标，造成60点物理伤害并使目标受到的物理伤害提高100%，持续9秒。",
},
["14x14224"] = {
["Title"] = "第三阶段：冥狱深渊的最后一战",
["Description"] = "海拉会命令冥狱深渊的部队背水一战，召唤冥狱深渊的爪牙，并使用她的超自然力量同时发动攻击，直到被击败。",
},
["24x7409"] = {
