["16x9336"] = {
["Title"] = "综述",
["Description"] = "缚火者卡格拉兹会持续获得能量，并在能量达到特定阶段后解锁新的能力。达到100点能量时，卡格拉兹会引导火焰风暴，消耗所有的能量，并开始新的循环。",
},
["14x19592"] = {
["Title"] = "真菌绽放",
["Description"] = "施法者在其四周的土地上传播瘟疫，使大量真菌开始疯长。站在真菌的位置会使玩家受到75点瘟疫伤害。",
},
["15x23601"] = {
["Title"] = "垂死苦难",
["Description"] = "当另一个寻亡之眼还存活在平台上时，死去的寻亡之眼每8秒施放一次苦难。",
},
["15x26499"] = {
["Title"] = "星界耀斑",
["Description"] = "搁浅在|cffffffff虚渺星瀚|r中时，玩家可以吸收|cffffffff星界耀斑|r，使急速提高5%，移动速度提高10%，持续23秒。此效果可叠加。",
},
["15x19476"] = {
["Title"] = "惩戒之潮",
["Description"] = "向所有方向施放灼热的圣光之潮，对所有敌人造成7点神圣伤害。",
},
["17x25910"] = {
["Title"] = "转移精华",
["Description"] = "动荡的注能者将其自身的精华引导至达瑟雅，周期性地使她造成的所有伤害提高10%，持续20秒。该效果可叠加。\r\n",
},
["16x26502"] = {
["Title"] = "土灵碎击",
["Description"] = "莱修克猛击当前目标，造成681点物理伤害，并使其受到|cffffffff土灵碎击|r的伤害提高3,000%，持续6秒。",
},
["15x15134"] = {
["Title"] = "黑暗印记",
["Description"] = "堕落的化身对一名目标施放烙印，使其在6秒后释放出暗影能量，造成18,326点暗影伤害，由8码范围内的所有玩家平摊，并将这些玩家击飞。",
},
["17x19513"] = {
["Title"] = "怒意释放猫眼石",
["Description"] = "携带猫眼石时你攻击的每个新生物都会获得一层狂野怒意。",
},
["2x5347"] = {
["Title"] = "顺劈斩",
["Description"] = "埃欧努斯对一名玩家及离其最近的盟友造成物理伤害，最多可影响3个目标。",
},
["1x5347"] = {
["Title"] = "顺劈斩",
["Description"] = "埃欧努斯对一名玩家及离其最近的盟友造成物理伤害，最多可影响3个目标。",
},
["15x26455"] = {
["Title"] = "粉碎",
["Description"] = "撞击一块|cffffffff扭曲大地|r并将其击碎，对受到撞击的玩家造成19点物理伤害r。 撞击产生碎片，在14秒内每1秒对所有玩家造成6点物理伤害。该效果可叠加。\r\n\r\n同时在房间中坠下|cffffffff崩塌碎石|r。",
},
["15x26453"] = {
["Title"] = "熔火疮疤",
["Description"] = "焦土每1秒对站在其中的玩家造成64,249点暗影烈焰伤害。",
},
["15x26452"] = {
["Title"] = "痛苦射线",
["Description"] = "卡扎拉召唤炽热的能量碎片，从|cffffffff恐惧裂隙|r中爆发而出。每块碎片点燃一道酷热的光束，追逐附近的一位玩家，并在移动的轨迹上留下|cffffffff熔火疮疤|r。被光束扫中的玩家每0.3秒受到107,019点暗影烈焰伤害。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在英雄和史诗难度下，痛苦射线会持续追逐玩家，直到被恐惧裂隙所吞噬。|r",
},
["23x16946"] = {
["Title"] = "来人，上！",
["Description"] = "哈兰·斯威提命令一名铁潮掷弹兵向随机敌人发起冲锋。",
},
["15x26449"] = {
["Title"] = "裂隙燃烧",
["Description"] = "|cffffffff恐惧裂隙|r的灼热高温每1秒对站在其中的玩家造成71,337点暗影烈焰伤害。",
},
["17x9978"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;完全治愈友方蘑菇以充分利用其增益效果。但是当蘑菇的生命值回满之后会开始凋零，并以越来越快的速度死去。不断治疗它们，以保持这些增益效果。\r\n$bullet;完全治愈活性蘑菇来获得|cFF2959D3|Hspell:159463|h[活性孢子]|h|r效果，以抵御|cFF2959D3|Hspell:163242|h[感染孢子]|h|r造成的致命伤害。",
},
["16x12764"] = {
["Title"] = "综述",
["Description"] = "伊森德雷与艾莫莉斯、莱索恩以及泰拉尔共享生命值。她会与一名前同伴的梦魇一同开始战斗。\r\n\r\n当伊森德雷的生命值剩余70%时，梦魇巨龙将飞上天空，附近的传送门会出现一个新的梦魇巨龙。\r\n\r\n当伊森德雷的生命值剩余40%时，空中的梦魇巨龙将会降落，而地上的梦魇之龙将会升空。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在史诗难度下，艾莫莉斯、莱索恩以及泰拉尔会从始至终和伊森德雷一同作战。|r",
},
["15x26434"] = {
["Title"] = "扭曲大地",
["Description"] = "奈萨里奥从地面升起土墙，并在墙体出现的位置引发|cffffffff熔火震击|r。",
},
["15x26432"] = {
["Title"] = "隔绝现实",
["Description"] = "奈萨里奥撕裂附近的|cffffffff扭曲大地|r，产生通往虚空领域的传送门，对冲击点5码内的玩家造成62点暗影伤害。传送门会持续向现实释放扭曲的畸变怪。\r\n\r\n站在传送门中的玩家获得|cffffffff现实隔绝|r效果。",
},
["24x12421"] = {
["Title"] = "恢复",
["Description"] = "引导滋养之水环绕施法者的盟友，每2秒为其恢复2%生命值，持续6秒。",
},
["16x25825"] = {
["Title"] = "风暴之翼",
["Description"] = "莱萨杰丝向下挥动翅膀，对所有玩家造成37点自然伤害并释放一阵风暴之波。风暴之波每0.5秒对6码内的玩家造成15点自然伤害，并且会推开位于其中的玩家。\r\n\r\n |TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在史诗难度下，风暴之波中的玩家会对其附近造成伤害。|r",
},
["15x26430"] = {
["Title"] = "回响裂隙",
["Description"] = "奈萨里奥粉碎脚下的地面，对受此影响24码范围内的玩家造成375点熔火伤害，并对所有其他玩家造成29点熔火伤害。在施放|cffffffff回响裂隙|r时，奈萨里奥此前创造的每个裂隙都会产生回响。\r\n\r\n另外，震荡会形成|cffffffff崩塌之地|r并扩散|cffffffff渗流熔岩|r。",
},
["16x13474"] = {
["Title"] = "净化之怒",
["Description"] = "怒火升腾，用奥术飞弹毁灭留在地上的所有食物。每摧毁一份食物就会对团队造成188点奥术伤害。",
},
