["8x5957"] = {
["Title"] = "腐蚀毒液",
["Description"] = "腐蚀毒液会随时间的延长而变大，在1秒内对接触它的敌人造成3点自然伤害。接触会使腐蚀毒液变小。",
},
["15x26124"] = {
["Title"] = "龙巢看护者之怒",
["Description"] = "巢穴守护者陷入狂怒状态，对所有玩家造成8点元素伤害。龙巢看护者之怒造成的伤害提高225%，持续10秒。该效果可叠加。",
},
["15x26114"] = {
["Title"] = "炽焰怒吼",
["Description"] = "焰誓传令官发出炽焰怒吼，对所有玩家造成249点火焰伤害，并使所有盟友造成的伤害提高150%，持续30秒。",
},
["14x15912"] = {
