["8x9829"] = {
["Title"] = "综述",
["Description"] = "元素师戈洛克会投掷熔岩石块来轰击敌人。他会周期性地召唤不稳定的熔渣元素，这些元素会缓慢朝熔炉移动。一旦不稳定的熔渣元素接近到熔炉，就会获得毁灭性的能量。",
},
["17x11169"] = {
["Title"] = "暴君之槌",
["Description"] = "对所有玩家造成8点火焰伤害，并将其击退。并额外辐射出烈焰，每2秒对所有玩家造成3点火焰伤害，持续8秒。\r\n\r\n消耗3点腐蚀能量。",
