},
["2x23159"] = {
["Title"] = "阿尔克鲁克斯",
["Description"] = "",
},
["17x21562"] = {
["Title"] = "伤害",
["Description"] = "$bullet;泥拳会对|cFF2959D3|Hspell:331212|h[鲁莽冲锋]|h|r路径上的所有玩家造成大量伤害。\r\n",
},
["16x25251"] = {
["Title"] = "坦克",
["Description"] = "$bullet;|cFF2959D3|Hspell:380487|h[岩石冲击]|h|r会造成大量伤害并产生|cFF2959D3|Hspell:381486|h[觉醒之土]|h|r。\r\n$bullet;|cFF2959D3|Hspell:376279|h[震荡猛击]|h|r会释放一道摧毁|cFF2959D3|Hspell:381486|h[觉醒之土]|h|r的地质能量。",
},
["16x25250"] = {
["Title"] = "综述",
["Description"] = "泰洛斯对进攻者发动毁灭性的强势攻击，在白热化的战斗中，泰洛斯施放的|cFF2959D3|Hspell:380487|h[岩石冲击]|h|r会在房间内产生|cFF2959D3|Hspell:381486|h[觉醒之土]|h|r。涌现而出的大地之柱会持续造成伤害，并且可被|cFF2959D3|Hspell:376279|h[震荡猛击]|h|r摧毁。\r\n\r\n达到100点能量时，泰洛斯会施放|cFF2959D3|Hspell:377166|h[共鸣湮灭]|h|r，摧毁|cFF2959D3|Hspell:381486|h[觉醒之土]|h|r，并使用|cFF2959D3|Hspell:382458|h[共鸣余震]|h|r永久掩埋房间中的一片区域。",
},
["16x19001"] = {
["Title"] = "上古火花",
["Description"] = "冲击目标，对其造成6点奥术伤害。",
},
["16x25248"] = {
["Title"] = "闪电打击",
["Description"] = "莱萨杰丝周期性召唤闪电打击，对冲击点4码范围内的玩家造成62点自然伤害并使其昏迷0.5秒。",
},
["15x17834"] = {
["Title"] = "坦克",
["Description"] = "$bullet;保护盟友不受|cFF2959D3|Hspell:261467|h[主母的召唤]|h|r召唤出的基阿拉克幼龙影响。\r\n$bullet;|cFF2959D3|Hspell:261088|h[飓风冲压]|h|r会对其中心区域的所有目标造成致命伤害。\r\n",
},
["16x25246"] = {
["Title"] = "飓风龙翼",
["Description"] = "达到100点能量时，莱萨杰丝召唤一阵强劲的狂风，对所有玩家造成44点自然伤害。此外，玩家还会被推开，每0.5秒受到5点自然伤害，持续3秒。\r\n\r\n莱萨杰丝每使用一次|cffffffff飓风龙翼|r，飓风的持续时间都会延长0.5秒。",
},
["24x5917"] = {
["Title"] = "鼓舞呐喊",
["Description"] = "在死亡时，杰翰发出最后的集结呐喊，使他的随从中所有剩余的成员获得鲁莽鼓舞的效果。",
},
["16x25245"] = {
["Title"] = "闪电吐息",
["Description"] = "莱萨杰丝在自身面前呼出一道闪电，每0.3秒对站在区域中的玩家造成82点自然伤害。",
},
["16x19607"] = {
["Title"] = "火焰护盾",
["Description"] = "施法者获得一个护盾，吸收接下来受到的125点伤害。在护盾持续期间，施法者无法被打断施法。",
},
["16x25244"] = {
["Title"] = "第一阶段：变迁之风",
["Description"] = "",
},
["1x5977"] = {
["Title"] = "毒液箭雨",
["Description"] = "夸格米拉对附近的所有玩家喷洒毒液，造成25点自然伤害，并在接下来的6秒内每2秒造成一次额外的自然伤害。",
},
["16x25243"] = {
["Title"] = "坦克",
["Description"] = "$bullet;如果移除|cFF2959D3|Hspell:388631|h[易爆]|h|r或打断|cFF2959D3|Hspell:388635|h[爆裂]|h|r，则会消灭不稳定的火花。\r\n$bullet; |cFF2959D3|Hspell:390817|h[雷鸣能量]|h|r所造成的伤害等同于|cFF2959D3|Hspell:386410|h[雷霆冲击]|h|r对其受害者造成的伤害总和。\r\n$bullet; |cFF2959D3|Hspell:377662|h[静电力场]|h|r会降低站立在此区域内的玩家的移动速度和强制移动效果。\r\n$bullet;移除|cFF2959D3|Hspell:382530|h[涌动]|h|r效果后，涌电毁灭者会移动并攻击玩家。",
},
["16x25242"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;如果移除|cFF2959D3|Hspell:388631|h[易爆]|h|r或打断|cFF2959D3|Hspell:388635|h[爆裂]|h|r，则会消灭不稳定的火花。\r\n$bullet;|cFF2959D3|Hspell:390817|h[雷鸣能量]|h|r所造成的伤害等同于|cFF2959D3|Hspell:386410|h[雷霆冲击]|h|r对其受害者造成的伤害总和。\r\n$bullet;|cFF2959D3|Hspell:377662|h[静电力场]|h|r会降低站立在此区域内的玩家的移动速度和强制移动效果。\r\n$bullet;|cFF2959D3|Hspell:377467|h[积雷充能]|h|r会对一定区域内的玩家造成伤害，并在释放后在携带者身上留下|cFF2959D3|Hspell:390911|h[残留能量]|h|r。",
},
["2x5977"] = {
["Title"] = "毒液箭雨",
["Description"] = "夸格米拉对附近的所有玩家喷洒毒液，造成25点自然伤害，并在接下来的6秒内每2秒造成一次额外的自然伤害。",
},
["16x25241"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;如果移除|cFF2959D3|Hspell:388631|h[易爆]|h|r或打断|cFF2959D3|Hspell:388635|h[爆裂]|h|r，则会消灭不稳定的火花。\r\n$bullet;|cFF2959D3|Hspell:377467|h[积雷充能]|h|r会对携带者一定区域内的玩家造成伤害，并在释放后跳跃至距离最近的玩家身上。\r\n$bullet;|cFF2959D3|Hspell:377662|h[静电力场]|h|r会降低站立在此区域内的玩家的移动速度及强制位移效果。\r\n$bullet;搜寻中的雷灵会在成功抵达使用|cFF2959D3|Hspell:389870 |h[风暴破击]|h|r创造它们的巨型风魔身边时，会施放|cFF2959D3|Hspell:389878|h[融合]|h|r。",
},
["16x25240"] = {
["Title"] = "综述",
["Description"] = "莱萨杰丝和她的拜荒者部队试图打破囚禁其同胞的牢笼。在战斗开始时，莱萨杰丝会使用|cFF2959D3|Hspell:377612|h[飓风龙翼]|h|r从中心平台横扫攻击者。\r\n\r\n在生命值降至65%时，莱萨杰丝会开始使用|cFF2959D3|Hspell:388115|h[闪电毁灭]|h|r对菲莱克和威拉诺兹的牢笼发起空袭，同时召集地面部队进行正面攻击。涌电毁灭者|cFF2959D3|Hspell:382530|h[涌动]|h|r雷电之力，抽取牢窟自身的能量。\r\n\r\n当牢窟的完整度降至50%时，莱萨杰丝会降落到伊律迪孔的牢笼上，开始使用|cFF2959D3|Hspell:387333|h[风暴喷涌]|h|r抽取牢窟的能量。\r\n\r\n当牢窟的完整度降至0%时，莱萨杰丝腾空而起，召唤巨型风魔抽取牢窟的剩余能量。\r\n\r\n当牢窟衰败时，莱萨杰丝会返回中心平台并成为|cFF2959D3|Hspell:377322|h[肆虐风暴]|h|r的中心。噬雷之龙化身成为新时代的阴云，全力对抗攻击者。",
},
["15x21956"] = {
["Title"] = "征服",
["Description"] = "每1秒造成10点物理伤害，持续20秒。该效果可叠加。",
},
["16x25230"] = {
["Title"] = "冻结",
["Description"] = "寒冷令玩家瘫痪，每1秒造成19点冰霜伤害，持续10秒。此效果无法被降低或避免。",
},
["15x20356"] = {
["Title"] = "充能长矛",
["Description"] = "施法者投掷一根充能长矛，对一条直线上的所有目标造成19点奥术伤害，并在落地点产生爆炸。\r\n爆炸会对100码范围内的所有玩家造成75点奥术伤害，并对所有其他玩家造成37.50 点奥术伤害。",
},
["23x12289"] = {
["Title"] = "乱爪狂扫",
["Description"] = "芬雷尔发动猛攻，造成106点物理伤害，由12码内的所有敌人分摊。\r\n\r\n此攻击必然命中，并忽略所有护甲。",
},
["15x25273"] = {
["Title"] = "骨骼碎裂",
["Description"] = "裂地者的攻击会造成骨折，使玩家受到的物理伤害提高6%，持续10秒。此效果可叠加。",
},
["17x19935"] = {
["Title"] = "谐律之魂",
["Description"] = "施法者与其盟友的生命力产生共鸣。如果盟友的生命值低于施法者，施法者将变得更加强大。",
},
["14x15610"] = {
["Title"] = "治疗链",
["Description"] = "运用治疗的能量为一个受伤的盟友恢复生命值，这股能量会继续治疗附近的其它盟友，最多影响5个目标。",
},
["16x20287"] = {
["Title"] = "艾萨拉女王",
["Description"] = "",
},
["16x24032"] = {
["Title"] = "放逐标记",
["Description"] = "安特洛斯标记最多5个目标，使其被放逐，每1秒对位于被标记玩家5码内的所有玩家造成11点暗影伤害，持续20秒。",
},
["2x23499"] = {
["Title"] = "安保措施",
["Description"] = "监禁室在坍缩时启动最终的安保措施，对所有玩家造成9点奥术伤害。",
},
["15x25294"] = {
["Title"] = "致死石爪",
["Description"] = "迪乌尔纳重创目标，造成187点物理伤害和49点自然伤害，并施加|cffffffff碎击龙爪|r和|cffffffff致死之伤|r。",
},
["15x25292"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;|cFF2959D3|Hspell:388410|h[纷乱之风]|h|r会使所有|cFF2959D3|Hspell:375424|h[狂怒风暴]|h|r移动到新的位置。\r\n$bullet; |cFF2959D3|Hspell:391686|h[传导印记]|h|r会在玩家靠近彼此时扩散并刷新。\r\n$bullet; |cFF2959D3|Hspell:376943|h[旋风]|h|r会把玩家拉向达瑟雅并造成大量伤害。",
},
["1x17102"] = {
["Title"] = "坦克",
["Description"] = "$bullet;商业大亨拉兹敦克开始天降杀机时，会召唤风险投资公司灼天者来协助他。\r\n$bullet;必须让商业大亨拉兹敦克用|cFF2959D3|Hspell:260202|h[钻地猛砸]|h|r攻击|cFF2959D3|Hspell:270277|h[大型红色火箭]|h|r的外壳，才能迫使他回到地面。",
},
["15x25290"] = {
["Title"] = "综述",
["Description"] = "达瑟雅运用新获得的力量在战场上召唤|cFF2959D3|Hspell:375424|h[狂怒风暴]|h|r，当达瑟雅刮起|cFF2959D3|Hspell:388410|h[纷乱之风]|h|r时，这些风暴会在她的命令下掠过战场。\r\n\r\n达到100点能量时，达瑟雅会施放|cFF2959D3|Hspell:387849|h[凝结风暴]|h|r以召唤动荡的注能者协助战斗。这些随从会在猛烈|cFF2959D3|Hspell:387627|h[爆发]|h|r后爆炸消散。",
},
["15x25282"] = {
["Title"] = "震荡猛击",
["Description"] = "泰洛斯放出一道地质能量，对玩家造成126点物理伤害并使其受到的伤害提高40%，持续45秒。该效果可叠加。\r\n\r\n摧毁任何接触到的|cffffffff觉醒之土|r。",
},
["24x6997"] = {
["Title"] = "伊克之狂暴",
["Description"] = "90秒后伊克会狂暴，攻击速度提高150%，造成的所有伤害提高500%。",
},
["14x24506"] = {
["Title"] = "虹吸屏障",
["Description"] = "道茜歌妮制造出护盾，吸收相当于其最大生命值3%的伤害。",
},
["15x25281"] = {
["Title"] = "共鸣湮灭",
["Description"] = "达到100点能量后，泰洛斯会发动残酷的猛击来释放自身不稳定的力量。\r\n\r\n这次猛击会对面前扇形范围内的所有玩家造成248点自然伤害，摧毁|cffffffff觉醒之土|r并留下|cffffffff共鸣余震|r。\r\n\r\n冲击的力量将会关闭洞穴，对所有玩家额外造成24点自然伤害，并使|cffffffff开裂碎石|r从天而降。",
},
["24x12007"] = {
["Title"] = "综述",
["Description"] = "瑟芬崔斯克一开始会单独面对玩家。当它的生命值处于66%和33%时，它会|cFF2959D3|Hspell:191873|h[下潜]|h|r，然后在远处重新出现，并召唤两个多头蛇子嗣。",
},
["15x19001"] = {
["Title"] = "上古火花",
["Description"] = "冲击目标，对其造成6点奥术伤害。",
},
["15x11398"] = {
["Title"] = "穿刺之伤",
["Description"] = "每1秒造成44点物理伤害，持续10秒。",
},
["15x25254"] = {
["Title"] = "热狂毁灭",
["Description"] = "房间充满|cffffffff共鸣余震|r后，泰洛斯开始散发出毁灭性的大地能量波，造成21点自然伤害，并使受到|cffffffff热狂毁灭|r的伤害提高50%。",
},
["15x30823"] = {
["Title"] = "精神洪流",
["Description"] = "瓦勒雷尔攻击一名玩家的精神，每1秒造成150点暗影伤害，持续10秒。伤害由目标8码范围内的玩家分摊。",
},
["15x25252"] = {
["Title"] = "伤害输出者",
