["Description"] = "黑伦度斯回收一个幻磷宝珠，爆发出毁灭能量，对所有玩家造成94点宇宙伤害，并在之后每1秒造成9点宇宙伤害，持续24秒。此效果可叠加。",
},
["14x19184"] = {
["Title"] = "深渊护持",
["Description"] = "海洋的守护为施法者及其盟友制造一个保护性的气泡，将所受伤害的75%转移到气泡上。",
},
["1x16912"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;分散以降低|cFF2959D3|Hspell:256106|h[艾泽里特填装弹]|h|r的伤害。\r\n$bullet;打断|cFF2959D3|Hspell:256060|h[复苏之酒]|h|r，阻止库拉格的治疗。",
},
["2x16912"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;分散以降低|cFF2959D3|Hspell:256106|h[艾泽里特填装弹]|h|r的伤害。\r\n$bullet;打断|cFF2959D3|Hspell:256060|h[复苏之酒]|h|r，阻止库拉格的治疗。",
},
["15x10014"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;|cFF2959D3|Hspell:160796|h[利刃冲刺]|h|r十分致命——和执行者苏卡战斗时尽量远离其他玩家。\r\n$bullet;拦截加安的|cFF2959D3|Hspell:164264|h[穿透射击]|h|r，保护被标记的玩家。",
},
["15x24833"] = {
["Title"] = "裂星射线",
["Description"] = "黑伦度斯激活一道|cffffffff裂星射线|r，每0.3秒对效果区域内的玩家造成15点宇宙伤害。",
},
["15x24831"] = {
["Title"] = "余震",
["Description"] = "冲击区域不久后会发生回响，对附近的玩家造成75点物理伤害。",
},
["15x24830"] = {
["Title"] = "碎地者飞弹",
["Description"] = "黑伦度斯释放出一排飞弹，对冲击点附近的玩家造成56点宇宙伤害，并生成|cffffffff余震|r。",
},
["16x11589"] = {
["Title"] = "纳鲁之光",
["Description"] = "伊瑞尔粉碎一座亵渎尖塔，并召唤出持续35秒的圣光宝珠。每颗宝珠会使15码范围内的所有玩家获得纳鲁之光效果，使其在30秒内免疫所有的暗影伤害，并且移动速度提高40%。",
},
["15x24829"] = {
["Title"] = "坍缩微尘",
["Description"] = "每个微尘都会坍缩，对3码内的玩家造成25点宇宙伤害。",
},
["15x24828"] = {
["Title"] = "幻磷爆发",
["Description"] = "接触微尘会使其爆发，对玩家造成31点宇宙伤害。",
},
["14x22095"] = {
["Title"] = "至高惩戒",
["Description"] = "向多名玩家引导黑暗能量，每0.5秒对每个玩家6码范围内的玩家造成11点暗影伤害。",
},
["15x28456"] = {
["Title"] = "织造共鸣",
["Description"] = "受到的自然伤害提高100%，持续20秒。该效果可叠加。\r\n",
},
["15x24824"] = {
["Title"] = "幻磷裂隙",
["Description"] = "每1秒对幻磷之云内的玩家造成31点宇宙伤害。",
},
["16x15301"] = {
["Title"] = "硫磺烈雨",
["Description"] = "格罗斯召唤数颗流星，每颗都会造成总计1,256点火焰伤害，由所有目标平摊。如果流星没有击中任何目标，则会生成一只硫磺地狱火。",
},
["17x18535"] = {
["Title"] = "喷涌黑暗",
["Description"] = "对45码范围内的玩家造成19点暗影伤害。",
},
["16x21428"] = {
["Title"] = "腐蚀结块",
["Description"] = "伊格诺斯下潜，器官暴露时，会形成致命的腐蚀结块。这团血浆可以吸收尼奥罗萨之血，从而迅速变得无法控制。",
},
["15x24820"] = {
["Title"] = "破碎的棱镜",
["Description"] = "棱镜的碎片依然残留着，每0.5秒造成12点宇宙伤害，并使玩家和幻磷微尘的移动速度降低。",
},
["15x11503"] = {
["Title"] = "邪能狂怒",
["Description"] = "古尔图格陷入邪能狂怒，随机锁定一名敌人。一股致病邪能会充斥全身的血管，使其获得额外的防御力。在除随机难度外所有难度的团队副本中，近战攻击命中古尔图格后会使其攻击速度提高2%。",
},
["14x15738"] = {
["Title"] = "吸取灵魂",
["Description"] = "对所有施法者正面的目标造成77点暗影伤害，并恢复相当于该数值一定比例的生命值。",
},
["16x9385"] = {
["Title"] = "狂暴冲锋",
["Description"] = "卡加斯径直向你冲锋，对其前方的所有目标造成125%的武器伤害，同时每2秒提高15%的物理伤害，持续20秒。卡加斯的移动速度也将每2秒提高40%，持续20秒。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在史诗难度中，卡加斯狂暴冲锋的时间越长，团队从热血咆哮中获得的支持越高。但如果卡加斯注视的目标死亡，观众会变得非常不满意。|r",
},
["15x24817"] = {
["Title"] = "余震",
["Description"] = "冲击区域不久后会发生回响，对附近的玩家造成75点物理伤害。",
},
["16x9296"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;被|cFF2959D3|Hspell:155365|h[长矛钉刺]|h|r击中的玩家需要大量治疗。\r\n$bullet;恐翼激活时，尽快驱散|cFF2959D3|Hspell:155399|h[爆燃]|h|r效果。\r\n$bullet;当|cFF2959D3|Hspell:154989|h[炼狱吐息]|h|r和|cFF2959D3|Hspell:155499|h[高热弹片]|h|r层数叠高时驱散。",
},
["15x24815"] = {
["Title"] = "碎裂残片",
["Description"] = "防御核心碎裂，抛射出残片，对冲击位置4码范围内的玩家造成45点物理伤害。",
},
["15x13233"] = {
["Title"] = "异域奇点",
["Description"] = "施法者在敌人脚下的时间结构中撕出孔洞。每个洞口都会产生爆炸，对区域内的受害者造成35点奥术伤害。\r\n爆炸之后会出现一个奇点。任何进入奇点领域的人将每秒受到98点奥术伤害。\r\n站在奇点中会使其缩小并最终消失。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02异域奇点会同时出现在连续的时空层级之中。|r\r\n",
},
["16x10146"] = {
["Title"] = "坦克",
["Description"] = "$bullet;每当其他坦克受到|cFF2959D3|Hspell:144358|h[受损自尊]|h|r影响时立即嘲讽傲之煞。\r\n$bullet;当有盟友被|cFF2959D3|Hspell:144574|h[腐化囚笼]|h|r困住时，站在牢笼旁边的开关上释放他们。\r\n$bullet;当傲之煞施放|cFF2959D3|Hspell:144400|h[傲气冲天]|h|r时，如果你的傲气值处于50到74之间，站在你的|cFF2959D3|Hspell:145320|h[投影]|h|r身边以避免团灭爆炸。",
},
["16x17001"] = {
["Title"] = "饥饿灵魂",
["Description"] = "阿古斯的怒火释放出饥饿灵魂，他们在灵魂世界游荡，如果接触到任何鬼魂就会发生爆炸，对附近的所有鬼魂施加灵魂引爆效果。",
},
["15x24811"] = {
["Title"] = "坍缩微尘",
["Description"] = "每个微尘都会坍缩，对3码内的玩家造成25点宇宙伤害。",
},
["15x24810"] = {
["Title"] = "幻磷爆发",
["Description"] = "接触微尘会使其爆发，对玩家造成31点宇宙伤害。",
},
["8x26690"] = {
["Title"] = "战争咆哮",
["Description"] = "发出令人丧胆的尖啸，对所有敌人造成12点自然伤害。",
},
["15x30853"] = {
["Title"] = "心灵震爆",
["Description"] = "对一名敌人造成37点暗影伤害。",
},
["14x13196"] = {
["Title"] = "梦魇爆破",
["Description"] = "梦魇脓液被消灭时会造成梦魇能量爆破，对附近的所有玩家造成28点暗影伤害。\r\n\r\n爆破同时会对伊格诺斯之眼造成伤害，无视所有伤害减免效果，对其造成相当于生命值0%的暗影伤害。",
},
["15x11716"] = {
["Title"] = "枷锁酷刑",
["Description"] = "阿克蒙德随机折磨3名玩家的灵魂，每秒造成12点暗影伤害，直到他们距离自己的灵魂超过30码外。该效果每跳一次，伤害就会提高10%。\r\n\r\n枷锁酷刑被移除时会对所有玩家造成40点暗影伤害。",
},
["14x19742"] = {
["Title"] = "吉布尔",
["Description"] = "",
},
["17x8487"] = {
["Title"] = "烈焰风暴",
["Description"] = "艾萨斯召唤出一道持续20秒的烈焰风暴，每2秒对目标区域内的所有敌人造成1,391点火焰伤害。",
},
["16x8585"] = {
["Title"] = "吸血狂乱",
["Description"] = "一只随机洞穴蝙蝠会陷入吸血狂乱，对所有敌人造成13点物理伤害。该伤害的一部分会被转化为施法者的生命值。",
},
["15x24802"] = {
["Title"] = "烧毁",
["Description"] = "生命值耗尽后不稳定的物质进入烧毁状态，免疫所有伤害。在5秒后不稳定的物质恢复自身50%的生命值。",
},
["17x23950"] = {
["Title"] = "尘土抽击",
["Description"] = "司垢莱克斯痛击沙地，对所有玩家造成25点物理伤害并施加|cffffffff幻磷之尘|r。",
},
["14x24900"] = {
["Title"] = "寒冷光环",
["Description"] = "霜息蜘蛛散发出冰冷的寒气，使其造成的冰霜伤害提高20%，并对所有玩家造成29点冰霜伤害。该效果可叠加。",
},
["14x10744"] = {
["Title"] = "穿刺投掷",
["Description"] = "造成44点物理伤害，无视目标护甲并将其击退，还会形成穿刺效果，每3秒造成7点物理伤害，持续30秒。黑手在钢铁熔炉时会得到强化，其穿刺投掷会对一整条线上的所有目标造成伤害。",
},
["23x29982"] = {
["Title"] = "暮光之风",
["Description"] = "每5.2秒造成25点暗影烈焰伤害，使移动速度降低10%。",
},
["16x26005"] = {
["Title"] = "焰鳞队长",
["Description"] = "",
},
["15x22095"] = {
["Title"] = "至高惩戒",
["Description"] = "向多名玩家引导黑暗能量，每0.5秒对每个玩家6码范围内的玩家造成11点暗影伤害。",
},
["17x22055"] = {
["Title"] = "饥肠辘辘",
["Description"] = "对午夜猎手的目标4码范围内的玩家造成187点物理伤害，并为德纳修斯恢复相当于该伤害150%的生命值。\r\n\r\n午夜猎手对路径上每名玩家造成的伤害递减。",
},
["14x10831"] = {
["Title"] = "燃烧",
["Description"] = "每秒造成13点火焰伤害，持续15秒。该效果可叠加。",
},
["14x8044"] = {
["Title"] = "吞噬",
["Description"] = "当操纵者卡兹提克催眠一名玩家后，他会选择一头饥饿的恐虫来进食。在恐虫进食期间，受害者每秒受到24点物理伤害，恐虫每秒获得5点能量。如果恐虫在进食中受到的伤害达到其总生命值的30%，它将停止进食，受害者也将摆脱催眠术的影响。",
},
["16x13637"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;驱散受到|cFF2959D3|Hspell:217877|h[燃烧的炸弹]|h|r影响的玩家，避免他们炸到其他人。\r\n$bullet;避开|cFF2959D3|Hspell:218012|h[奥术脉冲]|h|r以免昏迷。",
},
["23x14760"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;成为|cFF2959D3|Hspell:233196|h[恶魔突起]|h|r的目标时远离盟友。\r\n$bullet;在|cFF2959D3|Hspell:233206|h[暗影消退]|h|r阶段击败孟菲斯托斯之影。",
},
["1x6050"] = {
["Title"] = "制造烈焰之球",
["Description"] = "塔达拉姆王子制造出一颗漂浮在空中的烈焰之球并向目标移动，对沿途0码范围内的玩家造成火焰伤害。",
},
["15x22576"] = {
["Title"] = "显露内心",
["Description"] = "施法者揭露目标心中最深处的欲望，造成112点物理伤害，并对受害者施加|cffffffff扭曲欲望|r。\r\n\r\n显露欲望对受害者造成的后续伤害将会通过|cffffffff共享认知|r复制给随机盟友。\r\n\r\n当|cffffffff扭曲欲望|r结束时，目标会爆炸，并触发|cffffffff变心|r。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02伊涅瓦·暗脉女勋爵会在欲望容器填满66%时使用这项技能。|r",
},
["14x24890"] = {
["Title"] = "包围之网",
["Description"] = "瑟娜尔丝用蛛网包裹数名玩家，每1秒造成10点物理伤害，并使其在自身所在位置释放|cffffffff粘性蛛网|r，持续6秒。",
},
["2x6050"] = {
["Title"] = "制造烈焰之球",
["Description"] = "塔达拉姆王子制造出一颗漂浮在空中的烈焰之球并向目标移动，对沿途0码范围内的玩家造成火焰伤害。",
},
["17x33390"] = {
["Title"] = "碎片地带",
["Description"] = "虚空领主的强力法术留下宇宙的碎片，每1秒对其中的玩家造成15点宇宙伤害，并使其移动速度降低50%。",
},
["14x23816"] = {
["Title"] = "女妖之刃",
["Description"] = "向一名玩家接连斩击四次，每一击造成15点物理伤害和41点暗影伤害，并施加|cffffffff女妖的灾厄|r。",
},
["14x24884"] = {
["Title"] = "冰冷冲击",
["Description"] = "瑟娜尔丝用不稳定冰霜使玩家感到寒意，每1秒造成12点冰霜伤害，持续5秒，并在持续时间结束或被移除时触发|cffffffff冰霜驱逐|r。",
},
["17x24967"] = {
["Title"] = "乳石之牙",
["Description"] = "",
},
["14x24882"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;|cFF2959D3|Hspell:372030|h[粘性蛛网]|h|r可以防止玩家在|cFF2959D3|Hspell:372055|h[冰封地面]|h|r上滑动并免受推拉。\r\n$bullet;|cFF2959D3|Hspell:371976|h[冰冷冲击]|h|r和|cFF2959D3|Hspell:371979|h[冰霜驱逐]|h|r会对玩家造成大量伤害。",
},
["1x28707"] = {
["Title"] = "惊魂恫吓",
["Description"] = "演说者基克斯威兹克向一名玩家发出惊悚的尖啸，对其面前锥形范围内的玩家造成44点暗影伤害，并使他们在恐惧中畏缩，持续4秒。",
},
["14x24879"] = {
["Title"] = "综述",
["Description"] = "瑟娜尔丝以严寒攻击玩家，并使地面结上一层光滑坚冰。在巢穴下方区域进行短暂战斗之后，瑟娜尔丝开始向其冰冷巢穴的顶端攀登。\r\n\r\n瑟娜尔丝在楼梯的每个平台都会召唤一只霜息蜘蛛来帮助她。\r\n\r\n到达巢穴顶端时，瑟娜尔丝会将地面永久冻结，然后从蛛网下落，吞噬猎物。",
},
["16x15801"] = {
["Title"] = "平台：拉恩科纳",
["Description"] = "许多行动敏捷的恶魔都是来自被邪能浸透的拉恩科纳。",
},
["2x7290"] = {
["Title"] = "哀伤之柱",
["Description"] = "悲伤圣女冲击一名敌人，造成暗影伤害并且每2秒造成额外的暗影伤害，持续10秒。",
},
["7x7644"] = {
["Title"] = "炽热日光",
["Description"] = "夙娥在夜间短暂现身，随机向一名玩家射出一束日光，对目标周围8码范围内的所有玩家造成15点火焰伤害。\r\n\r\n随后，她会消失在黑暗中，被炽热日光接触到的霜寒彗星都会立即融化。",
},
["14x30372"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;废铁大师和垃圾场土狼可以被|cFF2959D3|Hspell:461536|h[滚动的垃圾]|h|r吸收，并将它们放置在垃圾球被摧毁的地方。\r\n$bullet;|cFF2959D3|Hspell:464149|h[焚烧]|h|r会将附近的垃圾堆变成|cFF2959D3|Hspell:464248|h[滚烫垃圾]|h|r。\r\n$bullet;|cFF2959D3|Hspell:464865|h[丢弃的毁灭炸弹]|h|r如果没有被|cFF2959D3|Hspell:461536|h[滚动的垃圾]|h|r吸收，则会对整个团队造成毁灭性的伤害。",
},
["8x12102"] = {
["Title"] = "火山",
["Description"] = "施法者随机向一个敌人射出一个熔岩石块。当其落地时，会形成一个火山，对其范围内的所有敌人造成31点火焰伤害。\r\n\r\n火山存在时，会在房间中的随机位置生成余烬。",
},
["1x12102"] = {
["Title"] = "火山",
