["Description"] = "",
},
["16x21205"] = {
["Title"] = "漆黑伤疤",
["Description"] = "以虚空魔法焚烧目标，造成45点暗影伤害，并使目标受到|cffffffff漆黑伤疤|r的伤害提高100%。\r\n\r\n该效果可叠加。",
},
["2x12380"] = {
