["15x23815"] = {
["Title"] = "女妖的觅心箭",
["Description"] = "向一个玩家发射三波箭矢，每一波造成99点物理伤害和31点暗影伤害，并施加|cffffffff女妖的灾厄|r。",
},
["15x23813"] = {
