["15x23808"] = {
["Title"] = "暗影匕首",
["Description"] = "希尔瓦娜斯投掷腐化的利刃，对所有被击中的目标每1秒造成15点暗影伤害，持续9秒。",
},
["16x20664"] = {
["Title"] = "吞噬阴影",
["Description"] = "玛乌特每1秒对所有玩家造成一次暗影伤害，持续3秒。暗影伤害的数值会随着其法力值的提高而增加。",
