["17x11179"] = {
["Title"] = "咆哮烈焰",
["Description"] = "执行者之击对命中的玩家造成6点火焰伤害。所有被命中的玩家会在其位置处生成灼烧烈焰。",
},
["17x23506"] = {
["Title"] = "祈求宿命",
["Description"] = "命运撰写师罗-卡洛为当前目标祈祷，让其走向无法逃避的终局。\r\n\r\n8秒后目标爆发，形成一个命运之影，并对所有玩家造成最多137点暗影伤害。玩家离爆发点越远，受到的伤害越低。",
},
["7x6328"] = {
["Title"] = "回旋之刃",
["Description"] = "风领主梅尔加拉克将利刃随机射向一名玩家所在位置，对利刃行进路线上的所有玩家造成22点物理伤害。利刃到达目的地后，会返回风领主梅尔加拉克手中。利刃还会对其返回路线上的所有玩家造成22点物理伤害。",
},
["33x17529"] = {
["Title"] = "神圣惩击",
