["14x30181"] = {
["Title"] = "奖励：震击与烈焰",
["Description"] = "投入一个震击礼券和一个烈焰礼券会产生一个超热线圈。这种电磁线圈产生或激活时会释放出|cffffffff流荡之焰|r。",
},
["17x9962"] = {
