["16x25885"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;|cFF2959D3|Hspell:388767|h[束缚之冰]|h|r会将目标定身在原地，直到被打破为止。\r\n$bullet;|cFF2959D3|Hspell:389287|h[冰川风暴]|h|r会在地面上留下一片冻结之地，降低玩家的移动速度。\r\n$bullet;|cFF2959D3|Hspell:389762|h[深度冻结]|h|r会对利斯卡诺兹路径上的所有人造成大量伤害并使其冻结。",
},
["16x9311"] = {
["Title"] = "双头飞龙之魂",
["Description"] = "为长矛钉刺和召唤兽群灌以元素火焰之力。\r\n\r\n非骑乘状态时可以使用高热弹片。",
},
["17x19638"] = {
["Title"] = "极寒之地",
["Description"] = "吉安娜的冰霜法术冻结地面，使站立变得更加困难。站在|cffffffff极寒之地|r上会以更快的速度获得|cffffffff寒冰之触|r。",
