["Description"] = "高阶裁决官阿丽兹召唤一个阴森的教民，随机追逐一名玩家。",
},
["2x12901"] = {
["Title"] = "心灵震爆",
["Description"] = "对目标10码范围内的所有敌人造成暗影伤害。",
},
["1x12901"] = {
["Title"] = "心灵震爆",
["Description"] = "对目标10码范围内的所有敌人造成暗影伤害。",
},
["17x21068"] = {
["Title"] = "腐蚀",
["Description"] = "每2秒造成7点自然伤害，受到的所有伤害提高25%，持续8秒。",
},
["16x13590"] = {
["Title"] = "火焰轰炸",
["Description"] = "胡墨格里斯猛地揪住帕达沃森，强迫他发射爆炸火矢，对区域内的所有敌人造成55点火焰伤害。",
},
["23x21857"] = {
["Title"] = "哈卡之子",
["Description"] = "阿塔莱祭司向他们的神灵献祭自己，变为哈卡之子并冲过去帮助他们的主人。",
},
["23x21856"] = {
["Title"] = "尖锐脊刺",
["Description"] = "使用带刺的双臂刺穿一名目标，第一击造成44点物理伤害，第二击造成37点暗影伤害。",
