["17x20381"] = {
["Title"] = "无尽末日",
["Description"] = "触发目标位置的虚空能量连锁反应。在命中位置5码范围造成37点暗影伤害，并且会额外触发|cffffffff无尽毁灭|r。",
},
["23x21854"] = {
["Title"] = "鲜血弹幕",
["Description"] = "向目标位置喷吐刺鼻的血液，对3码范围内的敌人造成16点暗影伤害，并使其造成的伤害降低10%，持续9秒。该效果可叠加。",
},
["23x25016"] = {
["Title"] = "火焰浪潮",
["Description"] = "引导净化烈焰时，艾博隆每3秒释放一道火焰浪潮，对所有玩家造成5点火焰伤害。",
},
["15x14971"] = {
["Title"] = "绝望的聚合体",
["Description"] = "",
},
["16x20357"] = {
["Title"] = "晶化护盾",
["Description"] = "施法者用晶化护盾笼罩自己，使其免疫所有伤害和打断效果，直到护盾被充能长矛打破。",
},
["2x5524"] = {
["Title"] = "第一阶段：第一节课",
["Description"] = "",
},
["23x21847"] = {
["Title"] = "念力投掷",
["Description"] = "宫务大臣向附近的一名玩家投掷一个罪碑雕像，对沿途的敌人造成44点物理伤害并将其击退。投掷罪碑雕像时的强大力量使其在落地时对所有玩家造成10点声波伤害。",
},
["23x21842"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;在|cFF2959D3|Hspell:323393|h[哀伤仪式]|h|r期间站在宫务大臣和罪碑雕像中间可以拦截心能飞弹，降低团队受到的伤害。\r\n$bullet;|cFF2959D3|Hspell:1236964|h[痛苦爆发]|h|r会对宫务大臣或罪碑雕像附近的玩家造成高额伤害。",
},
["15x10045"] = {
["Title"] = "高莱克，执行者苏卡的水手",
["Description"] = "击败高莱克之后，无畏舰炮的弹药会出现。",
},
["23x21841"] = {
["Title"] = "综述",
["Description"] = "宫务大臣操纵强大的念力，向场地投掷罪碑雕像。生命值降低至70%和40%时，宫务大臣会施放|cFF2959D3|Hspell:341245|h[宫务大臣的和声]|h|r。",
},
["23x21838"] = {
["Title"] = "爆冲",
["Description"] = "强风将所有玩家和心能推向平台后部。在强风存在期间，所有玩家每6秒获得一层疑云密布效果。\r\n",
},
["1x31414"] = {
["Title"] = "坦克",
["Description"] = "$bullet;打击者通过|cFF2959D3|Hspell:271903|h[硬币磁铁]|h|r吸收硬币，每消耗一堆都会使其获得强化。",
},
["8x10691"] = {
["Title"] = "暴食狼蛛",
["Description"] = "暴食狼蛛会随机锁定一名玩家。",
},
["24x7042"] = {
["Title"] = "高热",
["Description"] = "沃尔坎会点燃熔岩魔像，为其恢复30%的最大生命值。",
},
["23x21830"] = {
["Title"] = "疑云密布",
["Description"] = "你心中的猜疑逐渐滋生，每1秒造成1点奥术伤害，持续10秒。",
},
["23x21826"] = {
["Title"] = "第一阶段：迎头而上",
["Description"] = "玩家在地面与忠诚圣杰德沃丝战斗。",
},
["23x21825"] = {
["Title"] = "酸蚀排放",
["Description"] = "特雷德奥瓦向周围所有玩家的位置吐出酸液，对冲击点4码范围内的所有玩家造成40点自然伤害。\r\n\r\n由于特雷德奥瓦获得了智慧，她会尝试预测敌人的行动，并将酸液吐到预判的位置。 \r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在史诗难度下，飞弹的冲击点会留下腐烂之池。|r",
},
["16x20480"] = {
["Title"] = "狂热的巨兽",
["Description"] = "艾萨拉大军中的巨兽冲向了上古结界，将它们砸成碎片。这些巨兽在受到群体控制效果后会进入激怒状态。",
},
["14x22439"] = {
["Title"] = "综述",
["Description"] = "依照盘旋在附近的莱索尼娅的指令，当周围的所有心能之桶都被摧毁后，瓦里诺便会被激活。他强大的心能充能会在一片区域内造成伤害，应注意躲避。如果他的敌人没有分散站位，充能心能爆发会对其造成致命伤害。瓦里诺还会周期性地施放释放的心能，用心能充能轰击多片区域。",
},
["17x30110"] = {
["Title"] = "奖励路线",
["Description"] = "独臂盗匪向玩家滚出一枚巨大的娱乐城凭证，将路径上的任何目标|cffffffff碾碎！|r。玩家可以站在路径附近成为|cffffffff豪客！|r。\r\n\r\n抵达目的地时凭证翻倒，对15码内的玩家造成100点自然伤害，并对所有玩家额外造成36点自然伤害。\r\n\r\n玩家可以滚回凭证以将其摧毁。",
},
["8x12901"] = {
["Title"] = "心灵震爆",
["Description"] = "对目标10码范围内的所有敌人造成暗影伤害。",
},
["23x21821"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;站在长女格里斯蒂亚的|cFF2959D3|Hspell:335805|h[执政官的壁垒]|h|r内可以大幅降低德沃丝|cFF2959D3|Hspell:334625|h[深渊爆炸]|h|r的伤害。\r\n$bullet;|cFF2959D3|Hspell:322921|h[执政官之矛]|h|r会维持锁定，直到玩家交还所有|cFF2959D3|Hspell:330683|h[原始心能]|h|r宝珠。\r\n$bullet;你必须使用|cFF2959D3|Hspell:322921|h[执政官之矛]|h|r击中德沃丝，才能在她升空时将其击落。",
},
["23x21819"] = {
["Title"] = "坦克",
["Description"] = "$bullet;站在长女格里斯蒂亚的|cFF2959D3|Hspell:335805|h[执政官的壁垒]|h|r内可以大幅降低德沃丝|cFF2959D3|Hspell:334625|h[深渊爆炸]|h|r的伤害。\r\n$bullet;|cFF2959D3|Hspell:322921|h[执政官之矛]|h|r会维持锁定，直到玩家交还所有|cFF2959D3|Hspell:330683|h[原始心能]|h|r宝珠。\r\n$bullet;你必须使用|cFF2959D3|Hspell:322921|h[执政官之矛]|h|r击中德沃丝，才能在她升空时将其击落。",
},
["14x8327"] = {
["Title"] = "恐惧的化身",
["Description"] = "首见于永春台，击败所有恐惧的化身后，加尔鲁什身上的亚煞极之佑将会消散。",
},
["16x14252"] = {
["Title"] = "再生",
["Description"] = "生命值降至25%时，施法者将免疫所有伤害并开始施放再生，为自身恢复100%的最大生命值。\r\n\r\n击败赫娅和海姆达尔可打断施法。",
},
["16x20173"] = {
["Title"] = "黑暗通道",
["Description"] = "恐惧召唤者打开一道黑暗通道，每10秒从中涌出一批生物对玩家进行攻击，直到通道关闭为止。\r\n\r\n如果引导完成，则触发|cffffffff虚空爆发|r。\r\n",
},
["8x13990"] = {
