["14x20307"] = {
["Title"] = "败血之地",
["Description"] = "腐烂的地面使站在上面的所有玩家中毒，造成2,674点自然伤害并施加|cffffffff剧毒烙印|r效果。",
},
["14x20338"] = {
["Title"] = "奥术宝珠",
["Description"] = "生成一个充斥着不稳定奥术能量的宝珠，若无玩家对其进行吸收，则会爆炸。  玩家站在宝珠内即可吸收其内部的不稳定奥术能量，但在过程中会不断受到奥术伤害。\r\n持续站在宝珠内一定时间即可将能量完全吸收。",
},
["2x24743"] = {
["Title"] = "坦克",
["Description"] = "$bullet;|cFF2959D3|Hspell:369061|h[灼热轰击]|h|r会击中艾博隆面前的所有玩家。\r\n$bullet;|cFF2959D3|Hspell:368990|h[净化烈焰]|h|r会持续存在，直到所有宝库守卫全部失能。\r\n$bullet;|cFF2959D3|Hspell:368990|h[净化烈焰]|h|r生效期间，艾博隆会受到|cFF2959D3|Hspell:369031|h[神圣屏障]|h|r的保护。",
},
["15x11461"] = {
["Title"] = "暗影箭雨",
["Description"] = "向所有玩家射出暗影能量箭雨，造成14点暗影伤害。",
