["15x20609"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;|cFF2959D3|Hspell:307358|h[衰弱唾液]|h|r首先会对单一目标造成高额伤害，随后以扩散的形式对多个目标造成额外伤害。\r\n$bullet;躲避无厌者夏德哈的吐息攻击。\r\n$bullet;坦克在夏德哈施放|cFF2959D3|Hspell:306942|h[狂乱]|h|r后会承受高额伤害。",
},
["14x18536"] = {
["Title"] = "鲜血召唤",
["Description"] = "祖尔用受到戈霍恩赐福的鲜血制造出盟友，召唤鲜血大军。",
},
["1x2365"] = {
["Title"] = "祈求跪拜",
["Description"] = "暮光狂热者跪在柯尔拉面前准备进化。在跪姿下，他们不会做任何事，受到的所有伤害降低99%。",
},
["33x17219"] = {
["Title"] = "系统关闭",
["Description"] = "系统过载，受到的伤害提高50%。",
},
["15x20607"] = {
["Title"] = "综述",
["Description"] = "无厌者夏德哈的吐息会根据当前的遮罩改变它的伤害类型和次要效果。\r\n\r\n无厌者夏德哈进食时，它的躯体也会随着所吞噬的材料而改变。",
},
["15x20603"] = {
["Title"] = "吞噬魔法",
["Description"] = "玛乌特每6秒吞噬10%的法力值，造成的魔法伤害永久提高1%。\r\n\r\n该效果可叠加。",
},
["15x20601"] = {
["Title"] = "黑曜粉碎",
["Description"] = "玛乌特开始集聚力量，持续1分钟。引导结束后，玛乌特法力护盾破碎，对所有玩家造成374点暗影伤害。",
},
["14x16020"] = {
["Title"] = "冷凝之血",
["Description"] = "蒂玛对随机敌方玩家施放治疗量吸收效果。持续时间结束时目标会被冰冻，冰冻时间由剩余的治疗吸收效果决定。",
},
["14x20699"] = {
["Title"] = "适化抗原",
["Description"] = "梦魇抗原周期性获得适化抗原，造成的伤害提高10%，移动速度不会被降低到普通移速的10%以下。\r\n该效果可叠加。",
},
["23x12942"] = {
["Title"] = "剑刃奔涌",
["Description"] = "冲向一名玩家，对5码范围内的所有目标造成25点物理伤害。被击中的玩家将会流血，每2秒受到7点物理伤害，持续12秒。\r\n\r\n剑刃奔涌会留下一个顾问麦兰杜斯的影像。",
},
["16x21983"] = {
["Title"] = "罪孽与折磨",
["Description"] = "在随机位置抽取出随机敌人的昔日罪孽。\r\n\r\n昔日罪孽会持续对最近的玩家造成7点暗影伤害，直至所有的昔日罪孽通过共受苦难的光束相连接。\r\n\r\n罪孽显现后，彼此之间会形成一张心能之网。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02伊涅瓦·暗脉女勋爵会在罪孽容器填满33%时使用这项技能。|r\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02如果玩家未能在昔日罪孽消散前将其连接，则会触发|cFF2959D3|Hspell:331527|h[偿罪]|h|r。|r",
},
["14x20695"] = {
["Title"] = "暮光之息",
["Description"] = "每0.4秒对维克修娜前方锥形范围内的敌人造成15点暗影伤害，并施加虚空腐蚀，持续1.6秒。",
},
["17x19860"] = {
["Title"] = "死亡裂隙",
["Description"] = "创造连接生者领域和死亡领域的传送门。在死亡领域中进入裂隙可以清除全部|cffffffff寂灭凋零|r层数，并在生者领域中触发|cffffffff凋零爆裂|r。\r\n\r\n任何在死亡领域中与|cffffffff死亡裂隙|r碰撞的|cffffffff恐惧收割|r都会进入生者领域。\r\n",
},
["14x20688"] = {
["Title"] = "生物化合",
["Description"] = "每个聚合增生都能为恩佐斯恢复生命值，每2秒恢复6点生命值，吸收所有伤害，并且免疫治疗减免效果。此效果可叠加。",
},
["14x20687"] = {
["Title"] = "毁灭",
["Description"] = "毁灭施法者面前的玩家和教徒，每0.25秒造成6点暗影伤害，持续5秒。\r\n\r\n每次命中都会使其受到毁灭的伤害提高25%，持续6秒，最多叠加20次。",
},
["15x19862"] = {
["Title"] = "凋零爆裂",
["Description"] = "死亡能量从一个|cffffffff死亡裂隙|r里爆发出来，对所有敌人造成10点暗影伤害。",
},
["14x20686"] = {
["Title"] = "暗影残渣",
["Description"] = "一个黑暗能量池，每1秒对区域内玩家造成20点暗影伤害。",
},
["14x20685"] = {
["Title"] = "渗透暗影",
["Description"] = "维克修娜用黑暗能量包裹随机玩家，立即对目标和9码内玩家造成4,177点暗影伤害，并在8秒后再次造成此伤害。\r\n\r\n效果结束时，留下一滩暗影残渣。",
},
["15x21017"] = {
["Title"] = "轮回噩梦",
["Description"] = "尼奥罗萨之血的近战攻击会在目标身上留下持久腐蚀，每2秒造成1,306点暗影伤害，持续40秒。\r\n\r\n该效果可叠加。",
},
["14x20678"] = {
["Title"] = "漆黑之门",
["Description"] = "维克修娜的黑暗力量撕开一道传送门，对所有玩家造成44点暗影伤害，并使教徒进入场地。",
},
["14x20755"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;战略性激活|cFF2959D3|Hspell:310565|h[艾泽拉斯的光辉]|h|r能够使得你和盟友在面对恩佐斯的袭击时保持|cFF2959D3|Hspell:308997|h[理智]|h|r。\r\n$bullet;在场地内小心站位，确保|cFF2959D3|Hspell:315772|h[心灵之握]|h|r 不会把你拉入|cFF2959D3|Hspell:309990|h[痛楚帷幕]|h|r。\r\n$bullet;留出足够的空间，让有|cFF2959D3|Hspell:309980|h[妄念]|h|r效果的盟友可以互相安全地接触对方。\r\n$bullet;在|cFF2959D3|Hspell:313400|h[堕落心灵]|h|r结束前将其驱散可以保持盟友的理智。",
},
["15x11218"] = {
["Title"] = "玛诺洛斯凝视",
["Description"] = "玛诺洛斯的凝视使目标惊骇，持续4秒。被移除时对8码范围内的敌人造成145点暗影伤害，由所有玩家分摊。",
