["Description"] = "施法者每1秒对附近所有玩家造成105点暗影伤害。",
},
["24x12665"] = {
["Title"] = "余烬",
["Description"] = "余烬会随机选择目标。如果余烬经过熔岩，就会获得热量吸收效果，提高它的伤害。",
},
["33x17296"] = {
