["16x13398"] = {
["Title"] = "综述",
["Description"] = "魔剑士奥鲁瑞尔在三个附魔之间循环：冰霜、火焰和奥术。每个附魔可以赋予她一种技能，她只能在自己具有这个附魔效果时使用这种技能。她接下来会用几个指令操纵那种魔法：复制、引爆和复生。",
},
["8x10481"] = {
