["15x18599"] = {
["Title"] = "综述",
["Description"] = "蔚索斯使用风的力量攻击队伍，借此将其赶出自己的栖息地。",
},
["15x19208"] = {
["Title"] = "赤精之歌",
["Description"] = "召唤赤精来制造一片充满迷雾的区域，阻止该区域内外相互选取目标。当玩家站在该区域中时，每1秒会受到1点自然伤害。",
},
["15x19207"] = {
["Title"] = "迷雾之火",
["Description"] = "当两位斗士的联合能量达到30点时，这支双人小队会召唤隐藏在翡翠迷雾中的活动炸弹。每个炸弹都会爆炸并对所有玩家造成持续的冲击。迷雾内的玩家无法选定迷雾范围外的目标，而迷雾外的玩家无法选定迷雾范围内的目标。",
},
["17x14664"] = {
["Title"] = "星力洪流",
["Description"] = "施法者向目标投掷一颗宇宙能量球，命中后造成25点奥术伤害，然后对额外目标造成21点奥术伤害。随着施法者的能量消耗，攻击的额外目标数量会逐渐减少。 ",
},
["14x8054"] = {
["Title"] = "恶意突袭",
["Description"] = "至尊者柯尔凡使用盾击后，将对其正前方所有目标进行6次攻击。第一次攻击将使受害者每3秒受到48点物理攻击。后续的每一次攻击都将造成越来越高的物理伤害。",
},
["15x19203"] = {
["Title"] = "组合攻击",
["Description"] = "",
},
["14x20620"] = {
["Title"] = "熵能遮罩",
["Description"] = "无厌者夏德哈周身被虚空甲壳包围，对所有玩家造成785点暗影伤害，并且每2秒额外造成261点暗影伤害，持续25秒。此效果可叠加。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在普通和更高难度中。无厌者夏德哈的熵能遮罩会在附近的随机位置将虚空汇聚为熵能聚合。|r",
},
