["1x12520"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;治疗被|cFF2959D3|Hspell:188492|h[腐坏之喉]|h|r击中的盟友。\r\n$bullet;被|cFF2959D3|Hspell:199176|h[尖刺之舌]|h|r吞噬的盟友会受到大量伤害。",
},
["2x6994"] = {
