["2x10702"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;站在聚焦在阿拉卡纳斯身上的太阳光线中以阻止其|cFF2959D3|Hspell:154149|h[充能]|h|r，但同时也会受到伤害。",
},
["2x18245"] = {
