["16x20523"] = {
["Title"] = "综述",
["Description"] = "莱登周期性从其他领域汲取虚空和生命精华。不同种类的精华能够赋予莱登不同的能量。\r\n\r\n生命值到达40%后，莱登就会开始从这些领域汲取能量。莱登在施放与这两种能量种类相同的法术时，法术效果会得到强化。",
},
["16x31743"] = {
["Title"] = "突破牢狱",
["Description"] = "恶棍被消灭时四散爆发，对牢狱中的玩家造成34点自然伤害并击退他们。\r\n\r\n与|cffffffff震地牢狱|r的墙壁碰撞会将其摧毁。",
},
["17x27649"] = {
["Title"] = "第二阶段：烈焰世界",
["Description"] = "",
},
["14x11238"] = {
["Title"] = "邪能引导",
["Description"] = "玛诺洛斯会持续不断地进行轰击，利用邪能引导伤害敌人，并将其击退。起初在小范围内造成51点火焰伤害，之后在中等范围内造成58点火焰伤害，最后在大范围内造成86点火焰伤害。",
},
["17x22610"] = {
["Title"] = "浓缩心能",
["Description"] = "伊涅瓦·暗脉女勋爵选择随机敌人，浓缩他们心脏中的心能，在10秒内造成30点暗影伤害。\r\n\r\n在此期间，目标会被定身。\r\n\r\n浓缩心能消失后会发生暗影释放引发的爆炸，对8码范围内的所有敌人造成62点暗影伤害。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02伊涅瓦·暗脉女勋爵会在浓缩心能容器填满33%时使用这项技能。|r",
},
["16x27507"] = {
["Title"] = "阶段转换：烈焰之途",
["Description"] = "",
},
["24x8630"] = {
["Title"] = "熔岩蔽天",
["Description"] = "熔岩四溅，散落地面，每2秒对熔岩池内的敌人造成2点火焰伤害。",
},
["2x4580"] = {
["Title"] = "听觉震荡",
["Description"] = "黑暗尖啸者使30码范围内所有玩家的施法速度降低35%，持续30秒。",
},
["17x14856"] = {
["Title"] = "物质世界",
["Description"] = "在生者的国度，灵魂引擎会为燃烧军团吸取死去的暗夜精灵的灵魂。",
},
["17x14853"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;处于灵魂世界的玩家在|cFF2959D3|Hspell:236072|h[哀嚎之魂]|h|r发生时需要大量的治疗。\r\n$bullet;如果被施加了|cFF2959D3|Hspell:236449|h[灵魂束缚]|h|r，迅速移动到另一个世界中被施加了同样效果的玩家所在的位置。",
},
["5x7251"] = {
["Title"] = "迷雾重重",
["Description"] = "从未有学者记录过关于莱登的力量的具体细节。或许是因为这些记忆早已湮没在了历史的长河之中，又或许是因为从未有人从与风暴守护者的战斗中生还并讲述自己的经历……",
},
["15x14273"] = {
["Title"] = "海洋污染",
["Description"] = "污染目标，每秒对其造成35点冰霜伤害。光环被移除时会使污染产生爆炸，对所有玩家造成16点冰霜伤害。",
},
["23x10424"] = {
["Title"] = "火炮弹幕",
["Description"] = "用火炮轰击敌人，对冲击点9码范围内的敌人造成13点火焰伤害。",
},
["17x14826"] = {
["Title"] = "风蚀",
["Description"] = "造成50点物理伤害，并使目标受到风蚀的伤害提高75%，持续29秒。\r\n\r\n此效果可叠加。",
},
["1x29659"] = {
["Title"] = "丢掷食物",
["Description"] = "“船长”曲奇会向一名随机玩家所在的位置快速投掷食物。丢一次美味的食物，再丢一次腐烂的食物，如此反复。",
},
["17x14812"] = {
["Title"] = "浸没",
["Description"] = "向3名敌人发射多颗水球，使他们被水泡包裹浸没，持续6秒。目标在被浸没期间每2秒会受到35点冰霜伤害。",
},
["24x12498"] = {
["Title"] = "综述",
["Description"] = "当顾问拉图修斯传送到区域里以黑暗魔法进行攻击时，拉文凯斯会与玩家开战。一旦拉文凯斯的生命值降至20%，拉图修斯会现出他的真面目：恐惧魔王丹塔利纳克斯。拉文凯斯的视线不再受到蒙蔽，他会召唤先祖的灵魂强化玩家，从而击败丹塔利纳克斯并将军团彻底逐出黑鸦堡垒。",
},
["6x3676"] = {
["Title"] = "扭曲炸弹",
["Description"] = "姆诺兹多随机向一名玩家所在区域发射一枚时光能量球，落地后形成半径达8码的时光扭曲地带。该扭曲地带每秒对区域内的所有敌人造成35点奥术伤害。",
},
["17x14806"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;观察大海，注意即将到来的海浪，从而躲开|cFF2959D3|Hspell:233971|h[潮汐奔涌]|h|r。\r\n|cFF2959D3|Hspell:234231|h[浸没]|h|r会造成昏迷，尤其是海浪冲击海滩的时候。",
},
["14x15859"] = {
["Title"] = "阶段转换：泰沙拉克之怒",
["Description"] = "",
},
["1x7442"] = {
["Title"] = "召唤碧蓝魔环上尉",
["Description"] = "召唤一名召唤碧蓝魔环上尉来消灭玩家。",
},
["2x7442"] = {
["Title"] = "召唤碧蓝魔环上尉",
["Description"] = "召唤一名召唤碧蓝魔环上尉来消灭玩家。",
},
["16x8314"] = {
["Title"] = "亵渎武器",
["Description"] = "亚煞极的力量从亵渎武器上渗出，随着其生命值的下降，亵渎之地的影响范围也会逐渐缩小。",
},
["33x17331"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;右臂施放|cFF2959D3|Hspell:64290|h[岩石之握]|h|r时，迅速攻击它以释放你的盟友。\r\n$bullet;被|cFF2959D3|Hspell:63346|h[聚焦视线]|h|r锁定时应该规避移动，以避免受到大量伤害。",
},
["24x2473"] = {
