["Description"] = "",
},
["14x30506"] = {
["Title"] = "坦克",
["Description"] = "$bullet;|cFF2959D3|Hspell:466518|h[熔火真金指虎]|h|r会对穆格的前方造成大量伤害，并对被击中的玩家施加|cFF2959D3|Hspell:467202|h[纯金滴露]|h|r。\r\n$bullet;|cFF2959D3|Hspell:469490|h[双厄射击]|h|r的伤害可以被击中的最近的一名玩家降低。",
},
["2x10335"] = {
["Title"] = "黑石手雷",
["Description"] = "向目标位置投掷黑石手雷，对3码范围内的敌人造成159点火焰伤害。",
},
