["Description"] = "夙娥在夜间短暂现身，攻击玩家并引导太阳之泪。太阳之泪会在引导过程中随机对玩家造成30点火焰伤害。\r\n\r\n当夙娥完成太阳之泪的引导后，她将消失在黑夜中。",
},
["2x13077"] = {
["Title"] = "震荡波",
["Description"] = "在前方锥形区域造成冲击，造成73点物理伤害，并使10码内的敌人昏迷3秒。",
},
["2x12336"] = {
["Title"] = "符文烙印",
["Description"] = "奥丁对每名玩家施加印记，持续12秒，每1秒造成4点神圣伤害。进入地面上相应的符文区域会清除此效果，并使玩家获得“烙印”效果。",
},
["15x12817"] = {
["Title"] = "综述",
["Description"] = "斯考匹隆的巢穴会持续孵化出蝎子，并在他施放|cFF2959D3|Hspell:204371|h[召唤蝎子]|h|r时加入战斗。如果有玩家离它们太近，它们也会攻击玩家。",
},
["2x13070"] = {
["Title"] = "警惕的暮色卫队卫兵",
["Description"] = "援军火速增援，协助队长作战。",
},
["4x4104"] = {
["Title"] = "炽热",
["Description"] = "炽热每2秒造成9点火焰伤害，并使其伤害提高5%，持续3秒。此效果可以叠加。",
},
["23x9461"] = {
["Title"] = "综述",
["Description"] = "骨喉会利用其庞大的身躯碾压平台上的敌人，同时还会从地下深处召唤出小型食腐蛆虫。骨喉会周期性利用其惊人的吸力将所有玩家吸过来。",
},
["14x8319"] = {
["Title"] = "第三阶段：我的世界！",
["Description"] = "在生命值第二次降至10%时，加尔鲁什会吸收亚煞极剩余的力量，能量全满，获得治疗并强化其所有技能。",
},
["2x4287"] = {
["Title"] = "虚空之门",
["Description"] = "玛诺洛斯从扭曲虚空中召唤一道传送门，使他能够召唤其恶魔盟友。随着他生命值的降低，更多不同种类的恶魔将穿越传送门，悉数登场。",
},
["2x25750"] = {
["Title"] = "熔岩四溅",
["Description"] = "喷涌的岩浆在查尔加斯身边溅落，对冲击点周围4码范围内的所有玩家造成31点火焰伤害。",
},
["4x4287"] = {
["Title"] = "虚空之门",
["Description"] = "玛诺洛斯从扭曲虚空中召唤一道传送门，使他能够召唤其恶魔盟友。随着他生命值的降低，更多不同种类的恶魔将穿越传送门，悉数登场。",
},
["5x3202"] = {
["Title"] = "闪电导体",
["Description"] = "电荷金刚随机指定一名玩家为闪电导体，使他们每2秒对周围半径8码范围内的盟友造成2,559点自然伤害，持续15秒。",
},
["5x6908"] = {
["Title"] = "黑暗天灾",
["Description"] = "黑暗寄生效果被净化之后，它会转换为黑暗天灾。黑暗天灾持续时间相当于黑暗寄生的剩余持续时间并且每3秒孵化一只徘徊之眼。",
},
["24x12937"] = {
["Title"] = "邪能契约",
["Description"] = "每个恶魔使徒都会从附近的盟友身上获得力量。每个盟友会使其造成的伤害提高100%，生命值提高100%。",
},
["6x7860"] = {
["Title"] = "闪避",
["Description"] = "范围伤害对心能魔像造成的伤害降低90%。",
},
["15x20619"] = {
["Title"] = "剧毒遮罩",
["Description"] = "剧毒甲壳包裹住无厌者夏德哈，每3秒对所有玩家造成3,922点自然伤害。",
},
["2x14423"] = {
["Title"] = "灵魂收割",
["Description"] = "燃烧军团的灵魂收割器每秒对周围15码范围内的敌人造成26点火焰伤害。",
},
["2x7382"] = {
["Title"] = "腐化的灵魂碎片",
["Description"] = "腐化的灵魂碎片向布隆亚姆移动。如果碎片到达布隆亚姆的身边，他将吞噬这个灵魂碎片。",
},
["3x7741"] = {
["Title"] = "专注闪电",
["Description"] = "击碎者金罗克制造出一颗专注闪电球，并锁定一名玩家。专注闪电在接触该玩家后爆炸，对8码范围内的所有玩家造成59点自然伤害。\r\n\r\n这颗闪电球还会每半秒对5码范围内的敌人造成13点自然伤害。",
},
["24x12901"] = {
["Title"] = "心灵震爆",
["Description"] = "对目标10码范围内的所有敌人造成暗影伤害。",
},
["23x12964"] = {
["Title"] = "黑暗湮灭",
["Description"] = "对施法者前方一条直线的所有敌人造成561点暗影伤害，并将其击退。",
},
["23x9411"] = {
["Title"] = "蚀骨之矛",
["Description"] = "向目标投掷一把蚀骨之矛，穿透护甲并造成56点物理伤害，并击倒目标，持续2.5秒。",
},
["8x14423"] = {
["Title"] = "灵魂收割",
["Description"] = "燃烧军团的灵魂收割器每秒对周围15码范围内的敌人造成22点火焰伤害。",
},
["17x32636"] = {
["Title"] = "皇家虚空之翼",
["Description"] = "",
},
["23x12936"] = {
["Title"] = "坦克",
["Description"] = "$bullet;小心|cFF2959D3|Hspell:207907|h[强烈燃烧]|h|r，该技能会随着战斗的进行造成越来越高的伤害。\r\n$bullet;尽可能打断|cFF2959D3|Hspell:208165|h[枯萎灵魂]|h|r，以免叠加太多层数。",
},
["15x20643"] = {
["Title"] = "梦魇抗体",
["Description"] = "成功的近战攻击会削弱目标的能力，造成12点暗影伤害，使其急速降低3%，移动速度降低3%，持续4秒。\r\n该效果可叠加。",
},
["23x27622"] = {
["Title"] = "治疗者",
["Description"] = "$bullet; |cFF2959D3|Hspell:422162|h[诱引烛焰]|h|r会吸引所有卑微的劳工聚向目标。\r\n$bullet;老蜡须的|cFF2959D3|Hspell:422150|h[鲁莽冲锋]|h|r造成的|cFF2959D3|Hspell:422270|h[塌方点]|h|r和飞驰的矿车都会立即消灭卑微的劳工。",
},
["23x12931"] = {
["Title"] = "坦克",
["Description"] = "$bullet;通过跳跃可以从|cFF2959D3|Hspell:207278|h[奥术锁定]|h|r中解脱。\r\n$bullet;巡逻队长加多|cFF2959D3|Hspell:207806|h[发送信号]|h|r后，尽快对守夜人援军建立威胁值。",
},
["15x8007"] = {
["Title"] = "毁伤",
["Description"] = "掠风者克尔鲁克同时使用两把武器进行毁灭性的攻击。",
},
["23x25483"] = {
["Title"] = "综述",
["Description"] = "安布雷斯库持续释放|cFF2959D3|Hspell:385078 |h[奥术爆发]|h|r，这股奥术能量会生成在区域内徘徊的|cFF2959D3|Hspell:385267 |h[爆裂旋涡]|h|r。\r\n\r\n在生命值降至75%、50%和25%时，安布雷斯库会生成开始|cFF2959D3|Hspell:385331 |h[破裂]|h|r的爆裂水晶。",
},
["16x10067"] = {
["Title"] = "大地之柱",
["Description"] = "泰克图斯从地底拔出大地之柱。晃动数秒后，大地之柱会从目标位置窜出，杀死任何仍然在目标位置的玩家。\r\n\r\n当泰克图斯获得25点能量后将使用该技能。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在史诗难度中，泰克图斯还将在拥有50点能量时使用该技能。|r",
},
["23x12929"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;通过跳跃可以从|cFF2959D3|Hspell:207278|h[奥术锁定]|h|r中解脱。\r\n$bullet;在加多|cFF2959D3|Hspell:207806|h[发送信号]|h|r后，迅速击败守夜人援军，以免过多的敌人淹没队伍。",
},
["5x3319"] = {
["Title"] = "与熔岩虫肉搏",
["Description"] = "在熔喉发动大力撞击之后，会有一个短暂的机会，使两个玩家能够跳到他的钳子上。他们可以在那里把锁链缠在虫子面前的尖刺上，然后将熔喉拉向尖刺。",
},
["17x12999"] = {
["Title"] = "综述",
["Description"] = "在战斗过程中，故障的构造体会在多个模式之间进行切换，不同模式的技能不同。\r\n\r\n在清洁者模式下，吃下|cFF2959D3|Hspell:206788|h[毒性薄片]|h|r。在狂热者模式下，避开|cFF2959D3|Hspell:214672|h[毁灭]|h|r。崔利艾克斯处于看管者模式时，在清扫器故障时跳上去，避免团队受到|cFF2959D3|Hspell:207327|h[净化毁灭]|h|r的伤害。",
},
["16x12817"] = {
["Title"] = "综述",
["Description"] = "斯考匹隆的巢穴会持续孵化出蝎子，并在他施放|cFF2959D3|Hspell:204371|h[召唤蝎子]|h|r时加入战斗。如果有玩家离它们太近，它们也会攻击玩家。",
},
["1x12046"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;被|cFF2959D3|Hspell:192048|h[驱逐之光]|h|r击中后，远离其他玩家。\r\n$bullet;当赫娅拥有|cFF2959D3|Hspell:192132|h[秘法师加护：雷]|h|r时，注意跑入|cFF2959D3|Hspell:192305|h[风暴之眼]|h|r以确保安全。\r\n$bullet;当赫娅拥有|cFF2959D3|Hspell:192133|h[秘法师加护：光]|h|r时，注意躲避|cFF2959D3|Hspell:192307|h[圣洁庇护]|h|r的光球。",
},
["17x12965"] = {
["Title"] = "综述",
["Description"] = "梦魇之王萨维斯的大部分攻击会对受攻击者造成腐蚀效果。玩家的腐蚀值越高，就越容易受到梦魇的影响，最终在腐蚀值达到最大时，会完全失去控制，转而攻击盟友。\r\n\r\n玩家的唯一希望在于伊瑟拉的力量，她让许多玩家进入沉眠，生成他们的|cFF2959D3|Hspell:206005|h[梦境幻影]|h|r。幻影消逝时，受到影响的玩家会苏醒，而幻影受到的所有腐蚀效果和伤害都会失效。",
},
["17x22810"] = {
["Title"] = "裂耳尖啸",
["Description"] = "啸翼对她视野内的所有玩家造成75点声波伤害，并且每2秒造成12点声波伤害，持续12秒。玩家还会在自己的位置留下一滩|cffffffff鲜血脓液|r。",
},
["6x6299"] = {
["Title"] = "虫群",
["Description"] = "风领主梅尔加拉克与自己最信任的战士并肩作战。",
},
["17x12957"] = {
["Title"] = "治疗者",
["Description"] = "$bullet;根据当前时间流逝速度的不同，你对|cFF2959D3|Hspell:206609|h[时间释放]|h|r的反应时间会有极大的差异。\r\n$bullet;衰减时间粒子会通过|cFF2959D3|Hspell:207228|h[扭曲暗夜井]|h|r对整个团队造成持续性伤害。\r\n$bullet;|cFF2959D3|Hspell:211927|h[势不可挡]|h|r会造成越来越高的伤害，直到被|cFF2959D3|Hspell:212109|h[时空斩]|h|r打断为止。",
},
["24x4854"] = {
["Title"] = "寒冰箭",
["Description"] = "苍白的玛勒基对当前目标造成200点冰霜伤害，使其移动速度降低50%，持续4秒。",
},
["17x12912"] = {
["Title"] = "猛击",
["Description"] = "克洛苏斯用双拳砸向桥面，制造出一道冲击波，对所有玩家造成132点物理伤害。\r\n\r\n站在拳头下面的玩家会受到112点物理伤害。如果两个拳头的伤害都被玩家承担，对其他玩家造成的伤害降低至67点物理伤害。",
},
["23x22807"] = {
["Title"] = "劈肉",
["Description"] = "外科医生缝肉对他当前的目标造成50点物理伤害。",
},
["1x4815"] = {
["Title"] = "火球术",
["Description"] = "灼热勋爵对当前目标造成火焰伤害。",
},
["16x12999"] = {
["Title"] = "综述",
["Description"] = "在战斗过程中，故障的构造体会在多个模式之间进行切换，不同模式的技能不同。\r\n\r\n在清洁者模式下，吃下|cFF2959D3|Hspell:206788|h[毒性薄片]|h|r。在狂热者模式下，避开|cFF2959D3|Hspell:214672|h[毁灭]|h|r。崔利艾克斯处于看管者模式时，在清扫器故障时跳上去，避免团队受到|cFF2959D3|Hspell:207327|h[净化毁灭]|h|r的伤害。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在史诗难度下，崔利艾克斯会使用人格转移来激活额外的构造体。当崔利艾克斯当前的模式与构造体的模式一致时，就会激活人格重合。|r",
},
["14x11092"] = {
["Title"] = "坦克",
["Description"] = "$bullet;在没有吸引仇恨时站在|cFF2959D3|Hspell:179582|h[轰鸣的裂隙]|h|r中可以将其封印。\r\n$bullet;当邪能领主处于|cFF2959D3|Hspell:179667|h[赤手空拳]|h|r或|cFF2959D3|Hspell:179671|h[全副武装]|h|r状态时，两名坦克需要重叠站位。\r\n$bullet;|cFF2959D3|Hspell:179406|h[灵魂裂劈]|h|r会将你放逐到暗影领域，让你施放自己的|cFF2959D3|Hspell:182008|h[潜伏能量]|h|r。",
},
["14x20619"] = {
["Title"] = "剧毒遮罩",
["Description"] = "剧毒甲壳包裹住无厌者夏德哈，每3秒对所有玩家造成3,922点自然伤害。\r\n\r\n|TInterface\\EncounterJournal\\UI-EJ-WarningTextIcon:0:0:0:0|t|CFF741A02在普通和更高难度中，获得剧毒遮罩后，无厌者夏德哈会向房间中央喷吐一片毒泡流溢。|r",
},
["16x12970"] = {
["Title"] = "梦魇腐蚀",
["Description"] = "萨维斯的许多法术会在命中目标时对其传播梦魇腐蚀。玩家的腐蚀值越高，就越容易被梦魇控制。任何玩家如果被彻底腐蚀，萨维斯就可以控制他们。",
},
["15x11973"] = {
["Title"] = "邪能喷发",
["Description"] = "恐惧地狱火向随机位置发起冲锋，对目标位置附近8码范围内的敌人造成54点火焰伤害。",
},
["14x14934"] = {
["Title"] = "灵魂女王德雅娜",
["Description"] = "",
},
["14x31087"] = {
["Title"] = "增幅器",
["Description"] = "增幅器会持续获得能量。",
},
["6x7088"] = {
["Title"] = "兽性咆哮",
["Description"] = "战神贾拉克发出一声野蛮的咆哮，对所有玩家造成68点物理伤害，并使其在遭到战神贾拉克攻击时承受的伤害提高50%。这个效果可以叠加。",
},
["15x26305"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet;永恒炽焰和暗影精华中，有一个的生命值降到50%的话，他们就会把生命值结合起来，形成暗影烈焰融合体。\r\n$bullet;每个元素附近的玩家会周期性地获得|cFF2959D3|Hspell:401809|h[腐化暗影]|h|r和|cFF2959D3|Hspell:402617|h[炽炎之热]|h|r效果。",
},
["14x22014"] = {
["Title"] = "伤害输出者",
["Description"] = "$bullet; 罪孽回响和赤红秘法师非常危险，如果不能迅速应对，就会击垮你的团队。\r\n$bullet;蕾茉妮雅通过|cFF2959D3|Hspell:330580|h[血脉连接]|h|r和德纳修斯共享生命值。\r\n$bullet;小心站位以应对|cFF2959D3|Hspell:326851|h[血债]|h|r和|cFF2959D3|Hspell:332626|h[粉碎痛苦]|h|r，这两个技能都能将玩家从德纳修斯身边击退。",
},
["16x12913"] = {
["Title"] = "燃烧的沥青",
["Description"] = "克洛苏斯从肩膀上释放燃烧的沥青冲击。每团沥青会对着陆点3码范围内的所有敌人造成141点火焰伤害。如果燃烧的沥青没有命中玩家，则会形成一个燃烧的余烬。",
},
["2x4410"] = {
["Title"] = "冰锥术",
["Description"] = "西斯雷尔对其前方锥形区域内的玩家造成冰霜伤害。被冰锥术击中玩家移动速度降低50%，持续8秒。",
},
["1x4965"] = {
["Title"] = "闪电箭",
["Description"] = "皮萨斯对当前目标射出一支闪电箭，对其造成自然伤害。",
},
["16x14918"] = {
["Title"] = "坦克",
["Description"] = "$bullet;轮流接手基尔加丹，避免|cFF2959D3|Hspell:239932|h[邪爪]|h|r叠加的层数太高。 \r\n$bullet;在基尔加丹施放|cFF2959D3|Hspell:240910|h[末日决战]|h|r时，其中一枚飞弹会比其他飞弹大得多。这就是|cFF2959D3|Hspell:240911|h[末日之雹]|h|r，坦克必须快速移动以拦截这枚飞弹。",
},
["4x5784"] = {
["Title"] = "红玉石化",
["Description"] = "守卫试图将自己的敌人转化为红玉，使其受到的火焰伤害降低90%，但是会逐渐降低其移动速度。身上石化效果达到100层的敌人将变成石头，无法移动或执行任何动作。",
},
["17x13189"] = {
["Title"] = "支配触须",
["Description"] = "",
},
